'use strict';

/* v7 剧本库：六部作品的正文、选项与结局走向。由 content/build_story.py 生成。 */

const STORY6={"穗骨原":{"no":1,"name":"穗骨原","subtitle":"谷子、祖骨、和一块不肯松手的田","through":"父亲想把地赎回来，到死没赎成。你从恨他，到懂他，到发现自己也在做同样的事。","cast":[{"id":"father","name":"穗老六","role":"佃农","tag":"父"},{"id":"mother","name":"棠娘","role":"看水人","tag":"母"},{"id":"sibling","name":"穗禾","role":"拾穗","tag":"姐"}],"main":[{"id":"sui_m01","act":"main","age":[0,0],"mode":"montage","title":"落地","opening":"腊月里，土屋烧着谷草，烟从门缝往外钻。接生婆把你倒提起来，拍了两下，你才哭出声。父亲在门外攥着那把豁口镰刀，刃上的冻泥没擦。母亲在炕上说，轻点。父亲把镰刀搁在门槛外，进来看你一眼：又一个吃饭的。梁上挂着半袋谷，袋口扎得紧。头一年你活在别人背上，姐姐背你去渠边，母亲把米汤嚼细了喂你。你学会听脚步声认人。","ask":"满岁那天，桌上摆了三样东西，你先抓哪样？","days":360,"npc":"","memory":"梁上的半袋谷","choices":[{"title":"抓住镰刀柄","desc":"你把豁口镰刀的木柄抱住，谁抽也不松手。","hint":"母亲看了父亲一眼。","tone":"carry","outcome":"父亲没笑，只把镰刀连着你的手一起提了提，说：沉。母亲把你的手指一根一根掰开，指甲在她手背上划出白印。她把桌上的木梳收进柜里，没说话。那年秋天，父亲给你削了一把小木镰，刃是假的，柄是真的。你走到哪都攥着它，后来丢在渠边，找了三天。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2},"flag":"","thread":"小木镰丢在渠边没找回来"}},{"title":"够那半袋谷","desc":"你越过镰刀和木梳，朝梁下的半袋谷爬。","hint":"母亲抱开你时手在抖。","tone":"seek","outcome":"你抓住袋角，麻布上的谷壳扎进指缝。母亲把你抱起来，袋口松开一道缝，几粒谷落在炕席上。她一粒一粒捡回袋里，捡了很久。父亲说：小人精。那年冬天，她每次舀谷都先看一眼梁上，再低头数一遍。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}},{"title":"攥住母亲衣角","desc":"你攥住她的衣角，她一动你就哭。","hint":"她那天没去看水。","tone":"family","outcome":"母亲只好把你抱起来，一直抱到灶边。那天渠上换了别人看水，咱家的田口被挖窄了一寸。晚上她把你放在炕上，又提着木锹出门，回来时鞋上全是泥。她没跟任何人说这件事。第二天她的手腕肿了，舀水时换了左手。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":""}}]},{"id":"sui_m02","act":"main","age":[1,3],"mode":"dialogue","title":"渠边","opening":"你三岁那年春上，姐姐背你去渠边找母亲。母亲是看水人，裤腿卷到膝盖，站在渠里，用一把木锹把水往各家的田口分。上游王二家的水口挖得宽，水流到他家地里就慢了，到咱家垄头，只剩一层湿泥。母亲看见了，没说话，先看了一眼王二家的脸。父亲在自家田头磨那把豁口镰刀，锉刀声隔着水一阵一阵。","ask":"渠里的水不够分，你想怎么做？","days":120,"npc":"mother","memory":"母亲划的水线","choices":[{"title":"下渠堵漏","desc":"你下到渠里，用胸口堵住田埂上的漏眼。","hint":"你在炕上烧了三天。","tone":"help","outcome":"水凉得像刀，泥没到你的腰。母亲把你拎起来，骂了一句，声音发抖。漏眼堵住了，水慢慢漫过咱家的垄沟。你当晚发热，母亲守了三夜，第四天你退烧，她靠在门框上睡着了，手里还攥着擦身的布。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":""}},{"title":"告发王二家","desc":"晚饭时你告诉父亲，王二家把水口挖宽了。","hint":"两家从此不搭话。","tone":"tell","outcome":"父亲放下碗，提了镰刀出门。渠边吵了半宿，王二家的狗叫到天亮。第二天，王二娘把借咱家的那半升盐要了回去。母亲没说你，只把你的碗往你面前推了推。那年插秧，咱家最后才放上水，秧苗比别家矮了一截。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"王二娘要回了那半升盐"}},{"title":"学母亲看水","desc":"你蹲在岸上，看母亲怎么量水线，记住每一道口子。","hint":"水不认记性。","tone":"learn","outcome":"母亲用木锹在渠底划了一道印，说：到这儿，就够了。你点头，把印记在心里。姐姐在旁边撇嘴：记这个，能当饭吃？你没理她。第二天你去看，印被水冲平了。母亲重新划，说：水天天变，人得天天来。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":3},"flag":"","thread":""}}]},{"id":"sui_m03","act":"main","age":[4,4],"mode":"dialogue","title":"半袋谷","opening":"开春前，粮缸见了底。母亲用陶碗把缸底最后一点谷刮出来，倒进那条补过三回的麻袋，扎上口，正好半袋。她把袋口解开，用升子一升一升地量：七升倒在左边碗里，留种；两升倒在右边碗里，换盐。剩下的一把，她攥了攥，放进留种那边。盐贩子的车铃在门外响了一下。她抬头，先看你的脸。父亲从田里回来，站在门口看了一眼，说：种。","ask":"盐贩子进了门，你做什么？","days":30,"npc":"mother","memory":"半袋谷分两碗","choices":[{"title":"护住种袋","desc":"你趴到种袋上，把长命锁从脖子上扯下来递过去。","hint":"那把锁再没赎回来。","tone":"protect","outcome":"盐贩子捏着那把锁，掂了掂，留下三块粗盐。母亲没拦，只在灶边站了很久。那年春天你的脖子空着，姐姐说像少了颗牙。后来你长大了，母亲还提过一次：锁是你外婆打的，上头刻了个穗字。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"抓一把谷种","desc":"你从留种碗里抓了一把，塞进嘴里嚼。","hint":"西垄空了一截。","tone":"greed","outcome":"生谷子扎嘴，你嚼了半天咽不下去。母亲看见了，没骂，只把剩下的谷种重新数了一遍。开春播到西头，少了一小把，那一截垄空着，长满了灰灰菜。秋收时父亲从那儿过，用镰刀背敲了敲你的头，很轻。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"哀":1},"flag":"","thread":""}},{"title":"劝母亲多换盐","desc":"你扯着她的袖子说，多换点盐，种少些不打紧。","hint":"借种的字据按了手印。","tone":"practical","outcome":"母亲看了你一眼，从留种碗里又倒了一升给盐贩子。那晚的菜有了咸味，你多吃了半碗。开春家里没够种，父亲去谷债盟借了半斗，按了手印。那张字据后来压在田契下面，边角也粘了米汤。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":"借种的字据压在田契下"}}]},{"id":"sui_m04","act":"main","age":[7,7],"mode":"narration","title":"田埂上的字","opening":"七月里，谷子刚抽穗。你蹲在田埂上拔草，一个过路的老账房停下来问路。他背着一只旧褡裢，鞋面上全是灰。你说不清路，他就在田埂的软土上折了根柳枝，先写了一个穗字，又写了一个生字。他说：这是你的名字。你不信。他说：你叫什么？你说：穗生。他指了指地上：喏。你看了很久，觉得那两个字像两块不认识的田。远处父亲在磨那把豁口镰刀，锉刀声一下一下。","ask":"老账房起身要走，你做什么？","days":15,"npc":"","memory":"树枝写的名字","choices":[{"title":"跟他学写","desc":"你捏着柳枝，跟着他往渡口走，一路学写。","hint":"那天的草没拔完。","tone":"learn","outcome":"他走得不快，走三步写一个字。到村口，你学会了穗、生，还有棠——母亲的名字。他说：字不要钱，闲工夫才要钱。你回家时天黑了，草还剩半垄。父亲没问你去哪，只说：明天早起。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"惧":1},"flag":"learned_name","thread":""}},{"title":"写母亲的名字","desc":"你跑回家，把棠字写给母亲看，柳枝都攥热了。","hint":"老账房在田埂上走远了。","tone":"warm","outcome":"母亲正在淘米，手上都是水。她看了半天，说：这是啥？你说：你的名字。她把手在围裙上擦干，又看了一遍，说：不像。晚上她把这个字描在灶灰上，描了三回，第四回被风吹平了。第二天她没再问，出门前把灶灰扫了。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"母亲在灶灰上描自己的名字"}},{"title":"抹掉那个字","desc":"你用鞋底把字抹平，说这不是我的名字。","hint":"你一直写不好那个穗字。","tone":"rebel","outcome":"老账房看了你一眼，没笑，也没生气，把柳枝插在田埂上就走了。你回到家，晚上睡不着，用指头在肚皮上画那个字，画到一半忘了。第二天你去看，柳枝还在，字被牛踩没了。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":5},"flag":"","thread":""}}]},{"id":"sui_m05","act":"main","age":[11,11],"mode":"dialogue","title":"鞋底的票","opening":"入冬前，姐姐从穗仓城帮工回来，给你带了一块麦芽糖。糖粘在牙上，你含了半宿。半夜你起来解手，看见她蹲在灶前烤鞋，鞋底冒出个纸角。她抽出来看了一眼，又塞回去。你认得那两个字——穗仓，田埂上老账房写过。她回头看见你，说：敢说出去，我把你扔渠里。","ask":"姐姐要去城里，你怎么做？","days":20,"npc":"sibling","memory":"鞋底下的船票","choices":[{"title":"塞给她两升穗","desc":"你把藏在墙洞里的两升穗子倒进她的包袱。","hint":"那个冬天你总在灶边站着。","tone":"help","outcome":"姐姐掂了掂包袱，没看你，说：谁要你的。第二天她把穗子背到鱼尾泽卖了，票还在鞋底。船期在腊月，她没走，因为母亲咳了半冬。你饿得夜里啃灶灰里的红薯皮，她看见了，把自己的半碗粥倒给你，说：别跟娘说。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"告诉母亲船票","desc":"你把鞋底的事告诉母亲，母亲正在补父亲的裤脚。","hint":"她一年没叫过你的名字。","tone":"tell","outcome":"母亲没抬头，针在布上停了一下。第二天，姐姐的鞋被拆了，鞋底换成新的，纸票不见了。姐姐没哭，也没闹，只是从那天起叫你喂。过了一年，她才重新叫你的名字，像从牙缝里抠出来的。","eff":{"bond":-5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_sister_ticket","thread":"她一年没叫你的名字"}},{"title":"求她带上你","desc":"你抱住她的腿，说走的时候带上我，我不吃闲饭。","hint":"她把票撕了，扔进渠里。","tone":"family","outcome":"姐姐愣了一下，抬脚想甩开你，没甩掉。她蹲下来，把鞋脱了，抽出那张票，当着你的面撕成四片，扔进渠里。纸片在水上转了两圈，沉了。她说：行了吧。那年腊月船开的时候，她在家剁猪菜，刀落得很重。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":4},"flag":"","thread":""}}]},{"id":"sui_m06","act":"main","age":[13,13],"mode":"dialogue","title":"蝗","opening":"蝗虫是午后到的。先是远处一层黄雾，后来听见响，像下雨，可天是晴的。晒场上有人敲锣，一声接一声，全村的人都往田里跑。父亲手里攥着那把豁口镰刀，把一把扫帚塞给你，又夺回去，说：回屋。母亲从渠那边跑过来，头发散了，抓住你的胳膊说：留下，敲盆。父亲说：回去。母亲说：留下。两个人都没看你，眼睛盯着各自的手。","ask":"父亲和母亲都看着田，你呢？","days":10,"npc":"father","memory":"锣声响了一夜","choices":[{"title":"跟父亲回家","desc":"你低下头，跟着父亲往家走，门闩在你身后插上。","hint":"母亲半夜才回来。","tone":"obey","outcome":"你坐在门槛上，隔着门板听锣声，一声比一声远。梁上的半袋谷在黑暗里晃。母亲后半夜才回来，头发上挂着死蝗虫，手指被铜盆沿磨破了。她看见你，说：没睡？就再没别的话。西垄的谷子那夜吃光了。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"惧":3,"哀":4},"flag":"","thread":"西垄的谷子那夜吃光了"}},{"title":"留下来敲盆","desc":"你抓起铜盆，站到母亲身边，敲到天亮。","hint":"父亲三天没跟你说话。","tone":"stay","outcome":"铜盆敲裂了一道口，你的虎口也裂了。蝗虫撞在脸上，像热沙子。天快亮时，父亲从西头回来，看见你，站了一下，把身上的袄脱下来扔给你，说：回。那件袄上有蝗虫的汁，洗了三遍还有味。东垄保住了半截。父亲三天没跟你说话。","eff":{"bond":4,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}},{"title":"先藏好种袋","desc":"你跑回家，把半袋谷塞进祖骨罐边的土洞里。","hint":"你两边都没站。","tone":"sneak","outcome":"你把袋口扎紧，塞进村后祖骨罐旁的土洞，用碎瓦盖住。回到田里时，锣已经哑了，蝗虫落了一地，像一层会动的壳。母亲看见你，问：去哪了？你说：解手。第二年开春，那半袋谷还在，没有发霉。你一直没告诉他们。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":1},"flag":"hid_seed_sack","thread":""}}]},{"id":"sui_m07","act":"main","age":[17,17],"mode":"dialogue","title":"田契","opening":"冬至那晚，父亲把灶膛封了，从炕席底下摸出一个竹筒。筒口塞着布，布上有一股陈米味。他倒出田契，铺在磨盘上，四角用碗压住。纸边有一块用米汤粘过，母亲的手艺。他让你把灯端近，指头从东边数过去：一垄，两垄，三垄。他说：你爷的骨埋在这垄，靠槐树那头。记住。筒底还有一截麻绳，绳上磨出一道深痕，他说：罐上的，换过三回，就这截没舍得。","ask":"灯在你手里，你要问什么？","days":10,"npc":"father","memory":"第三垄的祖骨","choices":[{"title":"按手在田契上","desc":"你跪下，把手按在田契上，跟着他念祖骨的位置。","hint":"你的膝盖记住了那块砖。","tone":"obey","outcome":"父亲的手压在你的手背上，很粗，很热。他说：地没了，骨不能没。你念了三遍，第三遍他跟着你念。那晚你梦见一垄一垄的土在自己身下翻身。第二年有人来提亲，你没应，你说家里有地要种。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"accepted_land_burden","thread":"你答应过父亲守住第三垄"}},{"title":"问地是谁的","desc":"你指着契上的红印，问这地如今还算不算咱的。","hint":"他把赎字咽了回去。","tone":"ask","outcome":"父亲的手停在红印上，停了很久。他说：契是咱的，地不是。说完把契折起来，折得很慢，像怕折断了什么。他出去修犁，锉刀响到半夜。母亲在灶边坐着，没点灯。你第一次知道，他每年秋后去穗仓城，不是去卖谷。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"knows_land_not_ours","thread":""}},{"title":"替他收好田契","desc":"你把契纸按原样折好，塞回筒里，说先吃饭。","hint":"你没问赎地要多少年。","tone":"dodge","outcome":"父亲看了你一会儿，把筒子塞回炕席底下。那晚的粥很稀，谁都没说话。后来你想起这件事，最清楚的是他指甲缝里的黑泥，不是那个赎字。开春他照旧去穗仓城，你没问，他也没说。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4},"flag":"","thread":""}}]},{"id":"sui_m08","act":"main","age":[25,25],"mode":"dialogue","title":"渠口的夜","opening":"春灌的水下来时，上游王家把水口往自家田里挪了半尺。水到咱家垄头，只剩一层湿泥。你扛着锹去渠边，父亲已经在那儿了，手里还是那把豁口镰刀，刃口在月光下缺了一块。王二家的儿子坐在水口上，说：水往低处走，天定的。父亲没说话。你把锹插进泥里，站住了。","ask":"水口这一夜，你打算怎么站？","days":10,"npc":"father","memory":"渠口站了一夜","choices":[{"title":"横锹守水口","desc":"你把锹横在水口上，谁来也不让，站到天亮。","hint":"你眉上后来留了道疤。","tone":"defy","outcome":"后半夜王二家的儿子来扒水口，你拿锹柄挡，他捡石头砸，石头划过你眉骨，血糊了半只眼。你没退。天亮水漫进咱家垄沟，父亲在渠对面看着，一句话没说。回家他从灶膛下摸出酒坛，倒满一碗推过来：喝。坛口麻绳的旧痕，和祖骨罐上那道一样。他第一次给你倒酒。","eff":{"bond":4,"health":-3,"reputation":3,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"爱":2},"flag":"stood_at_canal","thread":""}},{"title":"去请谷债盟","desc":"你连夜走七里地去敲谷债盟的门，请人带水册来。","hint":"村里给你起了个外号。","tone":"rule","outcome":"盟老天亮才来，拿着水册一尺一尺量，把水口判回原处，还罚了王家两斗谷。水是有了，可王家从此见了咱家的人就啐一口。父亲在渠边听判，手一直攥着镰刀柄，没松开。回家他倒酒，倒到一半停了停，说：下回，先跟我说。那是他第一次给你倒酒。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}},{"title":"回家取袄","desc":"你看父亲只穿单衣，跑回家取袄，再回渠边。","hint":"他那年咳了一冬。","tone":"family","outcome":"你跑回家，母亲没睡，把袄递给你，又塞了个烤红薯。回到渠边，水口已被扒开，父亲一个人用身子堵着，水从他裤腿两边淌。你把袄披上，他骂：回去。你没回，站到他旁边。天亮水回来了。到家他摸出酒坛，第一碗推给你，手一直在抖。他这辈子第一次给你倒酒。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"惧":2},"flag":"","thread":"他那年咳了一冬"}}]},{"id":"sui_m09","act":"main","age":[26,28],"mode":"dialogue","title":"一垄聘礼","opening":"二十六岁那年，母亲托人去下湾说亲。女方叫杏，家里没有田，租着别人一垄水田，娘眼不好，缺劳力。她娘回了两个说法：要么你过去入赘三年，把她家的田种完，再带杏回骨沟村；要么拿一垄田的价做聘，人直接领走。咱家只有租来的三垄。母亲把柜底翻了一遍，翻出两块布、一对银耳环——是她出嫁时戴的。父亲坐在门槛上磨那把豁口镰刀，磨到天黑，说：入赘，户册上就不是穗家的人。","ask":"一垄田拿不出，这门亲怎么定？","days":90,"npc":"mother","memory":"一垄田的聘礼","choices":[{"title":"去鱼尾泽扛包","desc":"你去鱼尾泽盐行扛了三个月麻包，把一垄田的价挣回来。","hint":"插秧那半月你不在家。","tone":"grind","outcome":"回来时你把钱交到杏的娘手里，人瘦了一圈。她摸了摸你的手，说：手是粗的，心是实的。成亲那天父亲没来吃席，他在田里补埂，补到月亮出来。你端酒去，他接了，说：肩上有伤，少喝。那年插秧晚了半月，咱家的秧比别家矮一截。","eff":{"bond":3,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":1},"flag":"","thread":""}},{"title":"入赘三年","desc":"你答应去下湾入赘三年，种她家的田，三年后带杏回来。","hint":"这三年父亲的腰弯下去了。","tone":"obey","outcome":"户册上你改姓杏，谱上还是穗。你在下湾种了三年田，渠是杏家的，埂是杏家的，连锄头都是她家的。第三年秋后你带杏回骨沟村，父亲到村口接，腰比走时弯了一截。他把豁口镰刀塞给你，说：你家的地，你自己看。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"uxorilocal_three_years","thread":"父亲这三年弯了腰"}},{"title":"去下湾说亲","desc":"你空着手去下湾，把家里的底一五一十说给杏的娘听。","hint":"杏自己提着包袱跟了你。","tone":"honest","outcome":"杏的娘听完，把茶碗推远了些，说：我闺女不是去受苦的。杏从里屋出来，把一只包袱放在桌上，说：我跟他走。她娘没拦，也没送。成亲那天下雨，杏的鞋陷在泥里，你背她过的渠。她娘到死没再进过咱家的门。","eff":{"bond":2,"health":-1,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"杏的娘到死没进过咱家门"}}]},{"id":"sui_m10","act":"main","age":[30,30],"mode":"dialogue","title":"鞋底的城","opening":"穗禾那年终于要走。她把那张船票从鞋底抽出来，纸边磨得像布。她说穗仓城的米行招缝袋的女工，管饭。母亲在灶边没回头，说：家里不缺你一口。穗禾说：我缺。她把床底下的旧木箱拖出来，箱底压着这些年拾穗攒的谷子，装了半袋。父亲在院里磨镰刀，锉刀声停了。","ask":"船在鱼尾泽等，你送不送她？","days":20,"npc":"sibling","memory":"鞋底那张船票","choices":[{"title":"当簪给她盘缠","desc":"你把杏的陪嫁银簪当了，把钱塞进穗禾箱底，不让她知道。","hint":"杏找了那簪子半年。","tone":"help","outcome":"船开时穗禾没回头，只把箱子举了举。半年后她托人带回一块洋布、一包城里的糖。杏把布裁了件袄，穿了三年，袖口磨破才知道当簪的事。她没闹，只把袄叠好放进箱底，说：留着。此后她梳头都用手拢，再没戴过簪子。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"交出船票","desc":"你连夜把船票的事告诉母亲，母亲把她的鞋锁进柜里。","hint":"她三年没叫你名字。","tone":"report","outcome":"穗禾走不成，在村里又待了三年。她每天去渠边拾穗，回来把穗子摔在灶台上。三年后母亲自己把鞋还给她，说：走吧。她走那天没跟任何人说，只在你门槛上放了一双补好的鞋。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"stopped_sister","thread":"她三年没叫你名字"}},{"title":"送到鱼尾泽","desc":"你替她背箱子到鱼尾泽，回来只说没追上。","hint":"母亲在门口等了三个晚上。","tone":"sneak","outcome":"船离岸时穗禾把头上的木梳扔给你，说：给娘。你回到家，母亲坐在门槛上纳鞋底，没抬头，问：追上了？你说：没有。她把手里的针别在布上，说：你鞋底的泥是鱼尾泽的。之后她再没问过。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"lied_about_sister","thread":"母亲知道你说谎，没拆穿"}}]},{"id":"sui_m11","act":"main","age":[33,33],"mode":"dialogue","title":"门帘","opening":"杏从后半夜疼到晌午，还没生。接生婆把门帘放下，只让母亲进出。灶上烧着一锅水，梁上的半袋谷解开了口。父亲蹲在院角，用那把豁口镰刀削一根木棍，削一截，看一眼门口。母亲出来说：去祖骨罐前烧三张纸。又说：别进屋。","ask":"门帘里又传来一声，你往哪走？","days":10,"npc":"mother","memory":"门帘里的一声","choices":[{"title":"去祖骨罐前烧纸","desc":"你按母亲说的，去村后烧了三张纸，磕了三个头。","hint":"你回来时孩子已经哭了。","tone":"pray","outcome":"纸灰被风吹到罐身上，那道绳痕里落了一层。你磕完头往回跑，进门时孩子已经裹在旧袄里，杏躺着，头发全湿。她看了你一眼，问：外头冷不冷。你说不冷。她说：哦。母亲给孩子起名穗宁。后来杏跟邻居说，生穗宁那晌午，你在外头烧纸。她说的时候在择菜，没抬头。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":2,"惧":2},"flag":"","thread":""}},{"title":"掀帘进屋","desc":"你不顾母亲拦，掀帘进去，握住杏的手。","hint":"接生婆说血污冲了田气。","tone":"brave","outcome":"接生婆骂了一句，没赶你。杏的手像铁钳，掐得你手背出血。孩子落地时你看见一团紫红，接生婆把她倒提起来，你听见第一声哭。母亲在门外站着，没进来。那年秋天咱家田里生了虫，母亲说是产房的血气冲了田。你没接话。","eff":{"bond":5,"health":-2,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"惧":2},"flag":"","thread":""}},{"title":"去下湾请大夫","desc":"你转身往村口跑，去下湾请大夫，鞋跑掉了一只。","hint":"你回来时门帘已经挂起。","tone":"risk","outcome":"大夫赶到时孩子已经生了，脐带都剪了。他在门外收了手，说：来晚了。你进屋，杏看着你脚上的泥，说：你跑啥，我又不是头一回生。她说完自己笑了，笑到一半停住。后来她再没提过那天。母亲给孩子起名穗宁。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}}]},{"id":"sui_m12","act":"main","age":[40,40],"mode":"narration","title":"他留下的","opening":"父亲是秋后走的。头天他还在院里磨那把豁口镰刀，说：开春把西头那道埂补补。早上母亲叫他吃饭，他没应。你进去，他手搭在炕沿上。柴房里母亲搬开柴垛，露出祖骨罐，说：你爹怕人收走，三年前挪的，第三垄是空的。回屋她倒出竹筒：田契、麻绳、二十六张收条，从你十五岁排到今年；筒底有一小包谷种，每年留一把，一把没动。少，装不满一只竹筒。多，你数到半夜。","ask":"丧事要办，父亲留下的东西，你先动哪样？","days":30,"npc":"","memory":"二十六张收条","choices":[{"title":"卖掉半袋谷","desc":"你把梁上留种的半袋谷背到鱼尾泽卖了，先办丧事。","hint":"开春没有种，你按了手印。","tone":"sell","outcome":"丧事办得体面，棺木是松木的，没裂。开春没有种，你去谷债盟借了半斗，按了手印。母亲问起梁上那只袋，你说吃了。她看着空梁看了很久，说：他要是知道拿种换棺材，得骂人。她没骂你。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"sold_seed_for_funeral","thread":"梁上空了"}},{"title":"押田契办丧事","desc":"你把田契押给谷债盟，换丧事和过冬的粮。","hint":"母亲半年没提赎字。","tone":"deal","outcome":"谷债盟的人把契纸卷走，说三年为期。母亲坐在炕上，看着竹筒里剩下的收条，说：你爹攒了二十六年。你说：人得先埋。她点头，点得很慢。第三年你凑够了去赎，契纸边角已经磨毛。赎回来那天，母亲把它压回炕席底下。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"pawned_land_deed","thread":""}},{"title":"烧在他灵前","desc":"你把田契放进火盆，烧在父亲灵前。","hint":"母亲伸手拦，又缩回去。","tone":"quit","outcome":"火苗舔上契纸，红印先黑，字一个一个卷起来。母亲伸出手，停在半空，又缩回去。她说：也好，他到死都攥着这张纸。谷债盟的人来问契呢，你说烧了。他看了你半天，说：你比你爹狠。那年冬天你们没粮，杏回下湾借了一斗。","eff":{"bond":-2,"health":-2,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":7},"flag":"burned_land_deed","thread":"你比你爹狠"}}]},{"id":"sui_m13","act":"main","age":[46,47],"mode":"dialogue","title":"丰年","opening":"那年的谷子压弯了秆，是二十年来最好的一季。晒场上铺满了，连祖骨罐边都摊了谷。村里杀了一口猪，秋祭的锣敲到半夜。人人都在笑，咱家没人笑。母亲盛了一碗新米饭放在灶头，摆到凉。父亲没等到这样的年成。杏怀着第二胎，闻不得肉味，坐在灶边烧火。也就是那天，穗禾从穗仓城回来——她在米行缝了十几年麻袋，肺缝坏了。她瘦得只剩一把骨头，提着一只樟木箱，站在场边，没人认出来。","ask":"晒场上都是人，她站在场边，你怎么接她？","days":40,"npc":"sibling","memory":"丰年里的咳嗽","choices":[{"title":"接她坐头席","desc":"你拨开人群走过去，接过箱子，让她坐头席。","hint":"杏的脸白了一下。","tone":"warm","outcome":"穗禾坐在头席上，捧着那碗新米饭，没动筷子。村里人问她城里的事，她只说：仓城的米比咱的白。说完低头扒了一口，嚼了很久。杏在灶边忙，没过来，半个月没跟你同桌吃饭。夜里穗禾咳了半宿，杏起来熬了一碗姜汤，放在她门口，没进门。她住了下来。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"杏把姜汤放在门口"}},{"title":"问她住几天","desc":"你接过箱子，低声问她这次住几天，城里还有没有活。","hint":"她把手从箱柄上松开。","tone":"ask","outcome":"穗禾看了你一眼，说：住几天再说。她没坐席，把箱子提到灶房，自己盛了半碗剩饭。母亲拉她，她说路上吃过了。第二天她把箱子打开，里面是给母亲的一双棉鞋、给杏的一块布、给孩子的一把木梳，没有她自己的东西。她把棉鞋放在母亲脚边，住下了。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"","thread":""}},{"title":"先领她去罐前","desc":"你接过箱子，先领她到柴房祖骨罐前，说：回来了。","hint":"席上少了你，杏一个人张罗。","tone":"family","outcome":"穗禾在罐前站了很久，伸手摸那圈绳痕，说：爹，我回来了。她没哭，只把箱子放在罐边，从里头取出一双棉鞋，说是给爹做的，做了三年。鞋底纳得密，你替她烧在罐前。晒场上锣还在响，杏一个人在席上添酒，后来她说那天她像个寡妇。","eff":{"bond":3,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"","thread":"她给爹做了三年棉鞋"}}]},{"id":"sui_m14","act":"main","age":[55,56],"mode":"dialogue","title":"洗骨","opening":"母亲走那年，眼睛已经看不清了。她每天坐在灶边，把同一块布叠了又叠，叠一炷香的工夫。入冬后她不肯上炕，说炕上有人。你问是谁，她说：你爹。腊月里她开始认错人，把杏叫成穗禾，把穗禾叫成自己的娘。只有叫你的名字时是清的。小满八岁，在院里踢毽子，踢到灶房门口，被穗禾撵出去。","ask":"她想摸摸祖骨罐，你怎么应？","days":60,"npc":"mother","memory":"她摸那圈绳痕","choices":[{"title":"抬罐到枕边","desc":"你和穗禾把祖骨罐从柴房抬出来，放在她枕边。","hint":"罐底的土撒了一路。","tone":"family","outcome":"罐子沉，你们抬到门口歇了三回。母亲伸手摸那圈绳痕，摸了一遍又一遍，说：你爹的手。她那天夜里睡得很沉，第二天早上没醒。出殡时罐子又搬回柴房，罐底的土扫起来，撒在了她坟头。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":4},"flag":"","thread":""}},{"title":"摇头说罐不离土","desc":"你摇头，说祖骨罐不能离地，搬了要出事。","hint":"她把手缩回被子里。","tone":"rule","outcome":"母亲没再要，只说：也是。她把手缩回被子里，眼睛看着房梁。话出口，你听见的是你爹的声音。穗禾在门外听见了，进来坐了一夜，没跟你说话。母亲走后，你在她枕头下摸到一小块布，包着三粒谷种——是当年那半袋谷里的。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":""}},{"title":"坐在枕边说从前","desc":"你不搬罐，坐在炕沿上跟她说话，说渠、说谷、说穗禾。","hint":"她听着听着就睡着了。","tone":"stay","outcome":"你从渠口的夜说到半袋谷，说到一半忘了词，她替你说下去。她问穗禾来信没有，你说来了。她说：别骗我。天快亮时她睡着了，手还搭在你手背上。出殡那天你才想起来，她到底没再提罐子。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"","thread":""}}]},{"id":"sui_m15","act":"main","age":[60,60],"mode":"narration","title":"烟大","opening":"六十岁那年秋后，你带小满去空穗台。他十三岁，走路总踢石子。出门前你到柴房看了一眼祖骨罐，绳痕朝里。台上堆着旧穗，风一过，灰打着旋。火光照着台上的骨纹，一道一道，像田埂。你从怀里摸出一叠旧纸：几张谷债盟的旧契，一卷父亲的收条。火点着了，纸边卷起来，红印先黑。小满蹲在旁边问：爹，你哭啥？你说：烟大。","ask":"小满伸手要添纸，这一把怎么烧？","days":10,"npc":"","memory":"空穗台上的灰","choices":[{"title":"念收条给他听","desc":"你展开一张收条，念上面的年份和数，让他跟着念。","hint":"他念到第三张就打哈欠。","tone":"teach","outcome":"小满念了两张就不耐烦，跑去踢石子。你一个人把二十六张念完，念到今年开春那张，声音停了一下。夜里你咳了半宿，杏端水来，没问。第二天小满问你那些纸是谁的，你说：你爷爷的。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"","thread":"他没听完二十六张"}},{"title":"把收条抽回来","desc":"你把父亲的收条从火边抽回来，只烧那些债契。","hint":"小满问你留着做什么。","tone":"keep","outcome":"债契烧成灰，收条你一张张叠好塞回怀里。小满问：这个不烧？你说：这不是债。回到家你把收条放进竹筒，和那截麻绳搁在一处。那年冬天小满翻箱子找见它们，你没解释，他也没问。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"kept_receipts","thread":"收条和麻绳收在一处"}},{"title":"让他点火","desc":"你把火折子递给小满，让他把最后一张契纸点着。","hint":"他的手抖了一下。","tone":"carry","outcome":"小满点着了，火从纸角爬上去，他吓得松手，纸落在台上。你用脚把它拨回火里。他问：爹，烧这个干啥？你说：烧了就不欠了。他点点头，把火折子还给你，手心里全是汗。后来他再没见过那些纸。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"哀":3},"flag":"","thread":""}}]},{"id":"sui_m16","act":"main","age":[76,78],"mode":"narration","title":"像他","opening":"七十六岁以后，你的腿不行了，走到田头要歇两回。穗禾埋在祖骨罐边，已经七年。穗宁嫁到鱼尾泽，一年回来一趟。小满接了你手里的锹，不让你下渠。他说话短，像你，也像你爹。你坐在门槛上看他拍水口，杏耳朵背了，扫谷扫两下歇一歇。日头走得慢。地还是租的。你想起四岁那年，母亲把半袋谷分成两碗。小满直起腰问：西头那道埂还补不补？你说：补。话出口你愣住，这个字跟你爹当年一样。","ask":"小满说想去穗仓城，你怎么答？","days":400,"npc":"","memory":"门槛上的日头","choices":[{"title":"给他豁口镰刀","desc":"你把墙上的豁口镰刀取下来，塞进他的包袱。","hint":"他只带走了镰刀柄。","tone":"leave","outcome":"小满走那天，你送到渠口。他把镰刀背上，走了几步又回来，把刀刃卸下来，只留下木柄，说：这个沉，我拿柄就行。你站在渠口，看他走远。回家你把刃挂回墙上，柄没了，墙上空了一截。夜里你去柴房摸罐子，绳痕上落了一层灰。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"","thread":"墙上空了一截"}},{"title":"让他种完这季","desc":"你把镰刀压在桌上，说种完这季，我不拦你。","hint":"他种完了，也走了。","tone":"keep","outcome":"小满没说话，第二天照常下田。那季谷子他种得比往年都好，秋收后他把谷子装进半袋，扎紧口，放在梁下。走的时候他没带你，也没带那把镰刀。你站在门口，看他过了渠，没回头。夜里你把半袋谷挂回梁上，罐子在柴房里，绳痕朝里。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":7},"flag":"","thread":"半袋谷又挂在梁下"}},{"title":"陪他去穗仓城","desc":"你说我跟你去，我还没见过仓城。","hint":"你走到半路就走不动了。","tone":"seek","outcome":"你们走到鱼尾泽，你的腿肿了，在渡口的草棚下歇了两天。小满说：爹，回吧。你说：再走一天。第三天他一个人上了船，你坐在草棚里看船走远。船工问你等谁，你说：不等谁。回家那截路，你走了三天。到家先去柴房看罐子，绳痕上落了灰，你用袖子擦了擦。","eff":{"bond":4,"health":-4,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":""}}]}],"side":[{"id":"sui_s01","act":"side","age":[6,6],"mode":"narration","title":"拾穗会的木棍","opening":"秋收后第三天，拾穗会在田头插下一根枣木棍，棍上刻着九道刀痕，一道是一年。柳婆把手在围裙上擦了两遍，才把棍递给你：替我攥着。你攥到手掌发红，木刺扎进指腹。棍这边是割剩的落穗，那边是田主家还没收完的谷。远处父亲蹲在田埂上磨那把豁口镰刀，锉刀声一下一下。田主家的儿子从晒场那头过来，靴底踩着谷茬，咯吱响。","ask":"他伸手来拔这根棍，你怎么办？","days":25,"npc":"","memory":"九道痕的木棍","choices":[{"title":"把棍按回土里","desc":"你两只手压住棍顶，把被拔出的半截重新按进泥里。","hint":"他踢了你一脚。","tone":"protect","outcome":"他抬脚踢在你肋上，你倒了，手还攥着棍。柳婆过来，没扶你，先把棍扶正，用脚把土踩实，说：棍是死的，界是活的。晚上她拿烧酒给你揉肋，手劲很重，一句话没说。那半个秋天，田主家的人从你家门口过，都不往院里看。你后来才知道，那天她替你家说了话。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"爱":1},"flag":"","thread":"肋上那块青了半个月"}},{"title":"把穗子倒给她","desc":"你把兜在衣襟里的穗子全倒进柳婆的布袋，一粒没留。","hint":"晚饭时你的碗是空的。","tone":"warm","outcome":"柳婆掂了掂袋子，倒回一半给你。你说不要，她就把那一半分给旁边更小的孩子。回家母亲问捡的穗呢，你说掉了。姐姐拿筷子敲你的碗沿：傻子。夜里柳婆从窗缝塞进来两个烤穗子，皮焦了，瓤还硬。你啃到半夜，把穗子皮吐在手心里，没舍得扔。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"跟他去晒场","desc":"你放下木棍，跟着田主家的儿子去他家晒场捡谷。","hint":"柳婆没回头看你。","tone":"practical","outcome":"他家晒场边确实撒得多，你捡了满满一衣襟。廊下有人看着，没赶你。傍晚你从田头过，木棍还插在那儿，柳婆已经走了。之后半个月，你绕着她走；她照旧在田头分穗，没叫过你。那年的落穗你捡得比谁都多，姐姐夸了你一回。你把最饱的几穗藏在墙洞里，谁也没给。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3},"flag":"","thread":""}}]},{"id":"sui_x01","act":"side","age":[6,6],"mode":"narration","title":"罐子上的鸡","opening":"家里的芦花鸡不见了。娘说那是下蛋的鸡，一天一个蛋，蛋能换盐。你从早上找到晌午，晒场、渠边、柴垛都翻遍了，鞋里灌满了谷壳。日头把后颈晒得发烫，你舔了舔嘴唇，一股土味。最后在村后祖骨罐那儿听见动静。鸡蹲在最大那只罐子的盖子上，爪子扒着罐口的绳痕，你轰它，它歪头看你，不下来。管祖骨的万爷拄着拐过来，仰着脸看了一会儿，说：这鸡认祖宗。话音刚落，鸡在他鞋面上拉了一泡。你憋着笑，不敢笑。远处娘在喊你的名字，一声比一声近。","ask":"鸡蹲在祖骨罐上，你怎么弄它下来？","days":12,"npc":"","memory":"祖骨罐盖上的鸡","choices":[{"title":"爬上罐子去抓","desc":"你踩着石台爬上去，伸手去够鸡腿。","hint":"罐盖裂了一道缝。","tone":"brave","outcome":"你刚够到鸡腿，罐盖在膝盖下响了一声，裂开一道缝。鸡扑棱着飞下去，落在万爷肩上，又被他一把拍开。你从石台上滑下来，膝盖破了皮。万爷蹲下去摸那道缝，摸了很久，说：这罐子比你爹岁数大。他直起腰看了你一眼，没告诉你娘。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"喜":1},"flag":"","thread":"罐盖上裂了一道缝"}},{"title":"撒谷引它下来","desc":"你跑回家抓一把留种的谷，撒在罐子底下。","hint":"梁上的种袋瘪了一块。","tone":"practical","outcome":"鸡看见谷就跳下来了，落地时还扑了一下。你一把按住它，抱着往家走，鸡在你怀里挣，爪子蹬在你胸口。晚上娘数种袋，说怎么少了一把。你说不知道。她看了你一眼，把袋口重新扎紧，扎得比原来高出一截。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"惧":1},"flag":"","thread":""}},{"title":"说这是万爷的鸡","desc":"你跟娘说鸡跑到万爷家去了，不是咱家的。","hint":"那天的蛋没了。","tone":"secret","outcome":"娘信了，说算了，一只鸡。第二天万爷家的孙子抱着一只芦花鸡在村里走，说是他家鸡新下的蛋孵的。你站在门口看，那只鸡的冠子是歪的，跟你家那只一样。娘也看见了，什么也没说，回屋把鸡笼的门重新插好。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"恶":1},"flag":"","thread":""}}]},{"id":"sui_x02","act":"side","age":[8,8],"mode":"narration","title":"青杏","opening":"柳婆家院墙外那棵杏树，枝伸到路上来。杏子还青，咬一口酸得牙倒。你和二柱、三丫约好晌午动手。柳婆耳背，可她家那条黄狗不耳背。你们趴在水沟里等狗睡，沟水凉，泡得手指发白发皱。二柱说数到三十就上，数到十七他自己先爬了。你跟着爬，裤裆挂在墙头的碎瓦上，撕开一道。杏子塞满两个口袋，酸的，吃到腮帮子发麻。杏毛蹭在胳膊上，痒得钻心，你不敢挠。狗叫起来的时候，三丫已经跑没影了。你贴在墙根，听见柳婆在屋里问：谁呀？","ask":"狗叫起来了，你往哪里跑？","days":10,"npc":"","memory":"青杏与破裤裆","choices":[{"title":"捡一兜送去","desc":"你把杏倒出一半，捧到她门前，说摘多了。","hint":"她早知道是你摘的。","tone":"honest","outcome":"柳婆开门，看了看你手里的杏，又看了看你裤裆上的口子，说：青的也摘，糟蹋。她收下了，回屋拿出一小兜晒干的杏干给你。你走到巷口回头看，她正把那捧青杏倒进猪食槽。第二年杏熟，她隔着墙喊你：过来，今儿个熟了。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":""}},{"title":"把狗引进巷子","desc":"你掰半块窝头扔到巷子深处，狗追过去，你再翻墙。","hint":"狗后来没回家。","tone":"sneak","outcome":"狗追着窝头跑进巷子，你在墙上摘了满满一兜。当天夜里听见柳婆在村里喊狗，喊了三天。第四天有人说渠下游躺着一条黄狗，被车碾了。柳婆坐在门槛上，把那半块窝头的事问了二柱和三丫，问到你这儿，你说没看见狗。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"恶":3},"flag":"","thread":"柳婆的狗再没回来"}},{"title":"把二柱推在前面","desc":"狗扑过来时你侧身一让，二柱挡在前头。","hint":"他胳膊上留了疤。","tone":"dodge","outcome":"狗咬住二柱的袖子，他摔在墙根，胳膊划开一道。柳婆出来把狗喝住，看见是二柱，说：又是你。二柱没说是你推的，也没说不是。后来他跟他爹去了仓城，回来那年你已经认不出他。他撸起袖子给人看那道疤，说小时候被狗咬的。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":-1},"emotion":{"惧":3,"恶":2},"flag":"","thread":"二柱替你挨了一口"}}]},{"id":"sui_s10","act":"side","age":[9,9],"mode":"narration","title":"雨里的种摊","opening":"雨下了九天，去鱼尾泽的路泡成了河。爹撑船，你蹲在船头压着那半袋谷，袋口用麻绳扎了三道。水上集市搭在船与船之间，木板一踩就晃，缝里冒水。鱼腥、湿草绳、烂菜叶的味混在一处。卖种的摊子排在最后一条巷，一个外乡人蹲在船板上，手边两只口袋，一袋黄亮，一袋发暗。他抓一把给你看，掌心底下有半把是绿的，带白毛。","ask":"他抓起一把要倒进你家袋里，你怎么办？","days":12,"npc":"","memory":"船巷里的霉种","choices":[{"title":"攥住他的手腕","desc":"你抓住他手腕，把那把霉种举起来，给整条船巷的人看。","hint":"他船里钻出个小孩。","tone":"brave","outcome":"人群围上来，有人掀了他的口袋，绿毛谷撒了一船板。他被推下水，爬起来时嘴角破了，蹲在船尾抱着那个小孩。散集时他的船还在，两只空袋泡在水里。你家没换成种，爹一路没说话，到家把那半袋谷重新吊回梁上。","eff":{"bond":0,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"怒":2,"哀":2},"flag":"","thread":""}},{"title":"用自家谷换霉种","desc":"你把半袋谷倒给他，换下那袋霉种，扛到船尾倒进水里。","hint":"回家时梁上空了。","tone":"warm","outcome":"他愣了愣，接过袋子掂了掂，没说话。你一趟一趟把霉种捧到船尾，倒进浑水，绿毛浮了一层，被雨点打散。回家路上爹问种呢，你说换了。他把篙插进泥里，看了你很久，说：今年种什么。你没答。开春，你家是全村唯一没下种的。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":4,"爱":2},"flag":"traded_seed_for_mold","thread":"你家那年没有下种"}},{"title":"拉娘往鱼摊走","desc":"你拽娘往旁边鱼摊走，说那袋种不好，别买。","hint":"同村的人还在挑。","tone":"dodge","outcome":"娘信你，跟着走了，在鱼摊买了两条小鲫。回村后你听说上村的周三买了那袋种，出苗时一垄一垄地秃。周三蹲在田头拔苗，拔一把扔一把。你从渠边走，他抬头看你，你低下头。那年你家的秧出得齐，你一直记得他拔苗的那双手。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"恶":1},"flag":"","thread":""}}]},{"id":"sui_s02","act":"side","age":[10,10],"mode":"montage","title":"雨帖没应验","opening":"开春，看天的韩老头在晒场墙上贴了雨帖。他写的是三日有雨，宜先浸种。你在田埂上替人念，念到第三行卡住了，只认得日、有雨，就说：明日有雨。第二天下种，全村把种撒进干土。那半袋谷倒出去的时候，母亲的手在袋口停了一下。结果三日无雨，十日无雨，种子在土里发了霉，扒出来一股酸味。韩老头被围在晒场中间，旧褡裢踩在脚底下。","ask":"韩老头被围在晒场中间，你做什么？","days":40,"npc":"","memory":"雨帖没应验那年","choices":[{"title":"站出去认错","desc":"你走到人前，说帖上写的是三日，是你念错了。","hint":"父亲没抬头。","tone":"honest","outcome":"人群静了一下，随后有人说：小孩懂什么。你爹把你拽到身后，手掐得很紧。韩老头看了你一眼，把踩扁的褡裢捡起来，拍了拍土，谁也没看就走了。那年的种没了，村里人照旧骂他。你爹回家的路上没说话，进门才说：往后认不全的字，别念。你记了一辈子。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"confessed_misread","thread":""}},{"title":"撕下雨帖","desc":"你趁人挤，把墙上那张雨帖揭下来塞进怀里。","hint":"韩老头还是走了。","tone":"hide","outcome":"纸上的糨糊没干，粘了你一手。人群找不到帖，就说他根本没收过帖，全是嘴说的。韩老头没辩解，天黑前背着褡裢出了村。你把那张纸塞进村后祖骨罐棚的砖缝里，罐口那圈绳痕磨得发亮。每年返潮你拿出来晾一晾，再塞回去。字一年淡一年，你从没再读完过。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"hid_rain_poster","thread":"雨帖藏在祖骨罐棚的砖缝里"}},{"title":"跟着喊赶他走","desc":"你挤在人堆里，跟着他们喊：赶他走，赶他走。","hint":"你的嗓子哑了三天。","tone":"repeat","outcome":"有人把他的墨盒摔在地上，墨溅了一片，像一摊黑泥。韩老头蹲下去捡碎片，手指被划出血。你喊到嗓子哑，回家喝了半碗凉水。第二天他走了，村里没人送。后来每年开春，晒场墙上没再贴过雨帖，大家看天色下种。你也学会了说：那年雨帖不准。说得跟别人一模一样。","eff":{"bond":0,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":""}}]},{"id":"sui_x03","act":"side","age":[10,10],"mode":"narration","title":"脚边的蒲扇","opening":"苗婆婆是夜里走的。早上她儿媳来敲门，娘去帮忙，把你也带上了。屋里暗，窗纸糊了两层，光进来是黄的。苗婆婆躺在门板上，盖一块蓝布，脚露在外面，穿着新鞋，鞋底干干净净，没沾过土。有人塞给你一把蒲扇，让你在她脚边赶苍蝇。你扇着扇着，看见她的小脚趾是叠着长的，压在旁边那个趾头上。你想问，没问。屋里的人都在说话，说寿衣，说坟地，说该给谁报信。灶间飘出煮面的味。面里放了葱花，香味一阵一阵飘过来，压过了屋里别的味道。你的肚子叫了一声。","ask":"你坐在她脚边扇风，做点什么？","days":10,"npc":"","memory":"蒲扇下的新鞋","choices":[{"title":"一直扇到出殡","desc":"你哪儿也不去，坐在小板凳上，扇到日头偏西。","hint":"手酸了三天。","tone":"stay","outcome":"你扇到日头偏西，又扇到第二天出殡。中间有人来换你，你没让。起灵的时候，她儿媳过来摸了摸你的头，塞给你两个煮鸡蛋。回家路上你剥了一个，另一个揣了半个月，最后碎了，你埋在渠边。那年夏天特别长。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"替她扶正鞋子","desc":"你伸手把那只歪了的鞋摆正，鞋面是凉的。","hint":"大人们都看见了。","tone":"heal","outcome":"你刚把鞋摆正，她儿媳就过来拉住你的手，说不能动，动了路上走不稳。她把鞋又拨回原来的样子，拨得很轻。你退到门边站着。后来出殡，抬棺的人说老太太的鞋掉了两回，第二回是在村口。你听见了，没敢说。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"她的鞋掉了两回"}},{"title":"跑去找她孙子","desc":"你从屋里溜出去，跑到渠边找她孙子。","hint":"他还要接着玩水。","tone":"seek","outcome":"她孙子在渠边拿篾片编蚂蚱，裤腿湿到膝盖。你说你奶奶死了。他说：哦。又编了两下，问：那我今晚跟谁睡？你说不知道。他把编好的蚂蚱塞给你，自己往家走，走到一半跑起来。你捏着那只蚂蚱，篾片还是软的。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":""}}]},{"id":"sui_s03","act":"side","age":[12,12],"mode":"montage","title":"村里办丧事的三天","opening":"守祖骨罐的万爷死在夜里，村里办三天丧事。第一天报丧，第二天守灵，第三天出殡。你被派去添灯油，一夜添三回。堂屋停着门板，万爷躺在上面，脚头一盏灯。他常用的粗碗还摆在灶间，儿媳妇顺手拿去盛了待客的菜。他的狗钻在桌底下，谁踢也不走。你爹把那把豁口镰刀借给丧家削引魂幡的竹竿，还回来时刃上沾着青竹皮。","ask":"出殡前那晚，你打算做什么？","days":10,"npc":"","memory":"万爷的那副碗","choices":[{"title":"收起那只粗碗","desc":"你把万爷的粗碗从灶间收进柜子，不让人再盛菜。","hint":"他儿媳妇找了一下午。","tone":"keep","outcome":"出殡那晚，他儿媳妇打开柜找盆，看见了那只碗。她拿出来，用袖子擦了半天，没放回柜里，倒扣在灶台上。后来那只碗一直倒扣在那儿，裂了也不扔，谁也没再拿它盛过东西。她没问是谁收的。你也没说。多年后你路过那家，灶台上还扣着一只碗，蒙着灰。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}},{"title":"把狗领回家","desc":"散席后你把万爷的狗牵回自家院里，给它半碗粥。","hint":"它夜里叫了一整宿。","tone":"protect","outcome":"狗不吃，趴在门槛上，鼻子朝着万爷家的方向。你蹲在它旁边，蹲到腿麻。第三天它开始吃，吃完就睡在你鞋边。开春它跑回那间空屋，蹲在门口，怎么叫也不走。你每天给它送一次食，送了两年，直到它没再来。你一直没给它起名字。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"跟吹鼓手学调","desc":"出殡那天你跟在吹鼓手后头，把送葬的调子一句句记住。","hint":"你记了三十年。","tone":"learn","outcome":"吹鼓手是个瘦老头，见你跟着，捏着你的喉咙教你换气。你学不像，他也不急，说：记在耳朵里，比记在嘴上强。出殡回来，那支调子在你脑子里响了三天。往后村里每办丧事，你都去听。二十八年后你爹走，你想把那支调子吹给他听，端起唢呐，一个音也出不来。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"","thread":"那支送葬调子你一直吹不响"}}]},{"id":"sui_x04","act":"side","age":[12,12],"mode":"narration","title":"空坛子","opening":"谷债盟的赵五叔家少了一枚腌蛋。不知是谁说的，说是你拿的。晌午晒场上围了二十来人，赵五叔把一只空坛子摆在中间，坛口朝上，像要审它。有人说昨天看见你在墙根下蹲过。你说你在系鞋带。那人说系鞋带蹲那么久？你娘站在人圈外头，没进来。赵五叔说：不搜身，就问问。风把场上的谷壳吹起来，粘在人裤腿上。你听见自己肚子叫了一声，很响，满场都静了一下。你的鞋尖前有一片湿印，是刚才谁踩翻的水盆泼的，正慢慢渗进土里，边缘黑了一圈。","ask":"满场的人等着你说话，你说什么？","days":12,"npc":"","memory":"晒场上的空坛","choices":[{"title":"自己把口袋翻出来","desc":"你把两个口袋都翻出来，抖了抖，空的。","hint":"没人跟你道歉。","tone":"honest","outcome":"两个口袋翻出来，里头只有半块干饼和一根麻绳。赵五叔看了看，说：没拿就好。人就散了，散得很快，有人已经在说别家的闲话。你娘这才走进来，牵着你的手回家。路上她没问，走到门口才说：以后别人家墙根，别蹲。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}},{"title":"跑回家把门闩上","desc":"你一句话不说，转身跑回家，把门闩插死。","hint":"事情传得更难听。","tone":"escape","outcome":"你在屋里坐到天黑，听见门外有人走过两趟，说话声压得很低。第二天娘去井台打水，回来时脸是白的。此后半年，村里丢了什么，都有人往你家门口瞟一眼。那枚腌蛋的事再没人提，也没人说不是你。","eff":{"bond":-1,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":-1},"emotion":{"惧":4,"哀":3},"flag":"","thread":""}},{"title":"说是他儿子拿的","desc":"你抬头说：我看见你家小六从坛子里拿的。","hint":"你说的其实是真的。","tone":"rebel","outcome":"满场静了。赵五叔的小儿子小六站在人堆后头，脸一下红了，转身就跑。赵五叔追上去拎住他，搜出一个布包，里头是两枚腌蛋，一枚吃了，一枚还在。赵五叔回来把坛子抱走了，没看你。人群散了，有人拍你肩膀说你胆子大。你娘在人圈外头，一直没进来。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"怒":3,"喜":2},"flag":"","thread":"赵五叔再没进过你家门"}}]},{"id":"sui_x05","act":"side","age":[13,13],"mode":"narration","title":"渠开了口子","opening":"六月里半夜下暴雨。你是被水声吵醒的，不是雨声，是渠那边，一种闷的、连着响的声音。爹去了仓城送粮，没回来。娘抓起铜盆就往外跑，跑到门口回头看你一眼，什么也没说。你跟着出去。水已经漫过渠埂，从西头一个豁口往外翻，翻到低处的田里，白花花一片。天黑，只看得见水。有人在喊，喊的什么听不清。你脚下踩到一个软东西，是别人跑掉的鞋。雨打在脸上，睁不开眼。水里有股泥腥味，还有麦秸泡烂的酸味。娘的铜盆在远处响，一下，又一下，像在跟谁说话。","ask":"水还在涨，你先去哪一边？","days":10,"npc":"","memory":"雨夜渠里的白水","choices":[{"title":"跳下去堵豁口","desc":"你跳进豁口，用肩膀顶住往下滑的土。","hint":"腿被石头划开。","tone":"brave","outcome":"水把你冲得侧过去，灌了一嘴泥。有人抓住你的后领往上拽，是西头的李三。你们几个人用草袋和土把豁口堵了一半，水从缝里喷出来，喷在脸上生疼。天亮时水退了半尺。你回到家，裤腿上的血已经干了，娘拿剪刀把裤腿剪开，没说话。","eff":{"bond":3,"health":-4,"reputation":2,"coins":0,"stats":{"体魄":2},"emotion":{"惧":4,"爱":2},"flag":"","thread":""}},{"title":"跑去村里敲锣","desc":"你蹚水跑回村，抓起晒场上的锣就敲。","hint":"独木桥断了一块。","tone":"risk","outcome":"你跑过渠上那道独木桥，桥板断了一块，你半条腿掉下去，膝盖磕在桥桩上。锣敲到第三遍，村里的人才全出来。那一夜东垄淹了，西垄保住。第二天有人说锣敲晚了半刻，也有人说要不是那半刻，人都在屋里睡着。","eff":{"bond":2,"health":-3,"reputation":3,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":2},"flag":"","thread":""}},{"title":"回家抢出种袋","desc":"你掉头往家跑，把梁上那半袋种谷抱下来。","hint":"田里的水没人管。","tone":"save","outcome":"你把半袋谷抱到高处，又回去抱祖骨罐，罐子太沉，你只挪动了半尺。等你再出门，水已经漫过田埂，没到膝盖。天亮后西垄的谷子倒了一片，压在水里。娘回来，看见梁上空了，问：谷呢？你说：在炕上。","eff":{"bond":1,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"西垄的谷子倒在水里"}}]},{"id":"sui_x06","act":"side","age":[14,14],"mode":"dialogue","title":"拐子","opening":"开春，爹让你学使牛。那头老黄牛叫拐子，右角断过一截。爹把缰绳交到你手上，说：走沟，别走埂。你没听懂。拐子听懂了，它自己走沟。走到半路它停下，低头吃草，你拉缰绳，它不动。你使劲拽，它退了一步，正好踩进沟里的烂泥，身子一歪。你还没反应过来，它一甩头，你整个人从它背上翻过去，脸朝下摔进泥里，嘴里也是泥。泥是凉的，里面有沙，硌牙，还有一点草根的甜。拐子在旁边喷了个响鼻，像笑。爹在田头蹲着，没过来，肩膀一抖一抖。","ask":"你从泥里抬起头，接下来呢？","days":15,"npc":"father","memory":"拐子的那一甩","choices":[{"title":"爬起来接着赶","desc":"你抹了把脸，抓住缰绳，把牛重新赶上沟。","hint":"晚饭多给你半碗。","tone":"grind","outcome":"你赶了一下午，摔了三回，最后一回是自己跳下来的。天黑收工，拐子自己认得路，走在你前头。爹一路上没说话，到家门口才说：明天还使它。晚饭娘给你盛了满满一碗，碗沿上压了一筷子咸菜。你吃着吃着睡着了，脸埋在碗边。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"爱":2},"flag":"","thread":""}},{"title":"抓把泥抹牛脸","desc":"你抓起一把泥，回手抹在拐子脸上。","hint":"爹把缰绳收回去了。","tone":"rebel","outcome":"泥抹在牛脸上，拐子甩头，泥点子溅了爹一身，从肩膀到下巴。爹站了一会儿，把脸上的泥抹掉，走过来把缰绳从你手里抽走，牵着牛回村了。你跟在后面，隔了十几步。晚饭桌上谁也没提这事。第二天爹自己下田，你被留下劈柴。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"惧":2},"flag":"","thread":"爹再没让你碰过拐子"}},{"title":"坐在泥里不起来","desc":"你坐在泥里，抱着膝盖，不起来。","hint":"爹再没教你使牛。","tone":"quit","outcome":"你坐到日头偏西，泥在裤子上结了壳。娘提着饭篮来找你，看见你这样，笑了，说：多大的人了。她拉你起来，你腿麻，站不住。回家路上她替你拍背上的泥，拍了一路。那以后爹使牛都自己下田，再没叫过你，也没说过为什么。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":-1},"emotion":{"哀":3,"喜":1},"flag":"","thread":""}}]},{"id":"sui_s04","act":"side","age":[15,15],"mode":"narration","title":"嫁到鱼尾泽","opening":"邻家菱儿要嫁到鱼尾泽，聘礼是一垄种田，田契上的名字要换。出嫁前一天，她把嫁妆摊在晒场上晾：一口红漆箱，两床被子，一面铜镜。她坐在箱子上绞脸，脸上扑着粉，嘴唇咬得发红。鱼尾泽来的船停在河口，船头挂一盏没点的灯。她看见你，招手：过来，帮我拎箱子。箱角沉，你一提，底下掉出几粒谷壳。","ask":"跳板搭好了，菱儿站在船头看你，你做什么？","days":15,"npc":"","memory":"菱儿的红箱子","choices":[{"title":"塞一把谷进箱","desc":"你从梁上那半袋谷里抓一把，塞进她箱角的布缝。","hint":"她婆家拆洗时掉了满床。","tone":"warm","outcome":"她没看见，船开了才觉得箱子底下沙沙响。开春她托人捎回话，说拆被子时掉了一床谷壳，婆婆骂了三天，说不吉利。她把谷壳扫起来，没扔，装在一个小布袋里。捎话的人说，她问你好。你想不起她问的是哪一句好。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"她带走了一把谷壳"}},{"title":"把船家的话说给她","desc":"你告诉她，船家说鱼尾泽的媳妇头三年不许回娘家。","hint":"她脸上的粉白了一层。","tone":"honest","outcome":"她听完笑了一下，说你早知道了，是媒婆说的。她又说：不许回就不回，鱼比人好养。船上的人催她坐稳，她把裙子拢了拢。船开出去一丈，她忽然回头喊：我娘要是问，就说我笑了。你点头。后来她娘来问，你说她笑了。她娘哭了一夜。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"","thread":""}},{"title":"接着唱完嫁歌","desc":"她唱了半句就哑了，你接着把下半句唱完。","hint":"满船的人都回头看你。","tone":"brave","outcome":"调子是你听她哼过许多回的，词不全，你把半句翻来覆去。船家敲着船帮跟着哼，船尾的橹声慢下来。菱儿低着头，肩膀抖了几下，再抬起来时脸上又是粉。到鱼尾泽的河口，她踩着跳板下船，没回头。你看见她红鞋底沾了水，一步一个湿印，走到岸上就没了。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":""}}]},{"id":"sui_x07","act":"side","age":[16,16],"mode":"narration","title":"东垄的仓兵","opening":"收割后的东垄，拾穗会的人在捡剩下的穗子。仓兵骑马过来，说没交捡拾钱的不许捡。周婆婆已经捡了半袋，仓兵伸手把袋子夺过去，抖开，谷穗滚在泥里。周围站着七八个人，没人动。日头很毒，谷穗上的芒刺得眼睛疼。周婆婆蹲下去，一粒一粒往手心里捡，手背上的皮贴着骨头。你手里也攥着半袋，袋口是你自己扎的。仓兵的马打了个响鼻，往后退半步，蹄子踩在一穗谷子上。谷粒从蹄缝里挤出来，瘪了。日头把人的影子缩在脚底下，一挪就断。","ask":"仓兵还在看着，你做什么？","days":12,"npc":"","memory":"踩在泥里的谷穗","choices":[{"title":"把自己的半袋倒给她","desc":"你走过去，把袋口解开，倒进周婆婆的空袋里。","hint":"他记下了你的名字。","tone":"warm","outcome":"谷穗落进她的袋子，声音很轻。周婆婆抬头看你，嘴唇动了动。仓兵在马上问：你哪家的？你说了爹的名字。他从怀里摸出个小本，记了一笔，写完把本子合上，说：明天来仓房说话。他骑马走了。周婆婆拉着你的袖子，说：你不该。你说：没事。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"惧":1},"flag":"","thread":"仓兵记下了你的名字"}},{"title":"横在马的跟前","desc":"你走到马前站住，不说话，也不让路。","hint":"肩膀被鞭柄捅了一下。","tone":"defy","outcome":"马往旁边让了半步，仓兵勒住缰绳看你。他用鞭子的柄捅在你肩上，说：让开。你没让。他又捅了一下，这回重，你退了半步。他笑了一声，把袋子扔在地上，骑马走了。周婆婆把袋子抱起来，拍掉泥。你的肩膀青了一块，半个月才消。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":4,"爱":2},"flag":"","thread":""}},{"title":"蹲下和她一起捡","desc":"你不说话，蹲下去，和她一起把谷穗捡回袋里。","hint":"第二天捡拾钱涨了。","tone":"help","outcome":"你们捡到天擦黑，把撒出去的穗子捡回大半。仓兵走的时候看了你们一眼，没说话。第二天仓房贴出告示，捡拾钱涨了两文。有人说是因为昨天的事，也有人说本来就要涨。周婆婆把那半袋谷分了三分之一给你，你不要，她放在你家门槛上就走了。","eff":{"bond":1,"health":-1,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui_x08","act":"side","age":[18,18],"mode":"narration","title":"一百个数","opening":"鱼尾泽赶集那天，二柱说他能在水下待够一百个数。赌注是两斤咸鱼。码头边上蹲了二十来个人。二柱吸一口气下去了，水面上冒了几个泡。有人开始数，数得很慢，故意慢，数一个还拖个尾音。数到六十，水面平了。有人笑，说这小子沉底了。数到八十，你不笑了。水面上只有一圈一圈的波纹。数到九十，水里忽然冒出个头，是二柱，头发贴在脸上，嘴唇发紫，第一句话是：多少了？水从他下巴往下滴，滴在码头的木板上，一滴一个黑印。水是绿的，看不见底。","ask":"他问你数到多少，你怎么说？","days":10,"npc":"","memory":"水下的九十个数","choices":[{"title":"说九十九","desc":"你张嘴就说：九十九，就差一个。","hint":"有人不服，吵起来了。","tone":"warm","outcome":"满场哄起来，有人说数到九十，有人说九十二。二柱不管，抹了把脸，伸手要咸鱼。摊主不肯给，说没到一百。二柱又要下水，被人拉住。最后摊主扔了半斤过来，说算他请的。二柱把鱼分了一半给你，说：你够意思。你们蹲在码头上啃，啃得嘴都麻了。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":5,"爱":2},"flag":"","thread":""}},{"title":"说九十","desc":"你老实说：九十，还差十个。","hint":"他又跳下去了。","tone":"honest","outcome":"二柱愣了一下，骂了一句，又吸一口气下去了。这回数到四十，水面开始乱，他的手在水里抓了两下。你和另一个人跳下去把他拽上来。他趴在码头上吐水，吐完了笑，说：这鱼真他娘的贵。摊主还是给了半斤。他躺了半天，起来的时候腿还在抖。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"惧":2},"flag":"","thread":""}},{"title":"先跳下去拽他","desc":"数到八十五你就脱了鞋，跳下去摸他。","hint":"你俩在水里打了一架。","tone":"brave","outcome":"水底下浑，你摸到他的头发，他反手抓住你的胳膊。你们一起浮上来，他喘着气骂你搅了他的局。上岸后他推了你一把，你也推他。推着推着两个人坐在码头上笑。咸鱼最后没拿到，摊主收摊走了。天黑你们一路走回去，他一路说下回要待一百二。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":4,"惧":2},"flag":"","thread":""}}]},{"id":"sui_s09","act":"side","age":[19,19],"mode":"dialogue","title":"她从城里回来","opening":"穗禾走了两年，秋分那天回来。她穿一件靛蓝褂子，袖口收得窄，脚上是胶底鞋，站在晒场边上不敢下脚，怕踩着摊开的谷。她带回一包桂花糖、一双给娘的胶鞋、一顶给爹的毡帽。爹把帽子翻过来看里子，放回桌上，说城里东西不结实。晚饭她吃得少，筷子在碗沿上磕出响。夜里她跟你挤一铺炕，身上有煤烟和皂角的味，翻来覆去到半夜。","ask":"她说能带你进仓城，你怎么答？","days":20,"npc":"sibling","memory":"她带回的胶底鞋","choices":[{"title":"划自己那垄给她","desc":"你翻出田契，在灯下把名下那半垄指给她，让她折成谷带走。","hint":"爹三个月没跟你说话。","tone":"warm","outcome":"她盯着契纸看了很久，指着边角那块米汤粘过的地方问是谁粘的。第二天她把契拿到河口给船家看，折了八斗谷，没跟你道谢。爹知道后把碗摔在门槛上，三个月没跟你说话。开春插秧，爹从东头插到西头，中间空出一条，谁也没提补上。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":3},"flag":"gave_sister_land","thread":"田契上少了半垄"}},{"title":"把田契锁回柜里","desc":"你把契纸折好锁进柜子，说祖骨埋在这垄，谁也不能动。","hint":"她第二天一早就走。","tone":"rule","outcome":"她起早收拾箱子，没吃早饭。娘追到河口，塞给她半袋谷，她没要，只把毡帽从箱里拿出来，放在门槛上。此后两年她没回来，也没有信。爹有时把帽子拿起来弹灰，弹完挂回墙上，不说给谁留的。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}},{"title":"半夜送她到河口","desc":"你什么也不说，替她拎箱子摸黑走到河口，塞给她半袋谷。","hint":"她在船上没回头。","tone":"escort","outcome":"到河口天没亮，船家蹲在船头啃饼。她把箱子递上去，忽然说：你要想来，仓城东门问筛谷的刘婆。船开出去，橹声一下一下。你抱着空谷袋往回走，走到晒场天亮了，谷上全是露水，你一垄一垄替爹翻了一遍。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui_x09","act":"side","age":[20,20],"mode":"narration","title":"一截炭","opening":"村东的秦婶来找你，说她儿子在穗仓城扛包，半年没信。她不识字，拿来一张揉皱的草纸和一小截炭。她坐在门槛上，说一句，你写一句。她说：娘好，家里的鸡下了蛋。停了一下，又说：不要挂念。你写完，她不放心，让你念一遍。你念到不要挂念，她打断你，说这句删了。你问为什么。她说：他要真不挂念，就不会回来了。窗外有牛铃响，她侧着耳朵听了一会儿，说不是她家的。炭在草纸上留下一道黑，你的手指也黑了。草纸上有两道折痕，是折过又展开的。","ask":"炭还捏在手里，这信怎么落笔？","days":20,"npc":"","memory":"揉皱的草纸和炭","choices":[{"title":"删了那句添一句","desc":"你把那四个字划掉，在末尾添：娘等你回来。","hint":"她按了个手印。","tone":"honest","outcome":"她让你把添的那句念了三遍，念完点点头，在纸角按了个手印，印泥是她自己带来的，用一个小布包着。信寄出去两个月，回信来了，说中秋回来。秦婶拿着信挨家挨户让人念，念到第三家她已经会背了。中秋那天她在村口站到天黑，人回来了。","eff":{"bond":4,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"爱":5,"喜":2},"flag":"","thread":""}},{"title":"留着那句不改","desc":"你说删了不吉利，就这么寄出去。","hint":"她后来问起，你说写了。","tone":"secret","outcome":"她将信将疑，用布包好，让你顺路带到仓城。冬天她来问你，那句删了没有。你说删了。她看着你，看了一会儿，说：那就好。第二年开春她儿子回来一趟，住了三天。走的时候她送到渠口，回来路上跟人说，我儿子信里写着不要挂念。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":"那封信她一直没让人再念"}},{"title":"劝她自己走一趟","desc":"你说路我熟，收了这茬我陪你去仓城。","hint":"这一茬永远收不完。","tone":"expand","outcome":"她算了算日子，说等收了这茬。收完这茬要翻地，翻完地要下种，下完种要放水。秋天你问她走不走，她说等过了年。过了年她说腿不好。那张草纸一直压在灶王爷像底下，边角被烟熏黄了。她有时候拿出来看看，不识字，只是看。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"那封信一直没寄出去"}}]},{"id":"sui_x10","act":"side","age":[21,21],"mode":"dialogue","title":"青背","opening":"腊月里那场雪下了四天。牛棚的顶被压塌了一角，你半夜起来添草，看见青背卧着，眼睛睁着，睫毛上结了霜。你摸它的耳朵，是硬的。你叫它，它没动。爹披着袄出来，站在门口看了一眼，说：别动了，天亮了再说，人先回屋。天亮后来了五六个人，帮着把牛拖到村口。牛太沉，绳子勒进肉里，拖过的雪地上留了一道黄印子，很长。有人问要不要分肉。爹蹲在牛头边上，摸着那截断角，没说话。牛棚里还剩半捆草，是昨晚添的，没吃完。牛棚的草是湿的，踩上去不出声。","ask":"人都在等爹开口，你先说了什么？","days":15,"npc":"father","memory":"雪地上的黄印","choices":[{"title":"说分了吧","desc":"你说：分了吧，别糟蹋，各家都有孩子。","hint":"爹一口没吃。","tone":"practical","outcome":"肉按户分了，你家留了半扇。爹那天没上桌，坐在牛棚里，把塌下来的那角顶子重新支起来。晚上娘把肉炖了，端一碗进去，他接过去，放在脚边，凉了也没动。第二天早上碗是空的，不知道是狗舔了还是他吃了。","eff":{"bond":-1,"health":1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":1},"flag":"","thread":""}},{"title":"说埋了","desc":"你说：不分开，整头埋了。","hint":"冻土挖了半天。","tone":"carry","outcome":"你和李三在东头地里挖坑，冻土硬，一锹下去一个白印。挖到中午才够深。把牛推下去的时候，它的腿还是直的。埋完你在土堆上插了根木棍。第二年那块地的谷子长得比谁家都高，爹路过时总要多看两眼，什么也不说。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"东头地里埋着一头牛"}},{"title":"说剥皮做双靴","desc":"你说：皮留着，给爹做双靴。","hint":"他一次没穿过。","tone":"keep","outcome":"皮晾在墙上，绷得紧紧的，刮油的时候你吐了两回。靴子做出来，硬，穿上去磨脚。爹试了一下，脱下来放在床底下。此后每年入冬娘都拿出来晒一晒，晒完放回去。爹到死没穿过那双靴，也没说不要。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"床底下那双硬靴"}}]},{"id":"sui_x11","act":"side","age":[23,23],"mode":"narration","title":"走错的门","opening":"娘让你去给刘媒婆送礼。一只风干的鸡，两包红糖，用红纸包着。她嘱咐：进门先说好话，别站着，坐矮凳。你走到村中，看见一户门口挂着红布，就进去了。屋里坐着七八个人，桌上摊着瓜子。你把鸡放在桌上，说：刘婶，我娘让我来的。满屋人都看你。一个老太太说：刘婶在西头。这是赵家，今天下定。你退出来的时候，红纸包散了一个，红糖撒在人家门槛上。身后有人在笑。那只鸡在你手里挣了一下，爪子刮过你的手背。巷子里有人在剁猪草，一下一下。","ask":"鸡还在人家桌上，你怎么办？","days":12,"npc":"","memory":"门槛上的红糖","choices":[{"title":"折回去扫糖赔不是","desc":"你回身进屋，蹲下把门槛上的糖扫干净。","hint":"这门亲事后来黄了。","tone":"honest","outcome":"你借了笤帚，把红糖扫成一堆，捧在手心倒进人家灶间的罐子里。赵家老太太留你吃了碗面，说你这孩子实诚。那门亲事第二年黄了，赵家媳妇跟人说是下定那天门槛上撒了糖，不吉利。话传到你家，娘气得两天没跟你说话。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":2,"哀":2},"flag":"","thread":"赵家把亲事黄了赖在你身上"}},{"title":"顺嘴说是来道喜","desc":"你改口说：我娘让我来道喜，鸡是贺礼。","hint":"瓜子塞了一兜。","tone":"dodge","outcome":"赵家老爷子高兴，拉你坐下，抓了一把瓜子塞进你兜里。有人问你是哪家的，你说了。坐了一刻钟，你起身告辞，走到巷口才想起来鸡还在桌上。你回头看了一眼，门已经关上了。那只鸡后来怎么处理的，你不知道。刘媒婆那边等到天黑。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}},{"title":"拎起鸡就跑","desc":"你冲进去抓起鸡，转身就跑。","hint":"鸡沾了土，糖没了。","tone":"escape","outcome":"满屋人愣住，你已经跑到巷口。鸡在半路掉了一次，沾了一层土，你拍了两下没拍干净。刘媒婆家等到天黑，第二天来问你娘。娘赔了半包糖，回来问你鸡呢。你说送了。晚饭桌上有一盘鸡，你一口没吃。","eff":{"bond":-2,"health":-1,"reputation":-2,"coins":0,"stats":{"机缘":-1},"emotion":{"惧":3,"喜":2},"flag":"","thread":""}}]},{"id":"sui_s05","act":"side","age":[24,24],"mode":"narration","title":"村口的账房","opening":"秋分前，村口看场屋住进一个外乡账房，姓陈，背着麻绳和木匣。白天他量地，晚上点一盏豆油灯。你替他挑水，他给你一把炒黄豆。第七天他让你攥住绳头，从东垄走到西垄，麻绳勒进手心。走到第三垄，他翻你家田契，指腹在边角那块米汤粘过的地方蹭了蹭，问：谁粘的？你说：我娘。他嗯一声，把契纸照原样折好。有一晚下雨，你们并排坐在门槛上，他把伞往你这边偏了偏，谁也没说话。","ask":"他天亮就走，小鞋忘在窗台上，你怎么办？","days":20,"npc":"","memory":"窗台上的小鞋","choices":[{"title":"追到渡口还鞋","desc":"你抓起小鞋，沿河追了二里地，把鞋塞进他包袱。","hint":"他走得比来时快。","tone":"escort","outcome":"他没回头，只把包袱往肩上提了提。你看见他抬手在脸上抹了一下，像赶蚊子。船离岸时，他把那只鞋摆在船头的木板上，摆得很正。后来你才想起，他从没说过家里有孩子。你也没问。那年秋后，你晚饭后总去村口站一会儿，站到看场屋塌了半边。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把鞋收进箱底","desc":"你用布把鞋包好，压在自己箱底，谁也没告诉。","hint":"你自己的孩子穿不进去。","tone":"keep","outcome":"第二年你娶亲，箱子抬进新房，鞋还在底下。你媳妇翻出来问是谁的，你说路上捡的。她看了你一眼，没再问。后来孩子出生，脚长得快，你几次想把鞋拿出来比一比，手伸到箱底又停住。鞋压了二十多年，皮子硬得像块瓦，鞋尖上还留着他缝的线。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"kept_accountant_shoe","thread":"箱底压着一只小鞋"}},{"title":"交给仓兵挂树上","desc":"你把鞋交给仓兵，说是看场屋里捡的，让他挂在村口。","hint":"没人来认。","tone":"rule","outcome":"仓兵在本子上记了一笔，用麻绳把鞋挂在村口槐树上，说有人认就领走。鞋挂了两个月，先落灰，后发黑，最后只剩一根鞋带。过路的人问是谁的，你说不知道。第二年修枝，鞋带也剪掉了。看场屋后来住过两茬人，你都没去挑过水。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"reported_shoe","thread":""}}]},{"id":"sui_x12","act":"side","age":[25,25],"mode":"narration","title":"井底","opening":"旱到第三个月，渠底裂成一块一块，缝里能塞进一只手。村里决定在晒场东边打井。挖到两丈，土是干的；挖到三丈，绳子断了，筐掉下去，闷响一声。有人说下面有石头，有人说下面有东西，不肯再下。日头把井口的土晒得发白。你腰上系绳，往下一看，井底黑，什么也看不见。拉住绳子的人说：后生，想清楚。井口围了一圈人，都不说话。有人递过来一碗水，你喝了半碗，剩下半碗倒在井沿上，渗下去，没了。井绳是麻的，手心磨出的泡已经破了，粘在绳上。","ask":"绳子系在腰上，你下不下井？","days":20,"npc":"","memory":"井底的湿土味","choices":[{"title":"自己下去","desc":"你抓住绳子，蹬着井壁往下落。","hint":"手抖了一个时辰。","tone":"brave","outcome":"井底比上面凉，土是湿的，攥一把能捏成团。你喊了一声，上面听不清。你用手指在壁上抠，抠出一小股水，先是浑的，后来清了。上来的时候绳子磨破了腰。第一碗水端给了井边最老的周婆婆，她喝了一口，说甜。有人笑她，说井水哪有甜的。","eff":{"bond":3,"health":-3,"reputation":3,"coins":0,"stats":{"体魄":2},"emotion":{"惧":4,"喜":3},"flag":"","thread":""}},{"title":"再挖一丈我出工钱","desc":"你把家里半袋谷折了工钱，请人再挖一丈。","hint":"你家断了两天粮。","tone":"expand","outcome":"半袋谷换了六个工。又挖了一丈，土还是干的。第七天早上，井底渗出水来，慢，一晚上积了半尺。你家那两天吃的是野菜糊糊，娘没说一句。井打好后，村里按户分水，你家排第七。有人提过那半袋谷，爹摆手，说别提。","eff":{"bond":2,"health":-2,"reputation":2,"coins":-60,"stats":{"机缘":1},"emotion":{"喜":4,"惧":2},"flag":"","thread":"分水你家排第七"}},{"title":"去仓城求穗官司","desc":"你说这井不能私打，得报上去。","hint":"回来时井已经填了。","tone":"report","outcome":"你走了半天到仓城，在衙门外跪到日头偏西，递了呈子。官差说打井要先看地脉，回去等。你走回来是第三天，井已经被填了，填得平平的。村里人说等不起。那年秋天，村东头一户人家自己在院里挖出了水，没人报。","eff":{"bond":-2,"health":-2,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":4},"flag":"","thread":""}}]},{"id":"sui_s11","act":"side","age":[28,28],"mode":"narration","title":"住半月的房客","opening":"谷雨前，村里来了个外乡女人，三十来岁，说做半个月针线活，租你家西屋。她给的谷铢压手，说话轻，吃饭前先洗手，水泼在院里墙角。白天她不出门，晚上出去，回来时鞋底带泥。第五天夜里你起来添料，看见她蹲在村东老周家的田埂上，从怀里摸出一只白瓷瓶，瓶口贴着地。第二天那一片谷叶就卷了，你摸土，土是凉的。你手里还攥着爹那把豁口镰刀，刃上沾了湿泥，缺口里嵌着一线草屑。","ask":"她把瓷瓶收进袖子，你怎么办？","days":20,"npc":"","memory":"她夜里的白瓷瓶","choices":[{"title":"把自家那垄指给她","desc":"第二天你告诉她，村东地薄，要取就取你家南头那半垄。","hint":"她看了你很久。","tone":"carry","outcome":"她没答应，也没拒绝。当夜她去了南头，蹲在你家田里，白瓷瓶贴地，蹲了半个时辰。走时她把瓶塞好，说：你家的地力本来就不厚。半月后她走了，西屋炕席扫得干净，枕下压着几枚谷铢。第二年南头那半垄出苗稀，爹蹲在地头捏土，捏碎了吹掉，说这地老了。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"let_tenant_take_own_field","thread":"南头那半垄地力薄了"}},{"title":"去晒场敲铜锣","desc":"你摸黑跑到晒场，敲响那面铜锣，把半村人喊到田头。","hint":"她的鞋跑丢了一只。","tone":"report","outcome":"人举着火把围住西屋，从她箱底翻出三只瓷瓶，瓶里是浑水，晃一晃有白丝。天亮仓兵来把人带走，她赤着一只脚走在泥路上，回头看了你一眼。村里把西屋的炕拆了，说晦气。你娘把那几枚谷铢扔进灶膛，火苗绿了一下。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"恶":2},"flag":"reported_field_drainer","thread":""}},{"title":"照旧给她端水","desc":"你什么也不说，第二天照旧给她端洗脸水，看她收拾针线。","hint":"她多住了三天。","tone":"ignore","outcome":"她多住三天，每晚照旧出去，你每晚照旧给她留门。走那天她把一件补好的褂子叠在炕上，袖口针脚很密。半月后村东三家的谷子黄了一片，老周蹲在地头骂天。你站在渠边摸自己那件褂子的袖口，针脚扎得手心发痒。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"恶":2},"flag":"","thread":""}}]},{"id":"sui_x13","act":"side","age":[28,28],"mode":"narration","title":"左眉上有道疤","opening":"鱼尾泽的船工老周盯着你看了半天，说你像一个人。他说二十年前有个走村卖针线的货郎，姓什么忘了，也是这个眉眼，左眉上有一道疤。你左眉上没有疤。他说有，你撩起来给他看，说没有。他说：那是还没长出来。这话传开以后，集市上总有人多看你两眼。卖豆腐的多给你切一角，卖草鞋的说你先拿去穿，回头给钱。你走在路上，觉得脚下轻了，回家时兜里多了两个柿子。柿子软了，把兜布染红一块。他把手指在裤子上擦了擦，才指你的脸。柿子软的时候，皮上有一层白霜，沾在指头上。","ask":"有人又问起那道疤，你怎么应？","days":25,"npc":"","memory":"左眉上那道疤","choices":[{"title":"认下来白吃一集","desc":"你说对，我就是那货郎的儿子，笑一笑。","hint":"债主找上门了。","tone":"greed","outcome":"那一集你吃了三家的东西，一分钱没花。散集那天，一个瘦高个拦住你，说那货郎欠他三吊钱，二十年了，连本带利。你说我不是。他说你眉眼就是。围观的人越来越多，最后是娘赶来，掏出两吊钱把人打发走的。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":-40,"stats":{"魅力":1},"emotion":{"喜":4,"惧":2},"flag":"","thread":"那三吊钱娘一直没提"}},{"title":"见人就说不是","desc":"你撩起眉毛给人看，一遍一遍说没有疤。","hint":"豆腐不再多切。","tone":"honest","outcome":"你说得多了，人家就笑，说你这人没趣。卖豆腐的不再多切，卖草鞋的也不再赊。有一回你在渡口又碰见老周，他眯着眼看你，说：疤不疤的，像就是像。你想再争，船开了。你站在岸上，觉得这事说不清，也就不说了。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":2},"flag":"","thread":""}},{"title":"问货郎后来去哪","desc":"你提了两条鱼去找老周，问他那人往哪走了。","hint":"娘的箱底有个针线包。","tone":"seek","outcome":"老周说往北走了，过了河就没回来，那年冬天河上冻得早。你回家随口问你娘，认不认得一个卖针线的。她正在纳鞋底，针顿了一下，说：不认得。过了几天你翻箱找东西，看见箱底有个蓝布针线包，针是新的，一根没用过。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":3},"flag":"","thread":"箱底那个没开封的针线包"}}]},{"id":"sui_x14","act":"side","age":[31,31],"mode":"narration","title":"乱坟岗","opening":"从鱼尾泽回来晚了，月亮被云盖着。你挑着两捆麻，走渠边那条小路。走到乱坟岗，前面的路上有两个绿点，低，不动。你停下，它也停。老人说过，见了狼别跑，要把手里的东西举高。你把扁担举起来，麻捆滑下去一半。那两点动了一下，往前挪了三步。你听见自己的心跳，也听见身后有喘气声。你慢慢回头，后面还有一个，更近，蹲在坟包上。风里有股膻味。你手里的麻绳勒着掌心，汗把绳子浸软了。云层压得低，渠水黑得像一层壳。你把扁担从肩上取下来，手心里的汗是凉的。","ask":"前后都有狼，你往哪边走？","days":10,"npc":"","memory":"坟岗上的绿点","choices":[{"title":"点火烧麻冲过去","desc":"你摸出火石，点着一捆麻，举着往前冲。","hint":"手抖了一个时辰。","tone":"brave","outcome":"麻烧得快，火苗蹿到眉毛高。前面的狼退进坟堆，后面的也退了。你举着火一路跑，跑到渠口火才灭，麻烧掉半捆。进村的时候你腿是软的，靠着门框站了半天。第二天你回去找另一捆麻，麻还在，上面有几道牙印。","eff":{"bond":0,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":5,"喜":2},"flag":"","thread":""}},{"title":"退到坟后蹲到天亮","desc":"你退到一座坟包背后，蹲下，把扁担横在膝上。","hint":"腿麻得站不起来。","tone":"wait","outcome":"你蹲到鸡叫，腿麻得像别人的。天亮了你才看清，坟岗边有一摊吃剩的羊骨头，骨头上的肉还没啃净，是隔壁村丢的那只。你挑着麻往回走，走几步回一次头。到家娘问你脸怎么这么白，你说夜里凉。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":1},"flag":"","thread":""}},{"title":"扔下麻转身跑","desc":"你把两捆麻朝后一扔，撒腿往渠边跑。","hint":"麻没了，鞋也丢了一只。","tone":"escape","outcome":"你跳进渠里，水到腰，冰得人发麻。你在水里站了很久，直到听见村里第一声鸡叫。天亮回去，麻没了，绳子还在路上，断口是咬的。你光着一只脚走回家，路上捡了只别人扔的破鞋，不合脚，走一步掉一次。","eff":{"bond":0,"health":-2,"reputation":0,"coins":-20,"stats":{"机缘":-1},"emotion":{"惧":5,"哀":2},"flag":"","thread":""}}]},{"id":"sui_s06","act":"side","age":[34,34],"mode":"narration","title":"一碗热汤","opening":"腊月十六，雪压塌了村东的草垛。你从鱼尾泽回来，半路天黑了，草鞋冻成两块。柳婆家的灯还亮着。她开门看你一眼，侧身说：灶上有汤。锅里是野菜糊糊，飘着几星油花。她给你盛一碗，自己坐回灶前补麻袋，袋底还剩半袋谷。阿绵趴在桌边问你小时候冷不冷。你说起四岁那年娘分半袋谷，七升留种，两升换盐；说到娘攥了攥最后一把谷，你停住了。阿绵问后来呢，你说忘了。","ask":"碗见了底，柳婆又去刮锅，你做什么？","days":10,"npc":"","memory":"灶上的那碗汤","choices":[{"title":"把碗底拨给阿绵","desc":"你用筷子把碗底那几粒米拨进阿绵碗里，说太烫。","hint":"柳婆看见了，没说话。","tone":"warm","outcome":"阿绵先看她奶奶，柳婆点了一下头，她才低头吃。柳婆起身去添柴，背对着你说：她爹娘在鱼尾泽帮工，半年没回来。你没接话。走时你把随身的半袋谷倒在灶边缸里，只留一把路上嚼。雪停了你才发觉，柳婆塞在你怀里的是双旧棉袜，袜底补过三层。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"那双补了三层的棉袜"}},{"title":"说汤糊了去劈柴","desc":"你放下碗说汤有糊味，起身去院里把湿柴劈了。","hint":"她重新尝了一口。","tone":"repair","outcome":"柳婆尝了尝，说没糊。你还是把院里那堆湿柴劈了，码到屋檐下。劈到半夜，手指头冻得握不住斧子。柳婆给你换了盏亮些的灯，阿绵趴在桌边睡着了，嘴角挂着一点糊糊。第二天你走，她把汤又热了一遍，非看着你喝完。那碗比昨晚稠，碗底沉着几粒米。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"喝完就上路","desc":"你把碗一推，说家里等着，披上袄走进雪里。","hint":"身后的门没关。","tone":"leave","outcome":"柳婆追到门口，往你怀里塞了半块糠饼。你没回头，怕一回头就走不成。走到渠边，你听见身后门闩响了一下，很轻。回到家，母亲问路上吃了吗，你说吃了。那晚的饭你吃了两碗。第二年开春，柳婆的腿就下不了炕了。你去看她，她说不记得你来过。","eff":{"bond":0,"health":1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":5},"flag":"","thread":""}}]},{"id":"sui_x15","act":"side","age":[34,34],"mode":"narration","title":"柴房里的三花","opening":"秋收后，柴房里有了动静。你搬开柴垛，看见一只三花猫，瘦得肋骨一根一根，肚子底下护着三只没睁眼的小猫。它没跑，只是把身子压得更低，喉咙里响了一声，不是呼噜，是警告。你把手收回来，蹲在那儿看了很久。屋外晒着新谷，鸡在啄边上的碎粒。娘在灶间喊你吃饭，喊了两遍。你应了一声，没动。柴房里有股奶腥味，混着柴灰。灰落在小猫背上，母猫舔一口，灰就没了。它的一只眼睛有块白斑，另一只盯着你的手。屋里谷子晒得烫，你额头上的汗流到下巴。","ask":"它一直盯着你，你怎么办？","days":40,"npc":"","memory":"柴房的奶腥味","choices":[{"title":"每天留半碗饭","desc":"你把饭拨半碗放在柴房门口，走远些看它吃。","hint":"冬天它睡在灶膛边。","tone":"heal","outcome":"头三天它等你走了才吃。第四天你蹲在门口，它吃了，一边吃一边看你。入冬它自己搬进了灶膛边，三只小猫跟在后头。开春有天早上，门槛上放着一只野兔，脖子咬断了。娘说是猫叼的，说这东西记恩。你把它拎起来，还是温的。","eff":{"bond":2,"health":1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":5,"喜":2},"flag":"","thread":""}},{"title":"连窝端到村外草垛","desc":"你用簸箕把小猫连窝端起来，送到村外的草垛里。","hint":"它当晚就回来了。","tone":"distance","outcome":"你端着簸箕走到村外，猫跟在后头，一路叫。你把小猫塞进草垛深处，往回走，它绕着你转。第二天早上，牛棚里有猫叫。它把三只小猫一只一只叼回来了，路上掉了一只，你又去捡。它蹲在牛棚梁上看着你，眼睛在暗处发绿。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"把小猫送人","desc":"你留下母猫，三只小猫分别送了人。","hint":"它叫了三天。","tone":"practical","outcome":"三只小猫用篮子装着，分给了三家。第二天有一家送回来一只，说孩子过敏。你又转送给别人。母猫在村里转了三天，挨家挨户门口叫，最后不叫了。它还是住在柴房，还是吃你留的饭，只是不再蹭你的裤腿。那年冬天它没进灶间。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}}]},{"id":"sui_x16","act":"side","age":[38,38],"mode":"narration","title":"板车","opening":"西头李家的老太太瘫了半年。这天早上，来了一辆板车，车上铺着干草。她儿子李三把她抱上车，说去仓城看大夫。老太太不说话，手抓着门框，指甲抠进木头里。李三一根一根把她的手指掰开，掰得很慢。车走的时候，全村都站在门口看，没人说话。你手里端着一碗刚熬的粥，本来是要给她家的。她的小孙子跟在车后走了十几步，被他娘拉住了。车轮压在冻土上，一路响。板车的木头是湿的，压过的地方留下两道深印。霜化了一半，路边的草湿着。","ask":"板车还没走远，你做什么？","days":15,"npc":"","memory":"抠进木头的指甲","choices":[{"title":"把粥端到她嘴边","desc":"你追上去，把碗凑到她嘴边，让她喝两口。","hint":"李三回头看了你一眼。","tone":"heal","outcome":"她喝了两口，粥从嘴角流下来，你用手背替她擦了。李三说：够了。车又走了。那碗剩下的粥你端回家，凉了，结了皮。三天后李三回来，一个人，眼睛是肿的。他路过你家门口站了一下，没进来，也没说话。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"爱":3},"flag":"","thread":""}},{"title":"说一句仓城大夫好","desc":"你站在原地，大声说：仓城的大夫好，能治好。","hint":"她松开了手。","tone":"peace","outcome":"老太太听见了，转过头来看你，手从门框上松开了。李三把她往里挪了挪，盖上被子。车走了。此后村里没人再提这事。李三过年时来借过一次簸箕，还的时候在门口放了一把干枣，一句话没说。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"拦住车问她去哪","desc":"你走到车头前面站住，问李三：到底去哪？","hint":"有人把你拉开了。","tone":"ask","outcome":"李三不说话，绕开你推车。你还要问，被旁边的两个男人拉开，一个人说：人家家里的事。车走了。你站在路中间，看着草垛上的被子一起一伏。李三回来那天，你在地里，隔着半里地看见他一个人走，走得很慢。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":2},"flag":"","thread":"你一直不知道她去了哪"}}]},{"id":"sui_x17","act":"side","age":[42,42],"mode":"narration","title":"三尺","opening":"你家和李家地界上那三尺，从你爷爷那辈就争。今年李家在地界上栽了一排桑。爹当年说过那是渠埂，不能栽树，根会把埂拱塌。你去找李三说，李三说：地契上写着，从我家界石到渠心。你说界石早没了。他说：那就重新量。谷债盟的人来了，拿一根麻绳，量了一上午，日头把人晒得蔫。最后他说：三尺，各让一尺半。你问那一尺半在哪。他收起绳子说：量不出来，你们自己商量。桑苗栽得齐，一棵一棵，叶子还没长开。桑叶上落了一层灰，风一过就翻白。","ask":"绳子收起来了，这地界怎么算？","days":60,"npc":"","memory":"地界上一根麻绳","choices":[{"title":"让他三尺","desc":"你说：这三尺给你们，桑树别栽到渠边就行。","hint":"桑树遮了你家半垄。","tone":"peace","outcome":"李三愣了一下，说：你这话当真？你说当真。第二年桑树长起来，长得快，枝伸过来，遮了你家靠渠那半垄的日头。谷子比别处矮一截。李三秋天送了一筐桑葚过来，娘收了，洗了半盆，吃不完，剩下的晒成干。两家再没为这三尺说过话。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"靠渠那半垄矮一截"}},{"title":"夜里去拔桑苗","desc":"天黑透了，你提着一把锄头，把新栽的桑苗全起了。","hint":"李家在门口骂了三天。","tone":"sneak","outcome":"一共十七棵，你起得干净，根上的土抖回沟里。第二天李家在门口骂了三天，骂得嗓子哑。娘提着一篮鸡蛋去赔不是，回来说李三媳妇把鸡蛋摔在门外。桑苗后来补栽了，栽得离渠远了些。两家从此不走动。","eff":{"bond":-3,"health":-1,"reputation":-2,"coins":0,"stats":{"机缘":-1},"emotion":{"怒":4,"惧":2},"flag":"","thread":"两家从此不走动"}},{"title":"去穗官司递状子","desc":"你写了状子，走了半天路，递到穗官司。","hint":"等了两年。","tone":"rule","outcome":"状子递上去，收了，说排队。你每隔三个月去问一次，问了三回。第二年秋天官差来了一趟，拿尺量了半天，说：等明年开春再定。第三年开春你家添了孙子，你忙得没去问。那三尺地上，桑树已经能遮人了。","eff":{"bond":-1,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":""}}]},{"id":"sui_x18","act":"side","age":[45,45],"mode":"narration","title":"借米","opening":"王家嫁女儿，全村去吃席。晒场上摆了十二张桌，桌子是各家搬来的，高低不齐，桌腿底下垫着瓦片。你被派去端菜，一天走了三十几趟，鞋底磨薄了一层。新娘子出来敬酒，走到你这桌，有人起哄让你说句吉利话。你说早生贵子，有人说太俗。你说多子多福，有人说更俗。你把酒碗端起来，说：那我再说一句不俗的——明年这时候，别抱着孩子上我家借米。满场静了半息，然后笑翻了，新娘子也笑，酒洒了一身。酒是自家酿的米酒，洒在红袄上，洇出一块深色。桌上摆的是八大碗，最中间那碗扣肉还冒着热气。","ask":"满场等着，这碗酒你喝不喝？","days":12,"npc":"","memory":"十二张高低桌","choices":[{"title":"再喝一碗闹到半夜","desc":"你仰头干了，跟着人起哄，一直闹到半夜。","hint":"第二天鞋少了一只。","tone":"defy","outcome":"你喝到舌头打结，被人抬到草垛上睡。半夜醒来找水喝，摸黑走错了两回门。第二天早上醒在自家炕上，鞋少了一只，另一只鞋里塞着一把喜糖。娘问你怎么回来的，你说不知道。那只鞋过了半个月才在王家柴房里找着。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"喜":6,"爱":1},"flag":"","thread":""}},{"title":"帮着收拾到最后","desc":"你放下碗，去灶间帮着洗碗、撤桌。","hint":"王家婶子记住了你。","tone":"help","outcome":"碗堆成两摞，油水在盆里浮着。你洗到月亮偏西，最后一趟撤桌的时候，新娘子过来给你递了块手巾。王家婶子塞给你一包喜糖，说你是好人。回家路上娘说：人家办喜事，你倒像来帮工的。你说：反正也没事。","eff":{"bond":2,"health":-1,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"爱":3},"flag":"","thread":""}},{"title":"早走回家","desc":"你把碗放下，跟主家打了个招呼，先走了。","hint":"那晚的菜你说不上来。","tone":"leave","outcome":"你走到半路，身后的笑浪一阵一阵传过来。到家娘问你席上有什么菜，你想了想，说忘了。她说不吃肉？你说吃了。灶间还有半锅早上的粥，你盛了一碗，就着咸菜吃了。第二天听说那晚有人喝多了掉进渠里，你不在，没能帮上。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"喜":1,"哀":3},"flag":"","thread":""}}]},{"id":"sui_s12","act":"side","age":[46,46],"mode":"narration","title":"替他守一夜","opening":"阿庚欠了青苗债，仓兵说天亮来抬东西。他连夜去穗仓城求人，临走把钥匙塞给你，说：替我看一夜，别让他们碰我娘的罐。堂屋门槛上点一盏灯，灯芯剪得短，火苗只有豆大。祖骨罐在供桌底下，罐口一圈绳痕，深得能卡住指甲。后半夜起雨，雨点打在瓦上，像有人在上头撒豆子。你听见巷口有铁器碰铁器的声音。","ask":"铁器声到了门口，你怎么办？","days":10,"npc":"","memory":"门槛上的一盏灯","choices":[{"title":"横门闩挡在门口","desc":"你横上门闩，搬条凳坐在门后，手里攥着爹那把豁口镰刀。","hint":"门上被写了你家的姓。","tone":"brave","outcome":"仓兵撞了两下门，门板裂开一道缝，缝里伸进一根铁钩。你用镰刀背敲在那只手上，外面骂了一声。他们没再撞，只在门上用炭写了个字。天亮阿庚回来，看见那字，蹲下去用手指抠，抠不掉。那年秋征，你家多派了两斗。","eff":{"bond":3,"health":-1,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"爱":2},"flag":"","thread":"门板上留着一个炭字"}},{"title":"抽开门闩让开","desc":"你把门闩抽了，退到墙边，说欠债还物，按规矩来。","hint":"阿庚回来没进你家门。","tone":"rule","outcome":"他们进来四个人，两个抬罐，两个翻箱。罐出门时在门槛上磕掉一块陶，你伸手想扶，被挡开。阿庚回来在空了的供桌前坐了一夜，第二天见你，绕到渠那边走。后来他家门槛上再没点过灯。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"let_guards_take_urn","thread":""}},{"title":"抱罐藏进祖骨棚","desc":"你抱起罐冒雨挪进村后自家祖骨棚，塞在最里头那格。","hint":"棚里多一口，账上少一口。","tone":"sneak","outcome":"天亮仓兵来，抬走一口空箱和两床被。阿庚回来，你把钥匙还他，说罐在村后。他去抱回来时，罐底蹭了一身泥，绳痕里嵌着新土。这事后来还是被查出来，罚你家补交两斗谷。你爹的牌位前，你多烧了一回纸。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":2},"flag":"hid_neighbor_urn","thread":""}}]},{"id":"sui_x19","act":"side","age":[50,50],"mode":"narration","title":"保人","opening":"邻村一桩亲事，男方要个保人。不知怎么找到你，说你说话算数。你不认得那家人。中人领你去了，屋里坐满了，男方父亲递烟，女方母亲倒茶。两个年轻人站在门边，隔着一臂远，谁也不看谁。窗纸是新糊的，浆糊还没干透，有一股面味。要你在契上按个手印，写明两家情愿，日后无翻悔。你把手指在印泥里按了一下，红得很。抬头看见那姑娘在看你，眼睛里像有话，又像没有。院里的鸡在桌底下钻来钻去，啄掉在地上的瓜子壳。印泥是湿的，有一股桐油味。","ask":"手印还没落下，你问不问？","days":15,"npc":"","memory":"指头上的红印泥","choices":[{"title":"按了多说一句","desc":"你按下手印，对男方说：好好待她。","hint":"三年后她来赶集。","tone":"warm","outcome":"男方父亲愣了一下，说这是自然。那姑娘低下头，耳朵红了。中人把契收起来，卷成一个筒。三年后她抱着孩子来赶集，看见你在豆腐摊前，走过来让孩子叫保人爷。孩子认生，把脸埋在她肩上。她笑着说：他怕生。你说：怕生好。","eff":{"bond":3,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"","thread":""}},{"title":"问她自己愿不愿意","desc":"你转头问那姑娘：这是你自己愿意的吗？","hint":"她娘的脸沉了。","tone":"ask","outcome":"满屋静了。姑娘抬头看了你一眼，点了下头，很轻。她娘在旁边说：这还用问。中人咳了一声，说：老哥，走个过场。你按了手印。出门时中人跟你说：人家两家都谈好了，你多这一句，倒像有什么。你说：我就问问。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}},{"title":"不按这保不做","desc":"你把印泥推开，说：这保我不敢做。","hint":"亲事照办。","tone":"refuse","outcome":"满屋人都看你。男方父亲脸上挂不住，说：我们又不图你什么。你起身走了，走到院门口听见里面有人低声说话。亲事照办。过了两年听说过得不好，男人喝酒。你有时想起那天姑娘的眼神，想是不是该按那个手印。想完也就过去了。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"","thread":"你有时想起那个眼神"}}]},{"id":"sui_s07","act":"side","age":[52,52],"mode":"narration","title":"替柳婆守灵","opening":"柳婆是立冬夜里走的，九十六岁。灵停在堂屋，两条长凳架着门板，脚头一盏灯。守夜轮到后半夜，人都散了，只剩你。你拿爹那把豁口镰刀削了几根撑灵帐的竹竿，坐在门槛上听风。那根九道痕的木棍靠在棺边，是她自己要放的。灵桌底下是她的祖骨罐，罐口那圈绳痕深得能卡住指甲。阿绵从鱼尾泽赶回来，跪在灵前烧纸，纸灰落在鞋面上，烧到一半问你：奶奶说这棍不能烧，你知道为啥？","ask":"阿绵看着你，等一个说法，你怎么答？","days":10,"npc":"","memory":"灵前的九道痕","choices":[{"title":"把棍藏进袖子","desc":"你把木棍抽出棺边，塞进袖子，说烧不烧都一样。","hint":"阿绵看见了你袖口的木头。","tone":"sneak","outcome":"阿绵没拦，只把纸往火里推了推。天亮出殡，你袖子里硌着一根棍，走一路硌一路。下葬后回家，你把棍立在门后。你媳妇问哪来的，你说是柳婆的。她说留着不吉利。你没扔。那年冬天劈柴，你好几回伸手想拿它引火，摸到那九道痕，又缩回来。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":6},"flag":"","thread":"门后立着一根不能烧的棍"}},{"title":"当众把棍折断","desc":"你举起木棍，在膝盖上一折两段，一段放进棺里。","hint":"满屋的人都静了。","tone":"brave","outcome":"木头断的时候响了一声，像干骨头。阿绵看着你，眼睛红了，没哭。你把另一段递给她，说：一半跟着你奶奶，一半你拿着。她接过去，攥得指节发白。出殡后她把半截棍塞进包袱，回了鱼尾泽。你留下的那半截，后来钉在院里当了豆角架的桩，风吹日晒，痕还在。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把棍交还阿绵","desc":"你把木棍擦干净，双手递给阿绵，说这是你奶奶的界。","hint":"她不知道拿它做什么。","tone":"teach","outcome":"阿绵接过去翻来覆去看了半天，问九道痕是什么。你一道一道讲，讲到你六岁那年攥着它，田主家的儿子来拔，你停了一下，说：记不清了。她把棍靠在灵桌边，出殡时忘了拿。你替她收起来，想等她想起来。她一直没想起来。棍后来一直立在你家门后。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}}]},{"id":"sui_x20","act":"side","age":[54,54],"mode":"narration","title":"卡在门框里","opening":"赵家那头黑猪跑了，不知道谁没插好圈门。猪先在晒场上转了两圈，然后直奔你家——你家门开着，堂屋桌上摆着刚出锅的窝头。你听见响，从灶间出来，正看见那头猪两条前腿搭在桌沿上，嘴在盆里。它抬头看你，嘴边挂着一圈黄。你喊了一声，它从桌子底下钻过去，撞翻了条凳，又撞翻了水缸，最后卡在门框里，进退不得，叫得像要杀它。水淌了一地，漫到门槛。猪的背上有几道泥印，是刚才蹭在墙上的。桌上的窝头还剩五个，最上面那个被咬了一口。","ask":"猪卡在门框里，你怎么办？","days":10,"npc":"","memory":"门框里的黑猪","choices":[{"title":"从后面推","desc":"你绕到猪后面，抓住它的后腿往后推。","hint":"门框裂了。","tone":"help","outcome":"赵家来了三个人，一个抓耳朵，一个推屁股，你在后面顶。猪叫，人也叫。门框咔嚓一声裂了。猪出去以后在院里转了一圈，自己跑回圈里去了。赵家要赔门框，娘说不用，说门框本来就松。那盆窝头剩了两个，你吃了，有点猪味。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":5,"爱":1},"flag":"","thread":"门框裂了一道"}},{"title":"拿瓢敲它","desc":"你抓起灶台上的水瓢，在它屁股上敲。","hint":"越敲越叫。","tone":"defy","outcome":"你敲一下，它叫一声，越叫越响，四条腿在门槛上刨。你敲到第三下，瓢裂了。最后是娘从菜园里掐了一把青菜，站在门口晃，猪看见青菜就不叫了，跟着菜出了门。娘把菜扔在院里，说：跟人一样，得给个台阶。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":5,"怒":1},"flag":"","thread":""}},{"title":"站在门口等赵家","desc":"你靠着门框站着，看它折腾，等赵家来。","hint":"窝头吃完了。","tone":"ignore","outcome":"你看了一刻钟。猪在桌底下拱，把桌布拽下来，窝头滚了一地，它一个一个吃。赵家的人赶来时，盆已经空了。赵家婶子一个劲赔不是，说要赔面。你说不用，说反正也蒸多了。她走了以后你收拾地，捡起桌布，上面全是猪口水。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"喜":4,"恶":1},"flag":"","thread":""}}]},{"id":"sui_s13","act":"side","age":[58,58],"mode":"narration","title":"借粮的人","opening":"大旱第二年，谷价一天三涨，村口每天有外村人过。晌午来了一个男人，四十上下，裤脚卷到膝盖，脚上只剩一只草鞋，站在你家篱笆外不进来。他说是上村的，姓吴，家里三个孩子，老幺病着，只借半袋，秋后还一袋半。你炕席底下压着田契，边角那块米汤粘过的地方硌手；灶间梁上吊着那半袋留种的谷，袋口扎了三道麻绳，是你娘在时扎的，绳头还留着她的牙印。","ask":"他站在篱笆外不进来，你怎么说？","days":30,"npc":"","memory":"门外的空口袋","choices":[{"title":"解绳倒半袋给他","desc":"你把梁上的袋解下来，倒出一半，用簸箕撮进他的空袋。","hint":"梁上只剩一把种。","tone":"warm","outcome":"他接袋时手在抖，说了三遍秋后还。你送他到渠口，他走几步回一次头，鞠了三次躬。那年秋后他没来，第二年也没来。开春你家种不够，向拾穗会借了一升，秋后还两升。你娘扎的那个结，你没再打上。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"借出去的半袋没有还"}},{"title":"按住袋口说不借","desc":"你按住袋口，说这是留种的，借出去一家人都得饿死。","hint":"他在篱笆外站了很久。","tone":"refuse","outcome":"他没再说话，把空口袋叠好夹在腋下，走了。走出十几步，他回头看了一眼你家的烟囱。秋后有人从上村来，说他家老幺没熬过八月。你把那半袋谷吊回梁上，绳子勒进手掌。第二年下种，那袋谷一粒没霉，出得比谁家都齐。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":1},"flag":"refused_famine_grain","thread":""}},{"title":"领他去鱼尾泽找活","desc":"你锁上门，领他走两天路到鱼尾泽，找管短工的阿绵。","hint":"你家的地荒了两天。","tone":"help","outcome":"路上他把仅剩的草鞋让给你穿一段，你没要。阿绵看了他半天，让他去码头扛谷包，先支半袋碎米。他扛起包时腰直不起来，回头朝你点头。你走回村已是第三夜，自家田里的草长得比苗高。他后来每年托人捎一句话，话里从不提借粮。","eff":{"bond":1,"health":-2,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui_x21","act":"side","age":[58,58],"mode":"narration","title":"七个结","opening":"老周死在秋天。他在鱼尾泽撑了四十年船。你去送他，船还锁在岸边，缆绳上打了七个结。他儿子从仓城回来，站在船头，说这船要卖。有人问卖给谁。他说不知道，反正留着也没人撑。岸上摆着三张桌，来的人不多，多半是上了年纪的。风把纸钱吹到水里，浮着不走。你想起有一年发水，他半夜撑船把半个村的人渡出来，最后一趟回来，船里站着一只羊。船底的积水里飘着几根羊毛。船板上有一层青苔，踩上去滑。有人往水里撒了一把米，米沉下去，散开，看不见了。","ask":"他儿子在船头站着，你说什么？","days":20,"npc":"","memory":"缆绳上的七个结","choices":[{"title":"说这船我买了","desc":"你走过去，说：这船我要了，你说个价。","hint":"你不会撑船。","tone":"keep","outcome":"他儿子看了你半天，说了个很低的价，低得你不好意思。钱给了，船归你。你不会撑，头一回下水就在原地打转，转了一下午。后来船停在岸边，一年比一年旧。第三年缆绳的结松了一个，船身歪进水里，你也没去扶。","eff":{"bond":1,"health":-1,"reputation":1,"coins":-80,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"岸边那条歪进水里的船"}},{"title":"帮他把船撑到对岸","desc":"你说：我帮你撑过去，那边买主出价高。","hint":"撑到一半你就撑不动了。","tone":"escort","outcome":"你撑到河心，竹篙插进泥里拔不出来，船在河心打横。他儿子过来接过篙，一句话没说，两下就把船撑正了。到对岸，买主压价，最后没卖成。船又撑回来，锁在原处。他儿子走的时候跟你说：这船，还是留在这一岸吧。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把缆绳重新系好","desc":"你什么也不说，蹲下去把七个结解开，重新系了三个。","hint":"他儿子蹲在船头哭了。","tone":"witness","outcome":"七个结是老周系的，一个比一个紧。你解开用了很久，指甲缝里全是麻屑。你系了三个，系得不好看，但结实。他儿子一直在旁边看，看到最后蹲下去，把脸埋在胳膊里。岸上的人都没过去。风把最后几张纸钱吹进水里，慢慢沉了。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":6,"爱":2},"flag":"","thread":""}}]},{"id":"sui_x22","act":"side","age":[61,61],"mode":"narration","title":"横在路上的扁担","opening":"拾穗会的老太太们天不亮就去东垄。这天仓兵来得早，赶一辆板车，说要收地脚穗，连人带筐往车上倒。周婆婆八十一了，抱着筐不撒手，被拖着走了两步，鞋掉了一只。你从渠那边过来，扁担还在肩上。路上没有别人。板车上有半车谷穗，穗子上还带着露水。仓兵说：让开。你把扁担横过来，横在路中间。周婆婆在你身后喘气，喘得很响。她的手一直没松开筐，指节白得像骨头。露水把她的裤脚打湿了，贴在腿上。远处渠水的声音很细，像有人在很远的地方说话。","ask":"扁担横在路中间，让不让？","days":12,"npc":"","memory":"路中间的扁担","choices":[{"title":"横着不让","desc":"你把扁担端平，说：把筐放下。","hint":"胳膊肿了半个月。","tone":"defy","outcome":"仓兵拿鞭子抽在你胳膊上，抽了两下。你没让。第三下他抬手的时候，村口来了人，先是两个，后来七八个，都拿着家伙。仓兵看了看见，把筐扔在地上，赶着车走了。你的胳膊肿了半个月，抬不起来。周婆婆每天来给你送一碗米汤。","eff":{"bond":3,"health":-3,"reputation":3,"coins":0,"stats":{"体魄":1},"emotion":{"怒":4,"爱":3},"flag":"","thread":""}},{"title":"跑去敲钟","desc":"你扔下扁担往村里跑，去敲晒场那口钟。","hint":"回来时车已经走了。","tone":"risk","outcome":"钟绳粗，你跑得急，手磨破了一层皮。钟敲到第五下，人才陆陆续续出来。等你跑回东垄，板车已经走了，路上落了一地谷穗。周婆婆坐在地上，抱着一个空筐。你把她扶起来，她的鞋还在车辙里，压扁了。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"怒":4,"哀":3},"flag":"","thread":"钟绳磨破了手心"}},{"title":"去抢那个筐","desc":"你伸手抓住筐沿，往回一拽。","hint":"筐裂了，谷撒了一地。","tone":"protect","outcome":"筐是柳条编的，经不住两下，裂了。谷穗撒了一地，你和周婆婆蹲下去捡。仓兵在车上看着，看了一会儿，把车赶走了。你们捡到晌午，捡回大半筐。周婆婆一边捡一边说：不值当，不值当。你说：弯腰又不花钱。","eff":{"bond":3,"health":-2,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"怒":2},"flag":"","thread":""}}]},{"id":"sui_x23","act":"side","age":[65,65],"mode":"narration","title":"一坛石头","opening":"村东的孙老头死了，没儿没女。族长让你去清他的屋。屋里只有一张床、一口锅、三只坛子。第一只坛子里是谷，第二只也是谷，第三只封得最严，用蜡封了口。你和两个人把它抬到院子里，撬开。里面是一坛子石头，每块都用布包着，布里写着字。有一块写：某年某月，捡于东垄。有一块写：某年某月，还李家的。最上面一层，包着一块最圆的，布上写着：这块最像我。坛口的蜡裂了，一块一块，像干了的泥。布是旧的，蓝的，洗得发白，边角都毛了。","ask":"一坛子石头摆在院里，怎么处置？","days":15,"npc":"","memory":"布包着的石头","choices":[{"title":"埋在他坟边","desc":"你说：连坛子一起埋了，埋在他坟边上。","hint":"坟头长出几棵谷子。","tone":"keep","outcome":"你们挖了个坑，把三只坛子都埋了。族长说浪费地，说一个光棍埋一坛石头。你没接话。第二年开春，他坟头上长出几棵谷子，长得歪，不知道是鸟衔来的还是怎么的。有人说是孙老头自己种的。你去看过一回，蹲下来摸了摸穗子，是实的。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把布上的字念给村里人","desc":"你把布一块块解开，站在晒场上念。","hint":"李家老太太问起一块。","tone":"tell","outcome":"你念了一下午。有人笑，说这老头闲得慌。有人听着听着不笑了。念到还李家那块，李家的老太太挤到前头，问是哪块。你把石头递给她，她翻来覆去看，说：这不是我家的，我家没丢过东西。说完还是把石头揣进袖子里带走了。","eff":{"bond":1,"health":-1,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"喜":1},"flag":"","thread":""}},{"title":"挑一块回家","desc":"你挑了那块最圆的，揣进怀里。","hint":"孙子问这是什么。","tone":"greed","outcome":"那块石头圆得像颗蛋，握在手里是温的。你把它放在窗台上。孙子来的时候问这是什么，你说石头。他拿起来看了看，说上面有字。你说没有。他指给你看，布角上确实有个字，褪得只剩一道。你没再说话，把石头放回窗台，再没动过。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":"窗台上那块圆石头"}}]},{"id":"sui_s14","act":"side","age":[66,66],"mode":"narration","title":"他问那年的事","opening":"穗禾的孙子从穗仓城来，十九岁，穿一件洗得发白的褂子，说话带城里尾音。他在你家住两晚，帮你挑水、劈柴，劈完把斧子擦干净挂回墙上。第三天他要走，蹲在门槛上系鞋，忽然问：我奶奶说，那年她在河口等到天亮，你没来。他抬起头：你为啥没走？供桌底下那只罐罐口有一圈绳痕，深得能卡住指甲。院里晒着新谷，风一过，谷壳往墙根滚。梁上还挂着你爹那把豁口镰刀，缺口磨圆了。","ask":"他系好鞋等着你答，你说什么？","days":15,"npc":"","memory":"河口那年的船","choices":[{"title":"领他看祖骨那垄","desc":"你领他到村后看祖骨埋在哪一垄，回来把梁上那半袋谷给他。","hint":"梁上那根绳空了。","tone":"teach","outcome":"他蹲下去抓了一把土，土从指缝漏回原处。你说这底下埋着太爷爷，东头棚里是太奶奶的罐。他把那把土装进衣兜，拍了拍。走时他没说什么时候再来。第二年清明，那垄上多了一小堆新土，颜色发黑，是从城里带来的。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"把话说明白","desc":"你告诉他，那年你爹把田契塞进你手里，说这地不能断在你这辈。","hint":"他问那我奶奶算什么。","tone":"honest","outcome":"他系鞋带的手停了一下，又系了一遍，问：那我奶奶算什么。你答不上来。他站起来把劈好的柴码齐，说够烧一冬。走到篱笆外他回头，说城里也有地，是水泥的。你回屋把田契从炕席底下摸出来，边角那块米汤粘过的地方又翘了。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":1},"flag":"told_grandson_truth","thread":"他问的那句话你没答上"}},{"title":"送他到河口","desc":"你什么也不答，替他拎着包袱，一直送到河口那棵歪柳下。","hint":"船开了你才回家。","tone":"escort","outcome":"一路上你们没说话。到河口他把包袱接过去，说奶奶讲她那年也是从这儿走的。船离岸，他站在船尾手扶船帮，姿势跟他奶奶当年一样。你回家把院里那堆谷壳扫拢，扫成一堆，没舍得烧。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}}]},{"id":"sui_x24","act":"side","age":[69,69],"mode":"narration","title":"不知道给谁","opening":"入冬前，你把屋里的东西清了一遍。豁口镰刀、两只木箱、一个铜盆、一床没怎么盖过的褥子。儿子说城里的房子小，这些带不走。你把镰刀递给他，他接了，放在门后。你把铜盆给儿媳，她说现在不用这个了。你把褥子抱到晒场上晒，晒了一天，傍晚又抱回屋。天色暗下来，你坐在门槛上，脚边堆着一堆不知道给谁的东西。风从渠那边过来，带着霜味。门槛的石头上有一道凹，是几十年踩出来的。锅里的水开了，响了一声。屋里的灯没点，只有灶膛里一点红。","ask":"脚边这一堆东西，怎么办？","days":20,"npc":"","memory":"门槛前的一堆","choices":[{"title":"一件件送邻居","desc":"你把铜盆送给李家，褥子抱去给周婆婆。","hint":"镰刀你留下了。","tone":"warm","outcome":"李家媳妇接了铜盆，说正好缺一个。周婆婆把褥子铺在床上，摸了三遍，说厚。送完你回家，屋里空了一块。镰刀还在门后，你把它拿起来，刃上的豁口硌手。你把它挂回墙上，挂好了退后两步看，觉得墙也空。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":""}},{"title":"堆进柴房等以后","desc":"你把东西一件件搬进柴房，码整齐。","hint":"第二年褥子霉了。","tone":"save","outcome":"柴房堆得下不去脚。你想着等开春再说，开春忙，就忘了。第二年入冬想起来，去翻，褥子霉了一块，铜盆里积了灰。镰刀还在最上面，锈了一层。你用袖子擦了擦，擦不掉。儿子回来看见，说：这些早该扔了。你说：放着吧。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":1},"flag":"","thread":""}},{"title":"把镰刀挂回墙上","desc":"你把别的都放下，只把镰刀挂回原来的钉子。","hint":"钉子松了。","tone":"keep","outcome":"钉子是你爹钉的，钉了四十年，木头已经朽了。镰刀挂上去，钉子往下滑了一寸。你伸手去扶，它掉下来，刃磕在门槛上，又添了一个豁口。你蹲下去捡，蹲了很久才站起来。晚上你把镰刀放在枕头边，刃朝外，像小时候看见爹放的那样。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":6,"爱":3},"flag":"","thread":"刃上又多了一个豁口"}}]},{"id":"sui_s08","act":"side","age":[71,71],"mode":"narration","title":"来问旧事的人","opening":"霜降后，村里来了个年轻人，十九岁，穗仓城口音，说是替秋祭收旧事。他坐在你家门槛上，膝上摊着本子，问一句，记一句。你从拾穗会的木棍讲起，讲到十岁那年雨帖没应验，讲到韩老头被围在晒场，忽然停住了。他等着，笔尖悬在纸上。灶上的水开了，咕嘟咕嘟，你起身去添柴，背对着他说：记不清了。梁上还挂着你爹那把豁口镰刀，刃上的缺口磨圆了。","ask":"他问韩老头后来去了哪，你怎么说？","days":20,"npc":"","memory":"他记下的旧事","choices":[{"title":"说出那个字","desc":"你告诉他，帖上写的是三日，是你念错，不怪韩老头。","hint":"他抬头看了你很久。","tone":"honest","outcome":"他写得很慢，写完念给你听。你听见自己的名字和韩老头的名字写在同一行，像两块地终于挨上了界。他说回去要交给主事，能不能改，不知道。你送他到村口，他走远了你还站着。回来你把田契从炕席底下摸出来，边角那块米汤粘过的地方又翘了，你用手按了按。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"told_rain_truth","thread":""}},{"title":"让他照老话写","desc":"你说记不清了，让他照村里传的那套写。","hint":"他写下了赶走韩老头那句。","tone":"dodge","outcome":"他写完念了一遍，问你还有没有要补的。你说没有了。他合上本子，朝你鞠了一躬，说打扰了。你看着他走，想起韩老头当年也是这么走的，背一只旧褡裢，鞋面上全是灰。晚上你把梁上的半袋谷取下来，抓一把又放回去。谷子从指缝漏回袋里，沙沙响。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}},{"title":"领他去看墙","desc":"你带他到晒场，指给他看当年贴雨帖的那块墙皮。","hint":"墙皮已经换了三回。","tone":"witness","outcome":"晒场翻修过，墙是新泥，什么也没有。你站了半天，说：就是这儿。他伸手摸了摸，摸下一层白灰，问还记不记得帖上的字。你说记得几个。他等着，你却没往下说。回去的路上你走得慢，他要扶，你说不用。第二天他走了，本子上那页只写了一行：村人逐雨帖师。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":5},"flag":"","thread":"那页只写了一行"}}]}]},"无昼京":{"no":2,"name":"无昼京","subtitle":"永夜里，一盏灯能照亮几个人","through":"母亲替别人修了一辈子灯，自己家总在省灯芯。后来你才懂，她把光给出去，是因为相信光会回来。","cast":[{"id":"father","name":"亥叔","role":"夜脚夫","tag":"父"},{"id":"mother","name":"灯娘","role":"修灯匠","tag":"母"},{"id":"sibling","name":"小漏","role":"抄漏吏","tag":"妹"}],"main":[{"id":"wu_m01","act":"main","age":[0,0],"mode":"montage","title":"两截灯芯","opening":"你生在修灯铺的里间。接生婆的剪子先在灯上烤过，母亲躺着，手还搭在桌沿，桌上摊着七八盏别人家的坏灯。家里只剩一截灯芯，两指长，她让接生婆剪成两段，一段今晚点，一段包进油纸压在枕下。父亲还没回来，门外是永远的黑。灯点起来只有黄豆大，照得见母亲的下巴，照不见墙。她把你往灯边挪了挪，说：看清了，这是你的手。","ask":"两段灯芯摆在枕边，你伸手抓哪一段？","days":30,"npc":"mother","memory":"两指长的灯芯","choices":[{"title":"攥住长的那段","desc":"你攥住长的一段，油纸被你捏得发响。","hint":"明晚要摸黑。","tone":"greed","outcome":"母亲由着你攥。那晚灯亮到后半夜，她借着光把七盏坏灯一一看过，记下哪盏该换芯。天亮时长的烧完了，短的只剩半寸。第三晚家里没点灯，父亲在门槛上摸黑吃了一碗冷粥。后来母亲跟人说起你，总说：这孩子，抓的是长的。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":1},"flag":"","thread":""}},{"title":"抓短的那段","desc":"你把短的一段攥进手心，长的留给明天。","hint":"母亲把长的收进柜里。","tone":"steady","outcome":"母亲笑了一下，把长的那段用油纸包好，收进柜子最里头。那晚的灯只点了半炷香，她就着光给你缝了一双小鞋，鞋底纳得密。后来你穿到露脚趾，她又补了一层。家里省下的那半截灯芯，她一直没动，逢人就说：留着，等日子好一点。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":"柜里留着半截灯芯"}},{"title":"抓住她手指","desc":"你不抓灯芯，抓住母亲搭在枕边的手指。","hint":"她让整截灯芯亮了一夜。","tone":"family","outcome":"母亲没抽手。她把那截灯芯整个点上，说：头一晚，亮一点。灯芯烧到天亮，剩一撮黑灰。第二天她去邻家借了半勺油，回来时在门槛上歇了一会儿才进屋。多年后她跟人说，你满月那晚眼睛亮得像灯，她一辈子就见过那一回。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"whole_night_light","thread":""}}]},{"id":"wu_m02","act":"main","age":[5,5],"mode":"dialogue","title":"日门开的那天","opening":"日门开在十二钟楼底下，一年只开一回，一回只有一刻。那天全城的人都往广场去，人人手里提一盏灯，到门边就收进布套里。母亲把你举到肩上，叫你闭眼。你没闭。门缝先是白的，后来变成一条金线，光涌出来落在脸上，是热的，像灶膛口。你哭了。母亲在底下仰着脸问：怎么了？话没说完，旁边一个老太太被人挤倒，灯罩碎在地上，碎瓷滚到你脚边。","ask":"老太太倒在脚边，母亲抱着你，怎么办？","days":10,"npc":"mother","memory":"日门缝里的光","choices":[{"title":"求母亲扶她","desc":"你拽母亲的袖子，叫她放下你，去扶那个老太太。","hint":"你们退到人群最外圈。","tone":"warm","outcome":"母亲把你放到墙根，叫你抓住她的衣角，自己去扶。老太太的膝盖磕出了血，灯罩碎在脚边。母亲撕了衣角给她扎。等再抬头，日门已经合上，人群正往外散。回家的路上母亲没说话，进门才说：今天你没看清。你说看清了，她脸上有光。母亲低头去烧水，火点着了又灭。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"你没看完那年的日门"}},{"title":"抱紧她往前挤","desc":"你搂住母亲的脖子，叫她再往前一点，别管别人。","hint":"背后有人骂了一句。","tone":"brave","outcome":"母亲把你往上颠了颠，从两个肩膀中间侧过去。有人骂，她没回头，只把布套往你头上按了按。光正好落在你脸上，你伸手去抓，抓了一把热。回家你跟小漏说光能抓，小漏笑得眼睛弯，说你吹牛。母亲在灶边听着，说：能。她说完把灯芯捻小了一截。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"爱":1},"flag":"","thread":""}},{"title":"蹲下看影子","desc":"你从她肩上滑下来，蹲在光的边上，看自己的影子。","hint":"你记住的不是光。","tone":"learn","outcome":"光把你的影子拉得很长，一直铺到钟楼台阶上，头在台阶上，脚在你脚边。你伸手，影子也伸手。母亲把你拉起来时，日门已经合了，人群往外走，鞋底踩得石板响。她说：看什么呢。你说：它在前面。母亲没听懂，牵着你的手往家走，一路没再问。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4},"flag":"saw_shadow_first","thread":"影子先你一步"}}]},{"id":"wu_m03","act":"main","age":[9,9],"mode":"dialogue","title":"影子先走","opening":"九岁那年秋天，你替母亲往暗渠边送一盏修好的灯。灯是给裁缝家的，芯是新换的整根。你提着它，想起自家灶台上那盏，芯是剪剩的，短得够不着油。母亲在后头说：灯送出去，光会回来。巷子窄，墙上的灯罩都熏黑了。走到拐角，你看见自己的影子先一步拐进巷子——它转过去，你还没转。你站住，影子也站住，只露出半个肩。你回头喊母亲。她赶来，在围裙上擦擦手，蹲下看你的影子，说：漏了光。","ask":"母亲说漏了光，能补，要你每晚举灯。","days":30,"npc":"mother","memory":"先走半步的影子","choices":[{"title":"每晚举灯站墙根","desc":"你按母亲说的，每晚举灯站半个时辰，把影子照回脚下。","hint":"你的胳膊比同龄人沉。","tone":"repair","outcome":"举了三年。头一年影子回来，第二年又往前跑。母亲每晚在旁边剥灯芯草，剥一段，看你一眼。你的右胳膊比左边粗，扛东西时稳，只是个子没怎么长，站在小漏旁边矮了半个头。她总拿这个笑你，笑完给你留一块灯油糕。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"自己改个灯罩","desc":"你拿铁皮敲了个罩子，把光全兜在脚边。","hint":"母亲的一件旧衣烧了个洞。","tone":"niche","outcome":"铁皮是从废灯上剪的，边沿磨手。你把罩子卡在灯口，光聚成一小团，只照脚下，影子果然跟上了。母亲看见了，没夸，只说：这样费油。你没听。后来那盏灯的罩口烧红，把搭在椅背上的旧衣烫了个洞，是母亲出嫁时穿的。她把洞补成了一朵花，补得歪。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":5},"flag":"","thread":"你把母亲的旧衣烫了个洞"}},{"title":"随影子去","desc":"你把灯搁下，说随它去，它爱走哪走哪。","hint":"母亲把旧灯收进了柜底。","tone":"defy","outcome":"母亲没再提补的事。第二天她把那盏旧灯擦干净，收进柜底，压在一叠灯罩下面。你从此走路总比旁人快半步，影子也总在前头。巷子里的人说你这人急，像赶着去投胎。母亲听见了，不接话。你十九岁那年才知道，漏光的人，影子在影市上能卖个好价钱。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4},"flag":"kept_leaky_shadow","thread":"你的影子总在前头"}}]},{"id":"wu_m04","act":"main","age":[14,14],"mode":"dialogue","title":"替更牌","opening":"十四岁那年入冬，父亲的腿开始肿。夜里他回来，先在门槛上坐一会儿，靴子脱在门外，袜口勒出一道深沟，按下去一个坑，半天不回。母亲蹲下去看，拿手量了量，没说话，起身去灶上热盐水。父亲从怀里摸出一块木牌，牌上刻着他的更号和一道旧刀痕，搁在桌上，往你这边推了推。他说：替我去两晚。母亲的手停在灯罩上。","ask":"木牌推到你面前，两个晚上，接不接？","days":30,"npc":"father","memory":"刻着更号的木牌","choices":[{"title":"接下木牌","desc":"你把木牌揣进怀里，当夜就去货栈上工。","hint":"你的腿也会记住那重量。","tone":"carry","outcome":"第一夜你扛了十七趟，肩膀磨破，木牌在胸口硌出一道印。第二夜下雨，栈道的灯坏了两盏，你摔了一跤，货主扣了半刻光时。回家父亲看你的走路，看了很久，说：像我了。他说这话时在笑，你没敢看他的腿。那块木牌你一直揣着，揣到边角磨圆。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"爱":3,"惧":1},"flag":"","thread":"木牌边角被你磨圆"}},{"title":"把牌子交回工头","desc":"你去货栈找工头，说父亲走不动了，求换个白班。","hint":"父亲那晚没吃饭。","tone":"rule","outcome":"工头翻了翻册子，说白班没缺，倒有个扫灯楼的活，光时少一半。你替父亲应了，回家一说，父亲把木牌放在桌上，用指头把它转了半圈，说：我还没死。那晚他没在门槛坐，直接进了里间。第二天一早他照样去上夜工，走得很慢，木牌在腰间一下一下地撞。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_father_legs","thread":"父亲说：我还没死"}},{"title":"把木牌藏进砖缝","desc":"你趁父亲睡下，把木牌塞进灶膛后的砖缝。","hint":"他找了一夜。","tone":"sneak","outcome":"父亲把铺盖翻了两遍，把灯举到床底下照，最后什么也没说，半夜照样出门。你跟到巷口，看见他走三步歇一歇。母亲站在门口，手里捏着半截灯芯，轻声说：他这个人，你不让他去，他更难受。第二天你把木牌放回桌上，谁也没提这件事。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"wu_m05","act":"main","age":[19,19],"mode":"dialogue","title":"影市","opening":"十九岁那年，小漏想调去日门当值。她说话快，一句赶一句，说去了能多领半刻光时。母亲在灯下穿线，没抬头，说：那边风大。小漏笑起来眼睛弯：我不怕风。第二天你瞒着家里去了影市。影市开在漏底渠的旧闸口下，灯都蒙着布，只留一条缝。管市的是个瞎了一只眼的女人，面前一排小秤，秤盘里不是油，是各人的时辰。墙角贴着一张熏黄的旧账，最下一行是父亲的名字，后头跟着个陌生的名字。","ask":"黑牌推到手边，按不按手印？","days":10,"npc":"sibling","memory":"蒙着布的影市","choices":[{"title":"按下手印","desc":"你把拇指按在湿泥上，换一小袋光时砂。","hint":"此后半年，你看东西慢半拍。","tone":"trade","outcome":"那一时辰是从你往后十年里扣的，扣得悄没声。回家路上你觉得灯比平时暗，揉了揉眼，还是暗。小漏拿那袋砂去换了调令，走的那天在门口回头，笑起来眼睛弯。你站在门里，觉得她的脸隔着一层布。母亲追出去，往她包袱里塞了半截灯芯，她没要，说日门那边有。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"哀":3},"flag":"sold_first_hour","thread":"你看东西慢了半年"}},{"title":"连影子一起卖","desc":"你在黑牌背面按下第二个手印，把影子也押出去。","hint":"灯下从此少一个人影。","tone":"profit","outcome":"瞎眼女人掀开布，灯照过来，你的影子在墙上挣了一下，像条被拎起来的鱼。她沿墙根一划，影子就下来了，叠好收进匣子。你拿到双份光时砂，给小漏置了调令，给母亲买了一整根新灯芯。那晚她点了灯，看你半天，说：你的影子呢。你说灯太暗。她把灯挪远了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"爱":3,"惧":3},"flag":"sold_shadow","thread":"你在灯下没有影子"}},{"title":"把黑牌推回去","desc":"你说回去再想想，把刻着名字的黑牌推回去。","hint":"小漏再没跟你提过调令。","tone":"refuse","outcome":"瞎眼女人把黑牌收进袖里，说：想好了再来，价钱按天变。你爬出闸口，外面的天黑得和里头一样。小漏在灯下抄漏，抬头问你去哪了，你说走走。她哦了一声，低头继续抄，笔尖在纸上顿了一下，留下一个墨点。那墨点后来越描越大，最后成了一个补不上的洞。","eff":{"bond":-2,"health":1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"","thread":""}}]},{"id":"wu_m06","act":"main","age":[24,24],"mode":"dialogue","title":"门槛上的夜","opening":"二十四岁那年，父亲走完了最后一趟夜路。他回来时天没亮，在门槛上坐下，靴子没脱，背靠着门框。母亲去热盐水，他摆摆手。你在他旁边坐下，门槛只有一条，两个人挨着。他从怀里摸出一张折了四折的纸，纸边发毛，上头是司昼院的朱印，底下两个名字：一个是他的，一个你不认识。他说：那年你出生，家里没光时了。我借了他的名。","ask":"他把纸递过来，说烧了吧。你接不接？","days":10,"npc":"father","memory":"两个名字的旧纸","choices":[{"title":"凑到灯上烧了","desc":"你把纸凑到灯芯上，看它卷起来，烧成灰。","hint":"那个名字从此没人再提。","tone":"secret","outcome":"火苗舔到他的指头，他没缩。纸烧完，他用鞋底把灰蹭进门槛的缝里，说：干净了。那晚他睡得很沉，第二晚也睡，第三晚没醒。母亲给他擦身时，在他贴身的口袋里摸出一小截新灯芯，油纸包着，没舍得用。你把它放回他口袋里，跟他一起下了葬。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"burned_father_ledger","thread":"那截新灯芯跟他下了葬"}},{"title":"把纸送去司昼院","desc":"你揣着纸去司昼院，把那笔旧账报了。","hint":"他走的时候，账是平的。","tone":"report","outcome":"司昼院的人查了三天，判补缴半刻光时，从他灯牌里扣。父亲听完，说：该。他把灯牌解下来放在桌上，牌绳磨得发白。那半刻还没扣完，人就走了。出殡那天，司昼院的一个小吏在门口站了一会儿，没进来，放下了一小罐油。你没要，让他提回去了。","eff":{"bond":-5,"health":0,"reputation":3,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"惧":2},"flag":"reported_father_ledger","thread":"父亲最后说了一个字：该"}},{"title":"把纸塞回他手里","desc":"你折好纸，塞进他手心，说这事你自己拿。","hint":"他到死都攥着那张纸。","tone":"keep","outcome":"父亲看了你很久，把纸攥在手里，攥出了汗印。那晚他跟你说了很多话，说他年轻时也想过跑，说漏底渠的水冬天是温的，说他第一次抱你，手心里全是灯油味。说到一半停住，说：困了。第二天早上他的手还攥着，掰开时纸粘在掌心，得用温水泡。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":4},"flag":"","thread":""}}]},{"id":"wu_m07","act":"main","age":[30,30],"mode":"dialogue","title":"认光","opening":"三十岁那年，母亲的眼睛坏了。先是穿不上线，后来把七号灯芯当成三号，修好一盏灯，点起来满屋子是烟。她把灯罩凑到鼻尖闻了闻，说：油不对。客人走后，她坐在凳子上，手在桌上摸，摸到你的手，捏了捏。第二天她把你叫到灯前，说：从今天起，我教你认光。她闭上眼，让你把灯一盏一盏点起来，说：哪盏先热，哪盏就是好芯。","ask":"铺子往后怎么办，母亲闭着眼等你答。","days":180,"npc":"mother","memory":"母亲教我认光","choices":[{"title":"闭上眼跟她学","desc":"你学她闭上眼，一盏一盏摸灯罩、闻油、听芯。","hint":"你的手会先于眼睛变老。","tone":"learn","outcome":"她教你听灯芯烧到几寸会响，教你看灯罩上的雾往哪边偏。半年后你能闭着眼修好一盏灯。来修灯的人越来越多，有人放下灯就走，灯座里压着一小截灯芯。母亲坐在旁边剥灯芯草，说：你比我强。她说这话时脸朝着墙。后来她的手越来越闲，一上午剥不了一把。","eff":{"bond":5,"health":-1,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"爱":4,"哀":2},"flag":"learned_light","thread":""}},{"title":"去灯油行应差","desc":"你去灯油行应了差，想多领一份光时贴补家里。","hint":"母亲那晚自己修了一盏灯。","tone":"practical","outcome":"行会的人让你先认三十种油，你记了半个月。回家晚，母亲一个人坐在灯前，把一盏坏灯拆了又装，装错了，灯油淌了一桌。她看见你，说：回来了。第二天她把桌子擦了，没提灯的事。你领的光时多了，家里的灯能亮到半夜，她的眼睛却越来越不愿睁，白天也拿布蒙着。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"惧":2},"flag":"","thread":"母亲白天也蒙着眼"}},{"title":"把灯招牌摘了","desc":"你收了门口的灯招牌，说以后不修了，在家陪她。","hint":"巷子里的人提着坏灯站在门口。","tone":"quit","outcome":"招牌摘下来那天，来了三个客人，看见门关着，站了一会儿走了。母亲坐在里间，听见脚步，问：谁啊。你说：走错了。她说：哦。那天下午她摸到柜底，摸出那盏藏了多年的好灯，用袖子擦了很久，又放回去。你看见了，没问。她也没说。","eff":{"bond":4,"health":0,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"柜底那盏好灯"}}]},{"id":"wu_m08","act":"main","age":[45,45],"mode":"dialogue","title":"日门迟开","opening":"四十五岁那年，日门该在午时开。午时过了，门是黑的。广场上的人不肯散，越聚越多，有人搬了凳子，有人抱着孩子。钟楼敲了一刻又一刻，敲到第三回，人群开始往前涌。你听见暗渠那边传来一声闷响，像水从地底翻上来。灯一盏一盏灭。你护着母亲往墙边退——她眼睛看不见，手抓着你的袖子——回头找小漏。她那天在日门当值，穿的是抄漏吏的青褂。","ask":"人往门那边涌，小漏还在里头，你去不去？","days":10,"npc":"sibling","memory":"日门没开的那天","choices":[{"title":"逆着人去找她","desc":"你把母亲按在墙根，自己逆着人流往门那边挤。","hint":"你后来一直记得那只鞋。","tone":"brave","outcome":"你被人撞倒两次，膝盖磕在台阶上。门边的灯全灭了，你摸到一只鞋，青布面，鞋底纳得密，是母亲的手艺。你把它揣进怀里，被人流推了出去。那天夜里小漏没回来。母亲在门口坐了一夜，手里攥着半截灯芯，谁劝也不进屋。天亮时她把灯点上，说：给她照着路。","eff":{"bond":2,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":6,"爱":3},"flag":"lost_sister","thread":"你只找回她一只鞋"}},{"title":"先背母亲回家","desc":"你背起母亲往巷子里走，一次也没回头。","hint":"那一夜之后，母亲不再提日门。","tone":"protect","outcome":"母亲在你背上很轻，一路问：小漏呢。你说她在后头。进了巷子她才不问了。第二天小漏没回来。第三天钟警从暗渠口抬出七个人，盖着灯布。你没让母亲去看，自己去认的，回来说是别人。母亲点点头，从此再没问过，只是每天傍晚把门开着，留一条缝。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":6,"爱":2},"flag":"lost_sister","thread":"每天傍晚留一条门缝"}},{"title":"冲上钟楼敲钟","desc":"你逆着人流跑上钟楼，抓住那根旧绳敲了三下。","hint":"钟声救了一些人，也引来钟警。","tone":"report","outcome":"钟声压过人群的喊，钟楼的哨子响起来，闸门提前落下，把涌向门的人截成两半。有人骂你，有人跟着你往高处跑。小漏是后来从暗渠里抬出来的，手里还攥着抄漏的笔，笔尖弯了。钟警说：敲钟该有令。给你记了一笔。母亲去领人那天，把你留在家里，门从外面拴上了。","eff":{"bond":-3,"health":-1,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":3},"flag":"lost_sister","thread":""}}]},{"id":"wu_m09","act":"main","age":[60,60],"mode":"montage","title":"半条巷","opening":"六十岁那年冬天，巷子里的灯又坏了三盏。钟楼派下来的光时一年比一年少，家家把灯芯捻得比线还细。母亲是三年前走的，走前把一把小铜钥匙压在枕头下，没说是开哪把锁。你想起柜底那盏好灯——她藏了半辈子，说等好日子再点。钥匙正好开那把锁。你把灯取出来，铁皮上有一道她的指印，擦不掉。灌满油，换上整根灯芯，天黑时划了火，光一下子铺出去，铺到对门，铺到巷口，半条巷子都亮了。","ask":"半条巷亮了，有人端着空灯来借火。","days":60,"npc":"","memory":"照到巷口的光","choices":[{"title":"让灯一盏盏引火","desc":"你把灯挪到门口石墩上，谁来引火都不拒。","hint":"后半夜，你的油下去一半。","tone":"warm","outcome":"那晚来了十几家，有抱孩子的，有端着空灯盏的，有不好意思开口的老头。你坐在门槛上，看他们一个一个走回黑巷，灯一盏一盏亮起来。有个孩子回头喊：爷，明天还点吗。你说点。第二天油只剩个底，你去灯油行门口站了半天，空手回来的。晚上还是点了，短一刻。","eff":{"bond":5,"health":-1,"reputation":3,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"lit_alley","thread":"你答应孩子明天还点"}},{"title":"只借给阿萤","desc":"你招手让隔壁瞎眼的孩子过来，教他认灯芯。","hint":"别家站了一会儿，走了。","tone":"teach","outcome":"阿萤的眼睛看不见，手却稳。你教他用指头量灯芯，教他听油滚的声音。那晚别家没借到火，第二天巷子里有人说你小气，你听见了，没辩解。阿萤每天都来，坐在门槛上帮你绕灯芯。他走的时候总说：我闻得见你家的灯。你说明年让你点。他说好。","eff":{"bond":3,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"met_ayin","thread":"你说明年让阿萤点灯"}},{"title":"提灯回屋关门","desc":"你把灯提回屋里，插上门闩，让它只照一堵墙。","hint":"那晚你睡得很早。","tone":"alone","outcome":"光在墙上，墙上有你一个人影。你坐在灯前，把母亲留下的半截旧灯芯拿出来看，看了很久，没点。后半夜巷子里有孩子在哭，你听见了，没起身。第二天门口石墩上不知谁放了一小把灯芯草，捆得整整齐齐。你收进屋，放在柜底那盏空灯旁边。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":7},"flag":"","thread":""}}]},{"id":"wu_m10","act":"main","age":[70,76],"mode":"narration","title":"最后一次日门","opening":"七十岁以后，日子是按灯芯量的，一根烧完，就算过了一天。你走不快了，从门口到巷口要歇两回。七十六岁这年，钟楼贴出告示：漏壶要停了，日门最后开一次，就在下月十六。全城的人都往十二钟楼去，像你五岁那年一样。你坐在门槛上，把母亲留下的那盏灯擦了一遍。灯罩上有一道裂，是那年日门迟开时磕的。你老了，眼睛还行，看得见灯芯上落了一层薄灰。","ask":"日门最后一次开，这盏灯你留给谁？","days":30,"npc":"","memory":"留给谁的那盏灯","choices":[{"title":"把灯点在巷口","desc":"你把灯搁在巷口石墩上，给去日门的人照路。","hint":"你自己摸黑回来。","tone":"warm","outcome":"天没亮就有人从巷子过，一个接一个，灯在人流里晃。你坐在门槛上，看灯一点一点矮下去，像母亲当年剪的那截灯芯。人走完了，灯也灭了，巷子黑下来。你摸着墙往回走，走一步，停一步，到家门口时天还是黑的，可脸上有一点热。","eff":{"bond":4,"health":-4,"reputation":3,"coins":0,"stats":{"魅力":2},"emotion":{"爱":5,"哀":3},"flag":"gave_light_to_alley","thread":""}},{"title":"把灯交给阿萤","desc":"你把灯和那半截旧灯芯一起交给阿萤，教他护火。","hint":"你没去看最后一眼日门。","tone":"teach","outcome":"阿萤把灯抱在怀里，问你为什么不去。你说走不动了。他走了一段又回头，眼睛看不见，路却走得直。那天日门开时，巷子里只剩你一个。你把手伸出去，没摸着光，只摸到风。晚上阿萤回来说光很热，说门合上时有人哭。他把灯放回你门口，说：还你。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"爱":5,"哀":3},"flag":"gave_lamp_to_ayin","thread":"阿萤把灯还回来了"}},{"title":"提灯自己去","desc":"你提上灯，拄着拐，跟着人流往钟楼走。","hint":"走到半路，灯油见了底。","tone":"seek","outcome":"你走得很慢，人流给你让出一条道。到广场时，日门已经开了，光落在你脸上，还是热的。你举起灯，灯芯借那点光烧得亮了一下。你想起五岁那年哭，觉得那时候的脸真嫩。门合上时你还在笑。回家路上灯灭了，你摔了一跤，是钟警把你搀回来的。","eff":{"bond":0,"health":-4,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"喜":4,"哀":2},"flag":"saw_last_doorgate","thread":""}}]}],"side":[{"id":"wu_x01","act":"side","age":[6,6],"mode":"narration","title":"卖完了的三号","opening":"六岁那年腊月，母亲把灯牌挂在你脖子上，叫你一个人去灯油行领灯芯。队从柜台排到街口，人人缩着脖子，脚在石板上一下一下跺，跺出一层白灰，风一过就贴着地跑。你前头是个胖婶，围裙上别着三根别针，别针都锈了，走一步响一下。轮到她了，柜台后头新来的伙计问几号，她说三号。伙计在木牌上找了半天，抽出一块，念成山号。牌上的字是手写的，三横连了笔，看着是像山。胖婶说没有山号；伙计说牌上写着山号。两个人隔着柜台吵，后头的人跟着喊，喊成一片，喊到老账房出来，把牌子正过来看了一眼，说：卖完了。你攥着两个漏钱，钱在手里捂得发烫，没处花，抬头只看见柜台上那盏灯，火苗细得像根线。","ask":"你空手回家，母亲问灯芯呢，你怎么说？","days":10,"npc":"","memory":"卖完了的三号芯","choices":[{"title":"把吵架学一遍","desc":"你学着胖婶的口气，把柜台前那场吵从头演到尾。","hint":"母亲笑到咳嗽，锅糊了。","tone":"honest","outcome":"你连伙计抽牌子的手势都比划了。母亲先是抿着嘴，后来扶着桌沿笑，笑到咳嗽，脸涨红。她笑完从缸后摸出一把灯芯草，说：搓。你们搓了一根粗的，有小指粗，点起来火苗有拳头大，把锅底熏黑一层。父亲回来站在门口看了一会儿，说：这灯能煮饭。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":""}},{"title":"去后门等账房","desc":"你绕到行会后门，蹲在台阶上等那个老账房出来。","hint":"他给你半截，叫你别说。","tone":"ask","outcome":"你蹲到脚麻，老账房提着灯出来，看见你，愣了一下。他问清是哪家的孩子，从袖子里摸出半截灯芯，塞进你手心，说：自己留的，别跟人说。你攥着跑回家，母亲看了那半截很久，问哪来的。你说了。第二天她蒸了两个灯油糕，让你送去后门，人已经换了。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"爱":2},"flag":"","thread":"老账房给过你半截灯芯"}},{"title":"捡柜台的断芯","desc":"你趴到柜台底下，把别人踩断的灯芯一根根捡起来。","hint":"伙计揪着你的耳朵送回巷口。","tone":"sneak","outcome":"断芯捡了一小把，最长的一根只有两指。伙计从柜台后绕出来，揪着你的耳朵把你拎到街口，一路有人看。母亲来接，跟伙计赔了不是，回家没骂你。她把断芯摊在桌上，一根一根接，接成三根，接口处用线缠紧。那晚灯烧到接口就暗一下，像喘气。","eff":{"bond":1,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"喜":1,"惧":2},"flag":"","thread":""}}]},{"id":"wu_s01","act":"side","age":[7,7],"mode":"narration","title":"绳子外头的短芯","opening":"七岁那年，小漏带你去灯蕨坑拾剩料。坑在城西低处，一脚踩下去，泥从鞋帮边上翻上来。割过的畦上铺着一层断茎，晒干能搓最次的灯芯。料棚那头拉着一条麻绳，绳后堆着行会挑剩的短芯，白生生一堆，短，可还软。小漏说绳后不能去，去了要记名。你蹲下捡，看见一个比你矮半头的女孩贴着绳根，用树枝往里勾，勾一下，看一眼棚口那盏灯。她的影子压在绳上，细得像一根芯。","ask":"她回头朝你招手，你过不过去？","days":20,"npc":"","memory":"绳后的短灯芯","choices":[{"title":"蹲在绳外望风","desc":"你蹲到料棚拐角，替她盯着棚口那盏灯。","hint":"看坑人回来得比你想的早。","tone":"sneak","outcome":"她钻进去，把短芯一把一把往篮里捋。棚口那盏灯晃了一下，你咳了一声，她钻出来时篮子满了，你的鞋印却留在绳里。看坑人捏着你的后领问名字，小漏替你说了。回家母亲没骂，第二天一早提着一小包灯芯去行会门口站了半日。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"惧":2,"爱":1},"flag":"","thread":"母亲替你在行会门口站了半日"}},{"title":"把她拽出绳外","desc":"你抓住她手腕，把她从绳根拖出来，说那边不能去。","hint":"她篮子是空的，弟弟在家哭。","tone":"protect","outcome":"她挣了两下，没挣开，回头瞪你。篮子还是空的，她走时把树枝折成两截，扔在泥里。你捡起来，看见断口里有白浆。第二天她在坑口等你，塞给你一根短芯，说：这种带白圈的，烧得最长。她说完就走，没看你。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":1},"flag":"","thread":""}},{"title":"去喊看坑人","desc":"你跑回棚口，把看坑人叫醒，说有人钻绳子。","hint":"她记住了你的脸。","tone":"rule","outcome":"看坑人提着灯过去，把她从绳后拎出来，篮里的短芯倒了一地。她没哭，也没看你。看坑人夸你懂事，让你以后来拾料先挑。你挑了一捧最长的。回家路上小漏走在前头，一句话没说，进门才说：她家有个弟弟，喝米汤的。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}}]},{"id":"wu_x02","act":"side","age":[8,8],"mode":"narration","title":"光里的光脚","opening":"八岁那年，日门说好午时开。那天钟楼还没敲，门缝先白了，白得突然，像有人在里头掀了一下布。广场上的人全乱了：有的蹲下去套灯布，有的往回跑，有的举着灯不知道往哪放，灯罩撞在一起，叮当响。你和小漏还有巷子里几个孩子，从大人的腿缝里钻进去，一直钻到最前面，膝盖磕在别人鞋跟上，也不觉得疼。光落在地上，石板是热的，隔着鞋底也能觉出来。你们把鞋脱了摆在光里，光着脚来回跑，踩别人的影子玩，踩到谁，谁就跳起来骂一句。后头有人喊快出来，喊得嗓子都劈了，没人理。","ask":"钟楼敲起来了，光要收了，走不走？","days":10,"npc":"","memory":"石板上的光脚","choices":[{"title":"再跑最后一圈","desc":"你踩着光跑最后半圈，跑到门边才刹住脚。","hint":"回去时鞋少了一只。","tone":"brave","outcome":"你跑到门边，光正好收，门缝合拢时在你手背上留了一线热。回头找鞋，只剩一只，另一只不知被谁踢到哪去了。你光着一只脚回家，脚底黑得像抹了锅灰。母亲拿湿布擦，擦了两把，布全黑了。她说：明天别去了。第二天你还是去了，只是把鞋提在手里。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":4},"flag":"","thread":""}},{"title":"坐在光里不动","desc":"你坐着不走，让脚底板多热一会儿。","hint":"大人们从你身上跨过去。","tone":"stay","outcome":"你坐着，人流从你两边过，有人的衣角扫过你的脸。光一点点斜，从脚背爬到膝盖，再到腰，最后只剩门缝那么窄一条。钟楼敲完，光收了，广场一下暗下来。你站起来，脚是热的，走到巷口才凉。那年冬天你脚上没生冻疮，巷子里别的孩子都生了。","eff":{"bond":0,"health":2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3},"flag":"","thread":""}},{"title":"提鞋去追小漏","desc":"你提着两只鞋追上小漏，把一只塞给她。","hint":"她笑你穿反了。","tone":"family","outcome":"小漏接过去，看了一眼，说你穿反了。你低头，果然左右反了，脚趾挤在一头。两个人蹲在广场边上换鞋，笑得直不起身。回去的路上她一直牵着你，掌心里全是汗，到家才松开。她说：明年还来。你说来。这句话她记了很多年。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":""}}]},{"id":"wu_x03","act":"side","age":[10,10],"mode":"narration","title":"渠底的烂泥","opening":"十岁那年夏天，上游断了水，漏底渠退下去半人深，露出底下的烂泥。泥是黑的，冒着泡，一脚踩下去能陷到小腿，拔出来还得有人拽一把，鞋子常常留在泥里，人先出来。巷子里的孩子全下去了，有的摸螺，有的挖泥鳅，有的专门团泥球打人。泥球打在身上啪一声，留下一个圆印，干了一抠就掉。你站在渠沿上看了一会儿，鞋尖已经沾了泥。小漏在下头喊你，声音被笑声盖住一半。那天渠底闹得像过节，连渠沿上的老狗都躲开了，泥里翻出来的螺在篮子里爬，爬得沙沙响。","ask":"小漏在渠底招手叫你，下不下？","days":10,"npc":"","memory":"渠底的烂泥巴","choices":[{"title":"跳下去打泥仗","desc":"你把鞋甩在渠沿上，跳下去，先团了一个泥球。","hint":"回家时你娘认不出你。","tone":"brave","outcome":"你砸中了小漏的后背，她转身追你，两个人滚在泥里。泥灌进领口，凉，滑，一股腥味。打到后头分不清谁是谁，只看见一团团泥在飞。收工的人从渠沿上过，站着看，有人笑出了声。回家母亲在门口把你拦住，拿刷子刷了三遍，刷下来的泥能种一盆花。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":2},"emotion":{"喜":5,"爱":1},"flag":"","thread":""}},{"title":"蹲在渠沿捡螺","desc":"你蹲在渠沿上，把爬上岸的螺一只只捡进篮子。","hint":"底下的孩子骂你不合群。","tone":"steady","outcome":"螺爬上岸是想换水，你捡了半篮。底下的孩子喊你下来，你摇头，他们就朝你泼泥水，泼了你一裤腿。你没下去，把篮子挪远了些。傍晚渠底的人散了，你把半篮螺分给最小的两个孩子，剩下的提回家。母亲煮了一锅，汤是浑的。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":1},"flag":"","thread":""}},{"title":"拉小漏去摸泥鳅","desc":"你下去抓住小漏的手，说摸泥鳅比打泥仗强。","hint":"她摸到一条，捏得太紧。","tone":"family","outcome":"你们两个蹲在渠底最凹的地方，四只手插进泥里，慢慢地摸。泥鳅滑，一碰就钻。小漏忽然叫了一声，手从泥里抽出来，攥着一条，捏得太紧，泥鳅从指缝里挤出半截，尾巴甩了她一脸泥。她愣住，然后笑得坐进泥里。那天摸到四条，养在盆里，第二天全死了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":5,"爱":3},"flag":"","thread":"明年还来摸泥鳅"}}]},{"id":"wu_s02","act":"side","age":[11,11],"mode":"narration","title":"纸屏上的影子","opening":"十一岁那年，母亲让你把一盏修好的灯送到旧闸口顶上的裁缝家。你放下灯，往下看。闸口底下就是影市，灯都蒙着布，只留一条缝，像一排闭着的眼。台阶上坐着个男人，支一面纸屏，屏后点一盏小灯。有人蹲下说话，他就站起来，让灯光把影子投在屏上，拿湿笔沿边描，揭下来递过去。他坐下，你才看清他身后墙上没有影子。有人叫他段七，问影子卖完了怎么办。他说：卖光正好，走路没人跟。","ask":"他朝灯抬了抬下巴，你站不站过去？","days":10,"npc":"","memory":"纸屏上揭下的影子","choices":[{"title":"站到灯前去","desc":"你走下去，站在灯前，让影子落在纸屏上。","hint":"你的肩头从此缺了一角。","tone":"trade","outcome":"他把你的影子描了一张，卖给一个给孩子做伴的老太太。揭的时候你肩上凉了一下，像有人用指甲轻轻刮过。他分给你一小段灯芯，说：拿回去，别说在我这儿站过。回家你照墙，影子右肩缺了一小块。母亲问是不是灯歪了，你说嗯。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"欲":1},"flag":"shadow_notched","thread":"右肩缺了一小块影子"}},{"title":"去叫看渠人","desc":"你提着灯跑下台阶，把看渠人从棚子里叫出来。","hint":"段七的纸屏被踩破了。","tone":"report","outcome":"看渠人提着灯下来，一脚踩在纸屏上，屏破了一个洞。段七没争，收起屏架就走。他从你身边过，看了你一眼，没说话。母亲知道后说：做得对，那种人少沾。第二天裁缝家的灯罩又熏黑了，抱回来修，你看见屏架的竹条靠在渠边，没人捡。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}},{"title":"绕另一条巷走","desc":"你把灯提好，从闸口后头那条窄巷绕过去。","hint":"你一直没有回头。","tone":"avoid","outcome":"那条巷窄，墙上滴着水，灯罩磕了三回。你把灯送到，裁缝家的女人试了试火，说比先前亮。回去的路上你走得很慢，走到岔口站了一会儿，还是走了大路。后来你每回送灯到闸口，都绕那条窄巷，绕了很多年，始终不知道段七后来去了哪。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}}]},{"id":"wu_s09","act":"side","age":[12,12],"mode":"narration","title":"听灯的老周","opening":"十二岁那年，母亲让我把一篮灯芯送到九坊上头的老周家。老周修了一辈子灯，四十岁那年让灯油熏坏了眼，从此不点灯，只接活。他坐在矮凳上，影子被桌上的灯推到墙上，比人还高。桌上排着七八盏别人的灯，盏盏都亮着，屋里却没有一盏是给他自己点的。他拿一根铜片贴在灯罩上听，听完把灯转半圈，说：这盏芯歪了。他把灯递给我，让我看。我看了半天，什么也没看出来。","ask":"他问我火苗什么样，我照实说吗？","days":10,"npc":"","memory":"铜片贴在灯罩上","choices":[{"title":"坐下说给他听","desc":"你把他的灯全点上，一盏一盏说火苗的形状。","hint":"回家时自家的灯早灭了。","tone":"help","outcome":"你说这盏火苗矮，发蓝，像含着一口水；那盏高，尖上分叉。他听着，手指在桌上跟着比，比你慢半拍。说到天快亮，你嗓子哑了，他的油也见了底。回家母亲站在门口，家里那盏灯早灭了，灶是凉的。第二天他托人送来一小截灯芯，剪得齐。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"老周送来的一小截灯芯"}},{"title":"把实话说到底","desc":"你说他上回修的那盏灯，在客人家里冒了烟。","hint":"他把铜片放在了桌上。","tone":"honest","outcome":"他听完，手停在灯罩上，停了很久，说：我知道。第二天他把接的活一盏一盏退回去，铜片搁在桌角，再没碰过。行会来收灯牌，他没争，只问能不能把桌上那几盏修完。来收牌的人说不能。他坐在门口，脸朝着巷子，巷子里有人提灯走过，他也不知道。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"told_zhou_truth","thread":""}},{"title":"收下铜片就走","desc":"你把铜片揣进兜里，说回去想想，再没回去。","hint":"他等到入冬。","tone":"practical","outcome":"铜片贴耳，能听出芯烧到哪一寸，你后来靠它修好了不少灯。老周逢人问起你，就说这孩子耳朵好。入冬后有人来说他屋里冷，你去了一趟，门没锁，人已经硬了，桌上还摆着那七八盏灯，盏盏擦得干净，一盏也没点。铜片还在你兜里。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"欲":1},"flag":"","thread":"铜片还在你兜里"}}]},{"id":"wu_x04","act":"side","age":[12,12],"mode":"narration","title":"系风大所致","opening":"十二岁那年冬天，坊里发的灯油薄了一层。点起来先是一阵噼啪，像有人在芯里撒了豆子，然后火苗窜高，灯罩上炸开一道口子，一股焦味顺着墙爬。当夜，半条巷的灯都炸了，碎瓷扫出去三簸箕。第二天钟警来查，挨家看灯罩，看得很快，进门扫一眼就走。查到巷尾，他说：油没错。有人问那为什么炸，他说：你们的灯太旧。他发下纸笔，叫每户写一份灯爆说明，有范本，范本头一句是：系风大所致。母亲不识字，让你抄。你抄到第三份，抬头看了看窗外。","ask":"范本上写着系风大所致，抄不抄？","days":30,"npc":"","memory":"写着风大的纸","choices":[{"title":"照范本抄","desc":"你一笔一笔照抄，连范本上的错字也照着写。","hint":"钟警夸你家字工整。","tone":"obey","outcome":"你连范本上那个写错的字都描了一遍。钟警收纸时翻了翻，说你家字工整，还在巷口念了一遍。念到系风大所致，旁边有人笑，笑完也回去照抄。那年冬天巷子里炸了十九盏灯，交了十九份说明，十九份都写着风大。开春油好了，没人再提。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"恶":3},"flag":"","thread":""}},{"title":"在纸背画一盏灯","desc":"你在纸背面画了一盏炸开的灯，画得很细。","hint":"钟警把纸翻过来看了很久。","tone":"rebel","outcome":"你画了灯罩上的裂口，画了溅在墙上的油点，画了自己被熏黑的手指。钟警把纸翻过来，对着灯看了很久，问你谁画的。你说我。他把纸折起来收进袖子，没说话，走了。第二天行会来人换了一缸油，说是上一批存久了。没人提那张纸。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"恶":2},"flag":"","thread":""}},{"title":"把范本贴到墙上","desc":"你趁夜把范本贴在行会门口，用灯油粘的。","hint":"第二天全巷都去看。","tone":"defy","outcome":"纸贴得歪，油把字洇开一片。第二天一早，行会门口围了半条巷的人，有人念，有人笑，有人拿指头点着风大两个字。钟警来撕，撕了半张，剩下半张贴在墙上，风一吹，哗啦响。母亲知道了，把你关在屋里一天。傍晚她端饭进来，说：贴就贴了，别让人看见你的脸。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"惧":2},"flag":"","thread":"你贴的那半张纸还在墙上"}}]},{"id":"wu_x05","act":"side","age":[13,13],"mode":"narration","title":"柴垛后的三夜","opening":"十三岁那年，巷尾的周二丢了半刻光时。他一个人住，灯牌挂在门后，牌上刻的刻痕被人刮平了一道。他去钟楼问，人家翻册子，说账上是对的。他回来坐在门槛上，手里捏着灯牌，捏了半天，说：我夜里不点灯了。半刻光时够他点三个晚上。他的窗纸从那天起就一直黑着，门缝里透不出一线光，人走过都觉得那屋子比别处冷。你听说了，第二天起就蹲在他家对面的柴垛后头。柴垛有股霉味，蹲久了膝盖酸。第一夜没人。第二夜下雨。第三夜，有个人贴着墙根过来，手里拿着一把小刀。","ask":"那人蹲在周二门口，你出不出去？","days":20,"npc":"","memory":"柴垛后的三夜","choices":[{"title":"冲出去抱他的腿","desc":"你从柴垛后冲出来，抱住那人的腿喊人。","hint":"他反手给了你一拳。","tone":"brave","outcome":"你抱住他的腿，嗓子喊得劈了。他挣了两下没挣开，反手一拳打在你嘴角，血是咸的。左邻右舍举着灯出来，把他按在地上，是周二的侄子。周二站在门口，看清是谁，手里的灯晃了一下。后来侄子被送去暗禁。周二把灯牌上的刻痕用指甲重划了一道，划歪了。","eff":{"bond":3,"health":-2,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"喜":2},"flag":"","thread":""}},{"title":"先记下他的脸","desc":"你缩在柴垛后，等他走了，才去敲周二的门。","hint":"周二问了三遍：看清了吗。","tone":"witness","outcome":"你把那人的鞋、走路的样子、小刀的样子都记住了。周二开门，听你说完，问了三遍：看清了吗。第三遍你说看清了。他点点头，进屋拿了半块糕给你，说：别说出去。第二天他把门后的灯牌摘了，收进柜子。半个月后他搬走了，门后还留着一道钉子的印。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"惧":3,"哀":2},"flag":"","thread":"周二搬走了，门后留着钉子印"}},{"title":"去敲钟警的门","desc":"你跑去钟楼底下敲值房的门，把人叫来。","hint":"钟警来得比贼慢。","tone":"report","outcome":"值房的钟警披着衣服出来，先问你爹是谁，再问哪一坊。等他们提着灯走到巷尾，人早没了，周二的门开着，灯牌扔在地上。钟警看了看，说：没丢东西。就走了。周二把灯牌捡起来，拍掉土，挂回门后。第二天他见了你，说：以后别去了，你还小。他说话的时候没看你。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}}]},{"id":"wu_s15","act":"side","age":[15,15],"mode":"narration","title":"摸出来的三分","opening":"十五岁那年，霍伯来铺子里取灯。他在坊墙上修了四十年街灯，一根长竿挑罩，从底巷排到钟楼底下。四十岁那年他欠三刻光时，罚了暗禁，眼睛就是那年坏的。退牌后他把拆下的旧街灯收在屋里，一盏一盏擦。这盏是他头一回交到别人手上。进门不用人扶，先摸门框，再摸桌沿。他把灯捧起来掂了掂，往灯口里探，捏住芯头捏了捏，说：剪短了三分，省油。他的影子被灯推到墙上，那只手一直没动。","ask":"他问：这盏灯还算不算我修的？","days":10,"npc":"","memory":"剪短的三分芯","choices":[{"title":"说算，换整根新芯","desc":"你说算，回柜取出攒的整根芯，当他面换上。","hint":"你家这月的灯要短一截。","tone":"warm","outcome":"换芯时他一直听着，听见你把旧芯丢进废料盒，说：留着，还能点一炷。你没留。他抱着灯走到门口，回头说：省下的三分，客人看不见，天黑的时候他自己知道。那个月你家的灯烧的是剪剩的短芯，蓝了三回，母亲把灯挪得离墙远些。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":3},"flag":"","thread":""}},{"title":"收走他的刻刀","desc":"他要在灯座上刻自己的姓，你按住刀，说退牌的人不许留名。","hint":"他的手在桌沿停了一会儿。","tone":"rule","outcome":"行会的规定写在灯册第一页：退牌的人留名，出了事算铺子的。你把刀收进抽屉，说这盏灯以后署我的名。他点点头，把灯抱起来，抱得很稳。走到门口他停住，问：我修了四十年街灯，一盏都不算？你说：规矩。他哦了一声，鞋底在门槛上蹭了两下，走了。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"took_huo_knife","thread":"他没刻成的那个姓"}},{"title":"留他在铺里听灯","desc":"你请他每日来坐，把修好的灯一盏盏递到他手上过一遍。","hint":"行会迟早会问这个人是谁。","tone":"help","outcome":"他来了一个冬天，每天午后到，先摸门框。你修好的灯先给他过手，他捏芯头，听油滚，说哪盏还差半分。客人的灯经他手，一年没出过事。开春行会来人查铺子，问他是谁，你说是我师傅。他站在旁边，手垂着，没说话，等人走了才说：我担不起这句。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":2},"flag":"called_huo_master","thread":""}}]},{"id":"wu_x06","act":"side","age":[15,15],"mode":"dialogue","title":"雨房四十页","opening":"十五岁那年，抄漏房来了个新人。他是花了钱顶进来的，长得周正，走路带风，袖子甩得响，就是不识字。头一天抄册，屋里只有一盏灯，灯罩熏得发黄，他把漏字抄成了雨，一抄抄了四十页，页页工整。小漏回来学给你听，学得眼睛弯：那人还问管事，说雨房是不是新设的，他怎么没听说过。那卷册子送到司昼院，管事的翻了半天，问雨房在哪一坊，底下人答不上来，一路问下来，问回抄漏房。管事的气得脸发青，新人还挺高兴，说自己抄得快，一天抄了四十页。管事把册子合上又打开，最后只说了一句：先放着吧。","ask":"新人让你替他瞒，说请你吃糕。","days":60,"npc":"sibling","memory":"抄成雨的四十页","choices":[{"title":"教他写这个字","desc":"你蘸水在桌上写漏字，一笔一笔教他。","hint":"他学到第七天才会。","tone":"teach","outcome":"你写一撇，他写一撇，撇总是歪的。学到第三天，他把漏写成陋，第四天写成露，第七天终于写对一个，高兴得拍桌子，墨溅了你一脸。后来他抄册还是慢，一天只抄十页，抄得比谁都细。管事的骂他，他就笑。第二年他娶媳妇，喜帖上的漏字写得端端正正。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"爱":1},"flag":"","thread":""}},{"title":"让他去认罚","desc":"你说这瞒不住，让他自己去管事的那儿说。","hint":"他被扣了半年光时。","tone":"honest","outcome":"他站在管事面前，把雨房的事说了，说完还补一句：我抄得快。管事的气得把册子摔在桌上，罚他半年光时，从灯牌里扣。他出来时脸是白的，看见你，还是笑了一下，说：早说早好。那半年他每天散值后去渠边替人扛料，人瘦了一圈。","eff":{"bond":1,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"喜":1},"flag":"","thread":""}},{"title":"替他把四十页改了","desc":"你留下来，把四十页雨字一页页刮改成漏。","hint":"天亮时你的手端不住碗。","tone":"help","outcome":"改一个字要刮掉一层纸，刮轻了看不清，刮重了破。你改到后半夜，指头上磨出两个泡。新人在旁边替你掌灯，掌到睡着，灯一歪燎了他的袖子。天亮时四十页改完，看不太出来。管事的翻过去，说这卷抄得好。新人请你吃面，把碗里的蛋夹给你，说：我不爱吃。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"喜":2},"flag":"","thread":"他欠你四十页的字"}}]},{"id":"wu_s03","act":"side","age":[16,16],"mode":"narration","title":"灯罩里的孩子","opening":"十六岁那年冬天，你替母亲去漏底渠边收一盏旧灯。渠水比外头温，冒着一层白气，漂着灯芯草的碎屑。你蹲下够那盏灯，听见水声底下有别的动静，细，断断续续，像猫。渠壁凹进去一个洞，洞里搁着一只破灯罩，罩里裹着一块灯布，布里是个孩子，脸冻得发青，嘴还在动。灯罩边上压着半截灯芯，没点过。你把他抱起来，他轻得像一只空灯罩，渠壁上你的影子被水汽糊成一片。","ask":"孩子在你怀里轻得像空灯罩，抱去哪？","days":15,"npc":"","memory":"灯罩里的孩子","choices":[{"title":"抱回铺子里","desc":"你把孩子裹进怀里，一路小跑回修灯铺。","hint":"家里的灯从此要挪到墙角。","tone":"carry","outcome":"母亲接过孩子，先摸嘴，再摸手脚，叫你去热米汤。父亲回来在门槛上坐了很久，说：又添一张嘴。第二天他去司昼院，把孩子记在一个死了多年的姑婆名下，回来时鞋上全是泥。那盏家里的灯从此挪到墙角，罩子朝外，怕晃孩子的眼。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"took_foundling","thread":"孩子记在一个死人的名下"}},{"title":"抱去钟楼登记","desc":"你抱着孩子走到十二钟楼底下，交给值夜的小吏。","hint":"小吏问了你家的灯牌号。","tone":"rule","outcome":"小吏把孩子放在一张矮桌上，翻册子，问你的名字、住哪条巷、家里几口人、灯牌几号。你一一答了。他说：登记在渠籍，长大了送去灯蕨坑。孩子忽然哭起来，声音在钟楼底下撞来撞去。你走出很远还听见。回家母亲问你的手怎么这么凉，你说水边风大。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}},{"title":"放在有灯的门槛上","desc":"你抱着孩子绕到亮着灯的巷子，放下一家门槛上，敲了门就走。","hint":"你躲在拐角，看见门开了。","tone":"sneak","outcome":"门开了一条缝，一个女人的影子探出来，先看巷子两头，再低头。她把孩子抱起来，往怀里按了按，回身把门关上，门缝里的光也收进去了。你蹲在拐角等到天快亮，那家的灯一直没灭。后来你每回从那条巷过，都要看一眼门槛。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"爱":2},"flag":"","thread":""}}]},{"id":"wu_x07","act":"side","age":[17,17],"mode":"narration","title":"第三道闸","opening":"十七岁那年夏天，漏底渠的水涨了。上游下了雨，渠水从闸口底下翻上来，带着灯芯草的碎屑和一股沤过的味，闻久了叫人反胃。有人扒着栏杆喊：渠里有个孩子。你探头往下看，看见一团布在第三道闸的水面上打转，一会儿沉，一会儿浮，浮上来的时候能看见一只手。闸门每刻开一次，还有不到半刻。旁边的人都往后退，说水流太急，说这渠吞过人不吐骨头。你把外衣脱下来，搭在栏杆上，掌心里全是汗，栏杆的铁是凉的，凉得叫人清醒。下面那团布又沉下去了。","ask":"闸门还有半刻就开，下不下？","days":10,"npc":"","memory":"第三道闸的水","choices":[{"title":"跳下去抓那团布","desc":"你翻过栏杆跳下去，水没到胸口，脚下打滑。","hint":"你抓住了布，也被水抓住了。","tone":"risk","outcome":"水比想的凉，底下的石头滑得像抹了油。你抓住那团布，是个孩子，脸朝下。你一手抱他，一手去够渠壁上的铁环，够了两下没够着。闸门响了，水往下一沉又涌上来，把你推到栅栏边。有人从上面伸下竹竿，你咬住孩子的衣角，腾出手抓竿。上来时孩子在哭，哭声很响。","eff":{"bond":3,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":2},"emotion":{"惧":4,"喜":2},"flag":"","thread":""}},{"title":"跑去闸房喊关闸","desc":"你顺着渠沿往闸房跑，边跑边喊关闸。","hint":"闸房的人先问是谁让关的。","tone":"tell","outcome":"你跑到闸房，拍门拍得手心疼。里头的人开门，先问谁让关的，再问关哪一道。你说下面有个孩子，他说关闸要有令。你跪下去抱住他的腿，他才骂了一句，去扳绞盘。闸落下去，水缓了。底下的人用竹竿把孩子拨到岸边，那孩子吐了一口水，哭出声来。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"喜":2},"flag":"","thread":""}},{"title":"拆晾衣竿伸下去","desc":"你拆了旁边人家的晾衣竿，趴下伸到水里。","hint":"竿子短了一臂。","tone":"help","outcome":"竿子伸下去，差一臂。你整个人趴在渠沿上，半个身子探出去，后头有人拽着你的腰带。孩子的手碰到竿子，抓了一下，滑了，又抓。第二次抓住了袖子。你往上拖，拖到一半竿子裂了，旁边的人一把揪住孩子的领子。三个人瘫在渠沿上喘。","eff":{"bond":1,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":1},"flag":"","thread":"你拆了人家的晾衣竿"}}]},{"id":"wu_x08","act":"side","age":[19,19],"mode":"narration","title":"一瓶空的午后","opening":"十九岁那年，你在影市买了一瓶昨日午后。摊主说这是从第七坊上头收来的，昨儿午后日头好，光装得足。瓶子是深色的，塞着木塞，晃一晃，里头的砂响，听得人手心发痒。为这一瓶，你攒了三个月的砂才换到手，抱在怀里一路没敢松，怕磕了。回到巷口，你当着几个人的面拔了塞子，瓶子是空的，只有瓶底一层灰，灰是干的，一吹就散。摊主已经跑出三条街。你追，小漏也追，半条巷的人都追，鞋子踩得石板响，有人端着碗也跟着跑，碗里的汤洒了一路。","ask":"人追回来了，瓶子空了，怎么办？","days":10,"npc":"","memory":"一瓶空的午后","choices":[{"title":"把他按在渠沿上","desc":"你把他按在渠沿上，先不打，问他还有没有。","hint":"他哭着说家里还有三瓶。","tone":"collect","outcome":"他趴在地上，脸贴着渠沿的湿石头，说家里还有三瓶，都是空的，瓶底的灰是锅底刮的。围观的人笑开了，有人笑得蹲下去，有人把空瓶当球踢，踢到渠里，漂走了。你没打他。后来他给你扛了半个月的料抵账，扛完蹲在墙根抹脸，说这辈子不骗人了。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"怒":2},"flag":"","thread":""}},{"title":"当街把瓶子砸了","desc":"你把瓶子举起来，当街砸在石板上。","hint":"碎瓷崩了人，赔了半勺油。","tone":"rebel","outcome":"瓶子砸得粉碎，声音很脆。碎片崩到一个老头的脚背，划了一道口子，你赔了半勺油。人群散了，地上剩一堆碎瓷和那层灰。你蹲下去捻了一点，是锅底灰，还带点焦味。回家路上小漏说：三个月的砂。你说：值。她问值什么，你说：砸得响。她笑得直不起腰。","eff":{"bond":2,"health":0,"reputation":-1,"coins":-3,"stats":{"魅力":1},"emotion":{"喜":4,"怒":2},"flag":"","thread":""}},{"title":"让他把灰倒出来","desc":"你让他当着人把瓶底的灰倒在地上，倒干净。","hint":"风一吹，灰全糊在他脸上。","tone":"practical","outcome":"他把瓶子倒过来磕，磕出一小撮灰，风一吹，全糊在他自己脸上，眉毛都白了。周围人笑得跺脚。他杵在原地，眼睛眨巴，不敢擦。你伸手替他把脸抹了一把，抹了一手黑。你说：滚吧。他跑了，跑出十步回头看，看你还站着，又跑。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"恶":1},"flag":"","thread":""}}]},{"id":"wu_s16","act":"side","age":[20,20],"mode":"narration","title":"影市里的豆儿","opening":"二十岁那年，你去影市换半勺油。市在旧闸口底下，灯都蒙着布，只留一条缝，人从缝里过，脸被照成一条一条。你蹲在摊前数灯芯，背后有人叫：豆儿。声音不高，像在自家院里喊孩子。你没回头。她又叫一声，添了半句：豆儿，你娘生你那晚让我剪的芯，我还留着半截。你转过身，看见一个卖时辰的老女人，眼睛只剩一层白，秤盘上叠着别人的影子，方方正正。","ask":"她朝你伸出手，叫第三声豆儿。","days":10,"npc":"","memory":"叫出小名的人","choices":[{"title":"应声，替她还光时","desc":"你走过去应了，问清她欠的三刻，拿自己灯牌抵。","hint":"往后半年，你的灯要早灭一刻。","tone":"warm","outcome":"管市的人把灯牌号抄走，说从下月起扣，扣满三刻。她从秤盘底下摸出一小截灯芯，油纸发黄，芯头是个旧剪口。她说你娘那晚手抖，剪了两回才剪齐。你捏着那半截往回走，一路没点灯。那年冬天你家的灯每天早灭一刻，母亲问过一回，你说油不好。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"answered_childhood_name","thread":"她给的半截旧灯芯"}},{"title":"去叫管市的人","desc":"你退到布帘外，把管市的女人叫来，说她欠光时。","hint":"她被架走时没再叫你。","tone":"report","outcome":"管市的女人带着两个提灯的人下来，翻开她的秤，说她欠三刻，欠了两年。她被架着往暗渠那头走，脚在地上拖出两道印。走到帘口她回头，嘴动了一下，没出声。你站在布帘外，听见里头有人接着秤东西，秤砣磕在盘上，一下，一下。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"只认名字不认账","desc":"你说这名字是我娘起的，账我不认，转身往外走。","hint":"她在后头说了半句什么。","tone":"refuse","outcome":"她没拦。你走出三步，她在后头说：你娘那晚……话头被市上的秤声压住，听不真。你回头，她已经坐回摊子，秤盘上换了一叠别人的影子。往后你还去影市换油，从她摊前过，两个人都当不认识。那句没说完的话，你猜了很多年，猜到自己也老了。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"wu_x09","act":"side","age":[20,20],"mode":"narration","title":"墙上少了一样","opening":"二十岁那年，阿辛把影子卖了。他从前是巷子里最爱笑的人，笑起来能看到后槽牙，隔着两条巷都听得见，修灯的时候也笑，炸了灯也笑。卖影子那天他在影市门口站了很久，进去一趟，出来时手里多了一袋砂，脚下少了一样东西。起初没人看出来，连他自己也不提。后来有一天，几个孩子在墙上比手影，叫他来，他站在灯下，墙上什么都没有。孩子们吓得跑了，鞋掉了一只都没敢回头捡。他自己低头看了看，什么也没说，从那天起就不笑了。巷子里的人起初还逗他，后来也不逗了，见了他只点点头。","ask":"他坐在渠边，你走过去坐不坐？","days":20,"npc":"","memory":"墙上少了一样","choices":[{"title":"坐到他旁边去","desc":"你在他旁边坐下，不说话，陪他看渠水。","hint":"他先走的时候你没拦。","tone":"stay","outcome":"你们坐了半个时辰，渠水上有灯影，一晃一晃。他忽然说：我不是不想笑。说完就不说了。你没接。他的脸在灯下是平的，像没上釉的碗。后来他站起来，说回去了，走的时候脚步很轻，轻得听不见。你坐着没动，直到渠水上的灯影散了。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":"他在渠边说的那句话"}},{"title":"问他换了多少","desc":"你问他换了多少，够不够花，问得很直接。","hint":"他答了，答得很客气。","tone":"ask","outcome":"他说了一个数，说够他娘看病，够到开春。他说得很慢，一句一句，像在背一段别人教的话。说完问你：你要卖吗。你说不。他点了下头，说：别卖。然后就不说了。你后来想，那天他话比平时多，可一句都不像他说的，像有人早早教好了。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"站到灯下比手影","desc":"你学他以前的样子，站到灯下比手影给他看。","hint":"你比了很久，他看得很认真。","tone":"warm","outcome":"你在墙上比了一只兔子，比歪了，像一只瘸腿的狗。他看得很认真，从头看到尾。你又比了一个，手上出汗，影子发抖。他忽然抬手，在墙上比了一下，墙上空空的，什么也没留下。他把手收回去，说：算了。出了巷口，你的影子跟着你，你第一次觉得它碍眼。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"阿辛抬手那一下"}}]},{"id":"wu_s04","act":"side","age":[22,22],"mode":"narration","title":"灭了灯才说话","opening":"二十二岁那年，铺子关到最后一盏灯。有人站在门口，不进，背着光。他说：把灯灭了，我才说。你以为是讨水的，说铺子要关门了。他把一只灯搁在门槛上，灯是好的，罩子擦得干净，里头一滴油也没有。他说：修好它，别点。你说不点怎么修。他往里走了两步，停在灯照不到的角落，说：你修你的，我在暗处说。母亲在里间听见他的声音，把门帘放下了。","ask":"他在暗处坐下，叫了一声阿棠，你应不应？","days":30,"npc":"","memory":"暗处的那一声","choices":[{"title":"应一声，接着修","desc":"你嗯了一声，摸黑拆灯，听他说下去。","hint":"你替一个死人应了声。","tone":"secret","outcome":"他在暗处说话，说这灯是他闺女修的，说她的手一到冬天就裂口子，说灯油味洗不掉。说到一半他叫阿棠，问你手怎么这么凉。你嗯了一声。天亮前他走了。母亲掀帘出来，看见门槛上的灯修好了，问是谁。你说不认识。她摸了摸灯口，说：这灯是阿棠的。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"answered_as_atang","thread":"你替阿棠应了声"}},{"title":"点灯，把话说清","desc":"你划火点灯，照着自己，说我不是阿棠。","hint":"他抬手挡眼，退到门槛外。","tone":"honest","outcome":"光起来的一瞬，他拿手背挡眼，退到门外。你说我不是阿棠，我是修灯的。他站了一会儿，说：我知道。他把灯抱走，走得很慢。母亲掀帘出来，站在门口看他的背影，说：他是阿棠的爹。她说完回屋，半天没点灯。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"把暗铺子留给他","desc":"你披衣出门，把暗铺子和那只坏灯留给他。","hint":"天亮回来，他坐过的地方是凉的。","tone":"alone","outcome":"你在渠边坐到后半夜，水声盖住钟楼的一刻。回来时门开着，人没了，灯修好了，灯口对得很正。案上留着一小截灯芯，剪得齐。母亲坐在里间没睡，问：他走了？你说走了。她说：阿棠修灯，也留这么一截。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"wu_x10","act":"side","age":[22,22],"mode":"dialogue","title":"柜台上的半截芯","opening":"二十二岁那年，铺子里来了个孩子，抱着一盏比他的头还大的灯。灯座裂了，灯罩缺了个角，缺口磨得圆，显然用了很久。灯座上有一圈手印，是常年抱出来的。他把灯放在柜台上，踮着脚推过来，又摸出半截灯芯，放在灯旁边，说：我没有钱，用这个换。灯芯只有两指长，两头都烧过，中间那段是干净的，白得发亮。他手上全是灯油，指甲缝里黑。母亲在里间听见了，说：那半截也是芯，收着。你问他家里谁点灯，他说他娘，眼睛不好，夜里要缝东西，缝一件衣裳要缝三天。","ask":"半截烧过的芯摆在柜上，收不收？","days":30,"npc":"mother","memory":"两指长的半截","choices":[{"title":"收下芯，修好灯","desc":"你把半截芯收进抽屉，坐下修他的灯。","hint":"你贴了一根新芯进去。","tone":"warm","outcome":"灯座用胶和一小片铁皮补的，补得结实。新芯你剪了整根，塞进灯口，剪口朝下压平。孩子看着你剪，问这根多少钱。你说用那半截换的。他想了想，说那根短。你说短的也能点。他抱着灯走，走到门口回头，在门槛上放下一颗糖。","eff":{"bond":3,"health":0,"reputation":1,"coins":-2,"stats":{"魅力":1},"emotion":{"爱":3,"喜":2},"flag":"","thread":"门槛上那颗糖化了"}},{"title":"只修，不收芯","desc":"你把半截芯推回去，说修灯不要东西。","hint":"他跑了，第二天又来了。","tone":"help","outcome":"他把芯攥回去，站在那儿不动，问为什么。你说不为什么。他抱着灯跑了，跑得急，在门槛上绊了一下。第二天他又来了，抱着灯，说灯亮了一夜，他娘缝完了一件衣裳。他把一小把灯芯草放在柜台上，捆得整整齐齐。那把草你用了半个月。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4},"flag":"","thread":""}},{"title":"教他自己修","desc":"你把灯拆开，一样一样教他，让他自己装回去。","hint":"他装反了两次，你没接手。","tone":"teach","outcome":"他手小，拿不住钳子，你就让他用手指按。灯芯装反了两次，第三次装对了，他抬头看你，你点头。灯点起来，光有点歪，照在他脸上。他说：我回去教我娘。你说好。他走后，柜台上的油印子你擦了三遍才擦掉。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"爱":2},"flag":"","thread":""}}]},{"id":"wu_x11","act":"side","age":[25,25],"mode":"narration","title":"一级台阶","opening":"二十五岁那年，你替人往城底送灯，走到第七层底下，那儿还往下。楼梯越走越窄，最后一段是土的，踩上去往下掉渣。一个老头住在渠边的矮屋里，屋子矮得要弯腰进去，屋顶漏，地上摆着三个接水的碗。他姓崔，七十二岁，册上是昼籍。他爹那年在司昼院买了白昼配额，配额记在儿子名下，人就归了昼籍。昼籍不能夜出，出门要牌，他没牌。他一辈子没上去过。他说他见过一次白天，八岁那年，他爹抱他上过一级台阶，就一级。他说这话的时候，手在膝盖上比了个高度。","ask":"他求你带他上去看一眼，带不带？","days":60,"npc":"","memory":"八岁那年的一级","choices":[{"title":"扶他上台阶","desc":"你搀着他，一级一级往上走，走到地面。","hint":"钟警在巷口。","tone":"risk","outcome":"他走得很慢，每一级都要停。走到地面那天没有日门，天是黑的，只有街灯。他站在灯下，仰着头看，看了很久，说：原来上头也黑。他说完自己笑了，笑得咳嗽。上台阶的时候他走不动，你背他。第二天他没起来，第三天也没起来。册上他的昼籍一直没销。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":4,"喜":1},"flag":"","thread":"他上过一次地面"}},{"title":"给他画一个白天","desc":"你在地上用炭画了个圈，说这就是白天。","hint":"他蹲下去摸了很久。","tone":"niche","outcome":"你画了一个圈，圈里画了几道斜线当光。他蹲下去，用手指沿着线摸，摸了一遍又一遍，问：是热的吗。你说热。他把手贴在炭线上，贴了很久，手都黑了。他说：有点像。走的时候他把那圈用脚擦了，说别让人看见。第二年开春他没了，屋里的油还是满的。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}},{"title":"去司昼院问","desc":"你去司昼院问昼籍能不能改，排了半天队。","hint":"窗口的人让你明天再来。","tone":"ask","outcome":"窗口的人翻册子，翻了两遍，说昼籍改夜籍要本人来，还要三份保书。你问本人来不了呢。他说那就改不了。你回去跟老头说，他点点头，说：我爹当年也是这么说的。他从枕头底下摸出一张纸，是他爹留下的配额单，纸都脆了。他让你念，你念到一半，他把纸收了回去。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}}]},{"id":"wu_s05","act":"side","age":[27,27],"mode":"narration","title":"守灵的那一夜","opening":"二十七岁那年，楼上陈嫂的男人走了。他在灯蕨坑下头扛料，夜里回来咳，咳了半年，最后一口没上来。陈嫂来敲你的门，围裙还系着，手上沾着面。她说她得去顶他的夜班，不去，灯牌要收，家里两个孩子就得摸黑。她说：你替我守他一夜，灯不能灭，人不能离。你上楼，屋里收拾过了，他躺在两块门板拼的床上，脸上盖着灯布，脚边点一盏小灯，芯剪得很短。灯把他的影子投在门板上，影子比人长。","ask":"陈嫂把门钥匙塞进你手里，这一夜怎么守？","days":10,"npc":"","memory":"门板上的影子","choices":[{"title":"坐到天亮","desc":"你在门板边坐下，守着灯，隔一阵剪一次芯。","hint":"你自己家那盏灯忘了点。","tone":"stay","outcome":"后半夜你跟他说了很多话，说你爹的腿，说你娘补灯罩的手，说铺子里修不完的灯。说到灯芯只剩一指长，窗纸还是黑的。天亮前你听见他咳了一声，抬头才想起他已经不咳了。陈嫂回来时灯还亮着，她站在门口，没进来，先看了一眼灯芯。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"你跟他说的那些话"}},{"title":"替他上夜班","desc":"你揣上他的更牌，下楼，替他扛这一夜料。","hint":"陈嫂守着他，你替他去黑里走。","tone":"carry","outcome":"更牌上的字磨得快看不清。你扛到第二趟，肩膀就破了。老吴问你他是你什么人，你说邻居。他把最轻的一头让给你。天快亮时你想起楼上那盏灯，不知灭没灭，脚步乱了。后来陈嫂说，那夜她一个人对着门板，连个说话的都没有。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"守到子时就走","desc":"你把灯芯挑亮些，守到子时，锁门下楼。","hint":"那盏灯要烧到天亮，油不够。","tone":"leave","outcome":"你走时灯点得很亮，屋里比平时都亮。第二天早上陈嫂来还钥匙，说灯后半夜就灭了，油见了底。她说没事，人都走了，谁还看得见。她把钥匙放回你手心，指头凉。你后来总想起那盏灯灭下去的时候，屋里大概有多黑。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}}]},{"id":"wu_x12","act":"side","age":[27,27],"mode":"narration","title":"碗底一层水","opening":"二十七岁那年，坊里发的油越来越薄。点起来火苗发黄，灯罩上一层水汽，擦一遍，第二天又有。巷子里的孩子晚上写字，字越写越大，写到后头，一张纸只写得下四个字。有人去行会问，回来说：油是好油，是灯不干净。你不信。你把自家领的油倒进碗里，搁了一夜，第二天碗底一层水，上头一层油，油只有薄薄一片，晃一晃，水就泛上来。你把碗端到行会门口，站在台阶下，没喊，就举着。陆陆续续有人过来，也端着碗，谁也不说话，只把碗举高一点，让灯照见碗底。","ask":"行会的门开了，让你进去说。","days":30,"npc":"","memory":"碗底的那层水","choices":[{"title":"把碗搁在柜台上","desc":"你进去，把碗搁在柜台上，不说话，等他们看。","hint":"他们先问你叫什么。","tone":"defy","outcome":"掌柜的看了碗，说这是你家的碗不干净。你说碗是新的。他笑了，说新碗也有灰。后头跟着进来的人把碗一个一个搁在柜台上，摆了半张台面。掌柜的笑不出来了。那天下午行会换了油，没说道歉，只说上一批进了潮。你出门时，有人在你背后说：这小子记住脸了。","eff":{"bond":3,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"怒":3,"喜":2},"flag":"","thread":"行会记住了你的脸"}},{"title":"请人写一张状","desc":"你去找抄漏房的老先生，请他写一张状子。","hint":"状子递上去，先查的是你。","tone":"report","outcome":"老先生写得一手好字，写完念了一遍，问你想好了没有。你说想好了。状子递到钟楼，三天后来了人，先查递状子的是谁，再查碗是谁家的。查了半个月，油换了一批，你被记了一笔聚众。母亲知道了，把碗收进柜子，说：以后有气，回家摔。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"怒":3,"哀":1},"flag":"","thread":"你被记了一笔聚众"}},{"title":"夜里去堵油车","desc":"你带着几个人守在巷口，把送油的车拦下来。","hint":"车上有行会的印，也有钟警。","tone":"rebel","outcome":"油车半夜进巷，你们把车拦在巷口，掀了桶盖。桶里的油晃出来，泼在地上，映着灯，能看见底下那层水。赶车的说这是给上头的。你们不让走。钟警来了，先看车印，再看你们的脸。最后车退回去了，油也没换成。第二天坊里传话说：这油是给上头的。","eff":{"bond":3,"health":-1,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":4,"喜":1},"flag":"","thread":"油车退回去了，油没换"}}]},{"id":"wu_s17","act":"side","age":[28,28],"mode":"narration","title":"跪在光里的人","opening":"二十八岁那年，日门开在辰时。你挤到第三排，前后都是提灯的人，灯套着布，布底下透出一点红。门缝先白，后金，光斜着扫过来，落在后颈上，像有人把手贴上来。就在这时候，你脚边一个男人跪下去了。他四十来岁，穿灯蕨坑的短褂，两只手把一只空灯盏举过头顶，盏口朝着门。他不出声，只把灯举得更高，胳膊在抖。旁边的人往两边让了半步。","ask":"他跪在光里举着空灯，你怎么办？","days":10,"npc":"","memory":"空盏举过头顶","choices":[{"title":"蹲下替他挡着","desc":"你蹲下，解开外衣罩住他半边，替他把灯举稳。","hint":"钟警会记下你的灯牌号。","tone":"protect","outcome":"光落在两个人身上，他那只空盏里积了一点热，盏底烫手。钟警过来，用棍子挑开你的外衣，记了你的灯牌号，扣半刻。男人抱着灯一路弯腰跑回去，鞋掉了一只也没捡。后来你听说他闺女在黑户的屋里看见小半炷香的光，看见什么，没人问过。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"shielded_kneeler","thread":"记在你灯牌上的半刻"}},{"title":"拉起他罩上灯布","desc":"你抓住他胳膊把他拽起来，把灯布罩上他的灯盏。","hint":"他的手一直没松开。","tone":"rule","outcome":"他跪不住，被拽起来，灯布一罩，盏口那点热就散了。他没争，只说：我闺女十一年没见光。钟警从旁边过去，看了你们一眼，走了。他把空灯抱在胸前，站到日门合上，人群散尽才走。第二年他还在那个位置，还是跪着，你没再过去。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"","thread":""}},{"title":"让出我的位置","desc":"你往旁边退，把他推到自己的位置上，转身出人群。","hint":"这一年你没看见日门开。","tone":"leave","outcome":"他跪在你原来的地方，前头再没人挡。你逆着人流往外走，走到广场边上，听见后头一片抽气声，接着是钟响。你回头看，光是白的，落在别人背上。回家母亲问今年亮不亮，你说亮。她点点头，把灯芯捻小一截。那天你的影子一直落在后头，没跟上来。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"wu_x13","act":"side","age":[30,30],"mode":"narration","title":"落闸下的手","opening":"三十岁那年，日门提前开了三分钟。钟楼还没敲，门缝就白了，广场上的人一齐往前涌。你被夹在中间，脚离了地，往前挪了三四步。前面是门框，铁的门框，门上有一道落闸，平时用来截人，闸沿上全是锈，锈蹭在人的衣袖上。有人喊别挤，喊声被压下去。你旁边一个抱孩子的女人被挤得贴在门框上，孩子从她怀里滑下来，落到人腿中间，一声没哭。落闸就在这时候开始往下走，铁链一节一节地响，声音很慢，慢得能数清。孩子的鞋掉了一只，在人脚上滚。","ask":"孩子在人腿中间，闸往下落。","days":10,"npc":"","memory":"落闸底下的手","choices":[{"title":"把孩子举过头顶","desc":"你蹲不下去，弯着腰在人腿缝里摸，摸到就往上递。","hint":"你的手背被闸沿刮掉一块皮。","tone":"brave","outcome":"你弯腰，在人腿缝里摸，摸到一只小手，攥住。你把他往上提，举过头顶，往外递。有人接住了。落闸擦着你的手背下来，刮掉一块皮，血顺着指缝滴在石板上。门开完，人散开，你才看见那个女人，她被人流带到门那边去了，隔着闸喊。","eff":{"bond":4,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":2},"emotion":{"惧":3,"爱":2},"flag":"","thread":""}},{"title":"用肩膀顶住闸","desc":"你把肩膀塞进闸底，用背顶住，喊人拉孩子。","hint":"你的肩从此抬不高。","tone":"carry","outcome":"你把肩膀塞进闸和门框之间，铁压在骨头上，闷响了一声。你喊：拉孩子。有人蹲下去把孩子拖了出来。闸又往下压了一寸，你的腿软了，眼前一片白。后来是两个人把你从闸底下拽出来的。你的左肩从此抬不高。那个孩子后来长大了，在巷子里见了你，会喊一声叔。","eff":{"bond":3,"health":-4,"reputation":3,"coins":0,"stats":{"体魄":2},"emotion":{"惧":3,"爱":1},"flag":"","thread":"你的左肩抬不高了"}},{"title":"先护住那女人","desc":"你把她往门框边推，让她背靠铁柱站住。","hint":"孩子还在人腿中间。","tone":"protect","outcome":"你把她推到门框边，让她背贴着铁柱，两只手抓着框。她一直在喊孩子，喊得嗓子哑了。落闸下来的时候，人潮往两边分开，孩子在地上，被人踩了两脚，还活着。是个过路的老头把他抱起来的。你站在旁边，手上什么也没有，掌心还保持着抓东西的姿势。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"哀":2},"flag":"","thread":"你手里什么都没抓住"}}]},{"id":"wu_s10","act":"side","age":[31,31],"mode":"narration","title":"渠下的四十盏灯","opening":"三十一岁那年，有人叫我去漏底渠第三道闸下修灯。接活的是个女人，围裙上补了四块布，领我下了十七级台阶，推开一扇包着旧灯布的门。门里是一条长屋，梁上晾着灯芯草，桌上点着四十来盏灯，灯罩都用纸糊过，光不外泄。十几个孩子坐在灯下描字，影子在墙上叠成一片，没有一个交光时。女人说：这里的灯不收光时，谁家孩子要认字，就来。","ask":"她问能不能每月送一桶油来。","days":360,"npc":"","memory":"渠下的四十盏灯","choices":[{"title":"应下每月送油","desc":"你说好，从自家那份油里匀，每月十五送来。","hint":"你家的灯从此短一刻。","tone":"warm","outcome":"你送了三年。头一年用自家的油，第二年掺了灯蕨坑捡的剩料，火发黄。母亲问油怎么少了，你说铺子用。第三年冬天你提桶下台阶，脚下一滑，桶磕在墙上，漏了半桶，你用手把剩下的捧回罐里。孩子们那晚照旧描字，描到很晚，描完把纸压在灯座底下。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":2},"flag":"carried_oil","thread":"你送了三年的油"}},{"title":"去钟楼说一声","desc":"你上到地面，直接去钟楼，说渠下有人私点长明灯。","hint":"四十盏灯，一盏也没留下。","tone":"report","outcome":"钟警下去的时候是亮班。门被撞开，灯布扯下来，光一下子涌到渠壁上，孩子们的手还按在纸上。女人被带走，说是聚众。你站在台阶上头，听见下面有人喊了一声娘。后来那间长屋锁了，锁上生了锈，纸糊的灯罩散在渠边，被水泡烂，没人捡。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"reported_dawn_society","thread":"渠下那一声娘"}},{"title":"抱一盏回铺子","desc":"你挑一盏最亮的抱走，挂在铺子门口当招牌。","hint":"她不问，也不来要。","tone":"greed","outcome":"那盏灯挂在铺子门口，夜里不灭，来修灯的人都说这家有长明灯，靠得住。你的活多了三成。第二年春天你路过第三道闸，台阶上长了一层青苔，门缝里没有光。你想起抱走的那盏灯，灯座底下刻着一个孩子的名字，刻得很浅，被油浸黑了。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"欲":2,"哀":3},"flag":"","thread":""}}]},{"id":"wu_x14","act":"side","age":[33,33],"mode":"narration","title":"墙上的九个圈","opening":"三十三岁那年，第七坊上头的祁府叫你装灯。管家拿着一张图纸，指挥你在一面墙上打九个洞，排成梅花，说这是老爷从旧书上看来的。你打了，砖是青的，一钻一股灰，灰落在靴面上，抖不干净。灯装上去，晚上一点，九个灯罩的光落在对面墙上，九个白圈，一圈套一圈，正对着卧房的门。半夜老爷起来解手，一开门看见墙上九个白圈，一屁股坐在了地上，喊了一声，声音尖得不像他。管家披着衣服跑过来，看见墙，也愣了。管家陪着笑，把老爷扶回屋，回头瞪了你一眼。","ask":"管家让你把灯拆了，你怎么拆？","days":20,"npc":"","memory":"墙上的九个圈","choices":[{"title":"连夜拆了重装","desc":"你连夜拆灯，把九个洞挪到房梁下头。","hint":"管家扣了你半刻光时。","tone":"repair","outcome":"拆的时候管家一直站在梯子底下，催一句，看一眼门。你把九个洞挪到梁下，光朝下打，照地不照墙。装完天快亮了，管家扣了你半刻光时，说耽误了老爷睡觉。你收了工具出门，回头看见祁府的门开了条缝，老爷在里头往外看，看见你，把门关上了。","eff":{"bond":1,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"恶":3,"惧":1},"flag":"","thread":""}},{"title":"说这是好兆头","desc":"你告诉管家，九圈是九九归一，主长寿。","hint":"老爷赏了你，管家脸黑了。","tone":"deal","outcome":"你说得一本正经，还画了个图，说九圈套着，是长长久久。管家半信半疑，去回了老爷。老爷居然信了，赏了你一小袋光时砂，还叫人把卧房的门挪了个方向。管家送你出门，一路没说话。走到巷口他才说：你这个人，嘴比手快。后来祁府再没叫过你。","eff":{"bond":1,"health":0,"reputation":-1,"coins":6,"stats":{"魅力":2},"emotion":{"喜":3,"恶":2},"flag":"","thread":""}},{"title":"把灯罩磨一遍","desc":"你回家把九个灯罩用细砂磨了半夜，磨到透光不刺眼。","hint":"磨砂罩的手艺，你没跟人说过。","tone":"niche","outcome":"你磨到指头起泡，罩子上的光散开，墙上没有圈了，只有一片蒙蒙的亮。第二天装上去，管家看了，说这才像话。老爷那天夜里起来，没摔。过了半个月，祁府的邻家来问你灯罩在哪买的。你说自己磨的。他说：给我也磨九个。","eff":{"bond":0,"health":-1,"reputation":2,"coins":4,"stats":{"智识":2},"emotion":{"喜":2,"爱":1},"flag":"","thread":""}}]},{"id":"wu_s06","act":"side","age":[34,34],"mode":"montage","title":"念不完的信","opening":"三十四岁那年，巷尾阮先生叫你念信。他眼睛坏了，只认声音。儿子在日门做工，一季一封信。这封是脚夫捎来的，压着声说：人去冬没了，信是工友凑钱写的。你进屋点灯。他侧着头听，手捏住你一点袖口，捏到念完才松。他说：我这辈子没见过白天。生在暗班，长在灯下，每回排到队尾，等挤到前头，门就关了。你这才知道，他不是没赶上，是一回也没轮到。信念到最后多一行：下月十六，儿回。","ask":"他问下月是不是真能回，你怎么答？","days":120,"npc":"","memory":"念给阮先生的信","choices":[{"title":"照信念完","desc":"你把最后一行又念了一遍，一个字没改。","hint":"你每季都得来念一封。","tone":"obey","outcome":"他听完，把信叠好，压在枕头下，说下月要买半斤好油，灯点整夜。你走时他送到门口，扶着门框。下月到了，人没来。他又叫你去念旧信，一封一封，念到第三封时说：不急，路上慢。你看见桌上多摆了一副碗筷，筷子头朝外。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把实情说出来","desc":"你放下信，说脚夫讲，日门那边早没有这个人了。","hint":"他从此不叫你念信了。","tone":"tell","outcome":"他听完，手还按在桌沿上，按了很久，指节发白。他说：我知道了。他把信一封一封收进一个木匣，匣子盖不上，用绳捆了。你再去，门是开的，他坐在暗处，桌上没点灯。邻居说你走以后，他再没让人念过信，也没再摆那副碗筷。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":2},"flag":"told_ruan_truth","thread":"他再没让人念过信"}},{"title":"替他写回信","desc":"你回去裁纸，学代书人的字，替他儿子写一封。","hint":"你的字比代书人硬。","tone":"secret","outcome":"你写：工程未完，明年回。念给他听时，他说这一封怎么这样短。你说代书人忙。他把信贴在脸上，闻了很久，说：有灯油味。你说路上沾的。他把信跟别的信放一起，用一块灯布包着。后来每季你都写一封，写到第五封，他已经记不清儿子的字长什么样了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"wrote_letters","thread":"你替人写了五封信"}}]},{"id":"wu_x15","act":"side","age":[35,35],"mode":"narration","title":"两根芯一起灭","opening":"三十五岁那年换班，全坊歇一天。几个人在巷口坐着，比谁的灯芯烧得久，赌注是输的人下渠摸螺，摸不满一篓不算完。你把芯剪得比别人的粗一点，火苗旺，烧得快，第一个灭。第二个是卖豆腐的，他的芯受了潮，冒了一晚上烟，熏得人直躲。最后剩下瞎眼的老周和巷尾的哑巴，两根芯并排烧，一样长，烧到天快亮，一起灭了。两个人几乎同时伸手去护火，手都烫了一下，缩回来。围观的人拍手，也有人喊不算。巷子里的人也不管，各自散了，说天亮再算。","ask":"你输了，渠水凉，下不下？","days":30,"npc":"","memory":"两根芯一起灭","choices":[{"title":"脱鞋下渠","desc":"你把裤腿挽到膝盖，踩着渠底的石头摸螺。","hint":"摸上来的螺有一股泥味。","tone":"grind","outcome":"水凉得钻骨头，渠底的石头滑，你扶着渠壁走。摸了半个时辰，摸了一小篓，还有一只螃蟹，夹了你一下。回去架起锅煮，一巷子的人围着吃，腥得要命，有人吃了两个就不吃了。哑巴吃了最多，吃完打了个嗝，声音很响。第二天你嗓子哑了，哑巴见了你，笑得直拍腿。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":5,"爱":2},"flag":"","thread":""}},{"title":"赖账，请人吃糕","desc":"你不下渠，去铺子里买了两块灯油糕分给大家。","hint":"老周说这账记着。","tone":"dodge","outcome":"糕是隔夜的，硬。老周咬了一口，说这不算。你说算。他把糕举起来，对着灯看，说：糕里有芯。你把糕抢过来看，真有半根灯芯，是铺子里掉进去的。全巷又笑。老周说：这账记着。第二年换班，他先提了这事，你只好下渠，摸了一篓，比谁都多。","eff":{"bond":2,"health":0,"reputation":-1,"coins":-2,"stats":{"魅力":1},"emotion":{"喜":4},"flag":"","thread":"老周记着这笔账"}},{"title":"拉着老周一起下","desc":"你说两个人一起输，拉着老周一起下渠。","hint":"他眼睛看不见，手抓得很紧。","tone":"escort","outcome":"老周抓着你的胳膊，一步一步挪。他眼睛看不见，耳朵灵，说左边有水声，螺在那边。果然一摸一把。他摸得比你快，摸完坐在渠沿上，脚泡在水里，说这水比他小时候凉。一路上他一直哼一段调子，不成曲，哼到巷口才停。那篓螺吃了三天。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":""}}]},{"id":"wu_s18","act":"side","age":[36,36],"mode":"narration","title":"半刻引路灯","opening":"三十六岁那年冬天，影市后巷抬出一个人。管市的人把他放在渠沿上，脸盖灯布，脚上一只鞋。你认得他：段七，二十年前在闸口支纸屏卖影子。后来影子卖光了，人还在，走路没人跟。他身上那盏小灯的芯还是新的，剪得齐。管市的女人翻出一张灯牌、半张纸，说他欠半刻光时，欠了四年。欠着的人不能点引路灯，也不能进化灯房——化灯房在日门西边，一年只开三回。她把灯牌丢进渠里。","ask":"她等着有人认这半刻，你认不认？","days":10,"npc":"","memory":"半刻的引路灯","choices":[{"title":"替他补上这半刻","desc":"你把自己的灯牌递过去，说这半刻记在我名下。","hint":"这半年你家的灯早灭一刻。","tone":"pay","outcome":"管市的人在灯牌上划了一道，说分三个月扣。段七得了一盏纸糊的引路灯，点起来只有豆大。你把灯搁在他脚边，看他被抬进化灯房，墙上没有影子。回家母亲还没睡，问你怎么这样晚，你说市上人多。那三个月你家的灯每天早灭一刻，她没问，只把灯往你这边推了推。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":3},"flag":"paid_duan_seven","thread":""}},{"title":"报作无名尸","desc":"你说不认识他，让管市的人按无名尸登记。","hint":"册子上少了一个名字。","tone":"rule","outcome":"管市的女人点点头，在册上写：无名，男，约四十。灯牌收了，那盏小灯没人要，塞给你。你走出巷子，忽然想起二十年前他描影子时手腕上有一道疤。回家你把小灯点上，灯座底下刻着一个七字，刻得很浅，被油浸黑了。你看了很久，把灯放到柜子最高一层。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"灯座上那个七字"}},{"title":"卖他的灯抵债","desc":"你把那盏小灯拿到当铺，换了半刻，抵他的欠。","hint":"灯座上那个字，你没看清。","tone":"practical","outcome":"当铺的人掂了掂，说铜座还值点。半刻抵上了，段七有了一盏纸糊的引路灯，抬进了化灯房，墙上空着。你捏着当票往回走，走到半路才想起灯座上刻过一个字，当时油黑，没看清。那盏灯后来被人赎走了。赎的人是谁，当铺不说，你也没再问。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"欲":1},"flag":"","thread":""}}]},{"id":"wu_x16","act":"side","age":[37,37],"mode":"narration","title":"门槛外的石墩","opening":"三十七岁那年，铺子门口来了个老太太，眼睛是白的，拄着一根竹竿，竹竿头磨得发亮。她不进门，就坐在门槛外的石墩上，一坐一下午，中午也不回去吃饭。头几天你没问。第五天她开口，说你这铺子里的灯味，像她儿子。她儿子以前也修灯，手上有油，回家一进门，满屋子都是这个味。她儿子十年前去了日门那边，没回来。她说完，把竹竿往脚边挪了挪，说：我不进去，就在这儿坐坐。石墩上有一层灰，她坐下去，衣角沾了。她每天来，来得比铺子开门还早，走的时候天已经黑透。","ask":"她天天坐在门外，你打算怎么办？","days":120,"npc":"","memory":"门槛外的石墩","choices":[{"title":"门口多点一盏灯","desc":"你在门口多点一盏，搁在石墩旁边。","hint":"一个月的油没了。","tone":"warm","outcome":"灯搁在石墩边，不高，正好照到她膝盖。她来的时候会先伸手摸一下灯罩，摸到热的，就笑一下。有时候她带着活来，剥灯芯草，剥得很慢，剥完搁在门槛上就走。一个月下来，油下去得快，你去行会门口站了半天，没舍得买。她再来时，你自己那盏挪远了点。","eff":{"bond":4,"health":0,"reputation":1,"coins":-5,"stats":{"魅力":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":"你为她多点了一盏灯"}},{"title":"请她进来说话","desc":"你扶她进门，让她坐在柜台边，给她讲修灯的事。","hint":"她问的每句话都关于儿子。","tone":"peace","outcome":"她坐在柜台边，手放在台面上，摸到钳子、镊子、剪子，一样一样摸过去。她问你修一盏灯要多久，问你灯芯怎么剪，问手上有油洗不洗得掉。你一一答了。她听完，说：他也这么讲过。她坐了半个时辰，走的时候把凳子推回原处，推得很准。后来她隔三天来一次。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"爱":4,"哀":2},"flag":"","thread":""}},{"title":"说你娘也这样","desc":"你告诉她你娘眼睛也不好，认不清芯，只能靠闻。","hint":"她听完，把竹竿挪了个地方。","tone":"honest","outcome":"她听完，点点头，说：那你要多陪她。第二天她来，把竹竿往门边挪了挪，坐在更靠墙的地方，说：我在这儿，不挡你做活。她坐的位置背对着街，脸朝着铺子里。你修灯的时候偶尔抬头，能看见她的侧脸，眼窝是陷下去的，嘴闭着。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"wu_x17","act":"side","age":[40,40],"mode":"narration","title":"第三百一十七页","opening":"四十岁那年，抄漏房的老韩死了。他在那儿抄了三十年，抄秃了七十多支笔，笔杆都收在一个木匣里，匣盖上用刀刻着年份。你去替他收拾柜子，柜子里是一摞册子，用布包着，布上有霉斑。你翻开最上面一本，纸边发脆，一翻就掉屑。抄到第三百一十七页，有一页是空的，一个字也没有。再往后翻，字又有了。你把那页对着灯看，纸上有压痕，是写过又擦掉的。你认得那个笔迹，是老韩的，横平竖直，收笔带钩。你把册子合上，屋里静得能听见纸自己裂开的声音。","ask":"空页上原先写的什么，问不问？","days":30,"npc":"","memory":"第三百一十七页","choices":[{"title":"把册子交上去","desc":"你把册子包好，送到司昼院，说有一页空了。","hint":"接册子的人翻都没翻。","tone":"report","outcome":"接册子的人接过去，掂了掂，搁在墙角的纸堆上，说：抄漏房的东西，回头统一烧。你说那页是空的。他说：空的就空的。你站了一会儿，看那摞册子，最上头一本的角露在外面，被风翻了一页。你走出去，回头看了一眼，门已经关了。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"","thread":""}},{"title":"自己把那页补上","desc":"你回家拿了笔，照着前后的字，把那页补满。","hint":"你补的字，和老韩的不像。","tone":"secret","outcome":"你补了一夜，写的是那几天的漏记，光时、户名、刻数，一样不落。写完对着灯看，墨色比旁边的深。你把册子包回去，压在柜底。后来有人来查册，翻到那一页，说这页抄得好。你站在旁边，手心出汗。那人走后，你又把册子翻出来看了很久。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"惧":3,"哀":3},"flag":"","thread":"你补的那一页墨色更深"}},{"title":"把那页撕下来","desc":"你把空页撕下来，折好，揣进怀里。","hint":"册子上从此缺一页。","tone":"keep","outcome":"撕的时候纸响了一声，缺口的毛边很明显。你把纸折成四折，揣进怀里，回家压在枕头底下。那页是空的，什么也没有，可你每天都摸一下。半年后纸软了，边角起毛。有一晚你梦见老韩坐在灯下抄册，抄到一半抬头看你，什么也没说。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":"枕头底下那张空纸"}}]},{"id":"wu_s11","act":"side","age":[42,42],"mode":"narration","title":"闸口的三十息","opening":"四十二岁那年，老吴要去喝他闺女的喜酒，叫我替他守一夜闸。闸在漏底渠第二道口，一块铁板，一根绞绳，规矩是每刻开一次，数到三十息就关。关早了，水退回灯蕨坑，泡烂一畦芯草；关晚了，水往第七坊的下巷灌。老吴把更牌塞给我，教我听水声：声音变闷，就是要满。他走的时候换了身干净衣裳，鞋是新纳的，影子在渠沿上拉得很长。","ask":"第三刻，渠里有人拍铁板，你开不开？","days":10,"npc":"","memory":"绞绳上的手印","choices":[{"title":"多开二十息","desc":"你把绞绳多放二十息，让渠里的人爬出来。","hint":"下巷的水漫过了门槛。","tone":"risk","outcome":"爬出来的是灯蕨坑的四个女人，裤腿全湿了。她们刚上台阶，水就翻过渠沿往下巷去，谁家的门板被水推得撞墙。行会来人量了水线，扣了你一季光时。那四个女人里有一个后来给你送过一双补好的袜子，没留名字，袜底纳得密。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"替四个女人担的一季光时"}},{"title":"数到三十就关","desc":"你数得很慢，数到三十，照规矩把闸压下去。","hint":"拍板声响到后半夜。","tone":"rule","outcome":"铁板压下去，水声闷了一下，接着又响。拍板的声音一下一下，慢下来，后来没有了。天亮老吴回来，看了看水线，说：你没多开，对。他蹲在渠边抽了一袋烟，说上回有人多开十息，西头的墙塌了，压死九个。他把烟灰磕在水里，水面浮起一层白。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"惧":3},"flag":"closed_gate_on_time","thread":""}},{"title":"先回家搬东西","desc":"你跑回下巷，把自家的灯和油搬到高处，再回来。","hint":"回来时闸已经自己漂开了。","tone":"practical","outcome":"你把灯、油罐、母亲的牌位都搬到阁楼。回来时绞绳松了，闸板被水顶开一掌宽，下巷已经进了水。你踩在水里把闸压回去，压了半个时辰，膝盖抖得站不住。第二天行会问是谁当的班，你说是我。老吴在旁边看着你，什么也没说。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"老吴什么也没说"}}]},{"id":"wu_x18","act":"side","age":[43,43],"mode":"narration","title":"圆的也得朝南","opening":"四十三岁那年，钟楼下了新规：每户灯罩必须朝南。说是南边来的光正，朝南能省油，还说这是钟楼请人算过的。钟警挨家量，拿一根绳子，一头拴门框，一头拉出去，看灯罩的口朝哪。量到你家，灯罩是圆的，没有口。钟警绕着灯走了两圈，鞋底在砖上磨出声，说：圆的也得有个朝向。你说圆的不分朝向。他说：那就朝南。他掏出册子，笔尖在纸上戳了个点，又抬头看了看你家的屋顶，像是在找一根看不见的箭头。他把册子收进怀里，走的时候在门口停了一下，回头又看了看那盏灯。","ask":"他让你在灯罩上刻个记号，刻不刻？","days":60,"npc":"","memory":"圆的也得朝南","choices":[{"title":"在罩上刻个南","desc":"你用锥子在灯罩上刻了个南字，刻得歪。","hint":"光从那个字漏出去。","tone":"obey","outcome":"刻的时候罩子裂了一道细缝，从南字的一撇一直裂到底。钟警来复查，看了字，说好，记了一笔。那晚点灯，光从那道缝里漏出去，在墙上拉出一条细线。邻居来借火，看见那道缝，说这灯破了。你说：规定。他说：哦。他借了火，回头又看了一眼那条缝。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"恶":2,"哀":2},"flag":"","thread":""}},{"title":"把罩子转半圈","desc":"你把圆罩子转半圈，说这就是朝南了。","hint":"钟警看不出区别。","tone":"dodge","outcome":"你转的时候很慢，转完问他：这样行吗。他拿绳子比了比，说行。他在册上画了个圈，走了。第二天隔壁也转，转完来问你朝哪边。你随手指了一边，他照着转。一个月后整条巷的圆灯罩都朝一个方向，其实哪个方向都一样。有人来查，都合格。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"恶":1},"flag":"","thread":""}},{"title":"问他南在哪边","desc":"你问他南在哪边，请他指出来的。","hint":"他指了半天，指了两个方向。","tone":"ask","outcome":"他先指东边，你说是东。他愣了一下，改指西边，说：这边。你说那是西。他把绳子一收，说：你这人怎么说话。围观的人笑。他脸涨红，在册上写了拒不朝南，走了。隔天来了两个钟警，量了一遍，也没说出个所以然。最后那页册子上，你家灯罩后面画了个问号。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"怒":1},"flag":"","thread":"册上你家灯罩后面有个问号"}}]},{"id":"wu_s19","act":"side","age":[48,48],"mode":"narration","title":"天黑是因为没人点灯","opening":"四十八岁那年，巷子里的灯又少了两盏。日门迟开过那一回以后，钟楼派下来的光时一年比一年薄，入夜只剩三四点光，风一过就晃。隔壁阿荞五岁，她娘在灯油行糊纸袋，常常整夜不回。那天她坐在你门槛上，看你修灯，嘴里嚼着一根没点的灯芯草，嚼得只剩一头。看了很久，她忽然问：天黑，是不是因为没人点灯。她问得很认真，两只手撑在膝盖上，影子投在门槛里头。","ask":"她等着你答，你怎么跟她说？","days":30,"npc":"","memory":"天黑是不是因为没人点灯","choices":[{"title":"带她去点灯","desc":"你提上灯，牵着她，把巷里空着的灯座一盏盏点上。","hint":"回家时你自己的油见了底。","tone":"warm","outcome":"点到第五盏，油只剩一个底。阿荞踮着脚帮你把灯芯拨正，指头烫了一下，缩回去含在嘴里。那晚巷子亮到后半夜，她娘回来时在巷口站住，抬头看了一路。第二天你家没油，摸黑吃的饭。阿荞端一碗汤过来，说：我给你照路。她手里举着一根点着的灯芯草。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"","thread":""}},{"title":"告诉她天本来这样","desc":"你说天不是谁点黑的，它本来就这样，点灯也点不亮。","hint":"她以后不再问这类话。","tone":"honest","outcome":"她听完，哦了一声，把手从膝盖上拿下来，坐了一会儿就回家。后来她再没问过灯的事。她娘说她夜里不再哭着要灯，睡得很老实。有一年巷里点长明灯，别家孩子都挤在门口看，她站在自家门里，隔着门缝看，看了一会儿就把门关上了。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"told_child_darkness","thread":""}},{"title":"挂出她的问话","desc":"你把她的问话写在灯罩纸上，挂在铺子门口，让人答。","hint":"行会的人会来撕这张纸。","tone":"niche","outcome":"来修灯的人看见了，有的写：是。有的写：不是，是灯少。有个老头写了半行又划掉。纸挂了整整一冬，边角被油烟熏黑，答话挤得没处写。行会在巷口钉了块木牌，说铺面不许贴字，撕下纸卷走了。阿荞等他们走远，从袖里摸出一小片纸，说：我抄了一份。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":2},"flag":"","thread":"阿荞抄的那小片纸"}}]},{"id":"wu_x19","act":"side","age":[48,48],"mode":"narration","title":"巷口的长明灯","opening":"四十八岁那年，巷子里抓到一个偷光的，是个二十来岁的后生。他偷的是灯油行门口那盏长明灯，一夜偷了三次，第三次被按住。按规矩要罚暗禁十天，还要在巷口挂牌，牌上写明偷了几次。后生不说话，问他为什么偷，他咬住嘴唇不答，脖子上全是汗。你知道为什么：他妹妹在发烧，家里灯牌早空了，夜里要有人看着。他没说，你也没说。钟警问他认不认，他点头，脖子上的筋绷着，一下一下地跳。巷口那盏长明灯被偷了三次，灯芯短了一截，火苗矮得像要灭。","ask":"钟警问还有谁看见，你站出来吗？","days":60,"npc":"","memory":"巷口的长明灯","choices":[{"title":"说那三夜是我","desc":"你走出来，说那三夜是你偷的，跟他没关系。","hint":"后生看着你，没吭声。","tone":"defy","outcome":"钟警看看你，又看看他，笑了，说：你们两个商量好的？你说没有。他把你名字记下来，说暗禁十天，你去。你进暗禁那天，后生站在门口，一直站着。十天后你出来，眼睛不适应光，墙上的灯一盏一盏往后退。后生在你家门口等着，手里提着一盏灯。","eff":{"bond":4,"health":-3,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"爱":2},"flag":"","thread":"你在暗禁里待了十天"}},{"title":"替他出罚的光时","desc":"你掏出灯牌，说罚的光时你出，别挂他的牌。","hint":"你的灯牌空了一半。","tone":"pay","outcome":"钟警算了算，说光时能抵，牌子还得挂。你说挂我的。他看了你一眼，在册上改了名字。后生那天没说话，走的时候在你门口站了一会儿。牌子挂在巷口三天，上头写着你的名字。路过的人看一眼，有的人笑，有的人不说话。第四天牌子不见了。","eff":{"bond":3,"health":0,"reputation":-1,"coins":-8,"stats":{"魅力":1},"emotion":{"怒":1,"爱":3},"flag":"","thread":"巷口挂过三天你的名字"}},{"title":"把缘由说出来","desc":"你开口说他妹妹在发烧，说完看着他。","hint":"后生的脸白了。","tone":"honest","outcome":"你说完，巷子里静了一下。后生的脸白了，低着头，手在裤缝上蹭。钟警问：真的？他不答。钟警就当他默认，罚减半，牌子照挂。后生挂牌那天，从头到尾没看你。他妹妹后来好了，见你绕着走。你有时候想，那天你要是不说，他是不是还能抬头走路。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"","thread":"他妹妹见你绕着走"}}]},{"id":"wu_s12","act":"side","age":[52,52],"mode":"narration","title":"静下来的三分钟","opening":"五十二岁那年，日门开在午时。广场上挤得转不开身，人人提着灯，到门边就把灯罩上布套。隔壁的瞎眼孩子阿萤十一岁，第一次被带来，手抓着我的袖子。钟楼敲到第十二下，声音停了，广场一下子没了响动。连卖汤饼的都不翻勺，风把谁的灯布吹起来，也没人去按。静得能听见渠里的水。阿萤在我手心里敲了一下，问：来了没有。","ask":"静得能听见水，这三分钟怎么过？","days":10,"npc":"","memory":"手心上的暗号","choices":[{"title":"在他手心敲回去","desc":"一下是没来，两下是快了，光落下来时你按住他的手。","hint":"今年你自己没抬头。","tone":"warm","outcome":"你敲一下，他抿嘴；敲两下，他仰起脸。光落到广场上时，你看见他眼皮动了一下，赶紧把他手按平。他站着不动，脸朝着门那边，鼻翼一张一张。三分钟过完，人群出声，他问你亮不亮。你说亮。他笑了，问明年还来不来。你的影子被光压回脚边。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"told_ayin_light","thread":""}},{"title":"拽住插队的人","desc":"一个后生贴着墙往前挪，你抓住他后领，把他拽回来。","hint":"他怀里的灯摔碎了。","tone":"rule","outcome":"他往后一退，撞在别人身上，灯掉在地上碎了，响声在静里头炸开。半广场的人回头。他蹲下去捡碎片，说替他娘占的位置，他娘腿不好。钟警过来把他带出去。那一年有人说光被这声响惊短了，你走过巷子，有人在背后指，指到你拐弯。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"哀":4},"flag":"","thread":"那一年有人说光短了"}},{"title":"悄悄往前挪","desc":"你扶着阿萤，借着没人动，往前挪了七个位置。","hint":"后头抱孩子的人退了一步。","tone":"sneak","outcome":"你挪到第三排，光落在脸上，热的，眼皮上有一层红。身后有人轻轻嗯了一声，是个抱孩子的女人，孩子被挤得背过脸去。门合上时你回头看，那女人还站在原地，孩子睡着了。阿萤问你刚才怎么走得那么快。你说人多。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"欲":2,"惧":1},"flag":"","thread":""}}]},{"id":"wu_x20","act":"side","age":[54,54],"mode":"narration","title":"说到一半的灯","opening":"五十四岁那年，你收了个徒弟。他十八岁，手大，心粗，学东西快，就是嘴不停。修灯的时候也讲，讲巷口的狗，讲他娘的腰，讲他小时候掉进渠里怎么爬上来。那天他修一盏旧灯，油灌得太满，芯又穿反了，一边讲一边点。火苗从罩子底下窜出来，蓝的，窜得比灯还高。他还在讲，讲到一半，只听嘭一声，灯罩飞了，他的眉毛烧掉半边，脸上黑了一片，头发冒着烟。他张着嘴，停在刚才那句话的中间。你看着他，嘴角自己往上走，想压也压不住。屋里一股焦毛味，像谁把鸡燎了。","ask":"他张着嘴，那半句话还挂着呢。","days":90,"npc":"","memory":"烧掉的半边眉","choices":[{"title":"笑得蹲下去","desc":"你笑得扶着柜台蹲下去，笑到咳嗽。","hint":"他半个月没跟你说话。","tone":"honest","outcome":"你笑得停不下来，扶着柜台直不起腰。他站在那儿，手捂着脸，嘴还张着，半天才把话接上：……就是这么爬、爬上来的。你笑得更凶。他那天收拾东西回家，半个月没来。回来后眉毛长出一层短的，话还是那么多，只是不再边点灯边讲。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"哀":2},"flag":"","thread":"他半个月没来上工"}},{"title":"拉他坐下敷油","desc":"你拉他坐下，拿灯油给他敷脸，说眉毛能长。","hint":"他疼得直躲，你手很稳。","tone":"heal","outcome":"油敷上去，他疼得抽气，你按住他的肩。敷完你说：眉毛一个月就长回来，长回来更黑。他信了，天天照铜片看。第二天他在灯罩上贴了一张纸，写着油七分满，字很大。那张纸贴了三年，纸都黄了。他后来带的徒弟，第一天就被他按在灯前讲这一条，讲得很长。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"喜":2},"flag":"","thread":""}},{"title":"递给他扫帚","desc":"你把扫帚递给他，让他把地上的碎罩子扫了。","hint":"他扫完，站在门口不肯走。","tone":"practical","outcome":"他蹲下去，一片一片捡，捡到一片割了手。你没管，坐在旁边穿芯。他扫完，把碎瓷倒进筐里，站在门口不动，肩膀一抽一抽的。你说：明天再点一次。他说：还点？你说：不点你一辈子怕火。第二天他手抖着划火，点了三次才点着，一句话也没说。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"喜":2},"flag":"","thread":""}}]},{"id":"wu_s07","act":"side","age":[55,55],"mode":"narration","title":"一整夜的灯","opening":"五十五岁那年，灯油行的人叫你去祁府装一盏灯。祁府在第七坊上层，门前的灯牌是铜的，刻着一个祁字。管家领你进后院一间空屋，屋中央摆着一盏半人高的铜灯，灯腹能装一整壶油。管家说：老爷要这灯点满十二刻，一夜，不许灭。你问点给谁看。他说：不给人看，给刚落地的小少爷积福。灯油行的人量了十二刻油，一勺一勺往里灌，灌到灯口平了。那袋漏钱搁在桌上，谁也没数。","ask":"铜灯灌满了油，这火你接不接？","days":15,"npc":"","memory":"十二刻的铜灯","choices":[{"title":"换上自己的灯芯","desc":"你支开管家，把行会配的芯换成自己带来的好芯。","hint":"这个月的灯芯少了一段。","tone":"repair","outcome":"行会的芯是陈的，烧到第六刻就会炸花。你换上自己那根，火苗立得直，屋里亮得能看见梁上的灰。你蹲在灯边看了半个时辰，想起你爹说过，一辈子没点过整夜的灯。管家进来添茶，问你蹲着做什么，你说看火。他说：火有什么好看。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":"一根不留名的好灯芯"}},{"title":"问起灯牌上的名字","desc":"你指着门前的铜灯牌，问管家老爷是不是叫祁九。","hint":"管家看你的眼神变了。","tone":"ask","outcome":"管家说，老爷的名讳不是你能叫的。他顿了顿，又说：老爷年轻时在司昼院做过事，借名的事多了，谁记得清。你想起二十四岁那年，你爹递给你一张纸，上头另一个名字，就是祁九。管家把工钱结给你，让你从后门走。你走出祁府，回头看见那间屋的窗纸后头白得晃眼。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"恶":2},"flag":"asked_qijiu","thread":""}},{"title":"点着就走","desc":"你划火点灯，看火苗站稳，收了工钱就回巷子。","hint":"回家那盏灯，你一直没点。","tone":"practical","outcome":"灯点起来时，屋里一下子没了影子，四个墙角都亮。你退到门口，眼睛胀，缓了一会儿才看清台阶。回家母亲还没睡，在里间问：点上了？你说点上了。她又问：整夜？你说整夜。她哦了一声，把灯芯捻得更小。那晚你家的灯比平时早灭了一个时辰。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"wu_x21","act":"side","age":[57,57],"mode":"narration","title":"油纸里的整根","opening":"五十七岁那年，灯芯又断了货。行会门口挂了牌子，说下月才有，牌子上落了一层灰，显然挂了不止一天。你翻柜子，翻出最后一根，整根的，母亲当年留下的，油纸包着，纸都脆了，一碰掉渣。隔壁的孩子来借火，站在门口，手里端着一盏空灯，灯罩上糊着补丁。他说他娘今晚要赶一件活，明天要交。你把那根灯芯拿出来，放在桌上，看了很久。灯芯是白的，芯身上有一道细细的纹，是搓的时候留下的。你把油纸揭开一角，闻了闻，还是当年的味道，有点像晒过的草。","ask":"整根只剩一根，剪不剪开呢？","days":30,"npc":"","memory":"油纸里的整根","choices":[{"title":"剪成两段","desc":"你把灯芯剪成两段，一段给他，一段留在柜里。","hint":"你没有问自己留的那段做什么。","tone":"warm","outcome":"剪的时候手稳，一刀下去，两头齐。他拿了长的那段，跑回去，跑到巷口回头喊了一声。你把剩下那段用原来的油纸包好，放回柜子。当晚你家没点灯，坐在黑里听隔壁的动静。隔壁的灯亮起来，光从窗纸透过来一点，落在桌上，你伸手在那点光里放了放。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":1},"flag":"","thread":"剩下那半段一直没点"}},{"title":"整根都给他","desc":"你把整根塞给他，说拿去吧，别剪。","hint":"柜子空了。","tone":"help","outcome":"他不敢接，说这根太长。你说长点好，点得久。他接过去，两只手捧着，像捧一条鱼。他走后你把柜子关上，柜底空出来一块，能看见木头上的印子，是那根灯芯压了多年压出来的。你在那块空处放了一颗石子，是那年从渠边捡的，光滑，凉。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":2},"emotion":{"爱":4},"flag":"","thread":"柜底空出一块"}},{"title":"留半根，教他搓","desc":"你剪半根给他，又抓了一把灯芯草教他搓。","hint":"他搓的芯，烧起来冒烟。","tone":"teach","outcome":"他坐在门槛上搓，搓了三根，两根散了，一根粗细不匀。你让他点那根不匀的，火苗歪，冒黑烟，熏得他直眨眼。他说这不行。你说行，省着点用。他把三根都带回去了。第二天他来说，那根歪的烧了一夜，烟是大，可灯没灭。你说：那就够了。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"喜":2},"flag":"","thread":""}}]},{"id":"wu_x22","act":"side","age":[62,62],"mode":"narration","title":"遮光布的一条缝","opening":"六十二岁那年夏天，楼上的老太太们在天台上晒灯罩。天台的边上围着遮光布，布外头就是天。按规定，遮光布不能拉开，拉开了要罚。那天风大，布被吹开一条缝，缝里是黑的，什么也没有。可几个老太太还是凑过去看，一个接一个，看得认真，有人还抬手在缝前挥了挥。有人搬了凳子，有人把灯举高，说要照照看外头有什么。你上去送灯罩，被一个八十多的老太太拉住袖子，让你也看一眼。布被风吹得鼓起来，像有人在外头拿手推，一下一下。她手劲不小，拽得你的袖子都变了形。","ask":"钟警的哨子已经在楼下响了两遍。","days":10,"npc":"","memory":"遮光布的一条缝","choices":[{"title":"凑过去看一眼","desc":"你把眼睛贴在缝上，看了很久，什么也没看见。","hint":"你被挤得差点翻出去。","tone":"seek","outcome":"缝外头是黑的，黑得像灯灭以后那种黑。你看了一会儿，眼睛发花，看见一些自己跑的光点。旁边老太太问看见什么了。你说看见星星。她说胡说，星星是书上才有的。你说那你看。她凑过去，看了半天，说：还真有。两个人趴在布边上，一人看见一片。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":4,"惧":1},"flag":"","thread":""}},{"title":"把布按住","desc":"你伸手把布按住，说别看了，快下去。","hint":"老太太们不听你的。","tone":"steady","outcome":"你按着布，风从缝里钻出来，吹得布鼓起来，按不住。几个老太太从你胳膊底下钻过去看。有个小的，七十三了，腿脚比你利索，先跑到楼梯口，回头招手。你按着布，看着她们一个一个下去，最后自己也下了。第二天那块布换了新的，缝没有了。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":2,"爱":1},"flag":"","thread":""}},{"title":"把灯举到缝外","desc":"你把灯举出去，让光照一照外头。","hint":"光出去就没了。","tone":"defy","outcome":"灯举出去，光在布外头散开，什么也照不见，像泼出去的水。老太太们都不说话了，看着那盏灯。过了一会儿，有人说：费油。你说费就费。又举了一会儿，手酸了，收回来，灯芯短了一截。下楼时，一个老太太拉着你的袖子问：下回还举吗。你说举。她说：那我带油。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":1},"flag":"","thread":"她说下回带油"}}]},{"id":"wu_s13","act":"side","age":[63,63],"mode":"narration","title":"第一次看见火","opening":"六十三岁那年，渠边一户人家叫我送灯。门是两块旧板拼的，进门先要弯腰。屋里没窗，四壁糊着灯布，布上有一块块深色的印子，是多年熏出来的。女人把门闩上，才把桌上的灯布掀开一条缝。她儿子四岁，从生下来就没见过火，只见过布底下的光。孩子凑过去，眼睛刚睁开就哭了，哭得喘不上气，一边哭一边往后退，退到墙角，用手背挡着脸。","ask":"孩子哭得发抖，这盏灯留不留？","days":60,"npc":"","memory":"布底下的一线光","choices":[{"title":"陪着，一层层揭","desc":"你坐下来，把灯布一层层揭，每揭一层就停一会儿。","hint":"你回家时巷门已经落了闩。","tone":"heal","outcome":"揭到第三层，他不哭了，只抽气；揭到第五层，他伸手来够火，影子小小地落在墙上。天快亮时他睡着了，脸朝着灯。你出门晚了，巷门落了闩，钟警记了你的灯牌号，扣两刻。女人送你到门口，说下回不敢再叫你来。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":2},"flag":"brought_light_to_child","thread":"扣掉的两刻光时"}},{"title":"提灯转身就走","desc":"你说黑户点灯要连累整条巷，把灯提起来，闩上门。","hint":"女人在门里说了声谢。","tone":"protect","outcome":"你走在下巷，还听得见那孩子在哭，哭一阵，停一阵。第二个月钟警来查灯牌，下巷有几家被断了三夜光，有个老人夜里起来摔断了腿。女人家的门一直关着。开春你从那儿过，门板上贴了一张新纸，写着此户已迁。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"门板上那张此户已迁"}},{"title":"剪一条缝","desc":"你用灯布罩住灯，在朝墙那边剪一条指宽的缝。","hint":"那条缝留了整整一冬。","tone":"practical","outcome":"光贴着墙走，不朝门。孩子慢慢敢看了，每天坐在墙根，把手伸进那道光里，影子很小，像一只摊开的手。入冬后有一夜，巡巷的钟警看见门缝下有一条亮线，敲了门。第二天那户人家搬走了，桌子还在，灯布叠得整齐，压在灯座上。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}}]},{"id":"wu_s20","act":"side","age":[66,66],"mode":"narration","title":"省下来的三十一根","opening":"六十六岁那年冬天，油又薄了。你坐在灯下穿芯，剪子量了量，往下挪半寸，剪断。剪完没动，看着那截短的——母亲的手势，她剪了一辈子，剪到眼睛坏。她留下的灯摆在桌角，罩上那道裂还在。柜里一只旧罐，装着半年省下的短芯，一根根用纸捻着写了日子，你数过，三十一根。灯把你的影子推到罐子上。有人敲门，隔壁新搬来的女人端着空灯盏，说家里灯牌没办下来，孩子夜里咳，想借火。","ask":"她端着空灯盏站在门口，你怎么办？","days":60,"npc":"","memory":"三十一根短芯","choices":[{"title":"倒空那罐灯芯","desc":"你把三十一根短芯都倒进她灯盏里，说够点一阵。","hint":"你自己接着剪短芯。","tone":"warm","outcome":"她捧着灯盏，说这怎么好。你说拿着，孩子夜里要吃奶。她走几步又回来，把芯拨出一半放回你桌上，说够了。你追出去，她已经拐进巷子。那晚你把拨回来的一半摊在桌上数，十六根，长的长短的短。你点了最短的一根，坐到很晚。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"照册子记她一笔","desc":"你翻开灯册，问她姓名住处，把这一盏记在上头。","hint":"她没有灯牌，钟警会来收灯。","tone":"rule","outcome":"她报了名字，说住在西头第三间。你写完，合上册子，说这是规矩，没牌的人家不能借火。第三天钟警来敲门，把她家的灯收走了，说黑户点灯要罚三夜暗禁。她抱着孩子站在巷子里，没骂你。孩子咳了一夜，第二天你听见那声音换到别处去了。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"recorded_black_household","thread":"她抱着孩子站在巷子里"}},{"title":"剪成两段教她点","desc":"你取一根短芯剪成两段，教她分两晚点，各点一半。","hint":"孩子后半夜还是咳。","tone":"teach","outcome":"她学得很快，两段芯用纸捻好，揣进袖里。走时她说了三声谢。你关上门，坐在灯下，忽然想起母亲生你那晚也是这么剪的，一截今晚点，一截压在枕下。你把手里的剪子放下，又拿起来，把自家那根也剪短了半寸。那晚隔壁的咳嗽声断断续续，一直到亮班。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"你把自家的芯也剪短了"}}]},{"id":"wu_x23","act":"side","age":[66,66],"mode":"narration","title":"门板底下的狗","opening":"六十六岁那年冬天，老吴走了。他比你大五岁，在闸口守了四十年，守到眼睛看不清闸。他没有儿女，屋里只有一条黄狗，狗也老了，走路一瘸一瘸，叫起来声音是哑的。街坊来看了看，说丧事简办，就走了。你留下守夜。灯是行会发的，芯很细。老吴躺在门板上，脚边摆着他那双胶鞋，鞋底磨穿了两个洞，洞是圆的，像两只眼睛。黄狗趴在门板底下，一动不动，尾巴压在身下。你把自己的旧袄脱下来，给它盖上。后半夜下起雨，屋顶漏，水一滴一滴落在灯罩上，滋滋响。","ask":"天快亮了，钟警来收灯牌。","days":20,"npc":"","memory":"门板底下的狗","choices":[{"title":"把灯牌藏起来","desc":"你把老吴的灯牌解下来，塞进自己怀里。","hint":"钟警问了三遍。","tone":"keep","outcome":"钟警问灯牌呢。你说没看见。他看了看门板，又看了看你，没再问。灯牌在你怀里，木头的，还有老吴身上的味。出殡那天你把灯牌埋在坟头边上，土压得很实。黄狗在坟边转了三圈，趴下了。你蹲下去摸它的头，它舔了舔你的手。你把它抱回了家。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":"你把他那条狗抱回了家"}},{"title":"交牌，讨一句话","desc":"你把灯牌交了，问能不能在册上写他守过闸。","hint":"册上只添了两个字。","tone":"ask","outcome":"钟警翻了册子，在最后一行添了闸口两个字，写完把笔一搁，说：行了。你把册子转过来看，那一行很短，前面是名字，后面是闸口，再没有别的。四十年，两个字。你走出钟楼，天是黑的，雨停了。黄狗在台阶下等你，浑身湿透，看见你就站起来，抖了你一裤腿水。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"哀":2},"flag":"","thread":""}},{"title":"守到晌午才起身","desc":"你不走，把灯添满，守着，一直守到天亮以后。","hint":"你的腿麻了，站不起来。","tone":"stay","outcome":"天一直没亮。你守着，看灯芯一寸一寸短下去，雨停了，屋檐还在滴水。快晌午时你试着站起来，腿麻得没有知觉，扶着门框站了很久。黄狗在门口叫了一声。你回头看门板，老吴的鞋还在那儿，鞋底的两个洞，一个比一个大。你把灯吹了，狗贴过来蹭了蹭你的腿。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}}]},{"id":"wu_x24","act":"side","age":[70,70],"mode":"narration","title":"你只说得出热","opening":"七十岁那年，巷子里来了个孩子，五六岁，问他娘白天是什么样。他娘答不上来，想了半天，指了你，说这巷子里数你活得久。孩子跑来问你，仰着脸，手里攥着半块糕，糕上沾了灰。你活了七十年，见过日门开过几十回，见过光落在石板上、落在人脸上、落在水里。你想了想，说：白天是热的。他问：还有呢。你又想了想，手在膝盖上搓了两下，搓下来一点灰。孩子还仰着脸等。他等着，脚在地上蹭来蹭去，蹭出一小片干净的石板。你想起自己六岁那年也问过一个人，那个人怎么答的。","ask":"他还等着，你还能说出什么来？","days":20,"npc":"","memory":"你只说得出热","choices":[{"title":"把知道的都说了","desc":"你说光从门缝里进来，说石板烫脚，说人眯眼。","hint":"他听完，说像灶膛。","tone":"teach","outcome":"你说光是一条一条的，落在地上会晃；说那天的石板烫脚，脱了鞋站不住；说所有人都眯着眼，谁都看不清谁的脸。他听完，想了一会儿，说：像灶膛。你说像。他高兴了，跑回去跟他娘说白天像灶膛。他娘打了他一下，说别胡说。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"哀":2},"flag":"","thread":""}},{"title":"说记不清了","desc":"你说太久了，记不清，让他去问别人。","hint":"他走的时候，糕还剩半块。","tone":"avoid","outcome":"他哦了一声，把糕掰了一半递给你，说那你吃。你接了。他跑了两步又回来，说：那热是像火那样热，还是像汤那样热。你说像火。他点点头，跑了。你把那半块糕捏在手里，捏软了。你其实记得，记得光落在脸上的那一下，像有人拿热手巾捂了一下。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}},{"title":"带他上钟楼","desc":"你牵着他的手，带他往十二钟楼底下走。","hint":"走到半路你走不动了。","tone":"seek","outcome":"你们走得很慢，走一段歇一段。走到第三坊，你的膝盖疼得厉害，坐在人家门槛上。孩子蹲在你面前，问还去吗。你说去。走到钟楼底下，日门关着，门框是凉的。他伸手摸了摸，回头看你。你说：等它开。他说：什么时候开。你说：不知道。他就站在那儿，手贴在门上。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"喜":1},"flag":"","thread":"他说等门开"}}]},{"id":"wu_s14","act":"side","age":[72,72],"mode":"narration","title":"借出去的灯","opening":"七十二岁那年，我把灯借给了一个抱孩子的女人。她说天亮前还，放在巷口石墩上，说的时候孩子在她肩上睡，脸压得扁。天亮了她没来，第二天也没来。那盏灯的罩子上有一道裂，是我自己磕的，别人不一定认得，我认得。没有灯，家里那几晚就早早点上短芯，一碗饭吃完就灭。第七天，我在第三坊的当铺窗里看见了它，摆在最里头，罩子朝外，那道裂对着街。","ask":"灯在当铺窗里，你进不进去认？","days":200,"npc":"","memory":"当铺窗里的裂","choices":[{"title":"认了，转身走","desc":"你在窗外站了一会儿，什么也没说，回巷子去了。","hint":"夜里起身，你摸不准台阶。","tone":"leave","outcome":"你回去把短芯又剪短一截，一晚上只点半个时辰。冬天有一夜你起来添水，脚在台阶上踩空，磕了膝盖，坐了很久才爬起来。后来你不再走第三坊那条街。有人问起那盏好灯，你说送人了，说到这句就停住，不再往下说。","eff":{"bond":-1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"你不再走第三坊那条街"}},{"title":"去钟楼告她","desc":"你说灯是借出去被当的，请钟警按偷光论。","hint":"她抱着孩子跪在当铺门口。","tone":"report","outcome":"钟警查了当票，找到她家。她抱着孩子跪在当铺门口，说男人走了，孩子发热，当的是油钱。灯追回来了，罩子上多了一道新磕痕。她按手印认了罚，孩子在旁边一直咳。你抱着灯往回走，灯很轻，轻得不像话，你换了只手提。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_borrower","thread":"灯罩上多了一道磕痕"}},{"title":"让她来点灯","desc":"你找到她家，说灯给她用，往后每天来替你点一次。","hint":"她来了整整一个冬天。","tone":"deal","outcome":"她每天傍晚来，先把灯点着，再把你的水缸挑满，孩子放在门槛上玩灯芯草。开春她们搬走了，没留下话。你还是每天傍晚把灯摆在桌上，摆到天全黑，才自己去点。听着巷子里的脚步声，你总要先抬头看一眼门。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":""}}]},{"id":"wu_s08","act":"side","age":[74,74],"mode":"narration","title":"教小半认光","opening":"七十四岁那年，阿蕨拄着拐来敲你的门。她比你小一岁，左手食指上一道旧疤，是小时候在灯蕨坑让麻绳勒的。她说重孙小半六岁，夜里总哭，说黑里有东西。她把他推到你面前：你教教他，你眼睛快不行了，手还灵。孩子站在灯边不敢伸手，鼻子先凑过去，闻灯油，闻灯芯草，闻你手上的味道。你想起三十岁那年，母亲闭着眼，也是这样教你。","ask":"小半问，灯灭了，黑到哪里去了？","days":20,"npc":"","memory":"第一次教人认光","choices":[{"title":"教他听灯芯","desc":"你让他闭上眼，把灯芯凑近，听它烧到几寸会响。","hint":"你把最后一根好芯给了他。","tone":"teach","outcome":"他闭着眼，睫毛抖，听见第三声时笑了，说像水开了。你教他用手背试灯罩的热，教他闻油里掺没掺水。到天黑，他能摸出哪盏灯快灭了。他走时把那根好芯攥在手心，攥得发亮。那晚你家的灯烧的是剪剩的短芯，蓝了三次。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"喜":2},"flag":"","thread":"一根攥得发亮的好灯芯"}},{"title":"牵他去巷口看灯","desc":"你牵着他的手，一盏一盏看过去，看别人的灯。","hint":"回来那段路，你歇了三回。","tone":"escort","outcome":"巷口卖汤饼的灯是漏光的纸罩，风一吹，影子在墙上跑。修鞋的灯罩是铁皮的，光只照手底下那一块。你告诉他，灯不一样，黑也不一样。走到巷尾你走不动了，坐在石墩上，他跑去叫人。回来时他提着一盏家里的灯，一路照着你，灯举得太高，照的是墙。","eff":{"bond":4,"health":-3,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":1},"flag":"","thread":""}},{"title":"告诉他灯要买","desc":"你说光是用光时换的，家里点不起整夜，得学会在暗里睡。","hint":"他不哭了，阿蕨看了你很久。","tone":"honest","outcome":"小半点点头，问一刻是多长。你拿灯芯比给他看，这么长，一刻。他把手比成那么长，收进袖子里。阿蕨在门槛上坐下，说：他爹小时候也这么问过。孩子没再哭，夜里抱着一小截灯芯睡。阿蕨走时没回头，拐杖点地的声音一下一下，出了巷子。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":""}}]}]},"借寿渡":{"no":3,"name":"借寿渡","subtitle":"用我的日子，换你多留一天","through":"祖母用剩下的日子换你活下来。你身上有别人给的时间，一生都在决定要不要也把自己的一部分给出去。","cast":[{"id":"grandma","name":"阿婆","role":"烧契人","tag":"祖母"},{"id":"father","name":"渡生","role":"摆渡人","tag":"父"},{"id":"sibling","name":"纸鸢","role":"糊纸","tag":"妹"}],"main":[{"id":"jie_m01","act":"main","age":[0,0],"mode":"montage","title":"雾夜的一盏灯","opening":"你生在渡口的板屋里，那夜河上起雾，两盏灯只亮了一盏。父亲在对岸，船到河心就看不见水牌。阿婆把自己备下的寿衣拆了，改裹成一件小袄，袖子太长，掖了两折。她抱着你在岸边等船，雾贴在脸上，凉得像湿布。有个赶夜路的人从雾里过，问：抱的什么？阿婆说：抱的是三月初七，卯时。天亮前父亲才把船撑回来，灯罩是湿的。他看见你，没说话，先把船缆在桩上绕了三圈。","ask":"满月那夜你哭个不停，最后在谁怀里睡着？","days":30,"npc":"","memory":"雾夜的一盏灯","choices":[{"title":"抓住阿婆的袖口","desc":"阿婆把你抱到灰契台边，你攥着她的袖口睡沉。","hint":"契角上留下你的手印。","tone":"family","outcome":"你攥着她的袖子睡了一夜。袖里有一张折好的契纸，被汗浸软，角上留下一块淡黄的印。阿婆没换新的，往后每次烧契前，都先摸一下那个角。父亲夜里回来，站在门口看了一会儿，没进来抱你。第二天他出船，把缆绳多绕了一圈。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"惧":1},"flag":"","thread":""}},{"title":"让他去修船","desc":"父亲把你放回炕上，去换船底那块糟板，你哭到嗓子哑。","hint":"他天亮前就走了。","tone":"practical","outcome":"父亲把你放进阿婆怀里，蹲到船边拔钉子。那块板糟了半截，一拔就碎。你哭到嗓子哑，阿婆抱着你在岸边走，走到鸡叫。船修好了，他天亮前就出了船，回来时给你带了一小块麦芽糖，糖化了，粘在纸上。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":2},"flag":"","thread":""}},{"title":"伸手去够那盏灯","desc":"你从阿婆怀里探身，把岸上那盏灯的灯罩碰歪。","hint":"手背上烫出一粒泡。","tone":"seek","outcome":"灯罩歪了，光扫到河心。雾里有人应了一声，是父亲在船上。他循着光把船撑回来，船头撞在桩上，闷响一声。你手背上烫出一粒泡，阿婆用唾沫抹了抹。那盏灯的罩子从此都是歪的，谁也不去正它。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":1,"惧":2},"flag":"","thread":""}}]},{"id":"jie_m02","act":"main","age":[3,3],"mode":"dialogue","title":"灰契台的火","opening":"三岁那年入秋，你烧起来。先是手脚凉，后来说胡话，说灶台上的灰在动。郎中来过，留下三包药，说看今晚。父亲一盆一盆地端河水，用布擦你的手心。阿婆翻柜，翻出那件小袄裹住你，袄襟上还有去年的米汤印。她的手在你额头上按了按，起身往渡口西头去了。灰契台的石头被火烤得发黑。你从门缝里看见一点火光，很小，像一粒豆。","ask":"火还在烧，你从床上爬起来做什么？","days":10,"npc":"grandma","memory":"烧到名字那一下","choices":[{"title":"扑过去拉她的手","desc":"你从门缝爬出去，抓住她烧契的手往后拽。","hint":"火舌舔了你的手背。","tone":"protect","outcome":"契烧歪了，三年只借成一半。你的手背留下一块亮疤，阿婆的袖子烧穿一个洞。往后每逢阴天你咳嗽，她就把手按在你手背上，一按就是半宿。那块疤一直在，像一小片没化开的蜡。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":""}},{"title":"喊爹去拦她","desc":"你哭喊起来，父亲赤脚冲出去抢那张契。","hint":"阿婆三天没跟他说话。","tone":"tell","outcome":"父亲一把把契从火里抓出来，火苗断在中间，纸少了半张。你的烧当夜就退了。阿婆蹲在地上捡那些纸角，捡了很久。她左手被火燎起一串泡，后来那只手一直不太听使唤。她三天没跟你父亲说话，第四天让他把船缆重新系了一遍。","eff":{"bond":-3,"health":1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"阿婆的左手一直不利索"}},{"title":"闭上眼装睡","desc":"你缩回被里，听见她进门，赶紧把眼睛闭上。","hint":"你知道了她不让人知道的事。","tone":"secret","outcome":"她回来时身上有灰味。她以为你睡着，蹲下来摸了摸你的额头，从柜底摸出一个蓝布包，把东西塞进去，又推回最里头。蓝布包的一角露出半张空契，一个字也没写。你一直没问。那个角上的蓝线，你记了一辈子。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":1},"flag":"saw_blank_contract","thread":""}}]},{"id":"jie_m03","act":"main","age":[7,7],"mode":"narration","title":"纸寿巷的秤","opening":"阿婆带你去纸寿巷买契纸。巷子窄，两边墙上晒着纸人，风一吹，纸人的袖子一起动。写寿人的桌子摆在巷口，桌上一杆小秤，秤钩上挂一只铜盘，盘底磨得发亮。一个瘦男人坐在板凳上，卷起袖子，把手按在黄纸上，人都叫他陈三。写寿人往秤盘里放纸钱，秤杆慢慢平了。陈三说：十二年。写寿人就在契上写：十二年。巷口站着个穿绸的陌生人，不进来，只伸出一只手。阿婆把你的头按低，说：看路。","ask":"那张契烧到一半，你要做什么？","days":20,"npc":"","memory":"纸寿巷的铜盘","choices":[{"title":"按住陈三的契","desc":"你挣开阿婆，跑过去把陈三的契按住，说别卖完。","hint":"契角多了一个小印。","tone":"protect","outcome":"火烫了你的手，写寿人把你拨开，契已经烧掉一个角。他看了看你，笑：小保人。他蘸了印泥，把你的拇指按在剩下的纸角上。阿婆冲过来扯你，脸白得像纸。回家她用皂角给你搓手，搓掉一层皮。多年后你在契库看见那张契，角上那个小印还在，模糊得像一粒灰。","eff":{"bond":-2,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"哀":2},"flag":"bearing_witness_mark","thread":"契角上有你的指印"}},{"title":"大声问他生日","desc":"你走到陈三面前，问：你卖了日子，谁给你过生日？","hint":"那笔买卖没做成。","tone":"ask","outcome":"穿绸的人皱了皱眉，把手收回去，走了。陈三蹲在墙根，说：腊月十九。阿婆把这道记在灶砖上。那年冬天他没熬过去。阿婆说不是你的事，可你总记得他那只磨穿的鞋，后跟露着灰白的袜子。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"你替一个卖寿的人记生日"}},{"title":"拉阿婆往回走","desc":"你拽着阿婆的衣角往回走，不敢再回头。","hint":"你记住了他磨穿的鞋跟。","tone":"escape","outcome":"阿婆由着你拽，走得很快。到巷口她停下来，回头看了一眼，说：看过了就记住。你只记得陈三的鞋。那天晚上你把脚缩在被子里，不敢伸出去。此后很多年，你见人先看鞋。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":1},"flag":"","thread":""}}]},{"id":"jie_m04","act":"main","age":[12,12],"mode":"dialogue","title":"三月初七","opening":"纸鸢蹲在门槛上糊纸鸢，举起来给你看，笑得让人心里发酸。阿婆开始忘事：忘锅，水烧干三回；忘关风门；忘了你爹的名字，管他叫撑船的。她从纸寿巷回来，站在门口看你，问：你是哪家的孩子？可到了三月初七，天没亮她就起了，煮一个鸡蛋，用红纸染了，放在你枕边。她说：三月初七，卯时，七斤二两，昨夜下雨，船上湿。你剥鸡蛋，红纸染了手指。她忽然又问：你是谁家的？","ask":"她又问你是谁家的，你怎么答？","days":30,"npc":"grandma","memory":"红纸染的鸡蛋","choices":[{"title":"说是你家的","desc":"你把剥好的鸡蛋掰一半塞给她，说：你家的。","hint":"那天下午你没去渡口。","tone":"family","outcome":"她接过鸡蛋，没吃，握在手心里。半天里她问了你七回，你答了七回。第七回她忽然说：我孙子叫……她卡住了，看着你的脸，说：算了。那天下午渡口招学徒，你没去，第二年才补上。她在门上贴了一张纸，你不认字她也让你念：阿婆的孙子。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"你晚了一年才进渡口"}},{"title":"翻出小袄给她看","desc":"你把那件小袄翻出来，把袖口掖的两折给她看。","hint":"她清醒了一个下午。","tone":"warm","outcome":"阿婆摸着针脚，说：这是我缝的，袖子长，掖两折。她一下想起来了，讲你出生那夜雾大，灯只亮一盏，你爹的船到天亮才回来。她讲了三遍，每一遍都一样。天黑后她又忘了。从那天起，小袄一直搭在她膝上，谁收她跟谁急。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"小袄再没离开她的膝盖"}},{"title":"告诉父亲她忘了","desc":"晚上你把阿婆认不出你的事，一五一十告诉父亲。","hint":"那晚门上多了一道插销。","tone":"tell","outcome":"父亲听完，望着河面站了一会儿，第二天在门外加了一道插销，夜里从外头插上。阿婆拍了一夜门，隔着门板叫你的名字，叫了七遍，每一遍都对。你在门里应她，应到嗓子哑。第三天她用菜刀把插销砍了，谁也没提这件事。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"她砍掉了那道插销"}}]},{"id":"jie_m05","act":"main","age":[16,16],"mode":"dialogue","title":"第一杆秤","opening":"十六岁那年你到渡口做学徒。父亲不肯，说撑船的人脚不沾岸，命都在水上。阿婆说：他手稳。你于是去了。头三个月只烧水、扫地、递印泥。第一回独立称寿在九月，来的是个四十来岁的女人，要给病着的男人借两年。她把手在围裙上擦了三遍，才把寿纸放到铜盘里。秤杆翘起来，翘得很高。父亲站在门外，背对着你，看河面，说：翘是寿重，平了才是数。女人说：借两年。可秤上的数，只够一年半。","ask":"秤上差半年，你怎么落笔？","days":20,"npc":"father","memory":"秤杆翘了半寸","choices":[{"title":"照实写十八个月","desc":"你在契上写下十八个月，把笔搁正。","hint":"她走时在门槛上摔了一跤。","tone":"rule","outcome":"女人盯着那几个字看了很久，跪下给你磕了个头。你去扶，她已经起来了。她说：够了。出门时她在门槛上绊了一下，手撑在泥里。父亲说：你做得对。那晚你睡不着，听见河上有橹声，一直响到天亮。半年后她的男人还是走了，差整整六个月。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"差的那六个月"}},{"title":"把秤往下压半寸","desc":"你一只手扶住秤杆，慢慢往下压，压到平。","hint":"秤记住了这只手。","tone":"protect","outcome":"契上写了两年。女人拿着契出门，走几步又回来，把怀里两个鸡蛋放在桌上。你没要，她放下就跑。那男人多活了半年，开春还能下地。你的右手腕起了一道青，像被绳勒的，两年才退。父亲始终没问。此后你每次称寿，先看一眼自己的手腕。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"惧":3},"flag":"cheated_scale","thread":"手腕上的青痕两年才退"}},{"title":"放下秤去叫师傅","desc":"你把秤杆扶正，说：这契我称不了。","hint":"师傅来称，还是那个数。","tone":"dodge","outcome":"师傅来了，重新挂秤，称了三遍，还是十八个月。他把契写完，递给女人，说：这行手不能软。女人接过契，看了你一眼，那一眼你记了很多年。师傅走后，父亲说：秤不认人，可人得认秤。你没接话。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":""}}]},{"id":"jie_m06","act":"main","age":[22,22],"mode":"narration","title":"蓝布包","opening":"阿婆是秋天走的。头天傍晚她还坐在门口择菜，黄叶一堆，青叶一堆，分得比往常慢。半夜她叫你，说柜底有个蓝布包。你去拿，回来时她已经睡着了，手搭在床沿，掌心朝上。天亮她没醒。父亲从渡口回来，船没靠稳就跳上岸，鞋全湿了。他站在门口，脸朝着河面，说：请人来烧契。烧契人从她袖里摸出一张契，不是空的。上头用铅笔写着一行小字：余寿尽数转予长孙。","ask":"契念完了，谁来点这把火？","days":20,"npc":"","memory":"尽数转予长孙","choices":[{"title":"接火自己点","desc":"你接过火纸，先在引路纸船上写下自己的名字，再点契。","hint":"河上有人叫错你的名字。","tone":"carry","outcome":"名字写上去，纸船推进河心，没沉，顺水走了。契烧完，灰落进石缝里。那年冬天起，巷里人叫你叫不利索，有时叫成别人的名字。你自己也有过一回，站在门口想不起自己姓什么，想了半炷香。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":4},"flag":"gave_name_to_guide","thread":"你的名字留在河上"}},{"title":"把火递给纸鸢","desc":"你把火纸递到纸鸢手里，让她自己送阿婆这一程。","hint":"她烧完去收了阿婆的碗。","tone":"honest","outcome":"纸鸢接了火，手很稳。契烧到名字时停了一停，她等它自己卷，一点没催。烧完她把灰扫进河里，转身去收阿婆的碗。那只碗她收了很多年，一直放在自己柜里。此后她没再提过长孙两个字，也没问那行字是什么时候写的。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":1},"flag":"","thread":"她再没提过长孙两个字"}},{"title":"把契收进怀里","desc":"你从烧契人手里抽回契，折好塞进怀里，说等等。","hint":"你揣了三天才烧。","tone":"keep","outcome":"烧契人说：不烧，她的寿就散在河上，谁也接不住。父亲看着河面，说：随他。纸被体温焐软，边角起毛。第四天夜里你自己去灰契台烧了，没人看见。灰装进一个小布袋，压在柜底。那年冬天你总梦见门口有人在择菜。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"柜底有一小袋灰"}}]},{"id":"jie_m07","act":"main","age":[27,27],"mode":"dialogue","title":"改过的名字","opening":"纸鸢二十四岁那年，河对岸糊灯笼的人家来提亲，来了两回，第二回带一包桂花糖。亲事说得差不多，男方家托人问一句：姑娘名下还有多少寿？父亲不懂这些，来问你。你在契库翻了一夜，翻出一张旧契：借寿三年，保的是阿婆，出寿那一栏原本空着，后来填了纸鸢的名字。填字的笔迹你认得，她小时候学写字，横总是往上挑。那年她十九，阿婆病得起不来床。","ask":"这张旧契摊在灯下，你怎么办？","days":30,"npc":"sibling","memory":"她改过的名字","choices":[{"title":"划五年到她名下","desc":"你在契库另写一张转寿契，划五年给纸鸢。","hint":"她出嫁那天袖口响。","tone":"carry","outcome":"你按了印，把底档压在最底下。她的名字下面多了五年，够办一份体面的嫁妆。她出嫁那天穿红袄，袖口是旧纸糊的，走一步响一下。你没告诉她。三年后她生了个女儿，请你起名。你想了想，说：叫小满。她笑起来，说：这名字好，不欠谁的。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"gave_years_to_sister","thread":"她不知道那五年是谁给的"}},{"title":"把旧契摊给她看","desc":"你把那张旧契摊在她面前，问她为什么改。","hint":"她第一次没笑。","tone":"honest","outcome":"她看了很久，笑起来，说：我那时候手抖，把寿字写成了受。你别管。她说完把契折好，塞回你手里，转身去熬浆糊。那天她没再笑。提亲的人第二天来问，她说：不嫁了。父亲在门口看河面，一句话没说。她后来一直没嫁。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"她后来一直没嫁"}},{"title":"夜里把旧契烧了","desc":"你趁夜把旧契从契库抽出来，在灰契台烧掉。","hint":"烧了档，她名下就干净了。","tone":"secret","outcome":"烧契人说：烧了档，人就真没名了。你说：她本来也不想要这个名。第二天你告诉提亲的人，纸鸢名下没有寿，也没有债。婚事成了。她嫁过去第三年，渡警来查旧档，问起一张缺号的契。你说不知道。那晚你在灰契台坐到天亮。","eff":{"bond":3,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"burned_sister_record","thread":"契库少了一张旧档"}}]},{"id":"jie_m08","act":"main","age":[35,35],"mode":"narration","title":"买寿的人","opening":"三十五岁那年，有个穿绸的人到渡口找你。他不坐船，站在岸上，鞋底没沾泥。他说家里老太太要过八十大寿，缺八年。他报了一个数，那个数够你把旧船换三条，够给纸鸢置一份嫁妆，够把阿婆的坟修成石头的。他把一沓阳楮压在秤盘上，秤杆一下沉到底。你看着那杆秤，秤钩还在轻轻晃。他说：我打听过，你身上有别人给的日子，多出来的，卖一点不亏。","ask":"他把秤压住等你回话，你怎么回？","days":15,"npc":"","memory":"秤盘一下沉到底","choices":[{"title":"把秤盘扫翻","desc":"你一把把秤盘扫翻，阳楮散在岸边的泥里。","hint":"那个数你记了一辈子。","tone":"refuse","outcome":"他没恼，蹲下去一张一张捡，捡完在袖子上擦了擦手，说：打扰了。他走时天快黑了，对岸的灯还没点。你记住了他报的数，不是整数，零头三文。后来有个冬天船漏了，你蹲在舱里算，那个数正好够换三条船，你算完，把橹摔在舱板上。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"惧":1},"flag":"","thread":"你记住了那个价钱"}},{"title":"问他买给谁","desc":"你不接钱，问他这八年买给谁。","hint":"老太太到死不知道。","tone":"ask","outcome":"他说买给老太太，老太太自己不知道。你说：那你回去问问她愿不愿意。他愣了一下，说：她要是愿意，我就不来了。你把秤收进柜里，挂了锁。那个数你还是记住了，零头三文。那年冬天他家老太太没了，八十大寿没办。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"怒":1},"flag":"","thread":"八十大寿没办"}},{"title":"说自己的日子","desc":"你告诉他，你这条命是三岁那年阿婆烧契换的。","hint":"渡警来翻过阿婆的柜子。","tone":"confess","outcome":"他听完，把阳楮收回去，说：那我不买了。你送他上船，他站在船尾朝你拱手。那个数你没忘，零头三文。半个月后渡警来查旧档，问起三岁那年的一张契。契早烧了，查不出，可你被记了一笔。那年冬天的渡牌没发给你。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"told_own_borrowed_life","thread":"你那年没领到渡牌"}}]},{"id":"jie_m09","act":"main","age":[50,50],"mode":"narration","title":"手很稳","opening":"五十岁这年，灰契台的老烧契人死了，钥匙交到你手里。你在渡口称了三十四年寿，烧契却是头一回。你记得他的手式：契纸对折，字朝外，火从下角起，烧到名字时停一停。来烧契的人有的不说话，有的蹲下去数灰。灰落进河里，河面不响。你的手一直很稳。这天来个老太太，六十八岁，穿洗白的蓝布褂，手里牵个五岁的孙子。契上写着六个字：余寿尽数转予长孙。","ask":"她把契推过来，你要怎么烧？","days":60,"npc":"","memory":"手稳得像别人的","choices":[{"title":"称一称，报实话","desc":"你把她的寿纸放上铜盘，称完把数报给她。","hint":"她说四十天够拆洗棉裤。","tone":"honest","outcome":"秤平了，是四十天。你报了数。她想了想，说：够把棉裤拆洗一遍。契照烧，火很稳。她走那天你不在。后来她孙子来渡口，说阿婆的棉裤拆洗过，晒在竹竿上，没来得及缝。竹竿还在那儿，风一大就响。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"棉裤没来得及缝"}},{"title":"从自己名下添十天","desc":"你在契尾添十天，从自己那张空契上划过去。","hint":"你的手指开始发麻。","tone":"carry","outcome":"你没告诉她。她多活了十天，棉裤拆洗、晒干、缝好了，针脚歪歪扭扭。那年冬天你右手两根指头发麻，摸秤星摸不准，只能凑到灯下看，看完再称一遍。老太太的孙子后来每年清明送一包桂花糖，你一次也没吃。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"gave_ten_days","thread":"秤星摸不准了"}},{"title":"把火递给孩子","desc":"你把火纸递给站在旁边的孩子，说：你来点。","hint":"孩子点了三次没点着。","tone":"distance","outcome":"孩子的手抖，火纸掉了两回。老太太弯腰捡起来，自己把契点着了。烧完她拍了拍孙子的手，说：行了，别怕。孩子没哭，一直看着火。你站在旁边，忽然想起自己三岁那年，从门缝里看见的那粒火。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"","thread":""}}]},{"id":"jie_m10","act":"main","age":[70,70],"mode":"narration","title":"抱孩子的人","opening":"七十岁这年，河面又起雾。渡口两盏灯，对岸那盏坏了，只剩岸上一盏。一个年轻人抱着孩子站在岸边等船，孩子裹得很紧，只露出一张脸。他问你：这船过不过河？你说：过。他上船坐在船尾，把孩子往怀里又紧了紧。孩子的脸烧得通红，呼吸很轻，像一只小兽。年轻人说：听说这渡口能买日子。你手里的橹停了一下，船在水上转了半圈。","ask":"他问能不能买日子，你怎么答？","days":20,"npc":"","memory":"裹得很紧的孩子","choices":[{"title":"写自己的八年","desc":"你取一张新契，写上自己的名字和八年，按上印。","hint":"你手背上起了块青斑。","tone":"protect","outcome":"契烧起来，火苗比你的手掌长。孩子当夜退了烧。年轻人跪下磕头，你把他拉起来，说：别记我的名字，记日子就行。那年冬天你开始怕冷，手背上起了一块青斑，按下去是凉的。开春他抱着孩子来，孩子会笑了，伸手抓你的橹。","eff":{"bond":5,"health":-4,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"gave_own_years","thread":"孩子抓过你的橹"}},{"title":"教他自己写","desc":"你把小秤和印泥推到他面前，教他称，教他写。","hint":"他写的是自己的名字。","tone":"teach","outcome":"他学了半夜，称了三回，第三回手不抖了。他在契上写了自己的名字，按印时把印泥按出了格。孩子活了。他抱孩子下船时回头冲你笑，说：够了。十年后孩子来渡口坐船，已经比船桨高，不知道自己身上有谁的日子。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":2},"flag":"taught_father_trade","thread":"孩子不知道自己身上有谁的日子"}},{"title":"劝他别买","desc":"你告诉他，借来的日子要还双倍，还得是孩子还。","hint":"他记住了你说的每个字。","tone":"refuse","outcome":"年轻人抱着孩子下船，没回头。开春你听说孩子没了。第三年他来过一趟，站在岸上问你：那天你为什么不让我买？你说：我拦了。他说：你没拦。他走的时候，怀里空着，襁褓叠得方方正正。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":3},"flag":"","thread":"他说你没拦"}}]},{"id":"jie_m11","act":"main","age":[79,80],"mode":"narration","title":"门板上的日子","opening":"八十岁，你的记性也坏了。先忘船桨放哪，后来忘纸鸢嫁的是哪一家，再后来，你站在渡口，忘了自己为什么站在那儿。可你记得生日。你在门板上用炭写：渡生，腊月十一；纸鸢，五月初五；陈三，腊月十九。写到最后一个，你停了手——三月初七，卯时，那是你的。天黑前你把两盏灯都点上，对岸那盏是你新换的罩子。小袄搭在膝上，柜底蓝布包里还剩一张空契，是阿婆的，契角上有你婴儿时的手印。","ask":"这张空契，你要怎么处置？","days":360,"npc":"","memory":"三月初七，卯时","choices":[{"title":"称一称自己","desc":"你把小秤挂起来，把自己的寿纸放上铜盘。","hint":"秤杆翘着，你没让它平。","tone":"honest","outcome":"秤杆翘得很高，你没往上加，也没往下压。你把空契摊开，写上自己的名字，压在秤下，不烧。烧契人问你为什么，你说：这回我想知道，我到底欠了谁多少。她没再问，把秤擦了擦，挂回梁上。纸鸢看见门板上的数，拿沙子搓了半宿，搓得只剩几个生日。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"weighed_self","thread":"秤下压着你自己的契"}},{"title":"教孩子记日子","desc":"你叫来隔壁六岁的孩子，指着门板一个一个念。","hint":"他记住了三个。","tone":"teach","outcome":"孩子学得慢，把腊月十九念成腊月九。你说重来。教了七天，他记住三个。第八天他跑来问：三月初七是谁？你说：是我。他说：那我记着。他把这四个字念得很快，像背一首没听过的歌。你听见了，转身去添灶，柴塞了三次才塞进去。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":"他答应记着三月初七"}},{"title":"把空契送给他","desc":"你把空契折小，塞进孩子手里，说：拿去记生日。","hint":"那是阿婆留下的最后一张。","tone":"warm","outcome":"孩子拿着空契跑出去，纸被风吹得哗哗响。他问：这上头能写字？你说：能，写谁的生日都行。他跑了半条巷子又回来，说：我先写你的。你说：三月初七，卯时。他记不住，你就又说了一遍。风把纸吹起来，他追了很远，你站在门口看。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":2},"emotion":{"喜":2,"爱":4},"flag":"gave_blank_contract","thread":"空契到了孩子手里"}}]}],"side":[{"id":"jie_s01","act":"side","age":[6,6],"mode":"dialogue","title":"雾天不渡","opening":"那年你六岁，雾从河心往岸上爬，爬过水牌，把对岸那盏灯整个吃了。父亲把船缆又绕了一圈，说雾里看不见水牌，船出去就找不着回来的路。岸上站着个女人，怀里抱一个蓝布包袱，鞋帮湿透，站一会儿换一次脚。她说对岸捎话来，她娘昨夜就不认人了。她把包袱往上托了托，说：我会水。父亲看着河面，没接话。","ask":"雾里那盏灯，你要怎么用？","days":10,"npc":"father","memory":"没人过河的一天","choices":[{"title":"举灯站上船头","desc":"你把灯举到船头，父亲看你一眼，把橹推进水里。","hint":"手心的泡破了，落了疤。","tone":"protect","outcome":"船跟着灯光走，走得很慢。到河心，两盏灯只剩手里这一盏。女人上岸时天已经亮了，回头朝船上点了一下头。你的手心烫出一片白泡，破了，沾了河水，疼了半个月。父亲的船底蹭掉一道漆，他补了一冬。那盏灯的罩子从此更歪，谁也没去正它。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"手心留了一块白疤"}},{"title":"抽掉跳板","desc":"你把跳板抽回岸上，说雾天不渡，转身进屋。","hint":"她没再求你第二遍。","tone":"rule","outcome":"女人在岸上站到天黑。中间她把包袱打开过一次，里头是一双新做的布鞋，底上纳着密密的针脚。黄昏时对岸撑来一只小划子捎信，说她娘卯时走了。她把鞋包好，朝你父亲点了点头，走了。第二天早上跳板还在你屋门口，谁也没去搬。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"跳板在门口放了一夜"}},{"title":"蹲下来陪她等","desc":"你搬个小凳放在她旁边，自己坐在门槛上，不催也不劝。","hint":"你误了那天的早饭。","tone":"wait","outcome":"她坐着，你坐着。雾散得很慢，先露出水牌，再露出对岸的灯。她跟你说话，说她娘会做一种甜糕，蒸的时候要盖三层布。说到第三层布，对岸的划子来了。她站起来，把包袱抱紧，鞋底在泥里陷了一下。你回家时锅里只剩锅巴，阿婆没问你去了哪儿。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"jie_x01","act":"side","age":[7,7],"mode":"narration","title":"糊坏的脸","opening":"纸寿巷的浆糊是糯米熬的，凉了以后有一股微酸的甜味。阿婆接了笔生意，给一户人家糊替身，照着病人糊，眉眼要像，嘴不能笑。她在长凳上给你铺了一张草纸，说：你先练手。你在巷子里坐了两天，草纸把手心划出几道白印，指缝里全是干浆糊，一搓就掉白屑。第三天你画嘴，笔一抖，嘴角往上挑了。你拿指头去抹，越抹越宽，最后那张脸笑得像刚捡了钱。贴眼珠的时候你又贴反了，黑的朝里，白的朝外，两张脸一起盯着巷口。阿婆进来，看了一眼，把浆糊盆端走了，一句话没说。","ask":"这张笑得不像话的脸，你怎么收场？","days":15,"npc":"","memory":"笑得不像话的脸","choices":[{"title":"自己认下来","desc":"你把纸人抱到阿婆跟前，说嘴是你画歪的。","hint":"手心等着三下竹尺。","tone":"honest","outcome":"阿婆拿竹尺打了你手心三下，不重，响。打完她把纸人翻过来看背面，说背面糊得还算紧。买主来取时，她说这是新样式，替身笑得开，灾才肯走。老太太信了，抱着纸人回去。晚饭阿婆给你多夹了一筷子咸菜，没提这事。你手心发烫，扒饭扒得很快。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"爱":2},"flag":"","thread":""}},{"title":"说是猫碰的","desc":"你说昨夜有野猫跳上案子，把纸人撞倒了。","hint":"巷子里的话越传越邪。","tone":"hide","outcome":"阿婆信了一半。第二天巷口有人说纸人半夜眨眼，第三天有人来门口撒米。写寿人来看了一回，伸手把眼珠抠下来重贴，说：贴反了。人散了，你还站在原地。阿婆没骂你，只把案子上的脚印擦干净，那是你昨晚上案子够草纸时踩的。她擦得很慢，你看着她擦完。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":1},"flag":"","thread":"巷子里还留着纸人眨眼的话"}},{"title":"拆了重糊一个","desc":"你把它拆开，连夜重糊，天亮前糊完。","hint":"误了人家取替身的时辰。","tone":"repair","outcome":"你拆到后半夜，草纸不够，翻出几张废契，用背面糊了胸口，字透出来，隐隐约约。天亮时新纸人立得端正，眉眼像，嘴抿着。买主来取，看了眼说：太板了，孩子病着，要个会笑的。她抱着原来那个走了。新的立在墙角一个月，后来阿婆拿它垫了柜脚，柜子不晃了。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":2,"喜":1},"flag":"","thread":""}}]},{"id":"jie_s09","act":"side","age":[9,9],"mode":"narration","title":"两张一样的契","opening":"九岁那年秋后，渡口来个老汉，褂子是新的，浆得发硬，扣子扣错一颗。他从袖里摸出两张契纸，一样大小，一样折了四折，摊在灰契台上。他不认字。写寿人收了两斗米，给他两张，说一张烧给孙子，一张压箱底，可他分不清。灰契台石缝里嵌着上一场的纸灰，风一过，两张纸一齐响。梁上小秤垂着，铜盘不动，两盏灯还没点。你只认得一个“寿”字，是阿婆用炭写在门板上教的。","ask":"两张一样的契摊在灰上，你指哪一张？","days":15,"npc":"","memory":"两张一样的契","choices":[{"title":"牵他去纸寿巷","desc":"你把两张契都收进袖里，牵着他的袖子往纸寿巷走。","hint":"回来时天黑了，鞋少一只。","tone":"escort","outcome":"写寿人对着灯看半天，说一张是借，一张是还，指错要出人命。老汉要回两斗米，塞你半块饼。回来时你踩进沟里，鞋冲走一只，脚底划开一道口。阿婆用盐水给你洗，问你怎么这么晚，你说玩忘了。那半块饼你留了三天，硬得咬不动。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":2},"flag":"","thread":"一只鞋冲进了河里"}},{"title":"说给他孙子听","desc":"你把两张契摊在老汉孙子面前，说烧错一张，你爷就没日子了。","hint":"那孩子把契撕了。","tone":"honest","outcome":"孩子把两张契一起抓过去撕成四半，扔在石台上。老汉打他一巴掌，打完自己愣住，蹲下去捡纸片，捡不起来的用指头刮。回家路上两人一前一后，谁也没说话。那个冬天老汉走了。孩子开春来过渡，看见你就把头低下去，直到上船才抬起来。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"他上船才抬起头"}},{"title":"指着寿字替他分","desc":"你只认得一个寿字，就指着有寿字那张，说这张留着。","hint":"烧错了，你还不知道。","tone":"gamble","outcome":"老汉信了，把另一张投进火里，火苗很旺。他把有寿字那张叠好塞进贴身衣兜，走时还回头朝你拱手。入冬他孙子来买纸，说他爷把日子给错了人，家里正闹。你站在秤边，手心里全是汗，那杆秤晃了很久才停。从此你认字，先认那个寿。","eff":{"bond":0,"health":-1,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"misread_two_contracts","thread":""}}]},{"id":"jie_x02","act":"side","age":[9,9],"mode":"dialogue","title":"厚灯罩","opening":"入秋以后阿婆的眼睛不济了，穿针要举到窗户底下，半天穿不进。她不再去灰契台烧契，改在家里糊灯罩。纸是旧的契纸，糊一层刷一遍浆糊，她说厚了挡风。浆糊干在手指上，绷得发紧。她糊出来的那只厚得像鞋底，你举着去渡口，光只从边上漏出一点。父亲正在收缆，看了一眼说：照不见水牌。回来的路上你把灯举高，河面黑着，只有脚下一小块黄。阿婆在门口等你，手里还捏着半张没糊完的纸。她问：亮不亮。灯芯在她指缝里晃了一下。你张了张嘴，灶上的水正好开了，壶盖跳了两下。","ask":"这盏照不远的灯，你要怎么办？","days":20,"npc":"grandma","memory":"照不见水牌的灯","choices":[{"title":"撕薄一层","desc":"你趁她睡着，把灯罩揭下两层，重新糊薄。","hint":"她摸了半宿，没说话。","tone":"repair","outcome":"灯亮了一截，能照到水牌。第二天阿婆摸着灯罩，摸出薄了，没问，坐回灶边继续糊。你熬夜糊的那两层，手指被浆糊咬开两道口子，沾水就疼。晚饭时她说：你爹说得对。你等着她往下说，她没往下说。那盏灯后来一直挂在船头，罩子一年换一回，都是薄的。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"在罩上戳个洞","desc":"你用针在灯罩上戳了个洞，光从洞里射出去。","hint":"洞越戳越大，她假装没看见。","tone":"niche","outcome":"光从那个洞出去，细细一道，正好打在水牌上。父亲说凑合能看见，转头为这盏筛子灯跟她拌了两句嘴。阿婆不恼，第二天自己又戳了一个，说两个更亮。到冬天罩子上有七个洞，船靠岸时，那七个洞的光落在石阶上，摆渡的人都照着走。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"喜":2},"flag":"","thread":""}},{"title":"说不用她糊了","desc":"你把灯罩收进柜里，说渡口的灯够用。","hint":"她把柜门开了一夜。","tone":"honest","outcome":"阿婆没争，把没糊完的半张纸叠好，压在枕头底下。夜里你起来喝水，看见柜门开着，灯罩被拿出来摆在桌上，洞口朝上。她坐在桌边，手放在罩子上，像在等它凉。第二天她开始糊别的东西，一只纸碗，糊了拆，拆了糊。你没再提灯的事。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":"她开始糊那只纸碗"}}]},{"id":"jie_x03","act":"side","age":[11,11],"mode":"narration","title":"退回去的日子","opening":"阿婆这半年忘得快。早上煮了粥，中午问谁煮的。她把盐当糖放进你的碗里，看你吃完，问甜不甜。可她记得三月初七，天没亮就起来煮鸡蛋。你十一岁，开始算一笔事：你三岁那年烧过一张契，她的日子进了你身上。你翻出那件小袄，袖口掖着两折，袄襟上的米汤印还在，摸上去硬硬的。你抱着它去纸寿巷，找到写寿人，问他：能不能把日子退回去。他正在磨墨，手停了一下，问：谁的日子。你说：我阿婆的。他把袖子往上撸了撸，小臂上有一道旧疤，白得发亮。巷口有人在晒纸，竹竿压得弯下来。","ask":"写寿人等着你往下说，你说什么？","days":30,"npc":"","memory":"抱回去的小袄","choices":[{"title":"求他再写一张","desc":"你说把她的日子从我身上划走，写回她名下。","hint":"他开了一个你付不起的价。","tone":"ask","outcome":"他放下墨，说契烧了就是烧了，日子在你身上长住了，划不出来。你不信，他就把小秤挂上，让你称。你站上去，秤杆几乎不动。他说：你看，你的日子还不够自己用。他收了你那双布鞋当润笔，说回去给你阿婆过生日。你光着脚走回渡口，石头硌脚。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":2},"flag":"","thread":"你光着脚走回了渡口"}},{"title":"偷一张空契烧","desc":"你趁他不注意，抽走一张空契，跑到河边烧了。","hint":"火很短，什么也没还回去。","tone":"sneak","outcome":"空契烧得很快，火苗只有一指高，灰落在水上散了。你蹲在岸边等到天黑，什么也没发生。回家阿婆正在门口找你，见了你先把你的手翻过来看，看有没有烫着。她说：烧纸要到路口烧。她把你领回去，一路上攥着你的手腕，攥得很紧。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"不问了，回家","desc":"你把小袄抱回去，路上买了一个鸡蛋。","hint":"她问你是谁家的孩子。","tone":"family","outcome":"你回家煮了鸡蛋，用红纸染了，放在她枕边。她拿起来看了看，问：今天谁过生日。你说：你。她笑了，说胡说，我生日早过了。她把鸡蛋剥了，掰一半给你。那半天她没再忘事，讲你出生那夜下了雨，船到天亮才回来。天黑了，她又问：你是谁家的孩子。","eff":{"bond":4,"health":0,"reputation":0,"coins":-2,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"jie_x04","act":"side","age":[12,12],"mode":"dialogue","title":"雾里的红薯","opening":"河上起雾，起了三天。雾从水面立起来，把对岸的灯吃掉，把水牌也吃掉。父亲把船锁在桩上，说这种雾里出去，转一圈还在原地。渡口一下就空了。你和几个半大孩子沿着岸捡上游冲下来的东西：一只裂了口的木盆、半只草鞋、一个没有盖的坛子。雾里说话声传不远，喊一声，声音像被棉花吸走。你们把坛子搬到芦苇后头，偷了岸上人家两把红薯，捡干柴烧。火不敢烧大，烟在雾里散不开，呛得人直咳。父亲找来的时候，你们嘴边都是黑的，炭灰粘在嘴角，一擦一道。","ask":"父亲站在火边看你们，你怎么做？","days":10,"npc":"father","memory":"雾里的半块红薯","choices":[{"title":"拉他坐下","desc":"你掰了半块红薯递过去，往旁边挪了个位置。","hint":"他吃了，说没熟。","tone":"family","outcome":"父亲坐下，接过红薯咬了一口，说没熟，还是吃完了。他讲他小时候也在这岸上烧过红薯，烧糊了，他爹打了他一顿，打得他三天不敢坐。雾里他的声音比平时低。天黑前他先回去，说别让阿婆等。第二天起雾，他提着两个红薯来，放在坛子边上，什么也没说。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":2},"flag":"","thread":""}},{"title":"把木盆还回去","desc":"你认出木盆是上游张家的，抱着它走了一里地。","hint":"少了一个装东西的家伙。","tone":"honest","outcome":"张家正在门口捞东西，见了木盆，愣了一下，说这盆早冲走了。他女人进屋拿了一篮枣，硬塞给你。你抱着枣回去，红薯已经吃完了。伙伴们说你傻，第二天没人叫你。你把那篮枣的核埋在了芦苇后头。第二年发水，张家把自家的小划子借给渡口用了一整天。","eff":{"bond":-1,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"爱":1},"flag":"","thread":""}},{"title":"把坛子藏起来","desc":"你把坛子塞进芦苇深处，用草盖好，谁也不告诉。","hint":"第二年它还会在，人会散。","tone":"keep","outcome":"你把坛子藏在芦苇最密的地方，做了个记号。第二年雾再来，你去翻，坛子还在，盖上结了蛛网，里头积了半坛雨水。当年一起烧红薯的人，一个去了对岸学徒，一个跟船走了。你一个人坐在坛子边上，把水倒了，没再烧火。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"哀":2},"flag":"","thread":"芦苇里还藏着一只坛子"}}]},{"id":"jie_s02","act":"side","age":[13,13],"mode":"dialogue","title":"第四排的纸人","opening":"纸寿巷的作坊在巷子最里头，门口晾着一排纸人，风一过，几十只袖子一起动。你替阿婆送浆糊去，纸鸢在里头帮着裁纸，手指上全是干了的糨糊，白花花一层。屋里有草纸和松香混着的味道，闻久了嘴发干。你等她裁完最后一刀，抬头看见架子上第四排有个小纸人，穿着件小袄，袖子掖了两折。你认得那件袄。纸鸢顺着你的眼睛看了一眼，把手里的裁刀放下了。","ask":"那件小袄穿在纸人身上，你问什么？","days":15,"npc":"sibling","memory":"第四排的纸人","choices":[{"title":"接着裁那叠纸","desc":"你把浆糊放下，蹲下去帮纸鸢裁完剩下的那叠纸。","hint":"你手上裂了一个月的口子。","tone":"help","outcome":"你裁了一个下午，纸边裁得比她还齐。往后一个月，你每天早上去作坊帮着晒纸人，一排一排翻面，手上裂开的口子沾了糨糊，火辣辣地疼。纸鸢当你不知道，阿婆也当你不知道。架子第四排那个小纸人，你每天晒到它的时候，都把它翻得慢一点。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"爱":3},"flag":"","thread":"你替全家守着这件事"}},{"title":"抱回家给阿婆","desc":"你把纸人从架子上取下来，抱在怀里，一路走回渡口。","hint":"纸鸢一个月没跟你说话。","tone":"honest","outcome":"阿婆看见纸人，先摸了摸那两折袖子，问：这是谁家的孩子。你说：是我。她哦了一声，把纸人接过去放在膝上，一晚上没说话。夜里你起来喝水，看见她用手掌把纸人的脸一遍一遍抹平。第二天纸人不见了，架子上空出一块。纸鸢问你，你说不知道。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"架子上空出一块"}},{"title":"把它的脸按平","desc":"你把纸人从架子上拿下来，用手掌把那张脸按平。","hint":"老板娘打了你三下戒尺。","tone":"defy","outcome":"纸糊的脸被按塌了，浆糊从边上挤出来，粘在手心里。老板娘从里屋出来，用戒尺打了你手心三下，说替身没了脸，水就不认人。纸鸢把纸人抱回去，重新糊了一张脸，画得很像你，只是眉毛歪了一点。那年冬天起你下水就抽筋，过河要先报三遍名字。","eff":{"bond":1,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":1},"flag":"faceless_substitute","thread":"你过河要报三遍名字"}}]},{"id":"jie_x05","act":"side","age":[14,14],"mode":"narration","title":"沙洲上的铺盖","opening":"河心沙洲上住着个老头，姓什么没人知道，人家叫他沙洲上的。他没有名字，年轻时把名字押出去了，一直没赎回来。他夜里用小划子捎人过河，收得比渡口便宜。这天晌午，两个渡警上了沙洲，把他的铺盖卷起来扔进水里，说无名的船不许摆。老头不争，蹲下去捞铺盖，水没到膝盖。岸上站了些人看，谁也不动。你十四岁，在渡口搬货，手上抱着半筐炭，炭灰蹭在衣襟上。老头捞起铺盖，水从被角往下淌，他把它抱在怀里，像抱一个孩子。渡警说：船扣了。","ask":"渡警要拖船，你抱着炭筐站在那儿，怎么办？","days":12,"npc":"","memory":"沙洲上的铺盖","choices":[{"title":"说船是我家的","desc":"你放下炭筐，走过去说这船是我爹的，跟他无关。","hint":"稽核册上记了你的名字。","tone":"brave","outcome":"渡警翻了册子，把你的名字写上去，说要罚。船没扣成，改扣你家半年的渡牌。父亲赶来，当着人的面没说什么，回家把炭筐踢翻了，炭滚了一地。夜里他蹲着捡炭，捡完说：下次先跟我说。老头第二天送来两条鱼，鱼是用草绳串的，还活着。","eff":{"bond":-1,"health":-1,"reputation":1,"coins":-30,"stats":{"体魄":1},"emotion":{"怒":2,"爱":2},"flag":"","thread":"你家渡牌被扣了半年"}},{"title":"跑去叫父亲","desc":"你把炭筐一扔，跑回渡口喊人。","hint":"父亲来了，船还是被拖走。","tone":"tell","outcome":"父亲来得快，跟渡警说了半天，罚了钱，船还是被拖走。老头坐在沙洲上，看着船被拖过河，一直看到看不见。他没怪你，还朝你点了点头。你父亲回来一路上没说话，到家才说：这种事，叫我没用。第二年开春，老头死了，铺盖还在他家柴房里。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":"老头那床铺盖还在柴房里"}},{"title":"先把铺盖藏起来","desc":"你趁人不注意，把湿铺盖拖进芦苇里藏好。","hint":"人还是被带走了。","tone":"sneak","outcome":"铺盖藏住了，人没藏住。渡警把老头带上岸，说去问话，问了三天。你去柴房送饭，看见铺盖里裹着一块木牌，上面刻着一个女人的名字，字被水泡得发白。老头回来那天，第一件事是问铺盖。你说在。他说：那是我老婆。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"jie_x06","act":"side","age":[16,16],"mode":"narration","title":"船底的裂缝","opening":"十六岁那年夏天，你第一次一个人撑夜船。舱里坐着一个女人，怀里抱孩子，孩子烧得烫手。她要去对岸找郎中。船到河心，你听见脚下有声音，不是水拍船帮，是水在船里响。你低头，舱底积了一层，正往脚背上爬。船底的一块板裂了，裂缝有一指宽，水一股一股往上冒。女人也听见了，把孩子往上抱了抱。舱角放着一捆契，是白天人家托你捎过岸的，用油纸包着，绳子上系着木牌。撑到对岸还有半里。船帮上有一圈旧补丁，是父亲补的，用桐油抹过三遍，摸上去还是温的。","ask":"水到脚踝了，你拿什么堵？","days":10,"npc":"","memory":"船底那一指宽的缝","choices":[{"title":"用那捆契堵","desc":"你扯开油纸，把契纸一团团塞进裂缝。","hint":"那家人少了三年。","tone":"practical","outcome":"纸一沾水就软，塞进去，水慢下来。船撑到对岸时舱里积了半尺，孩子还烫，但到了。第二天那家人来取契，你说了实话，男人在渡口站了很久，说：三年，我认。他没骂你。那张泡烂的契后来补了一张，补的时候少了三年。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"那家人少了三年"}},{"title":"脱褂子堵","desc":"你把身上的褂子脱下来，卷紧，用肩膀顶住裂缝。","hint":"你在水里泡了半个时辰。","tone":"brave","outcome":"褂子堵不住，你就用背顶。水从布缝里渗，冷得像针。船到岸时你站不起来，是女人把你拖上去的。孩子在郎中那儿退了烧。你烧了三天，阿婆守了三夜。第四天你能坐起来，第一句话问的是那捆契。父亲说：契在，人也在。他把你的褂子补了，补丁在背上，很大一块。","eff":{"bond":4,"health":-4,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":""}},{"title":"掉头回岸","desc":"你拨转船头，往回撑，先靠自己这岸。","hint":"孩子多烧了一个时辰。","tone":"steady","outcome":"船回到这岸时已经沉了半截，水没到小腿。你们踩着水上了滩。郎中在河那边，等天亮才过河。孩子的耳朵后来听不太清，女人没怪你，见你还点头。那捆契湿了一个角，晒干后字还认得出。你从此每次出船前都要摸一遍船底，摸到木板发凉才放心。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"惧":4,"哀":2},"flag":"","thread":"那孩子的耳朵不灵了"}}]},{"id":"jie_s10","act":"side","age":[17,17],"mode":"narration","title":"混在一处的灰","opening":"十七岁那年清明前，灰契台一天烧七场。午后起风，两家的灰被卷到石台同一个凹处，分不出谁是谁。一个男人蹲下去，用竹片把灰往布袋里拨，连石缝里的都用指头抠出来。他说他儿子怕黑，要带回去放在床头。另一个是老太太，手里的布袋还空着，站在旁边看了一会儿，说：那我要哪一堆。小秤还挂在梁上，铜盘被风吹得轻轻碰秤座。","ask":"两家混在一处的灰，你怎么分？","days":10,"npc":"","memory":"混在一处的灰","choices":[{"title":"把话说清楚","desc":"你把两家的布袋都放在石台上，说灰混了，分不出来。","hint":"老太太回去躺了三天。","tone":"honest","outcome":"男人把布袋口捏紧，问：那我这三天对着谁说话。没人答他。老太太把空袋塞进袖子，说她老伴生前就不爱跟人挤。男人把灰带走，走到河心撒了一半。老太太回家躺了三天，起来把牌位擦了一遍。往后每年清明两家在渡口碰见，都点一下头，谁也不提那天。","eff":{"bond":0,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"把错认下来","desc":"你说灰是你扫混的，赔一张新契，当夜重烧一场。","hint":"罚了你三个月工钱。","tone":"carry","outcome":"师傅扣了你三个月工钱，让你在灰契台跪了半炷香。夜里你重烧一张契，写上那孩子的名字和生辰，烧成新灰装进男人的布袋。老太太那边，你把台上剩的灰扫一半给她，说就是原来那堆。两个人都走了，谁也不知道拿的是谁的。你膝盖疼了半个月，阴天更疼。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":3},"flag":"took_blame_for_ashes","thread":"膝盖阴天就疼"}},{"title":"一人分一半","desc":"你把灰扫成两堆，用秤分了，一人一袋。","hint":"谁也不知道拿的是谁。","tone":"practical","outcome":"你用小秤分了，两袋一样重。男人把布袋揣进怀里，走得很快；老太太把袋子抱在胸前，走得很慢，像抱着一个睡着的人。谁也没问。多年以后你在渡口碰见那男人，他跟你打招呼，说他儿子托梦，说黑。你没接话，低头把船缆又绕了一圈。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"","thread":"他说他儿子托梦说黑"}}]},{"id":"jie_x07","act":"side","age":[17,17],"mode":"narration","title":"沙洲上的碗","opening":"八月里退水，河心的沙洲露出来。平时那是水，只有撑船的人知道底下有沙。沙洲上什么都有：沉船的木料、锈成一团的铁钉、被水磨圆的瓷片，还有一只不知哪年冲下来的门板，立在那儿像一堵墙。全渡口的人都去了，撑船的、糊纸的、卖豆腐的，赤着脚在泥里踩。太阳很毒，泥是温的，脚陷进去拔出来带响。你和秦五家的老二翻了一下午，翻出一只完好的碗，碗底画着一条鱼。太阳偏西，水开始从沙洲边上往上爬，先是漫过脚印，再漫过脚背，凉得很。","ask":"水爬上来了，你还想再翻一会儿吗？","days":15,"npc":"","memory":"沙洲上的鱼碗","choices":[{"title":"再翻一会儿","desc":"你说再翻一炷香，往沙洲最里头走。","hint":"鞋被水卷走一只。","tone":"gamble","outcome":"你们往里头走，翻出一个铁盒，锁着，摇起来有响。两人用石头砸开，里头是一副发霉的棋子，少了两个。水已经到了膝盖，你们跑回来，你的鞋少了一只。赤脚走回家，脚底板被瓷片划了一道。那只碗你留着，用了很多年，碗底的鱼最后磨没了。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}},{"title":"去捞那个孩子","desc":"你听见有人喊，扔下碗，往沙洲外头跑。","hint":"你少捡了一筐。","tone":"protect","outcome":"一个外乡人的孩子被水冲离了沙洲，抱着一块木头。你游过去把他拖回来，他吐了两口水，哭出声。他娘追过来，把一篮煮鸡蛋全塞给你。你抱着鸡蛋回去，自己的筐还空着。那天的东西被别人捡光了。第二年沙洲再露出来，那个孩子站在岸上朝你挥手。","eff":{"bond":3,"health":-1,"reputation":3,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"爱":2},"flag":"","thread":""}},{"title":"坐岸上看他们抢","desc":"你抱着碗上了岸，坐在石头上看水一寸寸漫上来。","hint":"你看见沙洲怎么没的。","tone":"alone","outcome":"水先吃掉沙洲最外头那圈脚印，再吃掉门板，最后门板倒下去，没出声。人们抱着东西往岸上跑，跑得很难看。你坐在石头上，碗放在膝上。有个老太太跑不动，你下去扶了她一把。第二天他们分东西，谁也没叫你。回去的路上老太太说：这沙洲年年露，年年有人抢。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":1},"flag":"","thread":""}}]},{"id":"jie_s03","act":"side","age":[19,19],"mode":"narration","title":"卖给仇人的寿","opening":"那女人是傍晚来的，穿一件灰布褂子，袖口磨得发亮。她手里捏着一张折了四折的契，边角起了毛。她说要出寿，全出。你把小秤挂上梁，问她买家是谁。她把契推过来，名字那一栏朝里折着，说：你别念我的名字。秤盘里放上她的寿纸，秤杆一路沉下去，沉到底，铜盘磕在秤座上，响了一声。父亲在门口看了一眼，没进来。","ask":"她让你别念名字，你念不念？","days":15,"npc":"","memory":"折了四折的契","choices":[{"title":"照契念出名字","desc":"你把契展开，一字一字念出来，念到名字时抬了头。","hint":"买家的儿子站了出来。","tone":"rule","outcome":"买家的儿子在人群里，听完往前走了一步，说这寿他们家不要。他把定金从袖子里掏出来放在秤盘上，转身就走。女人把契捡起来，按原来的折痕折好，说：你念得对。她走的时候脚步很稳，秤还挂在梁上，铜盘晃了很久才停。","eff":{"bond":-1,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":"买家的儿子退了定金"}},{"title":"把名字折进去烧","desc":"你把名字那一角折向里，火从下角点起，没念出声。","hint":"你按印时按出了格。","tone":"secret","outcome":"火烧到折角时停了一下，又往上走。契成灰，名字没了。女人看着火，肩膀松下来，像卸下一副担子。三天后对岸传来她没了的消息。那个人还在喘气，家里人说是寿买对了。你袖口烧了个洞，一直没补，后来每次烧契都先把角折一折。","eff":{"bond":2,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"burned_nameless_contract","thread":"袖口上的洞没补"}},{"title":"把秤摘下来","desc":"你把小秤从梁上摘下，说这契不称，让她回去。","hint":"她去了纸寿巷。","tone":"refuse","outcome":"她看了你一会儿，把契收进袖子，说：你们都一样。第二天你听说纸寿巷有个写寿人接了这桩，抽了两成。契是在巷口烧的，念没念名字，没人告诉你。那阵子你称寿总要多称一遍，称完把秤擦得发亮，擦到铜盘上照得出人影。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":"你不知道那名字念没念"}}]},{"id":"jie_x08","act":"side","age":[19,19],"mode":"narration","title":"替陌生人烧契","opening":"那个人是清早发现的，靠在渡口的木桩上，衣裳湿到胸口，人已经硬了。身上没有契，没有牌子，只有袖子里一张折起来的纸，受寿人那一栏空着，出寿人写着两个字：自度。父亲说，无名的人过不了河，水会慢慢把他忘掉，得给他烧一张契，念一个名字。你蹲下去翻他的东西，翻出一块木牌，牌上刻着一个姓，后面那个字磨平了。姓周的。河上起了薄雾，灰契台的石面是凉的，摸上去像井水。你把他的手从袖子里拉出来，指头是弯的，掰不直。掌心有一层厚茧，是常年握橹磨的，指甲缝里嵌着洗不掉的炭黑。","ask":"这张契上，你给他念什么名字？","days":20,"npc":"","memory":"木牌上的一个周","choices":[{"title":"念木牌上的姓","desc":"你只念得出一个周字，就念周。","hint":"河上应了一声。","tone":"witness","outcome":"你念：周。火苗立起来，烧得很直。父亲在旁边站着，没纠正你。灰落进河里，往下游去了。那个人被抬上岸埋了，坟头插了一块木牌，还是只有一个周字。每年清明有人来给他添土，不知是谁。你后来想，也许有姓就够了，水只要一个抓手。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":""}},{"title":"给他起个新名字","desc":"你看他脚上沾着炭灰，就叫他周炭。","hint":"这名字只有你记得。","tone":"warm","outcome":"你念：周炭。念完自己觉得不像话，可火已经烧起来了，烧得比刚才旺。父亲说：行，有名字就成。埋他的时候你在木牌上刻了这两个字，刻得歪。此后很多年，你路过那片坟地都会看一眼。牌子烂了，字还在你嘴里，你偶尔念一声，像喊一个熟人。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"你给一个死人起了名字"}},{"title":"把木牌收起来","desc":"你把木牌揣进兜里，另写一个空名字烧了。","hint":"你身上多了一块牌子。","tone":"keep","outcome":"你烧了空契，火很短，一会儿就灭。木牌你留着，放在抽屉最里头，跟你的小秤放在一处。逢年过节你把它拿出来擦一擦。有一年发水，抽屉泡了，牌子上的字淡了。你拿刀重新刻了一遍，刻的时候手很稳，刻完发现刻错了笔画，成了一个谁都不认识的字。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":2,"惧":2},"flag":"","thread":"抽屉里那块刻错的木牌"}}]},{"id":"jie_x09","act":"side","age":[20,20],"mode":"narration","title":"赎错的名字","opening":"回名洲的契库在半坡上，屋里常年一股霉味。抽屉一格一格编着号，木牌上的号被虫蛀过，缺了一角。来的是个矮胖男人，穿一件新褂子，扣子扣得紧，说话时先清嗓子。他把木牌拍在柜上，说要赎名字，攒了十二年。你按号拉抽屉，里头的契压得实，揭开一张要哈一口气。名字念出来，他点头，说对，就是这个。你烧了赎契，把名字还给他。他站在门口念了三遍，忽然停住，摸了摸自己的下巴，说：不对。屋檐下挂着去年的玉米，穗子被虫蛀空了一半。","ask":"他站在门口说不对，你怎么办？","days":25,"npc":"","memory":"赎回来的假名字","choices":[{"title":"连夜查册换回来","desc":"你点灯翻册子，翻到后半夜，找到他的真名。","hint":"换回来要再烧一张，扣你的日子。","tone":"repair","outcome":"查到天亮，他的真名在一个不常用的偏册里，被水浸过，字迹发灰。换回来要再烧一张赎契，库里没有余纸，你从自己名下划了三个月。他拿回名字，站在坡上念了一遍，声音很小。走的时候他把新褂子的扣子解开了。你少了三个月，那年冬天格外怕冷。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":"你替他垫了三个月"}},{"title":"让他先用着","desc":"你说先用着，反正名字不过是个称呼。","hint":"他用这名字过了一年。","tone":"practical","outcome":"他回村，村里人不认这名字，他老婆开门问他找谁。他站在门口说：我是我。他老婆说：我知道。后来他用这名字去赶集、去上工，人家叫他，他也应。半年后他胖了，学会了纳鞋底。真正的名字主人家里来找过一回，看见他坐在门口纳鞋底，愣了半天，没开口。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":"他顶着别人的名字过日子"}},{"title":"报给阳楮司","desc":"你把错赎的事写清楚，报上去等发落。","hint":"上头扣了你的差事。","tone":"report","outcome":"阳楮司来了两个人，查了三天，把册子封了。男人被记了一笔，名字没收回去，也没还给他，就那么悬着。你被停了一个月的差，回渡口撑船。男人后来见了你还点头，只是不说话了。他老婆跟人说：他现在连自己叫什么都懒得争。","eff":{"bond":-2,"health":0,"reputation":2,"coins":-50,"stats":{"智识":1},"emotion":{"哀":3,"怒":1},"flag":"","thread":"册子封了，名字悬着"}}]},{"id":"jie_x10","act":"side","age":[22,22],"mode":"narration","title":"第三个印","opening":"阳楮司的规矩，一张契要盖三个印：渡口的、纸寿巷的、县里寿籍房的。寿籍房三年前走水，烧了一夜，房梁塌了，印也烧在里头。上头一直没发文说免，所以来烧契的人还得跑一趟废墟，在焦墙上按一个手印，算是第三个印。焦墙上的手印叠着手印，一层压一层，黑得发亮，近了能闻见油烟味。今天来的是个赶船的外乡人，他不肯按，说这不算印。写寿人说，不按就烧不成。他把手缩在袖子里，问：那墙是谁？风从废墟那头过来，带着一股陈年焦味。","ask":"他问那墙是谁，你怎么答？","days":18,"npc":"","memory":"焦墙上的手印","choices":[{"title":"替他按一个","desc":"你抓过他的手，往墙上按了一下。","hint":"你的手黑了一个月。","tone":"help","outcome":"他挣了一下，没挣开，手上多了个黑印。契烧成了，他上船前一直在搓手，搓不掉。你送他过河，他问那墙到底算不算数。你说算，按过的都算。他下船时把手举起来看了看，说：那我这三年，是按在一堵焦墙上的。他走了。你的手黑了一个月，洗到脱皮才淡。","eff":{"bond":1,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":2,"哀":2},"flag":"","thread":""}},{"title":"不给他烧","desc":"你把契推回去，说规矩不到，烧不了。","hint":"他白跑了一趟。","tone":"refuse","outcome":"他把契收进怀里，站在渡口看了半天河，最后买了一张最晚的船票。船开出去半里，他还在船尾站着。第二天他托船工捎回一句话，说他在别处烧了，多花了三倍的钱。写寿人听了，说：那墙迟早要塌。第二年春天，那面墙真的塌了，压死了两只鸡。","eff":{"bond":-1,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":1},"flag":"","thread":""}},{"title":"带他去看墙根","desc":"你领他到废墟，让他自己看墙根长出来的东西。","hint":"他按了，还写了字。","tone":"escort","outcome":"墙根长出一棵小树，从砖缝里钻出来，叶子是灰的。他看了很久，伸手按了一下，按完从地上捡了块炭，在墙上写了四个字：到此一游。写寿人看见了要骂，他没理。后来有人把那几个字拓下来，贴在纸寿巷的墙上。再后来墙塌了，字没了，拓片还在。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}}]},{"id":"jie_s11","act":"side","age":[24,24],"mode":"dialogue","title":"结冰的那年","opening":"二十四岁那年腊月，河面结冰，从这岸结到对岸，冰上落一层薄雪，看不出哪儿厚哪儿薄。船冻在桩边，橹冻在船上。父亲每天早上提一壶热水浇缆绳，浇开一截，又冻上一截。两盏灯只点着一盏，火苗贴着灯罩。第七天夜里，对岸有人举着火把喊船，喊了一夜。天亮才看清是个男人，说他娘躺在屋里喘不上气，要请这边的郎中过去。父亲蹲在岸边，用桨柄敲了敲冰，冰响了一声，很闷。","ask":"冰上那条没人走过的路，你走不走？","days":20,"npc":"father","memory":"冰封的第七天","choices":[{"title":"先踩一趟冰","desc":"你在腰上拴绳，让父亲拽着，一步一步往对岸挪。","hint":"两个脚趾后来没知觉。","tone":"brave","outcome":"走到河心，冰在脚底下叫了一声，你整个人陷下去，绳子勒进腰里。父亲把你拖上来，你怀里还护着郎中的药包，纸湿了一半。郎中是第二天绕上游的桥过来的，人救回来了。你右脚两个脚趾从此没知觉，走路有点跛。开春冰化，你在桩上刻了一道，刻得很深。","eff":{"bond":2,"health":-4,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"walked_on_ice","thread":"右脚两个脚趾没知觉"}},{"title":"把船锁上","desc":"你把跳板抽了，隔河告诉他冰在走水，谁也不许下。","hint":"他听了你的话。","tone":"rule","outcome":"他隔着河喊了半宿，后来不喊了。天亮时那边的火把灭了。你后来知道，他娘是后半夜走的，走的时候他守在床边。开春他来渡口，给你作了个揖，说：那天你说得对。你说不出话，替他把船钱免了。此后每年腊月，你都要在岸边多站一会儿，听冰响。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"每年腊月你在岸边多站一会儿"}},{"title":"带人撒灰开路","desc":"你把灰契台攒的灰一筐筐抬到冰上，撒出一条道。","hint":"契库的旧档全湿了。","tone":"niche","outcome":"灰撒上去，冰不滑了。两岸的男人排成一队，一个扶一个，把郎中挪了过去。那天夜里没有人掉下去。可灰契台攒了三年的灰全撒完了，契库底档被雪水浸透，开春查出一摞糊账。渡警来问，你认了，记了一过，那年没领到渡牌。你的手被筐绳勒出四道血口。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"jie_x11","act":"side","age":[24,24],"mode":"narration","title":"假契","opening":"那老太太是自己走来的，七十多，鞋底磨得薄，走路有声音。她拿出一张契，说要烧，把寿给她孙子。契上的字是新写的，墨还没干透，印却是旧的。你把印放在日头下照，边上有毛刺，是仿的。她不知道，说是侄子替她办的，办得妥当，还给她买了二斤肉。灰契台边上，她侄子正靠着树嗑瓜子，眼睛不看这边，耳朵一直朝着。你把契翻过来，背面有一行小字，写着余寿尽数，被指甲刮掉了一半。老太太的指甲缝里是黑的，指甲盖缺了一个角，一看就是干了一辈子活的手。灰契台的石缝里嵌着上一场没扫净的纸灰。","ask":"这张假契，你当着谁的面说破？","days":20,"npc":"","memory":"刮掉一半的字","choices":[{"title":"当着他的面撕了","desc":"你把契举起来，两下撕开，扔进火里。","hint":"他扑上来，被你按在石台上。","tone":"defy","outcome":"他从树底下冲过来，抓你的领子，你把他按在灰契台上，他的脸沾了一层灰。老太太在旁边拍手，不知是劝还是叫好。契烧成了灰，他的算盘落空。他去阳楮司告你毁契，你被罚了三个月工钱。老太太后来常在渡口坐着，见你就往你手里塞东西，有时是一个煮鸡蛋。","eff":{"bond":3,"health":-2,"reputation":1,"coins":-200,"stats":{"体魄":1},"emotion":{"怒":3,"爱":2},"flag":"","thread":"他告了你毁契"}},{"title":"换一张空契烧","desc":"你把假契收进袖里，另取空契烧给她看。","hint":"她以为成了，你不知道能瞒多久。","tone":"secret","outcome":"火照常烧，她跪下去磕头，磕了三个。侄子站在树底下看，看完走了。老太太回家，第二天给孙子做了新鞋。那张假契你压在箱底，压了两年，边角发黄。第三年她走了，走之前拉着你的手说：我孙子有日子了。你应了一声，没敢多说。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"箱底压着一张假契"}},{"title":"报到阳楮司","desc":"你把假契和那个印一起交上去。","hint":"老太太跪在渡口求你。","tone":"report","outcome":"阳楮司来拿人，侄子被带走那天，老太太追到渡口，跪在石阶上，说他就这一个亲人。她不知道他做了什么，只知道家里的肉是他买的。人判了，契作废，她的寿还在自己身上。她后来不再来渡口。有人说她一个人住在河那边，靠给人补鞋过活。","eff":{"bond":-3,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":"她再没来过渡口"}}]},{"id":"jie_s04","act":"side","age":[26,26],"mode":"narration","title":"退回去的契","opening":"那孩子是自己来的，七八岁，脚上一只鞋是湿的，身上那件小袄袖子太长，掖了两折。他把一张契摊在灰契台上，契角烧掉一点，字歪歪扭扭。他说：我奶奶把日子给我了，我现在好了，能不能退回去。他说话时一直盯着你的手，好像你会变戏法。灰契台上还留着上一场火的灰，风一吹，露出底下的石纹。你蹲下来，跟他一般高。","ask":"这张要退的契，你怎么答他？","days":20,"npc":"","memory":"一张要退的契","choices":[{"title":"指给他看契上的字","desc":"你蹲着，把契上的字一个一个指给他，说日子已经在他身上。","hint":"他把契撕成两半。","tone":"honest","outcome":"他听完，把契捏紧，捏了一会儿，撕成两半，扔进河里。纸在水上散开，一会儿就没了。他没哭，问你：那她还能活多久。你说不知道。他走的时候把湿鞋在门槛上蹭了蹭，蹭干净才出去。后来他再没来过渡口。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"他再没来过渡口"}},{"title":"烧一张空的退契","desc":"你另取一张空契，写上孩子的名字，当着他的面烧了。","hint":"火里垫的是你自己的日子。","tone":"warm","outcome":"火苗立起来，比纸高。他盯着火看，嘴唇跟着动，念的是他奶奶的名字。烧完他把灰捧起来装进衣兜，说要带回去给她看。你从自己名下划了四十天，谁也没告诉。那年冬天你怕冷，睡觉要盖两层被。开春他跑来告诉你，奶奶能下地了。你说好。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"burned_false_return","thread":"他兜里装着那捧灰"}},{"title":"带他去见奶奶","desc":"你牵着他过河，把契塞回他手里，让他自己去问。","hint":"老太太在里头骂了你一句。","tone":"escort","outcome":"老太太躺在里屋，听孙子问完，半天没说话。后来她伸手把契拿过去，压在枕头底下，说：不退。孩子问为什么。她说：退了，我就白疼你了。孩子没听懂，站在床边抠被角。出门时老太太在里头说：你带他来做什么。你答不上来，船撑到河心才想出一句话，也没说出口。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":3},"flag":"","thread":"她压在枕头下的契"}}]},{"id":"jie_x12","act":"side","age":[26,26],"mode":"narration","title":"河心打架","opening":"船到河心，两个人为一根竹篙打起来。一个是卖布的胖子，一个是挑担的老汉。胖子说老汉的担子刮破了他的新褂子，老汉说胖子先踩了他的鞋。两个人一个抓篙头，一个抓篙尾，船跟着晃。舱里的人都往两边挪，船歪得更厉害。你上去拉，被竹篙扫了一下胳膊。胖子一使劲，老汉松了手，两个一起栽进水里，水花溅到船尾。船没人撑，自己顺水往下漂，漂得很平，像不关谁的事。水花落在舱板上，一会儿就干了，留下几粒白盐。舱角有一筐没人领的鸡蛋，随着船晃，磕出细碎的响声。","ask":"船在漂，两个人在水里骂，你先顾哪个？","days":10,"npc":"","memory":"河心打的那一架","choices":[{"title":"跳下去追船","desc":"你把外衣一脱，跳进水里，游过去抓船缆。","hint":"你少了一只鞋。","tone":"brave","outcome":"你游了半里才追上，扒着船帮爬上去，把篙插进泥里。回头一看，两个人站在齐腰的水里还在吵，吵的已经不是褂子了，是谁先松的手。船上的人笑得直不起腰。你把船撑回去接他们，两人上船后一人坐一头，谁也不看谁。到岸时胖子把褂子脱下来，给老汉擦脚。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":2},"emotion":{"喜":4,"惧":1},"flag":"","thread":""}},{"title":"坐船头看","desc":"你抱着胳膊坐在船头，看他们吵到什么时候。","hint":"天黑才到家。","tone":"ignore","outcome":"船漂到下游一片芦苇边才停住，天已经黑了。全船的人趟水上岸，走回去。两个吵架的走在最后，走着走着并肩了。第二天胖子来渡口，褂子撕了个口，说算了。老汉挑着担子从岸上过，喊了一声：明天还坐你的船。你应了一声，把船缆重新系了一遍。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}},{"title":"把竹篙抽走","desc":"你从后头把竹篙一抽，两个人一起摔进舱里。","hint":"摔得不轻，笑得最凶的是他们。","tone":"niche","outcome":"两个人叠在舱板上，胖子压着老汉，老汉的鞋掉在你脚边。全船静了一瞬，然后爆开。胖子先笑，笑得褂子都皱了；老汉笑着骂他重。船稳了。到了岸，胖子把新褂子脱下来，说这褂子值了。老汉从担子里摸出两个梨，一人一个，剩一个塞给你。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":5,"爱":1},"flag":"","thread":""}}]},{"id":"jie_x13","act":"side","age":[29,29],"mode":"narration","title":"卖出去的二十年","opening":"来的是个三十来岁的男人，脸瘦，颧骨高，站在灰契台前，手里捏着一张纸，捏得起了毛。那张纸是退回契：三年前他把自己的二十年卖给仇人，换了仇人撤诉。仇人拿了寿，第二天还是把他告了，因为契上没写撤诉两个字。上个月仇人死了，寿没花完，按规矩余寿退回原主。管事的把契给他送来，让他来领。他在台前站了很久，火盆里的灰被风吹起来，落在他的鞋面上。他抖了抖脚，没抖掉，就不再管了。他带来的那张纸在手里越捏越软，字都糊了。","ask":"这剩下的日子，你要不要替他烧回去？","days":30,"npc":"","memory":"退回来的日子","choices":[{"title":"照规矩烧","desc":"你把退回契投进火里，念了他的名字。","hint":"他转身就走，没回头。","tone":"rule","outcome":"火苗吞了那张纸，烧得很旺。余寿回到他身上，他站着没动，像在等什么。等火灭了，他说：他欠我的，我拿回来了。说完上岸走了。那年冬天他病了一场，开春好了。渡口却有闲话，说你替死人做主，扣过他的日子。有半年，来烧契的人绕着你的台子走。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":2},"flag":"","thread":""}},{"title":"劝他收下","desc":"你把火盆往他那边推了推，说日子是自己的。","hint":"他收了，把日子给了儿子。","tone":"warm","outcome":"他蹲下去，把契角对着火，烧了。烧完他没有走，问你：这日子能不能转给别人。你说能。他后来把一半给了儿子，儿子那年娶了媳妇。他剩下的日子不多，过得也平常。有一回他撑船过河，跟你说了句话：我不图活，我图那二十年别白扔。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"把契压进箱底","desc":"你把退回契折好，收起来，说等你想好了再来。","hint":"那张契在箱底压了很多年。","tone":"keep","outcome":"他没说好，也没说不好，点了一下头就走了。契你收在箱底，跟空白的契纸放在一处。每年翻箱你都会看见它，看一眼又压回去。十年后他儿子来问，说你爹留过一张纸在你这儿。你把契给了他。他拿着看了半天，说：烧了吧。你没烧。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"箱底那张没收的契"}}]},{"id":"jie_s12","act":"side","age":[31,31],"mode":"narration","title":"两个人的数","opening":"三十一岁春天，来了一对夫妻，都不到四十。女人先说，想称一称两个人的日子，不借也不卖，只想知道谁先走，好把话说完。男人补一句：也好安排。你把小秤挂上梁，铜盘擦了一遍。女人先称，秤杆翘得很高，你报：九年零四个月。男人把寿纸放上去，秤杆几乎没动。你报：两年半。屋里静下来，窗外有鸭子叫。","ask":"他们问这两年半该怎么过，你怎么说？","days":30,"npc":"","memory":"秤上的两年半","choices":[{"title":"该怎么过就怎么过","desc":"你把秤收好，说日子不是省出来的，该干什么干什么。","hint":"他把想做的事排成了一张纸。","tone":"honest","outcome":"男人回家把想做的事列在纸上，一件一件划：修屋顶、补墙、把他娘的坟迁到朝阳坡上、去看一回海。最后一件没划掉。两年半头上他死在梯子上，手里还捏着瓦刀。女人把那页纸压在箱底，活了很久，纸黄了字还认得。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"纸上最后一件没划掉"}},{"title":"关半天渡口陪坐","desc":"你把船缆系死，说今天不摆了，三个人坐到天黑。","hint":"渡牌扣了三个月。","tone":"stay","outcome":"三个人坐在灰契台边，女人说起成亲那天下雨，男人说起第一次撑船把桨掉进河里。说到天黑，谁也没提那两年半。第二天有人告到阳楮司，渡牌扣三个月。那三个月你天天去他家修屋顶，修到一半，男人说：够了，剩下的我自己来。","eff":{"bond":4,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"屋顶修到一半"}},{"title":"少报他两年","desc":"你把他的数报成四年半，说秤老了，看不太准。","hint":"他多做了两年白工。","tone":"secret","outcome":"他松了口气，说四年半够把孙子送进学堂。他没日没夜地干，第二年冬天就倒了。女人来还秤时说：你那天报的是四年半。你说：秤老了。她把秤放在柜台上，说：他后来自己又去纸寿巷称过一回。走时把门带上，很轻。","eff":{"bond":-1,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":4},"flag":"underreported_years","thread":""}}]},{"id":"jie_x14","act":"side","age":[32,32],"mode":"narration","title":"不肯上船的人","opening":"那个人在渡口坐了三天。他带着一个蓝布包袱，身上是外乡的衣裳，鞋是新的，底子还没磨。船来了他不上，问他，他说怕水。他这辈子没坐过船，连池塘都没下过。第三天下午起了风，船晃，他站起来又坐下，坐下又站起来，把包袱抱得像块石头。父亲说，这种人上了船要出事。你看见他手背上有一道旧疤，是绳子勒的，他是做绳的。你问他过河做什么，他说对岸有个庙，他要去还愿，许了二十年。行李只有那个包袱，他把它抱在膝上，抱得手背上的筋都鼓起来。","ask":"他抱着包袱不敢上船，你怎么办？","days":12,"npc":"","memory":"不敢上船的人","choices":[{"title":"让他趴在舱底","desc":"你把舱板擦干净，让他趴下，拿布盖住他的头。","hint":"他一路没敢睁眼。","tone":"warm","outcome":"他趴着，指甲缝里全是木屑。船到河心，他问：到哪儿了。你说一半。他哦一声，没再问。靠岸时他腿软，扶着你的肩才站稳。他打开包袱，里头是二十年前许愿的一双布鞋，鞋底没沾过地。鞋放在庙门口，回来时他自己走上了船。你扶他时腰磕在船帮上，青了半个月。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"爱":3,"喜":2},"flag":"","thread":""}},{"title":"扶他站船头","desc":"你让他抓着你胳膊，站在船头，看着对岸。","hint":"他吐了，你洗了一下午船。","tone":"escort","outcome":"他站了不到半炷香就吐了，吐在船板上。你把他扶到船尾坐下，他一个劲说对不住。到岸他脸色发青，还是把愿还了。回来他给你钱，你不要，他就把包袱里那条新绳子留下了。绳子很结实，你用了三年。后来他每年过河一趟，都坐你的船，坐在船尾，不看水。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"喜":2},"flag":"","thread":""}},{"title":"替他过河还愿","desc":"你让他把鞋给你，你替他送到庙里。","hint":"他跪在岸边磕了个头。","tone":"help","outcome":"你把鞋送到庙门口，摆正，回来说给他听。他听完，跪下朝河那边磕了个头，磕得很响。他说：二十年，我不敢来，今天算是来了。他走的时候没坐船，沿着岸往上走，说要绕远路回去。你站在渡口看他走，一次也没回头。那天你少了半天的船钱。","eff":{"bond":2,"health":0,"reputation":0,"coins":-30,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"他绕远路走了"}}]},{"id":"jie_x15","act":"side","age":[35,35],"mode":"narration","title":"墙根下的戏","opening":"对岸来了戏班，唱三天。头一天渡口挤满了人，船排到河心。你收了三趟，第四趟天黑了，父亲把船锁了。你和秦五不甘心，半夜解了缆，撑船过去，蹲在戏台后头的墙根下听。墙是土坯的，声音透过来闷闷的，锣鼓敲在胸口上。台上唱的是借东风，旦角的嗓子劈了一下，台下照样叫好。你们蹲到鸡叫，回来时天蒙蒙亮，两个人嗓子都哑了，还在争论那句到底怎么转。河面上浮着一层唱戏的人扔下的瓜子壳。你的膝盖蹲麻了，站起来时扶着墙，墙上的土簌簌往下掉。","ask":"第三天戏班要走，你打算怎么送？","days":15,"npc":"","memory":"墙根下听的那出戏","choices":[{"title":"跟到下一个码头","desc":"你请了一天假，跟在戏班的船后头。","hint":"回来时挨了父亲一顿骂。","tone":"study","outcome":"你跟了三十里，学会半段。戏班管事的看你跟了一路，让你上船搬箱子，管一顿饭。你在船上待了两天，学会了那段的所有转腔。回来时父亲把船锁了三天，不让你碰。你在岸上唱，唱到对岸有人应了一声，声音比你准。你愣住了，那边又唱了一句。","eff":{"bond":-2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"喜":4,"爱":1},"flag":"","thread":"你学会的那半段戏"}},{"title":"挤进人堆里看","desc":"你把船一停，钻进人群，挤到台前。","hint":"回来时脚上是别人的鞋。","tone":"sneak","outcome":"台前挤得站不住脚，你的鞋被踩掉一只，摸黑找回来一只，穿上一看是别人的，大了两指。你穿着走回去，走一步掉一下。第二天你把鞋放在渡口石阶上等失主，没人来领，你就穿了半年，穿到合脚。那年冬天你在船上唱那段，秦五说你错了一个字，你说明明是他错。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":4,"惧":1},"flag":"","thread":""}},{"title":"留在船上听","desc":"你把船撑到对岸的芦苇边，躺在舱里听。","hint":"你睡着了，船漂了半里。","tone":"stay","outcome":"锣鼓从水上传过来，比墙根下清楚。你听着听着睡着了，醒来时船已经漂到下游，芦苇在头顶上响。天亮了，戏班走了，河面上什么都没有。你把船撑回去，一路把那句唱了三遍，第三遍唱对了。后来你常常这样，把船撑到河心，什么也不做，就听。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"哀":1},"flag":"","thread":""}}]},{"id":"jie_s05","act":"side","age":[38,38],"mode":"narration","title":"纸船上的名字","opening":"那个人是从上游漂下来的，卡在渡口的木桩上，衣裳泡得发白。你把他拖上岸，从他袖子里抖出一张契，出寿人那一栏写着自度两个字，受寿人空着。你把他放上小秤，秤盘一动不动，像挂着一块石头。他左脚少一个脚趾，断口很旧。父亲站在旁边说：无名的人，水会慢慢忘掉他。天快黑了，引路的纸船还空着，船上要写一个名字。","ask":"纸船上那个名字，你写谁？","days":15,"npc":"","memory":"秤盘一动不动","choices":[{"title":"写上自己的名字","desc":"你把自己名字写在纸船上，推船下水，看着它走。","hint":"右肩一到下雨就发沉。","tone":"protect","outcome":"纸船没沉，顺水走了。你回家换了衣裳，躺下就梦见一件湿衣裳搭在椅背上，滴了一夜水。往后每逢下雨，你右肩就发沉，像压着一只手。半年后有个女人来渡口打听一个男人，说他的船翻在上游。你听她说完，说没见过。她走后你在灰契台坐到天黑。","eff":{"bond":2,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"gave_name_to_stranger","thread":"一到雨天右肩就沉"}},{"title":"给他编一个名字","desc":"你在纸船上写了一个编来的名字，一笔一笔写得很慢。","hint":"他女人叫的不是这个名字。","tone":"gamble","outcome":"名字写完，你念了一遍，声音在雾里散开。纸船走了。开春他女人找来，拿着一双鞋，说他左脚少一个脚趾。你带她去河心，指了那片水。她蹲在船头叫了一个名字，不是纸船上的那个。水面上什么也没有。她走时说：谢你给他一个名字。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"她叫的名字不对"}},{"title":"让纸船空着走","desc":"你没写名字，把空纸船推进水里，站着看它散开。","hint":"到冬天你记不清他的脸。","tone":"rule","outcome":"空船在水上转了两圈，慢慢散了，纸片贴着水面往下游走。父亲说：这行就是这样，无名的归河。你把他那件湿衣裳晒在桩上，晒了三天，第四天不见了，不知道是风刮走还是有人收的。入冬后你想不起他的脸，只记得那只少了一个脚趾的左脚。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"","thread":""}}]},{"id":"jie_x16","act":"side","age":[38,38],"mode":"narration","title":"半夜发水","opening":"半夜发水。上游下了三天雨，水涨得比报信的船快。契库在坡下，水已经漫到门槛，屋里的人正往外搬契。你赶到时，坡上的土被泡松了，一块磨盘大的石头滚下来，砸在契库的墙角，墙塌了一面。守库的老周被压在梁下，只露出半截腿，脚边翻着一只鸟笼，笼门开着。水还在涨，漫过他的鞋，漫到小腿。有人喊先搬契，有人喊先抬梁。雨打在人脸上，睁不开眼。梁是湿的，抱上去打滑。坡上的水声比雨声大，像有人一直在倒水。有人把一盏灯举起来，光在雨里只有一小团。","ask":"水到小腿，你先抬梁还是先搬契？","days":10,"npc":"","memory":"雨夜里塌的墙角","choices":[{"title":"抬梁救人","desc":"你叫了两个人，一起把梁扛起来。","hint":"你的肩膀塌了一块。","tone":"protect","outcome":"梁抬起来半尺，老周被拖出来，腿是软的，人还醒着。他的腿保住了，走起路来一瘸一拐。契泡了小半库，上头追责，罚了你半年工钱。老周出院那天，第一件事是去契库看他的鸟笼。鸟早飞了，笼子还挂在梁上，泡得散了架。他站在那儿看了很久，说：飞了也好。","eff":{"bond":3,"health":-3,"reputation":2,"coins":-200,"stats":{"体魄":2},"emotion":{"惧":3,"爱":2},"flag":"","thread":"你的左肩使不上力"}},{"title":"先搬最里头那格","desc":"你冲进去，把最里头那一格契抱出来。","hint":"老周在水里多泡了一炷香。","tone":"practical","outcome":"那一格里存着三代人的契，纸都粘在一起，你抱出来时还是干的。老周被人拖出来时呛了水，咳了一个冬天。契保住了大半，上头记了你一功，赏了两块银子。老周没怪你，见你还笑，一笑就咳。第二年他走了，走之前让人把鸟笼给你送来，说给你装东西用。","eff":{"bond":-1,"health":0,"reputation":1,"coins":100,"stats":{"智识":2},"emotion":{"哀":3,"惧":2},"flag":"","thread":"老周咳了一个冬天"}},{"title":"跑上坡敲锣","desc":"你转身往坡上跑，一路敲锣喊人。","hint":"人来齐时，水已经封了门。","tone":"tell","outcome":"锣敲得急，人来得不算慢。可是水已经封了门，谁也不敢进去。最后是几个人用绳子拴着腰，一个一个摸进去，把老周拖出来。契泡了一夜。事后有人说你胆小，也有人说你那条命留着有用。你没辩解。那年冬天你路过契库，墙已经重新砌了，新砖比旧砖白。","eff":{"bond":1,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":""}}]},{"id":"jie_x17","act":"side","age":[41,41],"mode":"narration","title":"别烧了","opening":"那家的老头是写寿人，死了半年。他留了话：每天黄昏给他烧一张空契，烧满三年，一天不能断，断了他就回来。头三个月，一家人轮着烧，烧得很齐。半年后先是儿媳妇抱怨，说天天往河边跑，地里的活谁干；后来儿子也懒了，隔三差五忘。他们来找你，问有没有别的法子。你去看了那张遗嘱，字是老头自己的，写得端端正正，末尾还按了手印。院子里晒着玉米，一只鸡在灰堆里刨。鸡刨得很专心，刨一下，抖一下翅膀，灰扬起来。老头的老伴坐在门槛上剥豆子，一声不吭。","ask":"这三年，你要替他们想个什么法子？","days":40,"npc":"","memory":"烧过去三个字","choices":[{"title":"照烧三年","desc":"你说断不得，接过这活，每天黄昏烧一张。","hint":"你烧了两年半。","tone":"repeat","outcome":"你每天黄昏去河边烧一张，刮风下雨都去。烧到第二年，村里人见了你点头，说这家有个靠得住的。第三年最后一张，火苗很短，一会儿就灭了。那天晚上没有风，也没有人来。你把火盆收起来，觉得手里空。后来那家人搬走了，院子里的鸡给了邻居。","eff":{"bond":2,"health":-1,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":2},"flag":"","thread":""}},{"title":"停一天试试","desc":"你说少一天不会怎么样，让他们歇一天。","hint":"第二天死了三只鸡。","tone":"defy","outcome":"那天黄昏没人去河边。第二天早上，那家院子里死了三只鸡，直挺挺的，身上没伤。老太太跪在门口哭，说是他回来了。全村都来看，有人开始往河边跑。你去看那三只鸡，看不出什么。第三天他们烧了两张补上。你没再提停的事。那只在灰堆里刨食的鸡，后来也不见了。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":4,"怒":1},"flag":"","thread":"那三只鸡没人说得清"}},{"title":"写三个字烧过去","desc":"你在空契上写了别烧了，替他们烧了。","hint":"灰全落回院子里。","tone":"niche","outcome":"你写：别烧了。火烧起来，起了个小旋，灰没往河里去，全落回院子里，落了晾着的玉米一层。第二天没人再提烧契的事。那家儿子来问你写了什么，你说了。他站了一会儿，说：他生前最烦人啰嗦。此后河边清静了，玉米收进仓，鸡也回来了。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}}]},{"id":"jie_s13","act":"side","age":[43,43],"mode":"narration","title":"给狗一个生日","opening":"四十三岁那年夏天，隔壁的孩子抱着一条黄狗来渡口。狗已经硬了，耳朵上有个豁口，是小时候被猪咬的。孩子把狗放在灰契台上，从怀里摸出一张契纸，纸被他攥得发软。他说：它没有名字，也没有生日，人家说没名字的过不了河。他说要把自己的生日给它，让你写。他把手指头伸进嘴里咬了一下，挤出一滴血，按在契角上。小袄搭在椅背上，是你小时候那件。","ask":"这张要写生日的契，你落不落笔？","days":15,"npc":"","memory":"给狗一个生日","choices":[{"title":"写自己的生辰","desc":"你在纸上写下三月初七，卯时，替他把这一笔担下来。","hint":"从这天起，生日不算你的。","tone":"carry","outcome":"火苗立起来，比纸高。孩子蹲下去看灰，问上头写的是不是他的生日。你说是。他把灰装进布袋，挂在狗脖子上，埋在后坡。那天以后，每年三月初七你都在门槛外放一碗饭。孩子长大后问过一次，你说给一个老朋友。他哦了一声，没再问。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"gave_birthday_to_dog","thread":"门槛外那碗饭"}},{"title":"照规矩办","desc":"你说人不能把生日给畜生，狗没名字，只能空船走。","hint":"他学会狗叫。","tone":"rule","outcome":"孩子不听，抱着狗在灰契台上坐到天黑。你把空纸船推进水里，船转了两圈，散了。他回家后有一阵子不说话，蹲在墙根学狗叫，叫得院里别的狗都应。他娘来跟你说，让你别往心里去。第二年开春，你在后坡看见一个新堆的土包，上面插着两根树枝。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"后坡上的两根树枝"}},{"title":"教它一个名字","desc":"你铺一张新契纸，教他一笔一笔写：豁耳。","hint":"他写了十七遍才写正。","tone":"teach","outcome":"他写了十七遍，把豁字写得像个歪嘴。写完你让他自己念，他念得很响，念完把纸烧了。灰落进水里，没散。他说：它记住了。你说：你记住就行。那年冬天他常来渡口，蹲在秤边看你称寿，看了一年。他给狗起的那个名字，后来写在了他自己的门板上。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":1},"flag":"","thread":""}}]},{"id":"jie_x18","act":"side","age":[45,45],"mode":"narration","title":"一捧灰","opening":"那场丧事办得大。死的是个开油坊的老太太，三个儿子，请了两班吹鼓手，纸钱一捆一捆地烧。你被请去念契，站在灰契台边上，穿了一件借来的白褂子。风本来往河上去，念到一半，忽然转了，一股灰扑过来，糊了你满脸。你正张着嘴，灰进了口，一股焦味。你憋不住，打了个喷嚏，把嘴里的灰全喷出去，正喷在跪在最前头的孝子脸上。他的脸本来就哭得花，这一下白一块黑一块。全场静了。他的肩膀抖起来，先是抖，后是笑，笑得跪不住，扶着香案。旁边的人跟着笑，笑得东倒西歪。","ask":"满场都在笑，你怎么收这个场？","days":12,"npc":"","memory":"落在脸上的一捧灰","choices":[{"title":"顺着把话说圆","desc":"你抹了把脸，说老太太爱看热闹，这是她笑了。","hint":"有人说你不敬。","tone":"niche","outcome":"你一说，笑声更大了。孝子站起来，扶着你的肩，说：我娘就爱看人出丑。他让人又添了两捆纸。事后有个远房亲戚说你不懂规矩，在灵前说笑。孝子挡了回去，说：我娘要是听见，能从棺材里坐起来笑。那场丧事办得像办喜事，送葬的人一路都在说。","eff":{"bond":3,"health":0,"reputation":-1,"coins":20,"stats":{"魅力":2},"emotion":{"喜":5,"爱":1},"flag":"","thread":""}},{"title":"跪下认错","desc":"你跪下去，给灵位磕头，说冲撞了。","hint":"膝盖青了，主家反倒不安。","tone":"obey","outcome":"你跪下磕了三个头，灰还挂在眉毛上。孝子赶紧来扶，说使不得。扶起来他反倒不好意思，一个劲说天热，让你去棚下喝口水。丧事按规矩办完，一点岔子没有。回家你脱下白褂子，领子上全是黑的，那褂子还回去时主家说不用洗了。你膝盖疼了三天，走路打弯。","eff":{"bond":2,"health":-1,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"惧":2},"flag":"","thread":""}},{"title":"绷着脸念完","desc":"你把剩下的契念完，声音发抖，不敢看人。","hint":"你念错了一个字。","tone":"steady","outcome":"你绷着脸往下念，声音抖得厉害，越抖下面越笑。念到死者名字那一句，你把氏念成了民，全场又炸了一回。你自己也绷不住了，笑了一下，赶紧低头。丧事办完，孝子送你到门口，说：今天这一场，我记一辈子。他给了你双份的钱，你没推。","eff":{"bond":2,"health":0,"reputation":0,"coins":40,"stats":{"魅力":1},"emotion":{"喜":4,"哀":1},"flag":"","thread":""}}]},{"id":"jie_s06","act":"side","age":[47,47],"mode":"narration","title":"磨掉一半的号","opening":"回名洲的契库在半坡上，屋里常年一股霉味，抽屉一格一格编着号。来的是个五十来岁的男人，穿洗白的短褂，手里捏一块木牌，牌上的号磨得只剩一半。他说要赎名字。你把抽屉拉出来，里头的契压了二十年，纸都粘在一起，揭开一张要哈一口气。他站在门口不进来，说：我不记得我叫什么了，人家都叫我老陈家的。你问：那你姓什么。他搓着木牌，搓下一层木屑，说：这个也说不准。","ask":"他要赎的这张契，你怎么算？","days":20,"npc":"","memory":"磨掉一半的号","choices":[{"title":"按规矩收足","desc":"你把秤放平，报出他还差多少，让他自己选。","hint":"他选了明天。","tone":"collect","outcome":"他听完，把手伸进秤盘，说这些全给你。你称了，一年零四十天。契烧了，名字念出来时他跟着念，念错一个字，又念一遍。第二天早上他没起来。来收尸的人问他叫什么，你说了一个名字，那人写在木牌上，写完吹了吹墨。木牌是新挂的。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"新木牌上的墨"}},{"title":"替他补上差的","desc":"你在契尾添上自己的日子，把秤压平，不告诉他。","hint":"你的手凉了一冬。","tone":"carry","outcome":"名字还给他了。他捧着契走出门，走几步又回来，问：这上头写的真是我。你说是。他把契贴在胸口，笑了一下，牙是黄的。那年秋天他还来渡口坐过半天，跟人说他有名字了。入冬前他走了，走得有名有姓。你那双手凉了一冬，第二年开春才回暖。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"paid_for_name","thread":"手凉了一冬"}},{"title":"说这一格空了","desc":"你把抽屉推回去，说档找不着，让他下个月再来。","hint":"他来了四回。","tone":"hide","outcome":"他每月来一回，站在门口，不催。第三回他带了两个煮鸡蛋放在柜台上，说路上捡的。第四回他走不动，孙子搀他进门，说：我记起来了，我叫陈守田。说完他自己愣了一下，笑了。你说：那就不用赎了。他说：那也得赎，赎了才算还清。你把抽屉拉开，这回没关上。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"柜台上两个煮鸡蛋"}}]},{"id":"jie_x19","act":"side","age":[49,49],"mode":"narration","title":"新削的橹","opening":"渡口新来了个哑巴，二十来岁，自己钉了条小划子，在渡口下游半里处捎人。他收得少，人又稳，渐渐有人绕路去坐他的船。这天晌午，三个船工把他的划子拖上岸，拿斧子劈他的橹。哑巴拦，被人推倒在滩上，嘴里啊啊地叫，叫不出字。岸上有人看，没人过去。你正在船上补帆，针还捏在手里。带头的是老陈，跟你搭了六年船，你儿子满月他还送过一对银锁。滩上的鹅卵石被晒得发白，踩上去烫脚。哑巴的鞋掉了一只，脚趾在泥里抓。斧子砍在橹上，木屑跳起来，落进水里就散了。","ask":"老陈的斧子举着，你下不下船？","days":15,"npc":"","memory":"门口立着的新橹","choices":[{"title":"当街把话挑明","desc":"你跳下船，走到老陈面前，说这橹不能劈。","hint":"老陈从此不坐你的船。","tone":"brave","outcome":"老陈看了你半天，把斧子放下了，说：你替他。你说：我替他。他把斧子往滩上一扔，走了，再没跟你搭过船。哑巴从滩上爬起来，给你作了个揖，作得很深。第二天一早，你门口立着一把新橹，削得光，柄上缠了布。你把旧橹收进柴房，没舍得烧。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"爱":2},"flag":"","thread":"老陈再没搭过你的船"}},{"title":"出钱给他买新橹","desc":"你掏钱买了根好木料，请人连夜削了根橹。","hint":"哑巴不肯要，橹在门口立了三天。","tone":"pay","outcome":"橹立在你门口，哑巴每天路过看一眼，不拿。第三天你把它扛到他船上，他才收下，收下就跪下了，你赶紧拉。老陈那边没消气，说你拿钱买人心。渡口的人分了两拨，一拨坐你的船，一拨坐他的。哑巴的划子还是在下游半里，只是橹是新的，划起来没声音。","eff":{"bond":3,"health":0,"reputation":0,"coins":-150,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"去找渡警","desc":"你跑到渡警房，把劈橹的事说了。","hint":"各打五十大板，划子还是漏。","tone":"report","outcome":"渡警来了，问了几句，说私斗各罚。老陈罚了钱，哑巴的划子因为没牌照，被扣了三天。哑巴蹲在岸边等，等到第三天，把划子领回来，船底被拖漏了一块。你帮他补，补了一下午。他一直看着你的手，看到补完，忽然朝你笑了一下，牙很白。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":1,"爱":2},"flag":"","thread":"划子底上那块补丁"}}]},{"id":"jie_x20","act":"side","age":[54,54],"mode":"narration","title":"河心的碗筷","opening":"每年清明，你都把船撑到河心，停一炷香。舱里摆一副空碗筷，倒半碗酒，酒是自家酿的，浑浊。今年船上多了一个年轻人，是搭船的，问给谁。你说给一个姓周的，二十年前从上游来卖炭，喝多了酒，夜里掉进河里，没人捞，也没人来认。你只知道他姓周，炭筐还在岸上放了三天才被人拿走。河心的水是黑的，看不见底。年轻人听完，没说话，把手里的包袱抱紧了些。包袱皮上有一块补丁，针脚很粗，像是自己缝的。他把包袱放在膝盖上，两只手压着。","ask":"年轻人抱着包袱，你要不要开口？","days":20,"npc":"","memory":"河心的那副碗筷","choices":[{"title":"让他一起坐下","desc":"你把碗筷往他那边推了推，说坐吧。","hint":"他磕了个头，把炭灰撒进河里。","tone":"warm","outcome":"他坐下，从包袱里摸出一小袋炭灰，说是家里灶膛的。他把灰撒进河里，撒得很慢。然后他跪下，朝水面磕了个头，磕完说：我爹走那年我六岁。他站起来时膝盖上沾了水。你没问他为什么现在才来。船靠岸他付船钱，你没收，那天的两趟生意就误了。","eff":{"bond":4,"health":0,"reputation":0,"coins":-20,"stats":{"魅力":1},"emotion":{"哀":3,"爱":3},"flag":"","thread":""}},{"title":"把碗筷交给他","desc":"你说以后这碗筷你来摆，我把位置告诉你。","hint":"第二年他自己来了。","tone":"teach","outcome":"他学得很认真，问酒要倒多少，问船要停在哪个位置。你一一说了。第二年清明，你到河心，他的船已经在那儿了，摆着同样的碗筷，酒倒得比你满。他见了你，站起来，说：我今年带了我儿子来。舱里坐着个小男孩，正用手指头蘸酒，被他打了一下手。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":""}},{"title":"什么也不说","desc":"你把船撑稳，让他自己看河面。","hint":"他下船时回头看了一眼那只碗。","tone":"keep","outcome":"一路上谁也没说话。到了岸，他把包袱背好，走了两步，回头看了一眼舱里那副碗筷。你没解释。他走远了。第二年清明，你到河心，看见水面上漂着一点炭灰，散成一小片。河风把你手里的纸钱吹走了一半，你懒得去追。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":""}}]},{"id":"jie_s07","act":"side","age":[55,55],"mode":"narration","title":"一张契两个人","opening":"那对老夫妻是天黑前来的，两个人搀着，走得一样慢。老头耳朵还灵，老太太耳背，他凑到她耳边说话，声音大得整条岸都听见：你先按。老太太摇头。他们把一张契纸摊在灰契台上，纸是新的，边角压得很平，在箱底放了些年。写寿人说一张契只能写一个名字。老头说他还有六年，她还有两年，说：写她的名字。老太太说不要，说他会做饭吗，锅都烧穿三个。两个人说到两盏灯都点上，谁也没按手印。","ask":"一张契写一个人，你写谁？","days":15,"npc":"","memory":"谁也没按手印","choices":[{"title":"收下老头的寿","desc":"你把老头的寿纸放上秤，秤平了，写老太太的名字。","hint":"她骂了他五年。","tone":"rule","outcome":"老头按了印，按得很重，印泥出了格。老太太在旁边拉他的袖子，没拉住。契烧完，两个人搀着回去了。老头第二年开春走的。老太太又活了五年，五年里每天骂他一句，骂完给他留一碗饭，搁在灵位前，第二天早上再端走。第五年她走时手里捏着那张契的角。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"","thread":"她捏着契角走了"}},{"title":"把契收起来","desc":"你把契折好压在秤下，说回去商量清楚再来。","hint":"那年冬天老头先走了。","tone":"dodge","outcome":"他们把契留下，搀着回去了，一路上还在争。入冬老头病倒，没熬到腊月。开春老太太一个人来渡口，站在岸上问：那天你要是把契烧了，他是不是还能多活两年。你说不知道。她说：我也不知道，我就是想问问。她没上船，沿河岸走回去，走得比来时慢。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"她问的那句话"}},{"title":"添上自己的日子","desc":"你在契尾添上自己的两年，写下两个人的名字。","hint":"老头从灰里拨出你的名字。","tone":"carry","outcome":"火苗分成两股往上走。老头蹲下去看灰，从灰里拨出你的名字，拨了半天，说：这不行。你说烧都烧了。往后两年两个人都能下地，老头把渡口的台阶修了，一块一块垫平。第三年秋天他们前后脚走的，差三天。此后每年清明，你门口多一双布鞋，鞋底纳得密。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":1,"爱":4,"哀":3},"flag":"gave_years_to_couple","thread":"清明门口那双布鞋"}}]},{"id":"jie_s14","act":"side","age":[58,58],"mode":"dialogue","title":"出嫁前一夜","opening":"五十八岁秋，纸鸢要出门了。对岸修钟的老先生托媒人来过三回，第三回带来一对修好的座钟，走得很齐。头天夜里她来渡口，穿改过的红袄，袖口是旧纸糊的，走一步响一下。她坐在门槛上，红布包放在膝上，半天没打开。椅背上搭着你小时候那件小袄，她进门时伸手摸了一下袖口。两盏灯都点着，河上有风。她说：哥，我明天就姓别人的姓了。她笑了一下，说：我二十岁那年，还以为自己活不到二十。","ask":"红布包放在膝上，你伸手做什么？","days":10,"npc":"sibling","memory":"红布包里的日子","choices":[{"title":"划掉她的名字","desc":"你取出家契，当着她的面，把她的名字划了一道。","hint":"她笑着看你划完。","tone":"rule","outcome":"笔尖在纸上顿了一下，划出一道黑。她一直笑着看，划完说：那我明天就不算这家的人了。她把红布包打开，里头是阿婆那只碗，碗口磕了一个豁。她把碗放在桌上，说：这个留给你。走的时候她没有回头，红袄的袖口一路响到岸上。那只碗你后来用它喝水，喝了很多年。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"阿婆那只豁口碗"}},{"title":"给她压箱的日子","desc":"你另写一张契，从自己名下划五年，塞进她的箱底。","hint":"她到死不知是谁给的。","tone":"carry","outcome":"你写到后半夜，火苗在灯罩里一跳一跳。第二天她的箱子上船，是你亲手抬的，箱底压着那张契，谁也没说。她嫁过去第七年，男人病了一场，她把那张契拿出来用，用完烧了，说不知是哪个亲人留的。那五年从你身上走的，你冬天怕冷，手背上起了一块青。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"gave_years_to_sister_again","thread":""}},{"title":"陪她坐到天亮","desc":"你把西屋的炕烧上，什么也不问，给她倒一碗热水。","hint":"鸡叫时她走了。","tone":"stay","outcome":"两个人坐在门槛上，谁也没提明天。她说起小时候糊纸人，浆糊抹多了，纸人的脸塌了；说起阿婆记得每个人的生日，唯独忘了自己。鸡叫头遍她站起来，把红布包塞给你，说：门板上那些日子，我抄了一份。她走了。你打开，最后一行是三月初七，字比别的都小。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":"红布包里那张纸"}}]},{"id":"jie_x21","act":"side","age":[58,58],"mode":"narration","title":"大年初一","opening":"大年初一，渡口没生意。河上结了薄冰，船出不去，人也不来。几个老伙计挤在船舱里，把舱板擦干净当桌子，赌骰子。赌注不兴钱，输的人学鸟叫，或者替赢家撑一天船。你手气背，连输五把，站在船头学了一早上鸟叫，学的是鹭鸶，学得不像，像鸭子。对岸有人探头看，说渡口来了新鸟。舱里笑得船都晃。中午有人从家里端来一锅炖菜，碗不够，用船上的瓢。太阳照在冰上，晃眼。冰底下有水在走，能听见细细的响声，像谁在下面搓绳子。有人说起年轻时的事，说错了好几处，别人也不纠正。","ask":"骰子又转到你面前，你掷不掷？","days":12,"npc":"","memory":"船头上的鸟叫","choices":[{"title":"掷，押上三天船","desc":"你把骰子往舱板上一拍，说输了替你撑三天。","hint":"你输到初五。","tone":"gamble","outcome":"骰子转了两圈，停在一点上。舱里笑翻了，有人拍着舱板直咳嗽。你认了，从初二撑到初五。初三那天河开了，你撑船，赢家坐在舱里嗑瓜子。初五晚上他请你喝酒，喝到半夜，说：其实我那天也想输。你替他撑的那三天，自己的船歇在岸边，缆绳被人踩松，船撞掉了漆。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"爱":2},"flag":"","thread":""}},{"title":"不掷了，去唱歌","desc":"你把骰子推给别人，站到船头唱那段戏。","hint":"唱到对岸有人应。","tone":"defy","outcome":"你唱的是上回学的那段，唱到高处破了音。舱里的人跟着起哄，有人拿瓢敲船帮打拍子。唱到一半，对岸真的有人应了一句，接得严丝合缝。全船静了一下，然后笑得更响。那人后来撑船过来，是个跑船的，说这条河上会唱这段的不多了。你嗓子哑了半个月。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"喜":4,"爱":2},"flag":"","thread":""}},{"title":"收摊，各回各家","desc":"你说天不早了，把骰子收进兜里。","hint":"有人骂你不合群。","tone":"steady","outcome":"有人骂你扫兴，骂完还是散了。你最后一个走，把舱里的瓜子壳扫到河里。冰上落了一层壳，风一吹，滑得很远。回家的路上你听见身后还有人在唱，唱得跑调。第二年大年初一，他们又来了，来得比你还早，骰子是新买的。","eff":{"bond":-1,"health":1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":1},"flag":"","thread":""}}]},{"id":"jie_x22","act":"side","age":[62,62],"mode":"narration","title":"三尺河滩","opening":"河滩上那三尺地，两家人打了二十年。最早是为了插一根界石，后来界石被水冲了，就为界石该插在哪儿打；再后来打官司，县里判了，两家都不认；最后各自往滩上垒石头，你垒一垛，我垒一垛，垒得比人高。今年水大，两垛石头都冲没了，滩也塌了半边。两家人站在空滩上，谁也不说话。过了一会儿，姓赵的先开口，说：你家的石头压了我家的地。另一个说：地都没了。两个人脚底下是塌剩的泥，踩一脚陷一寸，谁也没往前踩。远处有只水鸟落在浅水里，抖了抖翅膀。","ask":"两家都看着你，你拿什么量？","days":30,"npc":"","memory":"归河的三尺地","choices":[{"title":"去挖老界石","desc":"你脱了鞋下滩，在泥里摸那半块界石。","hint":"摸出来半块，两家都不认。","tone":"repeat","outcome":"你摸了半个时辰，摸出半块石头，上面的字还剩一个。姓赵的说不算，另一个也说不算。两家人蹲在泥里看那块石头，看了半天。最后姓赵的把石头抱回家，说垫猪圈。另一家没拦。第二年滩上又长出水草，谁也没再去垒石头。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"哀":1},"flag":"","thread":""}},{"title":"说这地归河","desc":"你把石头往水里一扔，说以后这地谁也别要。","hint":"两家一起骂你，骂完各自回家。","tone":"niche","outcome":"两家人一起骂你，骂得很难听，从你爷爷骂到你孙子。你站着听完，一句话没回。骂完了，姓赵的先走，另一家也走了。第二年开春，你在滩上看见两家人一起在补堤，一个递石头，一个垒。他们看见你，其中一个喊：这地归河，堤总得有人修。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":2},"emotion":{"怒":2,"喜":2},"flag":"","thread":""}},{"title":"收起尺子走人","desc":"你说量不了，收起尺子，撑船走了。","hint":"回头看见他们还站在水里。","tone":"quit","outcome":"你撑着船走，走了半里回头，两家人还站在滩上，水到脚踝，谁也没动。船到河心，你听见他们又吵起来了，声音在河面上传得远。你把橹摇慢了些。后来那块滩彻底塌进河里，两家人的堤挨在了一处，年年一起修，修了十几年。","eff":{"bond":0,"health":1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"喜":1},"flag":"","thread":""}}]},{"id":"jie_x23","act":"side","age":[66,66],"mode":"narration","title":"涨潮就开","opening":"那个老太太每天早晨来，站在渡口最下面一级石阶上，问：船什么时候开。你每天答：涨潮就开。她点点头，转身回去，第二天再来。她穿一件洗得发白的蓝褂子，手里攥着一块手帕，手帕里包着两块糖，糖纸都化了。她儿子十年前出门跑船，说挣够了钱就回来。头两年还有信，后来信断了。她的记性坏了，忘了很多事，只记得每天来问船。有一回下雨，她撑着一把破伞站在石阶上，伞骨断了一根，雨水顺着伞骨流进她脖子里。她也不躲，就那么站着，手帕捏得很紧。","ask":"她看着河面，你答她什么？","days":60,"npc":"","memory":"每天问的那句话","choices":[{"title":"说船今天就到","desc":"你说今天就到，还撑船到对岸转了一圈。","hint":"你回来说没接着。","tone":"warm","outcome":"她听了，把糖拿出来，说要给他留着。你撑船到对岸，在码头站了一炷香，回来跟她说没接着，明天再来。她说好。第二天她来得比你还早。这样过了一个月。有一天她没来，你去她家，门开着，她坐在门槛上，说：他该到了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":3},"flag":"","thread":"她手里那两块糖"}},{"title":"告诉她实话","desc":"你说船不会来了，您儿子回不来了。","hint":"她点头，第二天还来。","tone":"honest","outcome":"她听完，点了点头，说：我知道。然后问你：船什么时候开。你说涨潮。她说好，转身走了。第二天她又来了，问同样的话。你答同样的话。这样反倒踏实。她手里的糖换过几回，都是新的，包在手帕里，化一点就换。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}},{"title":"照旧答她","desc":"你说涨潮就开，跟昨天一样。","hint":"她走的那天，手里攥着一张船票。","tone":"repeat","outcome":"你答了两个月。她每天来，每天走。有一天下大雨，她没来，第二天也没来。邻居说她夜里走了，走的时候手里攥着一张旧船票，票上的日子是十年前。她儿子没回来。你把那天的船撑到对岸，空船，又撑回来。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":1},"flag":"","thread":""}}]},{"id":"jie_x24","act":"side","age":[71,71],"mode":"narration","title":"听船","opening":"渡口下游住着个瞎老头，每天傍晚来岸边坐着，听船靠岸。他儿子跑船，跑这条河，十天半月回来一趟。船靠岸的时候，船帮会磕在石阶上，磕一下是空的，磕两下是载了货。老头听得出来。你每次靠岸都多敲一下，他就知道是你，会朝河面点一下头。今年他儿子换了大船，跑远水去了，半年没回来。他还是每天来，坐在那块石头上，背对着河。天冷了，他穿一件旧棉袄，袖口磨破，露出棉絮。你靠岸，敲一下，他点头。石阶上的霜还没化，踩上去有声。","ask":"今天他坐在那儿，你敲几下？","days":40,"npc":"","memory":"多敲的那一下","choices":[{"title":"告诉他去了远水","desc":"你上岸，蹲在他旁边，说了实话。","hint":"他坐了很久，说那也得敲。","tone":"honest","outcome":"他听完，手在膝盖上拍了拍，说：远水好，远水挣得多。然后他说：那也得敲，敲了他就知道岸在哪儿。你问他怎么知道。他说：听不见，心里也知道。你扶他起来，他走的时候用手杖在石阶上敲了三下，敲得很准。第二天有人在渡口说你嘴直，把实话说重了。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"多敲两下","desc":"你靠岸时敲了三下，替两个人敲。","hint":"你敲了半年。","tone":"warm","outcome":"他听见三下，愣了一下，然后笑了，说：你也学会替人敲了。此后你每天敲三下，敲了半年。开春他儿子回来一趟，船靠岸时敲了一下，老头站起来，说：回来了。他儿子在船上喊了一声爹。你站在旁边，把缆绳系好，没过去。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":1},"flag":"","thread":""}},{"title":"带他到河心","desc":"你扶他上船，说带他去看看他儿子跑的水。","hint":"他在船头站着，说风是甜的。","tone":"escort","outcome":"他上船时手抖，坐稳了就不抖了。船到河心，他站起来，脸朝着风。他说：这水比我那时候宽了。又说：风是甜的，要下雨。那天夜里真下了雨。送他回去，他在门口站了一会儿，说：明天还来。你说好。第二天他来了，敲石阶的声音比往常响。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"喜":2},"flag":"","thread":""}}]},{"id":"jie_s15","act":"side","age":[74,74],"mode":"narration","title":"疼不疼","opening":"七十四岁这年，渡口的活儿多半交给别人，你只在灰契台边坐着看火。来的是个姑娘，十六七岁，从纸寿巷走来，鞋上全是土。她手里捏着一张写好的契，只差一个手印。她说她娘咳了半年，郎中说熬不过冬，写寿人说她名下有九年，可出六年。她把契摊在你面前，问：借寿到底疼不疼。灰契台上没有火，风把契角掀起来又放下。","ask":"她问借寿到底疼不疼，你怎么答她？","days":20,"npc":"","memory":"借寿到底疼不疼","choices":[{"title":"说实话，疼","desc":"你告诉她疼在后头：每回有人叫你名字，都要算一算还剩几年。","hint":"她还是按了手印。","tone":"honest","outcome":"她听完撸起袖子，露出手腕一道旧疤，说：那我受得住。她按了印，印泥按出了格。契烧起来，火苗很短。她娘多活一冬，开春还是走了。姑娘嫁到上游，每年回来一趟，站在灰契台边不烧契，只站一会儿。你每回都陪她站，谁也不说话。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"","thread":""}},{"title":"说声不疼，替她烧","desc":"你说不疼，接过她的契，划掉她的名字，添上自己的六年。","hint":"你的手再拿不稳筷子。","tone":"carry","outcome":"你趁她不注意，把出寿那一栏改成自己的名字，按下印。火苗立起来，比纸高，她伸手去够，被你挡回去。她娘多活两年，看见她出嫁，也看见外孙。姑娘一直以为契是她自己烧的，逢人就说渡口的老先生心好。你的手从那年起拿不稳筷子，夹菜要夹两回。","eff":{"bond":5,"health":-4,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"took_girls_six_years","thread":"筷子夹两回"}},{"title":"让她坐一夜","desc":"你不答，点一盏小灯，让她坐在台边看别人烧契。","hint":"天亮她把契带回去了。","tone":"wait","outcome":"那一夜来三个人：一个给儿子烧，一个给仇人烧，一个给自己烧。姑娘没说话，看到第三场，把手放在火边烤了烤。天亮她把契折回原样揣进袖子，说：我知道了。她没按印。她娘那年冬天走了。后来每年清明她都来坐一会儿，说不后悔。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"每年清明她来坐一会儿"}}]},{"id":"jie_s08","act":"side","age":[78,78],"mode":"narration","title":"秤盘里的纸片","opening":"七十八岁这年冬天，你把小秤挂回门框上，取一张空白契纸放在铜盘里。秤杆翘起来，翘得很高。你撕了一些小纸片，一片算一天，一天一天往盘里加，加到秤杆平了，就不再加。你把纸片取下来数，数了三遍，每一遍都一样。屋里很静，灶上的水响了一声。小袄搭在椅背上，袖口那两折早磨薄了。你把纸片拢成一叠，放在膝上，窗外河面白蒙蒙的。","ask":"这一叠纸片，你打算怎么办？","days":30,"npc":"","memory":"数了三遍的日子","choices":[{"title":"把秤收进柜里","desc":"你把纸片和小秤一起收进柜底，第二天照常去渡口。","hint":"谁也不知道你数过。","tone":"steady","outcome":"第二天你照常去渡口，把船缆绕三圈，把两盏灯都点上。纸鸢来看你，问你怎么瘦了，你说冬天都这样。那叠纸片压在柜底，和一小袋灰放在一起。后来你忘了自己数过几遍，只记得秤杆平的那一下，铜盘轻轻碰了碰秤座。日子照旧过，最后一天也没人知道是第几天。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":"柜底那叠纸片"}},{"title":"叫纸鸢一起数","desc":"你把纸鸢叫来，把纸片摊在桌上，让她再数一遍。","hint":"她数出不一样的数。","tone":"honest","outcome":"纸鸢数了两遍，数出的数比你的多。她说你漏了，把纸片重新码成一摞，码得很齐。她当天就搬回来住，把西屋的炕烧上，夜里起来两回看你。她的男人来劝过三回，她没回去。开春她的女儿也搬来了，三个人挤在板屋里。那叠纸片搁在窗台上，谁也没再数。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"told_sister_count","thread":"纸鸢搬回来住了"}},{"title":"把多的压在灯下","desc":"你把纸片分出一半，写成一张无名契，压在灯座底下。","hint":"灯座底下后来空了。","tone":"carry","outcome":"你把纸片分成两半，一半折进一张无名契，写完不落名字，压在渡口那盏灯的灯座底下。谁需要谁拿，谁拿谁就多活几天。那年冬天你弱得快，走两步要歇一歇。开春灯座底下的契不见了，灰也没有。你没问是谁拿的。到死你也不知道那几天落到了谁身上。","eff":{"bond":3,"health":-4,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"left_unnamed_contract","thread":"灯座底下空了"}}]}]},"钟葬群岛":{"no":4,"name":"钟葬群岛","subtitle":"替死人敲钟的人，替活人记住","through":"每沉一口钟，全岛就忘掉一个人。你做了守钟人，替别人记住他们忘掉的名字。","cast":[{"id":"father","name":"铜九","role":"守钟人","tag":"父"},{"id":"mother","name":"海娥","role":"织网","tag":"母"},{"id":"sibling","name":"小螺","role":"捞钟人","tag":"妹"}],"main":[{"id":"zhong_m01","act":"main","age":[0,0],"mode":"montage","title":"第三口钟","opening":"凌晨，海面很平。塔上的钟自己响了一声，不脆，像有人在水底敲空碗。父亲放下碗，说：又沉了一口。那天沉的是第三口钟。母亲在草席上生你，接生婆剪脐带时，钟声还没散，窗缝里灌进来一股海腥味。屋里的人忽然都不说话了——他们同时忘了一个名字。父亲把钟谱摊在膝上，笔尖悬着，找不到该写的地方。你在这时候哭出声，很响。","ask":"满月那晚，父亲摊开钟谱，你伸手抓什么？","days":30,"npc":"","memory":"第三口钟沉了","choices":[{"title":"攥住钟锤柄","desc":"你把父亲的钟锤抱在怀里，木柄上全是他的汗味。","hint":"母亲从此不提船钱。","tone":"carry","outcome":"父亲把钟锤往你手里送了送，说：沉，是块守钟的料。当晚他把你的名字写进钟谱的守钟人一栏，墨还没干就合上了。母亲在灶边织网，梭子来回，没抬头。那之后她再没提过攒船钱的事，罐子却一直放在织机底下，没动过。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"named_as_keeper","thread":"母亲的船钱罐还在织机下"}},{"title":"抓住那截衣角","desc":"你抓住母亲袖口一截烧焦的布，掰不开。","hint":"布上有奶味和烟味。","tone":"keep","outcome":"母亲的手停住。她把那截布从你手里抽出来，看了看，又塞回你的襁褓。那晚她没睡，在门口坐到天亮，海边烧过一堆小火，剩半截衣角埋在灰里。你从小枕着那块布，布上有奶味和烟味，钟一响就醒。她每年烧衣的时候，会往你这边看一眼。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"枕下的半截衣角"}},{"title":"朝海哭到天亮","desc":"谁抱都哭，只有抱到门口朝海才停。","hint":"父亲把钟谱合上了。","tone":"seek","outcome":"母亲抱着你在门口站了半宿，海风把你的哭声吹散。父亲坐在桌边，钟谱摊着，笔尖的墨干在纸上。他说：这孩子留不住。你的名字那一栏空了三年，后来是你自己踩着小凳，拿他的笔描上去的，描得歪，他没改。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"惧":2},"flag":"unnamed_three_years","thread":"名字是你自己描上去的"}}]},{"id":"zhong_m02","act":"main","age":[6,6],"mode":"dialogue","title":"铜喉塔","opening":"六岁那年，父亲第一次带你上铜喉塔。塔身是铜的，摸上去比海水凉，手一贴上去，骨头里都听见响。爬到第七层，往下看，七声礁在潮里排开，一块对着一口钟。父亲让你把耳朵贴在壁上，说：听。海底有钟在响，一声一声，隔着水传上来，像有人在很远的地方敲一口空锅。钟声中间有个女人在念名字，念一遍，停一停。父亲嗓子哑，说话像钟的余音：听见什么了？","ask":"父亲问你听见什么，你怎么答？","days":10,"npc":"father","memory":"海底传来的钟声","choices":[{"title":"说出听见的名字","desc":"你把听见的那个名字说给父亲，一个字一个字说清。","hint":"父亲说是你听岔了。","tone":"honest","outcome":"父亲听完，先看塔下的海，再看你的嘴。他掏出钟谱，把那个名字写上去，写完又用指甲刮掉，刮得纸起毛。当晚议会的人上塔问话，父亲说是孩子听岔了，把人送下塔。那一年他没再带你上塔。母亲在你枕边放了一小袋盐，说压惊。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":2},"flag":"told_father_name","thread":"父亲把那个名字刮掉了"}},{"title":"跟父亲下塔","desc":"他说绳子卡了，你跟着下去，在底下替他扶梯。","hint":"那个名字没听清。","tone":"help","outcome":"梯子很陡，父亲踩一阶，你扶一阶。他的手在你头顶上，粗糙，稳。钟声从塔顶漏下来，隔了一层铜，听不真了。他在底下换绳，你在旁边举灯，灯油滴在手背上。那晚回家，他多给了你半块饼。那个名字你只记住一个阿字，后来在钟声里找了很多年。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":"只记住一个阿字"}},{"title":"敲小钟应一声","desc":"你摘下塔上的小钟锤，朝铜壁敲了一下。","hint":"海底的声音停了。","tone":"defy","outcome":"声音停了，停得很干净。父亲在塔下喊你，喊了七声，你没应。他冲上来，脸白得像刚捞上来的鱼，第一次朝你吼：你应它，它就来。塔上的小钟裂了一道缝，从那以后声音是哑的。他没再带你上塔，直到第二年开春。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":4,"哀":1},"flag":"answered_bell","thread":"小钟裂了一道缝"}}]},{"id":"zhong_m03","act":"main","age":[11,11],"mode":"dialogue","title":"这是病","opening":"第四口钟是冬天沉的。沉之前，岛上有个磨刀的阿潭，独眼，右手少半根指头，给你磨过一把小刀，刀柄缠蓝线。钟沉那天早上，你路过他家门口，他女人在扫台阶，台阶上有鱼鳞和海腥味，门槛边晾着一双旧靴子。你问：谭伯呢？她抬头说：谁。你说：磨刀的，独眼。她想了想，说：好像是有过这么个人。她记得那双靴子，不记得靴子是谁的。回家母亲把手在围裙上擦了擦，说：这是病，别记。","ask":"母亲说这是病，你怎么办？","days":20,"npc":"mother","memory":"独眼阿潭的靴子","choices":[{"title":"把记得的写下来","desc":"你偷一张钟谱的纸，用炭画下阿潭的白眼睛和蓝线刀柄。","hint":"纸藏在针线盒底。","tone":"keep","outcome":"母亲翻你的枕头，翻出那张纸。她看了很久，没烧，把它折成小方块，压进针线盒底。她说：收着，别给人看。从那天起，她给你缝了个贴身的小袋，袋子是用旧网线编的。你后来才知道，那个袋子本来是给要离岛的人装船钱的。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":2},"flag":"wrote_forgotten_man","thread":"针线盒底的那张纸"}},{"title":"当面念出名字","desc":"你站在院子里，把谭伯的名字念了三遍，念得很大声。","hint":"母亲第一次打了你。","tone":"honest","outcome":"母亲从灶边冲出来，捂住你的嘴，把你拖进屋。她的手很凉，劲很大。那天晚上她打了你一下，打在手心上，不重。她说：你把他喊回来，钟就要再沉一口。你问：那我记着也不行。她说：记着是你的事，喊出来是全岛的事。她说完去洗碗，碗在水里碰得很响。","eff":{"bond":-3,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"spoke_name_aloud","thread":"母亲说喊出来是全岛的事"}},{"title":"喝下艾草水","desc":"母亲熏你的耳朵，你端着碗，一口一口喝完。","hint":"你忘了他的声音。","tone":"obey","outcome":"艾草水苦得舌根发麻。你喝完吐了一回，母亲给你拍背，手一直在动。那天夜里你梦见磨刀的声音，第二天就不记得了。你先忘了他的声音，还记得那只白眼睛；过了半个月，白眼睛也淡了，只剩一把缠蓝线的刀柄。刀还在你抽屉里，你不知道是谁磨的。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":4,"惧":2},"flag":"drank_mugwort","thread":"缠蓝线的刀柄"}}]},{"id":"zhong_m04","act":"main","age":[15,15],"mode":"dialogue","title":"数名字","opening":"十五岁，你正式做学徒。守钟房在铜喉塔底下，屋顶漏，墙上挂着一排耳塞，是用蜡和布搓的；岛上的人把该还的东西刻在蜡上。父亲把钟谱摊在桌上，纸被海水泡过，边角发毛，字迹洇成一团一团。他教你：一声钟，一个名字；钟声不停，名字不能断，断了那一个就还不上。他敲了一下小钟，让你数。你数到第五声，第七声里多出一个名字，很轻，像有人在你耳边补了一句。","ask":"第七声里多出一个名字，你怎么记？","days":30,"npc":"father","memory":"钟声里数名字","choices":[{"title":"照实写进钟谱","desc":"你把那多出来的名字写进第七行，一笔一画。","hint":"父亲把那一行划了。","tone":"rule","outcome":"父亲看了一眼，拿过笔，把那行划掉，划得很重，纸都破了。他说：多记一个，全岛多背一年。你问是谁的名字，他没答，把钟谱合上，压在一块铜锭底下。晚上你收拾桌子，看见他在最后一页添了一行小字，写完用手掌盖住。你把抹布拧干，没问。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"saw_father_secret_line","thread":"最后一页被手掌盖住"}},{"title":"记在自己手心","desc":"你把那个名字写在左手心，写完攥成拳。","hint":"汗把字洇开了。","tone":"secret","outcome":"那天你攥了一夜拳头，第二天洗手，字已经洇成一团黑。你又写了一遍，写在手腕内侧，袖子盖得住。父亲看见了，没问。后来你在他钟谱的夹层里摸到一张薄纸，泡烂的纸，软得像布，上面是同一个名字，笔迹是他的。你把它放回去，从此你们谁也没提。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"哀":2},"flag":"knows_father_extra_name","thread":"钟谱夹层里的薄纸"}},{"title":"停下来问父亲","desc":"你按住钟绳，问他那多出来的是谁，问到他不答。","hint":"他陪你坐到天亮。","tone":"ask","outcome":"父亲说：你数错了。你从头再数，数到第七声，那个名字又来了。他不说话了，坐在门槛上，一口一口喝凉茶。塔外的潮水退下去，露出礁石。你数到天亮，数得舌头发干。他起身时拍了拍你的肩，说：学不会也好。这句话你记了很多年。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":1},"flag":"","thread":"他说学不会也好"}}]},{"id":"zhong_m05","act":"main","age":[19,19],"mode":"dialogue","title":"钟舌","opening":"十九岁那年，小螺半夜翻窗回来，浑身海腥味，头发上还挂着海草。她从怀里掏出一枚钟舌，铜的，冷的，比本岛任何一口钟的舌头都短一寸。她说：你猜我从哪儿摸的。沉钟渊底下，一口没名字的钟。你要怕，就当它是条不会烂的鱼。她说得像开玩笑，尾音还往上挑，手却一直在抖。钟舌上刻着一圈字，不是岛上的字，你一个也不认得。她把钟舌塞进你手里：替我藏两天。","ask":"这枚钟舌，你要怎么处置？","days":15,"npc":"sibling","memory":"不属于岛的钟舌","choices":[{"title":"帮她藏起来","desc":"你把钟舌裹进旧网，塞到灶膛后头的砖缝里。","hint":"卫队来搜过一次。","tone":"secret","outcome":"卫队是第三天来的，挨家翻箱。母亲把织机挪了半尺，正好挡住那块松砖。卫队的人用铁棍敲墙，敲到灶边，母亲说灶刚熄，灰会迷眼。他们走了。小螺回来取钟舌，把脸埋在你肩上，很快松开。你后来发现她没取走，只把钟舌挪到了自己的鱼篓底。","eff":{"bond":5,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":2},"flag":"hid_foreign_clapper","thread":"钟舌还在小螺的鱼篓里"}},{"title":"交给父亲","desc":"你趁小螺睡着，把钟舌包好，放到父亲的钟谱上。","hint":"她被罚去静湾。","tone":"report","outcome":"父亲看了钟舌一眼，脸色没变，只说：从哪来的，送回哪去。第二天卫队来了，小螺被带走，判在静湾服无钟苦役三个月。她走的时候没看你，鞋底在门槛上蹭了一下。三个月后她回来，手上多了两道绳痕，还讲海腥味的笑话，只是不再讲海底的事。","eff":{"bond":-6,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_sister_clapper","thread":"她不再讲海底的事"}},{"title":"让她扔回海里","desc":"你把钟舌推回去，说扔回海里，别带进家门。","hint":"她说扔了。","tone":"practical","outcome":"小螺把钟舌揣回怀里，说：行，扔。第二天她出海，回来时两手空空，晚饭吃了三碗。你没问。半年后你替她晒鱼篓，篓底摸到一块硬东西，用油布包着，还是那枚钟舌。你把它放回原处，盖好。海风把鱼篓吹得响，像很小的钟。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":"鱼篓底的油布包"}}]},{"id":"zhong_m06","act":"main","age":[24,24],"mode":"narration","title":"守一夜","opening":"二十四岁那年，第五口钟要沉。钟谱上被划掉的名字是阿鲛，渔妇阿箬的女儿，三年前死在海上，尸首没捞回来。按规矩，守钟人要在沉钟前夜去那户人家，点一盏灯，陪到钟响。阿箬的屋里挂着件小袄，灶上温着一碗鱼汤。她把这些年攒的潮铢推给你，你没接。她抓住你的手腕说：钟响的时候，你替我念她的名字，一遍一遍念，我跟着你念。她顿了顿：别让我忘了她。","ask":"钟要沉了，阿箬抓着你的手，你怎么答？","days":10,"npc":"","memory":"阿箬家的那盏灯","choices":[{"title":"答应替她记","desc":"你点头，坐在灯下，把阿鲛的名字念了一夜。","hint":"第二天她问你贵姓。","tone":"carry","outcome":"钟响的时候，阿箬跟着你念，念到第三遍就停了，眼睛看着灯芯。钟声散尽，她松开你的手，起身去灶上热鱼汤，问：你是哪家的后生。你说你是守钟的。她点头，给你盛了一碗。你喝完出门，在海边把阿鲛的名字念了三遍，记进自己心里，此后每年这天都替她记一回。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"carries_a_jiao","thread":"每年替她记一回"}},{"title":"告诉她实话","desc":"你说忘是忘定了，我只能替你记着，留不住。","hint":"她把你赶出门。","tone":"honest","outcome":"阿箬把你的手甩开，说：那你来干什么。她把灯吹了，屋里黑下来。钟响时你站在门外，听见她在里面念，念得很快，像怕赶不上。第二天她把小袄烧了，烟从窗口出来，一股焦布味。她再没跟你说过话。你每年还是替她记着阿鲛，记在一个她不知道的地方。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"她再没跟你说过话"}},{"title":"骗她不会忘","desc":"你说钟只收该收的，她不会忘，让她安心睡。","hint":"她睡得很沉。","tone":"hide","outcome":"阿箬信了，把灯芯捻小，躺下，很快就睡着，呼吸很轻。钟响的时候她翻了个身，没醒。第二天她起来，站在小袄前面问你：我女儿呢。你说：出海了。她点头，去灶上热粥，多摆了一副碗。你每年替她圆一次这个谎，圆到她搬去别的岛。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":4},"flag":"lied_to_a_ruo","thread":"多摆的那副碗"}}]},{"id":"zhong_m07","act":"main","age":[31,31],"mode":"dialogue","title":"最后一块衣角","opening":"三十一岁，第五口钟沉了以后，母亲开始烧东西。先是旧衣服，后来是鞋，再后来是一卷没织完的网线。她每天傍晚去海边，火很小，烟贴着水面走。你问她烧给谁，她说：烧给海。她坐在灶边，手一直在动，像在补一张看不见的网。有一回你翻她的针线盒，翻出一块烧剩的衣角，巴掌大，是襁褓上的布。母亲收回去用手量了量：就这么点大。她说：最后一块了。你问是谁的。她想了很久：记不清了。","ask":"母亲把最后一块衣角交给你，你怎么办？","days":20,"npc":"mother","memory":"烧剩的半块布","choices":[{"title":"替她烧了","desc":"你蹲下去，用火镰点着衣角，看它卷成一个小卷。","hint":"烟里有股奶味。","tone":"obey","outcome":"布烧得很快，火苗是黄的，烟里有股奶味。母亲站在旁边，手垂着，没动。烧完她说：好。从那天起她再没去过海边，傍晚坐在门口织网，织得比以前慢。你想起塔上那个念了又念的名字，阿澜。这个名字此后只有你一个人知道，你没告诉过她。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"burned_last_cloth","thread":"阿澜只剩你记得"}},{"title":"把衣角藏起来","desc":"你假装失手，把衣角掉进沙里，用脚踩住。","hint":"母亲找了一夜。","tone":"keep","outcome":"母亲蹲在沙滩上找，找到半夜，火镰掉在水里也没管。第二天她没问你，把织机搬到窗边，一整天没说话。那块衣角你藏在钟谱夹层里，和父亲那张泡烂的薄纸放在一起。很多年后你打开，布已经硬了，还有一点焦味。母亲到死都以为烧了。","eff":{"bond":-2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":2},"flag":"hid_last_cloth","thread":"她到死都以为烧了"}},{"title":"问她那是谁","desc":"你抓住她的手，说阿澜，问她记不记得这个名字。","hint":"她把名字念错了。","tone":"ask","outcome":"母亲的手在你手里停住。她说：阿澜。她把这个名字念了两遍，第三遍念成了阿蓝，自己没发觉。她说：我记得她怕黑，记得她左耳后有一颗痣。可我想不起她长什么样。你告诉她，名字是从父亲钟谱最后一页看来的。她点点头，把手抽回去，转身进屋，那晚没点灯。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":6,"惧":3},"flag":"told_mother_name","thread":"她把阿澜念成了阿蓝"}}]},{"id":"zhong_m08","act":"main","age":[38,38],"mode":"dialogue","title":"你叫什么","opening":"三十八岁那年，父亲开始忘事。先是忘了钟绳挂在第几个钉子上，后来忘了退潮的时辰。有一天他在塔下叫你，叫了一声喂，又改口叫小螺。你回头，他站在梯子上，手里拿着钟谱，问你：你叫什么来着。他说得很平常，像问今天涨不涨潮，嗓子哑得像钟的余音。他记得你是他儿子，记得你左腕上有颗痣，吃饭时还是把鱼肚上的肉夹给你。他只是想不起那个名字了。","ask":"父亲问你叫什么，你怎么答？","days":30,"npc":"father","memory":"父亲忘了你的名字","choices":[{"title":"写在他手心上","desc":"你拉过他的手，用指头一笔一笔写你的名字。","hint":"你写了九天。","tone":"heal","outcome":"第一天他看了半天，说：好字。第二天他又问。你写，他看。写到第九天，他把手攥起来，说：别写了，磨得疼。后来你在他枕头底下摸到一张泡烂的纸，被口水浸软，上面歪歪扭扭全是你的名字，写满一页，最后一个只写了一半。你把纸晾干，夹进钟谱。","eff":{"bond":5,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":4},"flag":"wrote_name_on_palm","thread":"写满一页名字的软纸"}},{"title":"说这是钟声吃的","desc":"你说这病是钟声吃记忆，不是你老了，别撑着上塔。","hint":"他把钟锤挂上门后。","tone":"honest","outcome":"父亲听完，坐在梯子上没动。第二天他把钟锤从塔上拿下来，挂在门后，再没上去过。他每天擦那把锤子，擦得木柄发亮。有人来请他去听钟，他摆手，说：我听不准了，别误事。你替他上了塔。夜里你听见他在院里跟母亲说话，只听见一句：别让孩子看见我数不清。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"father_left_tower","thread":"他每天擦那把钟锤"}},{"title":"应下小螺这名字","desc":"他再叫你小螺，你就应，应得跟真的一样。","hint":"妹妹在门口站着。","tone":"dodge","outcome":"他叫你小螺，你应。他让你去把西边的钟绳收紧，你去。小螺有一回在门口听见了，站着没进来，转身走了。晚上她在灶上热饭，说了一句：哥，你应得挺像。她说完笑了一下，笑得很短。父亲到死都以为家里有个儿子叫小螺，另外一个，他忘了叫什么。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"哥，你应得挺像"}}]},{"id":"zhong_m09","act":"main","age":[45,45],"mode":"dialogue","title":"她叫阿澜","opening":"四十五岁，母亲病了一个冬天。她躺在床上，手还在动，一下一下，像在织一张看不见的网。小螺从海上赶回来，鞋上带着海腥味，进门还说：娘，我给你带了条会骂人的鱼，它一路骂我网眼大。母亲笑了一下。岛上的人说，钟吃掉的名字，会在人临死前吐回来半口。那天傍晚，母亲忽然说：阿澜。她说完自己愣住，问你：阿澜是谁。屋里很静，钟声从塔上漏下来，一声。她的手还在被子上动。","ask":"母亲问阿澜是谁，你怎么答？","days":20,"npc":"mother","memory":"母亲最后的话","choices":[{"title":"说那是你姐姐","desc":"你俯下身，说阿澜是她的大女儿，死在第三口钟那天。","hint":"她听完，把脸转向墙。","tone":"honest","outcome":"母亲的眼睛睁着，看着房梁。她说：那我怎么不记得。你说：钟把她带走了。她想了很久，说：我记得有个人怕黑。她又问：她怕黑，我怎么没给她留灯。你说：留了，每年都留。她点点头，把手放到被子外面，慢慢不动了。窗外退潮，礁石露出来。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"爱":3},"flag":"mother_died_knowing","thread":"她问怎么没给她留灯"}},{"title":"说那是网的名字","desc":"你说阿澜是她织过的一种网，她织得最好，别多想。","hint":"她信了。","tone":"peace","outcome":"母亲哦了一声，说：那网结实，能兜住石头。她说完就睡了，睡得很安稳。后半夜她走了，手停在被子外面，像还要去够梭子。你替她把手指一根一根合上。小螺问你她最后说了什么，你说：说网。小螺点头，说：她这辈子就会这个。你没再解释。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":5},"flag":"lied_to_mother_end","thread":"她以为阿澜是一种网"}},{"title":"不答，替她数钟","desc":"你握住她的手，跟着塔上的钟，一声一声数到七。","hint":"你数到七，她的手停了。","tone":"carry","outcome":"你数到第三声，她的手动了一下；数到第五声，她跟着你的手指数；数到第七声，她的手停了。你没告诉她阿澜是谁。后来你想，她也许本来就知道，只是那个名字被钟咬掉了一半。你把她烧剩的衣角缝进自己的袖口，从此每年海边多一个人站着。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"爱":3},"flag":"counted_to_seven","thread":"袖口里的衣角"}}]},{"id":"zhong_m10","act":"main","age":[52,52],"mode":"narration","title":"裂缝","opening":"五十二岁，最后一口钟裂了。裂缝从钟口往上爬，爬到钟肩，像一条干了的水道。潮声议会的人来了三回，带着新的钟谱和一箱铜料，说补钟要献记忆，一年一段，献到钟不裂为止。静潮教团的哑姑也来了，跪在静湾的沙上，不出声。她见你过来，用手指在沙上写：让它沉，人就轻了。父亲已经认不出塔，每天还在门后擦那把钟锤。","ask":"钟裂着，全岛在等，你先做什么？","days":60,"npc":"","memory":"最后一口钟裂了","choices":[{"title":"献出母亲的记忆","desc":"你把手按在钟上，先交出母亲的声音，换一年。","hint":"你很快忘了她怎么叫你。","tone":"repair","outcome":"铜是凉的，凉到手心发麻。你走出静湾时，忽然想不起母亲的声音，只记得她织网时手一直在动。第二年裂缝又长一寸，你又去一回，这回交出她坐在门口的样子。第三回你站在她坟前，认不出碑上的字。钟撑住了，你的来处却越来越薄。","eff":{"bond":0,"health":-3,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":6,"惧":3},"flag":"fed_mother_memory","thread":"你忘了母亲的声音"}},{"title":"告诉全岛准备忘","desc":"你挨家敲门，说钟要沉了，让各家把名字写在手上。","hint":"父亲把钟锤藏了。","tone":"refuse","outcome":"岛上的人先是骂你，后来有人真的拿炭在手上写名字。议会的人来拦，说钟还没沉，不许散播。父亲听说了，把钟锤藏进灶膛后的砖缝，谁问都说不知道。哑姑在静湾朝你点头。你回家看见父亲坐在门槛上，手里空着，一遍一遍擦手心。","eff":{"bond":-1,"health":0,"reputation":-3,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":3},"flag":"warned_island","thread":"父亲把钟锤藏了"}},{"title":"按册子找下一家","desc":"你翻开议会的新册，去敲第一户的门，让他们献。","hint":"开门的是个小女孩。","tone":"practical","outcome":"开门的是个七八岁的女孩，她娘病在床上。你把册子摊开，说献一段记忆，钟就能多撑一年。女孩问：忘了娘，是不是就不疼了。你没答。她娘在屋里说：献我的。你站在门口，把册子合上又打开，最后写下了她娘的名字。回塔的路上，你听见自己的脚步很响。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":2},"flag":"collected_memory","thread":"女孩问忘了娘疼不疼"}}]},{"id":"zhong_m11","act":"main","age":[70,78],"mode":"narration","title":"静湾","opening":"七十岁那年，你握着父亲的钟锤站在静湾。钟在水里，只露出钟肩，裂缝张开，像一张要说话的嘴。全岛的人在岸上等。这八年钟一直裂着，没沉。裂缝每长一寸，就有人往里填东西——有人填铜，有人填记忆。你填自己：填到最后，你记得钟谱上每个名字，却忘了阿箬的脸、母亲的声音。七十八岁春，钟在水下响了一声，很闷。小螺带着女儿站在人群里，女孩攥着那枚不属于本岛的钟舌，海腥味飘过来。","ask":"钟要沉了，你举着锤，怎么办？","days":360,"npc":"","memory":"握着钟锤的八年","choices":[{"title":"敲响它","desc":"你把钟锤抡圆，砸在钟耳上，让全岛都听见。","hint":"钟声散后，谁都不能再忘。","tone":"brave","outcome":"钟声从静湾滚出去，撞在七块礁石上，又滚回来。岸上的人一个个站住——他们想起来了：阿澜、阿鲛、阿潭，还有你。有人叫出你的名字，声音发抖。钟没有沉，裂缝合上一半，海却退得很快，露出老航道。你知道它还会回来收。那天夜里，岛上没有一个人睡着。","eff":{"bond":3,"health":-3,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":5,"惧":4},"flag":"rang_last_bell","thread":"海退得太快了"}},{"title":"让它沉","desc":"你退后三步，把钟锤放在沙上，看着水漫过钟肩。","hint":"明天没人记得你。","tone":"leave","outcome":"水漫过钟肩，漫过裂缝，钟没有响。岸上的人先是愣着，后来互相看看，像刚从长睡里醒来。有人问：咱们站这儿干什么。有人笑，说回家吃饭。你站在最后面，把那本泡烂的钟谱塞进钟口，看着它一起沉下去。小螺回头找了你一眼，没认出你。第二天船出了湾，海退了。","eff":{"bond":-2,"health":-4,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"哀":5,"爱":2},"flag":"let_bell_sink","thread":"小螺没认出你"}},{"title":"把名字分给人","desc":"你翻开钟谱，一页一页念，让岸上的人一人认一个名字。","hint":"有人会记错。","tone":"teach","outcome":"你念一个，就有人举手。阿鲛分给卖鱼的，阿潭分给磨刀铺，阿澜分给小螺的女儿。有人念两遍才念对，有人把两个字记成一个。念完你把空谱扔进水里，钟自己沉了，没响。岸上的人各自攥着一个名字回家，像攥着一枚烫手的铜。","eff":{"bond":4,"health":-2,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"爱":4,"哀":4},"flag":"shared_names","thread":"有人把两个字记成一个"}}]}],"side":[{"id":"zhong_x02","act":"side","age":[6,6],"mode":"narration","title":"网里那个人","opening":"六岁那年，退潮后的滩上摊着一排渔网，网眼里挂着碎海草，太阳一晒，腥味往上冒。你从网这头走到那头，脚底板被盐壳硌得疼。走到第三张网，中间鼓起一个人形的包，比鱼大，比狗大。你蹲下去看，那包动了一下。你后退，鞋跟陷进湿沙里。跑去喊人的时候你摔了一跤，膝盖上沾了一层沙。大人们来了，围成一圈，谁也不先伸手。守仓的六指婆挤进来，看了一眼，说：点灯。有人真去点了灯，把一盏渔灯放在网边。海风一吹，灯苗歪了，网里那个包又动了一下。","ask":"网里那个鼓包，你敢不敢碰？","days":10,"npc":"","memory":"渔网里的人形","choices":[{"title":"按规矩盖上席","desc":"你照大人教的，拖一张草席盖上去，四角压石头。","hint":"席子底下在起伏。","tone":"rule","outcome":"席子盖上去，安静了一会儿，然后开始起伏，像有鱼在里头顶。没人敢掀。守钟人赶来时，席子底下传出一句：闷。是阿坤，昨晚喝多了，睡在网里。灯已经点了，规矩说点了灯的得敲完，于是全滩的人站着，听那口小钟替他敲了一回。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":4,"惧":2},"flag":"covered_living_man","thread":"替活人敲的那口小钟"}},{"title":"掀开网看","desc":"你伸手把网掀开一角，蹲下去看里头。","hint":"六指婆说晦气。","tone":"honest","outcome":"网里是个男人，脸朝下，后颈上全是网绳压出的红印。你喊：是活的。大人们愣住，六指婆把灯端起来照了照，说：活人睡网，晦气。那盏灯还是被端到海边烧了，烧完才散。阿坤醒来，第一句话是要水喝，第二句问：你们围着我干什么。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}},{"title":"拿竹竿捅","desc":"你隔两步远，捡根竹竿，往那个包上捅一下。","hint":"捅在鼻子上。","tone":"defy","outcome":"网里炸出一声喷嚏，整张网弹起来，围着的七八个人一齐后退，有人踩翻了渔灯。阿坤从网里坐起来，鼻子底下两道血，骂了一句很脏的话。六指婆笑得直不起腰，笑完说：灯钱你赔。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":-2,"stats":{"机缘":1},"emotion":{"喜":5,"惧":1},"flag":"","thread":""}}]},{"id":"zhong_s01","act":"side","age":[7,7],"mode":"narration","title":"数钟歌","opening":"七岁那年夏天，退潮后礁石一块块露出来，孩子们在滩上跳格子，一边跳一边唱数钟歌：七块礁，七口钟，七个不能念的名字。唱到第七句，谁接不上，就要被推下海。你唱得最熟，因为母亲织网时也哼这个调。那天新来的孩子唱到第七句，把“沉”唱成了“睡”。孩子们一下全停了，只有盐壳在脚底下响。他娘站在岸上，手里提着一串咸鱼。","ask":"第七句唱错了，你怎么办？","days":10,"npc":"","memory":"孩子们数钟的歌","choices":[{"title":"替他唱完第七句","desc":"你大声接上，把“睡”唱回“沉”，然后自己跳进水里。","hint":"咸水从鼻子里出来。","tone":"protect","outcome":"你跳下去，水到胸口，脚底踩到滑的石头。他伸手拉你，自己没湿。孩子们笑起来，把格子让给他。往后几年，一到第七句，他就看你一眼。你落下一个毛病：下水前先咳一声。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":"一到第七句他就看你"}},{"title":"按住他重唱三遍","desc":"你把他按在礁石上，一句一句逼他唱对，唱错就重来。","hint":"他后来不唱歌了。","tone":"rule","outcome":"第三遍他唱对了，声音很平。孩子们叫他哑钟，他娘把咸鱼塞给他，牵走了。那年秋天他没再来滩上。再后来他上了外岛的船，走的时候没跟人说。数钟歌里第七句从此少一个声音。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"他走时没跟人说"}},{"title":"跟着把他推下去","desc":"你伸手推在他后背上，和大家一起喊，喊得比谁都响。","hint":"他额头磕在礁上。","tone":"defy","outcome":"他栽进水里，起来时额角裂了一道口，血混着海水往下流。他笑着说小伤，把咸鱼分给推他的人。你没接。那天回家，母亲问你怎么一身盐，你说摔了一跤。那道疤他带了一辈子。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"恶":2},"flag":"","thread":"那道疤他带了一辈子"}}]},{"id":"zhong_x01","act":"side","age":[8,8],"mode":"narration","title":"多出来的半声","opening":"八岁那年秋天，退潮钟一响，滩上的孩子就排成一排数。规矩是谁数错，谁替大家把一篮鱼送上铜喉塔。钟在塔顶，声音撞到七声礁上会弹回来，最后一下总带回半声，像有人在后头补了一记。你数到七就闭嘴，阿蛤数到八，还伸着八根指头。他说你们都没听见。你说那是回声。他推你，你推他，两个人滚在盐壳上，膝盖磨出血印，嘴里全是咸味。大人在岸上喊，父亲在塔上探出半个身子，手搭在钟绳上。海风把晒鱼的腥味吹过来，绳上的小螺壳碰在一起响，谁都不说话了。","ask":"多出来的那半声，算谁的？","days":10,"npc":"","memory":"滩上的八根指头","choices":[{"title":"认下这一声","desc":"你举起手，说八是你数的，鱼你去送。","hint":"阿蛤不领这个情。","tone":"protect","outcome":"你提着鱼篮上塔，篮底漏水，走一路滴一路。父亲看了一眼篮子，没问。阿蛤在塔下等着，等你下来，说：我没让你认。他把鱼篮抢过去自己提回家，路上没回头。第二天孩子们还是唱那半声，唱给你听。","eff":{"bond":-2,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":2,"惧":1},"flag":"","thread":"阿蛤把鱼篮提回去了"}},{"title":"上塔问个明白","desc":"你拉着阿蛤爬塔，让父亲当着两人的面再敲一遍。","hint":"父亲数到了八。","tone":"ask","outcome":"父亲敲了一下，两个人一起数，数到八。他停住，手在钟绳上多握了一会儿，说：回头我报上去。第二天议会来了人，量了钟口的裂缝，说塔身松了，回声不对。钟没修，谱上倒添了一行小字。阿蛤从此见你就说：我没数错，说到十八岁。","eff":{"bond":3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"惧":1},"flag":"counted_eight","thread":""}},{"title":"按他进浅水","desc":"你把他按在滩上的浅水里，逼他改口说七。","hint":"他呛了一口咸水。","tone":"defy","outcome":"阿蛤在水里扑腾，喝了一口，举着七根指头喊七。孩子们笑起来，笑得很响。他爬起来，吐了口沙子，说：你等着。那天傍晚他娘端着一盆洗鱼水站在你家门口，泼在门槛上。你娘拿扫帚扫了半天，一句话没说。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"恶":2},"flag":"","thread":"他娘泼在门槛上的水"}}]},{"id":"zhong_s09","act":"side","age":[10,10],"mode":"narration","title":"喜宴上的誓","opening":"十岁那年秋天，阿树娶阿棠。祠堂里摆两张桌，桌上是咸鱼、海带和一坛浊酒，海腥味压过酒味。按规矩，两家的岛钟要合鸣，鸣过之后新人把誓说给钟听。阿棠的娘把一块耳蜡按进她手心，说：说响些，钟听见了才算数。阿棠张了张嘴，没出声；阿树也张了张嘴，也没出声。满祠堂的人都不说话，只有钟绳在梁上轻轻晃。你蹲在桌底下，替他们捧着那盏灯。","ask":"一句誓都说不出口，你怎么办？","days":10,"npc":"","memory":"祠堂里的半句誓","choices":[{"title":"替他们把誓喊出来","desc":"你从桌底钻出来，站到钟前，把两个人的誓一句一句喊完。","hint":"钟记住了你的嗓子。","tone":"protect","outcome":"你喊到第三句，钟自己响了一声，很轻。阿棠的娘把酒倒进海里，祠堂里的人这才动筷子。婚后他们待你像自家人，年年给你留一条鱼。可你说话从此带一点回声，数钟歌唱到第七句就哑。阿棠后来跟人说：那天的誓，不是我们说的。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"惧":2},"flag":"spoke_wedding_vow","thread":"誓是你替他们说的"}},{"title":"去叫证婚的守钟师","desc":"你跑去塔上把父亲拉来，让他按规矩把誓录进谱里。","hint":"誓一入谱，全岛多背一年。","tone":"rule","outcome":"父亲提着钟谱下塔，鞋都没换。他把两个人叫到钟前，一句一句问，一句一句记，记在泡烂的纸页边上。誓录进去了，婚算成了。那年冬天岛上多病了一个月，议会把多出来的名字写在谱末，字很小。阿棠从此在人前不叫阿树的名字，只叫一声喂。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"registered_wedding_vow","thread":"她在人前只叫一声喂"}},{"title":"敲盆把话盖过去","desc":"你抓起桌边的铜盆跳上凳子，敲得满祠堂听不见人说话。","hint":"婚成了，谱上没有他们。","tone":"defy","outcome":"铜盆响得刺耳，阿棠趁机把誓说给阿树一个人听，说得很轻。钟没听见。婚事办完了，可钟谱上两个人的名字没有并到一处。第二年他们生了孩子，孩子的名字只能写在谱的边角上，字小得像蚊子。阿棠的娘三年没跟你说话，见你就把门关上。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"惧":3},"flag":"covered_wedding_vow","thread":"谱边角上那个小字"}}]},{"id":"zhong_x03","act":"side","age":[11,11],"mode":"dialogue","title":"一箱螃蟹","opening":"十一岁那年，小螺从沉钟渊拖上来一只箱子。木头的，四角包铜，铜上长着绿锈，锁是死的。箱子一挪就响，不是木头响，是里头有东西在撞，一下，停一停，再一下，像有人隔着板子敲指头。她把它摆在塔底，蹲在旁边听，头发上的水往下滴，滴在箱盖上，洇出一小片深色。她说行会出三十个潮铢收，她还没答应。说完她就出海了，让你看着。塔底只有这一只箱子和你。墙根泛着一圈白霜似的盐，潮气从砖缝里往上爬。天黑以后海面上没有风，箱子里那声音显得特别清楚，响一下，你数一下。","ask":"箱子里响了一夜，你开不开？","days":10,"npc":"sibling","memory":"响了一夜的箱子","choices":[{"title":"半夜撬开","desc":"你等不到天亮，摸来父亲的凿子插进缝里。","hint":"手指被夹了两下。","tone":"greed","outcome":"锁没开，板子裂了。箱盖弹起来，一窝螃蟹涌出来，青壳，小的指甲盖大，大的有巴掌，满地横着跑。你抓了半篓，手指被夹了两下。小螺回来，看见满地蟹壳和你的手，说：三十个潮铢，你吃了。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":5},"flag":"opened_box_early","thread":"半篓螃蟹"}},{"title":"守着等小螺","desc":"你抱着膝坐在箱子对面，响一下数一下。","hint":"数到两百多就睡着了。","tone":"wait","outcome":"你数到两百多，天蒙蒙亮，睡着了。小螺回来时箱子还在响，她笑着骂你一句，抬脚一踹，箱盖开了，螃蟹爬出来，两个人蹲在地上抓。那天的早饭是蟹，吃到中午，手指上全是腥味，谁也没提行会的三十个潮铢。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":""}},{"title":"抱去问余婆","desc":"你抱着箱子去北礁，让余婆摸一摸是什么。","hint":"她屋里全是螃蟹。","tone":"elder","outcome":"她九十一岁，眼睛剩一条缝，伸手在箱盖上摸了一圈，说：活的，放回去。你还没问为什么，箱子自己散了——不是开，是木板被蟹钳一点点咬松。螃蟹爬了满屋，钻进她的鞋里、灶膛里、床底下。余婆坐在床上，脚不沾地，笑得直咳嗽。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":4,"爱":1},"flag":"","thread":"余婆屋里的螃蟹"}}]},{"id":"zhong_s02","act":"side","age":[12,12],"mode":"narration","title":"一墙耳蜡","opening":"十二岁那年，母亲让你送一袋盐去北礁。余婆的屋里只有一个灶、一张床，和一面墙的耳蜡。蜡是灰白的，一块挨一块，每块上刻一个名字，用指甲划的。她九十一岁，眼睛只剩一条缝，耳朵却尖，听脚步就知道是你。她说年轻时替人报名，全岛的名字都在她这儿。她从灶边摸出一块新蜡，蜡上刻着两个字，外面裹着一张泡烂的纸。她说：这个人我快记不住了。你替我记。","ask":"余婆把一块蜡塞给你，你怎么办？","days":60,"npc":"","memory":"余婆的一墙名字","choices":[{"title":"坐下来学那一墙名字","desc":"你每天下午来，让她念，你跟着背，背错就重来。","hint":"十三个名字你背漏了。","tone":"learn","outcome":"你学到入冬，背下两百来个，梦里都是别人的姓。那块刻着两个字的蜡你贴身收着，蜡被体温焐软了边。余婆腊月里走了，走前把墙上最后一块按在你手心。议会来收墙，你站在门口，忽然想不起其中十三个。那十三个名字此后一直空着，像掉了牙的牙床。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"learned_names","thread":"十三个名字空着"}},{"title":"报给议会收走","desc":"你跑去议会说北礁有一墙名字，请他们抄进钟谱。","hint":"蜡墙当天就搬走了。","tone":"report","outcome":"来了三个人，把蜡一块块撬下来，装进木箱，说要抄进新谱。余婆坐在灶边，手放在膝盖上，没拦。木箱抬出门时她问：抄完了还回来吗。没人答。新谱放进潮库房，第二年你去看，纸泡烂了一半，蜡也化了，黏在箱底。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"reported_wax_wall","thread":"蜡在箱底化了"}},{"title":"只拿走自家那块","desc":"你在墙上找到自家的姓，抠下那块蜡，揣进袖子。","hint":"她看着你挑。","tone":"practical","outcome":"余婆没说话，看你在墙上找。你找到铜九两个字，抠下来，蜡边碎了一角。她说：挑得对，一个人记一个就够。那块两个字的新蜡你没拿，留在她灶台上。你回家把自家的蜡放进盐罐，盐把蜡面磨亮。余婆死后那面墙被邻居拆了当柴烧，有股蜡味，飘了半个礁。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":"盐罐里那块蜡"}}]},{"id":"zhong_x04","act":"side","age":[12,12],"mode":"narration","title":"盐仓那一夜","opening":"十二岁那年夏末，一场雨下了整夜。盐仓在坡上，屋顶是旧船板拼的，板缝里塞着麻絮。雨从缝里漏下来，一条一条，落在盐堆上，落一处化一处，化出一个个圆坑，坑底积着浑水。守仓的六指婆半夜拍门，把半条巷的孩子都叫起来抢盐。你端着一只簸箕往里跑，脚下一滑，整个人扑在盐堆上，嘴里、鼻子里、领口里全是盐，咸得舌根发苦。有人在你旁边也摔了，摔得比你远。雨打在船板上，声音很密，像有人在头顶撒豆子。六指婆举着一盏灯，灯罩上蒙着油布，光只照亮她半张脸和满地白花花的盐。","ask":"盐化在水里，你先顾哪头？","days":10,"npc":"","memory":"盐堆上的一跤","choices":[{"title":"爬上去堵漏","desc":"你爬上仓顶，用旧网蒙住最大的漏口，人压上去。","hint":"雨砸在背上像石子。","tone":"brave","outcome":"你压在网上，衣服贴在骨头上，凉。六指婆在底下喊你下来，你不下。天亮雨停，那一片盐保住了，你烧了三天，躺着的三天里舌头上一直是咸的。六指婆来看过一回，放下一小包糖，没说给谁的。","eff":{"bond":2,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":1},"flag":"","thread":""}},{"title":"一簸箕一簸箕搬","desc":"你和几个孩子把没化的盐扒到干的那头去。","hint":"手心磨出两个泡。","tone":"grind","outcome":"搬到后半夜，手臂抬不起来，簸箕边把手心磨出两个泡。天亮一数，化掉三成，剩下的堆成一座小山，盖了席子。六指婆给每人盛一碗粥，粥里放了一撮糖——她藏了很多年的一小罐，罐口磕了个缺。","eff":{"bond":1,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":2,"爱":2},"flag":"","thread":""}},{"title":"脱鞋在盐上滑","desc":"你把鞋一脱，踩着湿盐往前滑，一下滑出半间仓。","hint":"六指婆也摔了一跤。","tone":"defy","outcome":"孩子们看见了，全脱了鞋，一个跟一个滑，摔成一堆，笑得直不起身。六指婆举着扫帚追，追到盐堆上也滑了一跤，坐在地上，扫帚飞出去老远。那晚化掉的盐够全岛吃一个月，谁也没挨骂。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":6},"flag":"","thread":"六指婆滑的那一跤"}}]},{"id":"zhong_x05","act":"side","age":[13,13],"mode":"narration","title":"不肯靠岸的船","opening":"十三岁那年，阿埕的船从外海回来了，回来得不是地方——它在七声礁外头打转，一圈，又一圈，帆收了，桨横在舷边，没人划。岸上的人很快站满了滩。阿埕的媳妇抱着孩子站在最前头，孩子在她怀里睡着了，脸被海风吹得发红。浪不大，船就是不肯进来，像有人在水底下拽着它的龙骨。老人说：船上有人没咽气，进不来。也有人说：是咽了气，才进不来。两种说法都没人敢去试。太阳偏西，海面亮得刺眼，船影在礁石间一趟一趟地移。船头挂着一串晒干的小鱼，风一吹，碰在一起响，声音传到岸上，细得像针。","ask":"船在礁外打转，谁去接它？","days":10,"npc":"","memory":"礁外那圈船影","choices":[{"title":"划出去拖它","desc":"你和小螺上小舢板，划到礁外，把绳子系上。","hint":"你看见了舵上的手。","tone":"brave","outcome":"靠近时你看见阿埕坐在船尾，一只手搭在舵上，头低着，像在看水。绳子系上，你们往回拖，他的船跟得很沉，像船底还挂着东西。拖进湾里天已经黑了。你从此一闭眼就看见那只搭在舵上的手，指节上有个旧疤。","eff":{"bond":1,"health":-1,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"哀":5,"惧":3},"flag":"towed_dead_mans_boat","thread":"舵上那只手"}},{"title":"在礁上点灯","desc":"你举着一盏灯站在礁上，等它自己进来。","hint":"她站了一夜。","tone":"wait","outcome":"船在灯影外头转，转到天快亮，潮水退了，它自己搁在浅滩上，龙骨擦着沙，发出很长的一声。阿埕的媳妇在岸上站了一夜，脚踝肿得像馒头。她把孩子往上抱了抱，回头看你一眼，那一眼你记了很久。","eff":{"bond":-2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"她记住了你没出去"}},{"title":"上塔敲钟引它","desc":"你跑上塔，抓住钟绳就敲，一下一下。","hint":"名字提前进了谱。","tone":"rule","outcome":"退潮钟一响，滩上的人全抬头。船在礁外停了半息，然后慢慢转了方向，跟着钟声进湾，搁在沙上。阿埕的名字当天就写进谱。他媳妇没哭，走过来问你：是你敲的。你说是我。她说：他听见了。说完抱着孩子回去了。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"rang_for_boat","thread":""}}]},{"id":"zhong_x06","act":"side","age":[15,15],"mode":"dialogue","title":"我还没死","opening":"十五岁那年，你替父亲抄谱。旧谱泡过海水，字迹发毛，得一笔一笔描到新册上。抄到第三十七行，上一行是阿蚝死去的妹子阿媚。你抄完阿媚，手一滑，下一行阿蚝也顺手归进了亡者那栏。两行挨着，笔迹一样，你自己都没看出来。三天后阿蚝踹开塔门，一脚踩在门槛上，鞋底带进来的沙撒了一地。他嗓门大，整条巷都听得见：我还没死！他手里攥着一张纸，纸都被他攥软了，边角被汗浸透。父亲站在楼梯上，没下来，手里拿着笔，笔尖上还挂着一点墨。","ask":"把人写死了，你怎么收场？","days":15,"npc":"father","memory":"抄错的那一行","choices":[{"title":"认下这笔债","desc":"你当众说错是你抄的，咬破手指按在自己名下。","hint":"父亲在楼梯上咳了一声。","tone":"honest","outcome":"巷子里的人都听见了。阿蚝愣住，骂声停在半截。你按完手印，血在纸上洇开一小片。他走的时候把那张纸留下了。那年冬天全岛都在说：守钟人的儿子替人死了一回。父亲一直没问你为什么。","eff":{"bond":-3,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"爱":1},"flag":"took_debt_for_ashu","thread":""}},{"title":"夜里刮掉那行","desc":"等父亲睡熟，你摸上楼，用刀尖刮那一行。","hint":"纸破了个洞。","tone":"secret","outcome":"纸太脆，刮到一半破了，破成一个指甲盖大的洞，正好在阿蚝的名字上。你把新册合上压平，装作没动过。第二天父亲翻到那页，手指在洞上按了按，抬头看你，看了很久，什么也没说，把册子合上了。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":4},"flag":"scraped_register","thread":"谱上那个洞"}},{"title":"让他骂完","desc":"你站着不动，等他骂到没词，去灶上倒碗水。","hint":"他第二天还要你改。","tone":"steady","outcome":"他骂你咒他，骂你家的钟，骂到后来词穷了，站在塔底喘气。你把水递过去，他接了，喝一半，碗往地上一放，说：明天给我改回来。第二天你改了。他再没提这事，只是每年上塔送鱼，多送一条。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"爱":2},"flag":"","thread":""}}]},{"id":"zhong_s03","act":"side","age":[17,17],"mode":"dialogue","title":"钟里有一只碗","opening":"十七岁那年，小螺第一次带你下沉钟渊。她在你腰上系绳，绳打七个结，说拉三个结是上来，拉五个结是绳断了。水到胸口时你听见钟声，不是从塔上，是从脚底下传上来的，闷，像有人在楼下搬桌子。潜到第三口气，你看见那口钟：侧躺在沙上，钟口朝上，里头是干的，干得发白，摆着一只碗、一双筷子，碗底结着一圈盐。","ask":"钟里那只碗，你要不要动？","days":10,"npc":"sibling","memory":"沉钟渊的那口钟","choices":[{"title":"把碗扶正，添一把盐","desc":"你把碗摆正，从怀里摸出一撮盐撒进去，朝钟口磕三个头。","hint":"上来时你咳出海水。","tone":"heal","outcome":"磕到第三个头，气就不够了。小螺拉绳，把你拖上去，你在船上咳了半天，咳出咸水。那口钟在你耳边响了一声，很轻。之后每逢阴天，你左胸里像压着一只碗。你没跟人说起过那口钟里的碗，也没再下去过。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"惧":3},"flag":"fed_bell_bowl","thread":"阴天胸口像压着碗"}},{"title":"上来讲给父亲听","desc":"你把看见的一字不落说给父亲，包括碗和那双筷子。","hint":"沉钟渊封了，小螺没了活计。","tone":"honest","outcome":"父亲听完，连夜上了议会。第二天沉钟渊立了浮标，不许下潜。小螺的鱼篓空了一个月，她坐在码头补网，见你过来就把脸转开。她说：你知道那底下有多少人靠它吃饭。你没答。那年冬天她借了别人的船，去了更远的未响海。","eff":{"bond":-4,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"reported_bell_bowl","thread":"她去了更远的海"}},{"title":"把碗揣进怀里带走","desc":"你把碗塞进怀里，用衣襟裹住，朝小螺比了个上去的手势。","hint":"碗里的盐永远干不了。","tone":"greed","outcome":"碗在怀里是凉的，贴着肋骨。上岸后你把它藏在塔底的砖缝里。第二天早上去看，碗底又结了一圈盐，昨天明明擦干了。你没敢再用它吃饭。小螺问你在底下拿了什么，你说什么也没拿。她看了你一会儿，没再问。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"欲":2,"惧":2},"flag":"took_bell_bowl","thread":"碗底天天结盐"}}]},{"id":"zhong_x07","act":"side","age":[17,17],"mode":"narration","title":"扎在皮上的字","opening":"十七岁那年，阿蜜来找你。她织网，六十多，没有儿女，男人十年前沉在海里，尸首没捞上来。她坐在塔底的矮凳上，把一根缝网的大针和一小碗锅底灰放在桌上，说：你手稳，你替我扎。她把左袖卷到肩，露出小臂，皮松了，一捏一把。手背上有一道旧疤，横着，是年轻时被网绳勒的。她说：海上捞上来的人，脸都泡烂了，认不出。字扎大一点，扎在这儿，谁都看得见。塔外的潮水在退，礁石一块一块露出来，露出底下黑色的水痕。针在桌上，针尖对着你。","ask":"她要你把她名字扎进皮里，扎不扎？","days":20,"npc":"","memory":"锅底灰和一根针","choices":[{"title":"替她一针一针扎","desc":"你让她把手放平，一针一针扎，灰拌酒抹进去。","hint":"她说字太小。","tone":"warm","outcome":"她攥着桌沿，指节发白，一声没吭。扎完她抬起胳膊看，说：小了。你说再大就废了。她把袖子放下来，说：够了。走的时候她在门口站了一会儿才出去，下梯子踩得很慢。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":3},"flag":"tattooed_ami","thread":"她手臂上那两个字"}},{"title":"说活着才要名字","desc":"你把手按在针上，说人死了认不认得出，你也管不着。","hint":"她把针收回去了。","tone":"honest","outcome":"她把手收回去，针插回线团，锅底灰倒进灶膛。她说：你说得对。她走得很慢。第二年春天她的船翻在湾口，人捞上来了，脸没坏，用不着认。你去认的尸，站在草席边上认了很久。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"你自己去认的尸"}},{"title":"偷偷写进谱里","desc":"你趁父亲不在，在活人栏末尾添上阿蜜两个字。","hint":"墨水吃进纸里。","tone":"sneak","outcome":"父亲回来翻谱，一眼看见了，用指甲刮了三下，刮不掉。他把谱合上，说：多一个名字，全岛多背一年。第二天他还是没再刮。阿蜜不知道这件事，见你就笑，笑得眼睛眯成一条缝。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":3},"flag":"added_ami_name","thread":""}}]},{"id":"zhong_s10","act":"side","age":[18,18],"mode":"narration","title":"皮上的名字","opening":"十八岁那年，阿屿来找你。他弟弟阿汀是第四口钟沉那天没的，尸首没捞上来，钟谱上只留了一行。他坐在塔下，把左袖卷到肩，手臂内侧已经划好了两个字，墨吃进皮里，边上肿得发亮，还差最后一笔。他把针和一碗盐水推给你，说：你识字，你替我添。又说：你念一遍就行，我自己不敢念。塔外正在退潮，海腥味从窗缝里进来，桌上压着一张泡烂的纸。","ask":"针在你手里，最后一笔添不添？","days":15,"npc":"","memory":"皮上的两个字","choices":[{"title":"替他添上这一笔","desc":"你按住他胳膊，念一遍阿汀，把最后一笔描完，血珠冒出来。","hint":"钟会顺着血找来。","tone":"warm","outcome":"最后一笔落下去，他咬着筷子没出声。血珠沿字边走，盐水一抹，字黑了。你念名字时，塔上的钟自己响了一声。此后你半夜总听见有人叫阿汀，应过一回，右耳就整夜有钟声。三年后他的船没回来，捞上来时胳膊泡白了，字还在，钟却不肯为他响：名字在皮上，钟不认。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":3},"flag":"inked_ati_name","thread":"右耳整夜有钟声"}},{"title":"报到守钟卫队","desc":"你把针收进袖子，出门就往卫队那边走，没回头。","hint":"他们用浮石磨他的皮。","tone":"report","outcome":"卫队当天下午就来了，两个人按住他，一个人用浮石和盐水磨。磨到第三遍，他不再挣了。字没了，皮上留一块淡红的疤，两个指头后来弯不直，捏不住网梭，改在岸上补船。他没骂你，只是有一年冬天在鱼市碰见，把手往袖子里缩了缩。","eff":{"bond":-5,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"reported_tattoo","thread":"他把手缩进袖子"}},{"title":"推给他一张纸","desc":"你把那张泡烂的纸推过去，说照这个描，别出声，我下去。","hint":"他描错了一笔。","tone":"avoid","outcome":"你下了塔，在礁上坐到天黑。他自己对着铜镜描，描歪了一笔，阿汀描成了阿灯。第二天他来谢你，把胳膊给你看，你没说是错的。此后他逢人就念阿灯，念得又顺又响。真正的阿汀没人念了，钟谱上那一行慢慢洇开，只剩一个汀字还认得出。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"恶":1},"flag":"","thread":"阿汀被描成了阿灯"}}]},{"id":"zhong_x08","act":"side","age":[18,18],"mode":"narration","title":"三百斤鱼","opening":"十八岁那年秋汛，一网起上来三百多斤，倒在滩上，鱼尾还在拍沙。按老规矩，船主先挑，剩下的按人头分。船主挑完，最大的几条都进了他家的筐，轮到阿潭家的寡妇，筐底只有些小杂鱼，还有一条被踩烂了肚子的。她没说话，把那条烂鱼捡起来，抖了抖沙。有人小声说了一句，船主回头，说：他家这几年没人上船。滩上一下子静了，只有鱼尾拍沙的声音，一下，一下。海腥味浓得发闷。她蹲下去，把那条烂鱼放在自己脚边，用手背把鱼身上的沙抹掉，抹了三回。","ask":"鱼分不匀，你站哪一边去？","days":10,"npc":"","memory":"筐底那条烂鱼","choices":[{"title":"把自家那筐倒给她","desc":"你走过去，端起自家的筐，整个倒进她的筐里。","hint":"你娘拎着空篮先回了家。","tone":"protect","outcome":"鱼滚出来，落了一地。你娘站在人群后头，手里还拎着空篮子，什么也没说，转身先走了。那晚桌上只有一碗咸菜。她把碗往你面前推了推，说：吃。她自己没动筷子。","eff":{"bond":3,"health":-1,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"敲秤杆喊按人头分","desc":"你抄起秤杆跳上船帮，敲三下，喊按人头分。","hint":"来年船上没有你。","tone":"rebel","outcome":"喊到第三遍，有人跟着喊。船主的脸涨红，最后把大鱼倒回滩上重分。分完你多得一条，是别人塞给你的。来年开春船主招人，名单上没有你，你也没去问。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"惧":2},"flag":"spoke_at_split","thread":"来年的船上没有你"}},{"title":"把最大的扔回海","desc":"你抱起最大那条，走到水边，扔了回去。","hint":"她等的就是那条。","tone":"defy","outcome":"鱼砸进水里，尾巴一甩，没了。滩上没人说话。船主骂了一句。寡妇也看你，眼睛红了——她等的就是那条。你站着没动，裤脚被浪打湿，一直湿到膝盖。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"恶":1},"flag":"","thread":""}}]},{"id":"zhong_x09","act":"side","age":[20,20],"mode":"narration","title":"水底下的钟","opening":"二十岁那年夏天，你夜里划小舢板去收蟹笼。月亮被云挡着，海面黑得发亮，桨一入水，搅起一片碎光。收第三只笼时，脚底下的水响了一声。不是水响，是钟——从很深的地方传上来，闷，拖得长，像有人在水底推一口大缸。你停了桨。第二声来的时候，船自己转了半个圈，蟹笼的绳子绷紧，往水里坠。海面上涌起一层细密的泡，腥味突然重了，压得人喘不上气，喉咙里像塞了一团湿棉花。岸上的灯很远，像一粒米。你手掌贴在船板上，能摸到木头被水泡涨的软。","ask":"海底的钟响了，往回划还是往下听？","days":10,"npc":"","memory":"脚下传来的钟声","choices":[{"title":"割绳往回划","desc":"你摸出刀，割断蟹笼绳，抓起桨拼命往岸划。","hint":"十二只笼全没了。","tone":"escape","outcome":"绳子一断，船身猛地一轻。你划得肩膀发麻，上岸时回头看，那片水面全是泡，像烧开了一样。十二只蟹笼全没了，那是家里过冬的。你娘问了一夜，你只说浪大。第二天滩上捡到一只空笼，笼里只剩壳。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"哀":2},"flag":"","thread":"十二只蟹笼"}},{"title":"扎下去听","desc":"你把桨横在船上，吸一口气，翻下水去。","hint":"钟里有人在念名字。","tone":"seek","outcome":"水比想的冷，耳朵里全是嗡响。往下三四丈，你摸到一片铜，冰凉，上面全是麻点。钟里有人在念名字，一个字一个字，很慢。你想再往下，胸口开始烧，绳头在手里滑。浮上来时鼻子出血，滴在船板上，黑红的一小片。","eff":{"bond":0,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"惧":5,"哀":1},"flag":"dived_to_bell","thread":""}},{"title":"用桨敲船帮应它","desc":"你抓起桨，用桨背敲船帮，一声一声应。","hint":"左耳从此一直响。","tone":"defy","outcome":"应到第七下，海底那口钟停了，停得很干脆。水面平下来，蟹笼的绳子也松了。你把笼子一只只收上来，收完天已经亮了。从那以后你左耳一直有钟声，别人的话要凑近才听得清。","eff":{"bond":0,"health":-3,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":4,"喜":2},"flag":"left_ear_rings","thread":"左耳里一直响的钟"}}]},{"id":"zhong_x10","act":"side","age":[22,22],"mode":"narration","title":"说给钟听的誓","opening":"二十二岁那年，阿渚娶阿涟。祠堂摆了两张桌，咸鱼、海带、一坛浊酒，海腥味压过酒味。按规矩，两家的岛钟要合鸣，新人把誓说给钟听，钟听见了才算数。阿渚平时嗓门大得能盖过潮声，站在钟前却把嘴闭上了，喉结上下动。阿涟也闭着嘴，手指绞着衣角。满祠堂的人都等着，谁也不敢催——都说誓让钟听全了，钟就记下了，谁先走，谁的名字先被收。灯芯爆了一下，阿渚张了张嘴，出来一口气，没有字。阿涟的耳根红了，红到脖子。有人在桌底下踢了你一脚，让你想办法。","ask":"这誓说给钟听，还是说给人听？","days":10,"npc":"","memory":"谁也没出声的誓","choices":[{"title":"按住钟绳停七息","desc":"你伸手按住钟绳，把钟停住，说：七息，快说。","hint":"议会来查过。","tone":"risk","outcome":"两个人凑到一起，说得又急又轻，说到第五息，阿涟笑了一下。第七息你松手，钟响了一声，很轻。议会后来查过一次，你说是绳子卡了。阿渚从此见你就把最大的鱼留给你。","eff":{"bond":4,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"喜":3},"flag":"stopped_bell_seven_breaths","thread":""}},{"title":"替他们记在心里","desc":"你不敲钟，把两个人的誓一句一句记在自己心里。","hint":"谱上不算数。","tone":"carry","outcome":"婚事在谱上不算数，孩子将来上不了谱，这些他们都清楚。阿涟说：不算就不算。她说完看了阿渚一眼，阿渚把她的手攥住了。祠堂里的人散了，桌上的鱼没怎么动，酒也没人喝。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":2},"flag":"kept_vow_unnamed","thread":"谱上不算数的婚事"}},{"title":"照规矩敲到底","desc":"你抓住钟绳，一下一下敲满七下。","hint":"阿涟看了你一眼。","tone":"rule","outcome":"钟声撞在梁上，又落下来。阿渚的脸白了一下，很快又笑起来，笑得比刚才响。阿涟没笑。三年后阿渚在海上没了，名字进谱那天，阿涟坐在门槛上，说：那天他说的那句，我记住了。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"rang_wedding_bell","thread":""}}]},{"id":"zhong_x11","act":"side","age":[24,24],"mode":"dialogue","title":"哑巴的三天","opening":"二十四岁那年，北礁的哑巴从塔上摔下来，腿断了，骨头戳出皮外，血把裤管浸成深色。他守的是北礁那口小钟，一天敲三回，一回不能少。他躺在草席上，用手比划：三天。他伸出三根指头，又指指塔，再指指自己的嘴——三天不能断，断了议会就换人。换人那天他得搬出塔下的屋，屋里有他娘留下的织机。他比划得很急，喉咙里发出嗬嗬的声音。塔下的铜梯锈了一层，海风一吹，吱吱地响。他媳妇蹲在门口烧水，锅里飘着一层油花。你娘在门口看着你，手里还拿着药碗。","ask":"哑巴的钟，谁来替他敲三天？","days":20,"npc":"mother","memory":"哑巴的三根指头","choices":[{"title":"冒充他上塔","desc":"你换上他的旧褂子，三天不开口。","hint":"饭从塔底吊上来。","tone":"secret","outcome":"三天里你不说话，怕一张嘴露了生人的口音。饭是他媳妇从塔底吊上来的，一碗粥，两个地瓜。第三天傍晚议会的人来查钟，从塔下走过，抬头看了一眼，走了。你下来时嗓子哑得说不出话，一开口先咳。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"stood_watch_for_mute","thread":"三天没说出口的话"}},{"title":"替他报备","desc":"你去议会报明他伤了腿，请人替他几天。","hint":"替班费掏空了船钱。","tone":"report","outcome":"议会的人来看了一趟，说他这条腿好不了，钟要换人守。替班费收走了你家攒的船钱。哑巴听完，手在被子上抓了一把，没抓住什么。他后来在滩上补网，一天补到晚，再没上过塔。","eff":{"bond":1,"health":0,"reputation":1,"coins":-20,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_mute","thread":""}},{"title":"背他上塔教他拉","desc":"你把他背上塔，让他坐在绳下，教他用一条腿的劲。","hint":"钟声一长一短。","tone":"teach","outcome":"他学了两天，拉得歪，钟声一长一短。议会的人来听了一回，说声不整，记了一次。他没下来，一直在塔上住着，腿长歪了，走路一拐一拐，钟倒是守到了死。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}}]},{"id":"zhong_s11","act":"side","age":[26,26],"mode":"dialogue","title":"会响的箱子","opening":"二十六岁那年，小螺从沉钟渊拖上来一只箱子。木头的，四角包铜，铜上生绿锈，锁是死的。箱子一挪就响，不是木头响，是里面有东西在撞，一下一下，跟人心跳一样。她把箱子摆在塔底，蹲在旁边听，头发上的海腥味往下滴水。她说：行会出三十个潮铢收它，我还没答应。她抬头看你：你说里头是什么。箱缝里渗出一点水，是黑的。","ask":"箱子还在响，你把它怎么办？","days":20,"npc":"sibling","memory":"一挪就响的箱子","choices":[{"title":"藏进塔底替她担下","desc":"你跟行会说箱子散在礁上了，把它塞进塔底的砖洞。","hint":"它每一潮都响一回。","tone":"secret","outcome":"行会的人来问了两回，你都说散了。箱子塞进塔底，每天两次潮水一动，它就在砖洞里头撞，隔着地板传上来。你渐渐睡不整夜，右耳常年有闷响。小螺照旧分到一份钱，什么都不知道。第三年砖洞渗黑水，塔底的地板烂了两块，你换地板时没敢把箱子挪出来。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":3},"flag":"hid_ringing_box","thread":"塔底砖洞里的黑水"}},{"title":"报议会，当众沉回去","desc":"你去议会说了，第三天来了船，把箱子抬到七声礁外坠下去。","hint":"小螺的份子钱没了。","tone":"rule","outcome":"沉箱那天来了一船人，箱盖撬开过一线，里头是一口拳头大的钟，钟舌用头发缠着。议会的人念了一个名字，不是你岛上的姓。船开出七声礁，箱子坠下去，海面冒了一串泡。行会扣了小螺三个月份子，她坐在码头补网，说：你至少该先跟我说一声。此后她下潜不再叫你。","eff":{"bond":-4,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"sunken_ringing_box","thread":"她下潜不再叫你"}},{"title":"卖给北滩的陆商","desc":"你让行会牵头，把箱子卖给等在北滩的陆商，价加了一倍。","hint":"船开出未响海，它还在响。","tone":"trade","outcome":"陆商当场数了钱，用麻布把箱子裹三层，抬上船。船半夜开走，你在岸上还听见那一下一下的撞，撞到桅杆那边才散。小螺换了一副新网，请你喝了半坛酒。第二年有外岛的人说，那箱子在陆上的铺子里，标价翻了三倍，还在响，买的人排到门口。","eff":{"bond":2,"health":0,"reputation":-1,"coins":140,"stats":{"机缘":2},"emotion":{"欲":3,"惧":2},"flag":"sold_ringing_box","thread":"那箱子还在别人的铺子里响"}}]},{"id":"zhong_x12","act":"side","age":[26,26],"mode":"narration","title":"一把名字","opening":"二十六岁那年，鱼市最里头那个摊子上，有个老婆婆替人杀鱼。她姓什么没人记得，都叫她念婆。她杀鱼的时候嘴里一直在念，念一个名字，剖一条鱼，念一个名字，刮一片鳞。鱼鳞粘在她手背上，亮闪闪的，她也不擦。有人说她念的是死人的名字，全岛死过的，她都记着，一个不落。有人不信，蹲下去听了半个时辰，听完脸色发白，站起来走了。你那天去买鱼，站在摊前，她抬头看你一眼，说：你家的名字我念过三个。她的手没停，刀在鱼肚上一划，血顺着手腕流到肘上。","ask":"她的名字都在嘴里，你要不要掏出来？","days":30,"npc":"","memory":"杀鱼时念的名字","choices":[{"title":"蹲下来听她念完","desc":"你把篮子放在脚边，蹲在摊前，听她一条一条鱼地念。","hint":"她念到你家那三个。","tone":"learn","outcome":"念到你家那三个，她停了一下，抬头看你，又接着念。日头从棚顶漏下来，落在鱼鳞上，晃眼。听到后来你腿麻了，站不起来，扶着摊子才立住。回家路上你一路在数，数到第三十条鱼就乱了，后面全混在一起。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"heard_name_list","thread":"她念到你家那三个"}},{"title":"请议会派人来记","desc":"你跑到议会，说鱼市有个念婆记着所有死人的名字。","hint":"她被请去坐了三天。","tone":"report","outcome":"议会派了两个人，带着新册，坐在鱼摊旁边记。她念一条，他们记一条。记到第三天才记完，册子用了半本。议会给她一块木牌，让她挂摊上，写着「名录」。她不会看，木牌挂在鱼钩旁边，血水滴上去，字慢慢黑了。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":1},"flag":"reported_name_list","thread":"血水滴黑的木牌"}},{"title":"买一条鱼就走","desc":"你挑了一条，付了钱，拎着往回走，不回头。","hint":"她念到一半停了。","tone":"avoid","outcome":"你走到巷口，听见身后那念声停了一下，又接上，接得比刚才慢。鱼在篮子里还动，尾巴拍着篮底。回家剖开，鱼肚里有一小团没消化的虾，你娘说这鱼新鲜。你把那团虾倒在灶边，看了很久。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"念声停的那一下"}}]},{"id":"zhong_x13","act":"side","age":[28,28],"mode":"narration","title":"收旧铜的船","opening":"二十八岁那年，北滩来了一条收旧铜的船，船主姓奚，外岛人，牙很黄，说话带着别处的口音。他收旧钟、旧锚、旧铜锁，按斤称。议会卖给他一口钟——钟肩上裂了，敲不响，谱上写着报废。抬钟那天用的是两根新绳，八个壮汉，钟离地的时候滩上的沙跟着震了一下。有人掏了掏耳朵，说这一下震得慌。老奚蹲下去看钟口的纹路，用手指敲了敲，说：好铜。他手下的人已经开始往船上滚了。你站在滩上，嘴里有股铜锈味。八个壮汉的脚在湿沙上踩出十六个坑，很快又被浪填平。","ask":"钟要被熔了，你拦不拦下来？","days":15,"npc":"","memory":"滚上船的那口钟","choices":[{"title":"站到绳子前头","desc":"你走过去，伸手按住绳子，八个壮汉停下来。","hint":"卖钟那家绕着你走。","tone":"brave","outcome":"管事说：谱上写了报废。你说：谱上还写着这口钟的名字。管事不说话了。钟被抬回塔下，搁在墙根，从此没人管。卖钟那户人家少了一笔钱，见你就绕道走，绕了三年。","eff":{"bond":1,"health":0,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"恶":1},"flag":"stopped_bell_sale","thread":"墙根那口废钟"}},{"title":"让他抄下内壁的字","desc":"你跟老奚谈，钟可以带走，内壁的字得先抄。","hint":"他不识字。","tone":"deal","outcome":"他答应了，拿出一张包铜的纸，用炭画。他不识字，画得像一堆横竖。你把纸收起来，后来对着灯看了半宿，只认出两个字，第三个怎么也认不出，笔画在炭灰里化开了。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}},{"title":"上船敲它一下","desc":"你爬上船，抄起铁棍，朝钟肩敲了一下。","hint":"三个岛都听见了。","tone":"defy","outcome":"钟是裂的，声音哑，可还是滚出去了，撞在礁上又滚回来。老奚的脸变了，议会的人也变了。三个岛的人后来都说那天听见一声怪响。钟还是被熔了，只是熔之前，全岛都知道它响过。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"哀":2},"flag":"rang_scrap_bell","thread":""}}]},{"id":"zhong_s04","act":"side","age":[29,29],"mode":"narration","title":"三双空鞋","opening":"二十九岁那年秋天，三条船出去，回来一条。祠堂地上铺了三张草席，席上摆三双鞋，鞋里填了沙，怕被风吹走。门槛上结了一层盐，踩上去咯吱响。阿树的媳妇抱着他的烟杆坐在最前头，烟杆里的灰早凉了。按规矩，人没有尸首，不能携钟入海，钟就不该敲。可三家人都在等，等的是一声。","ask":"没有尸首的葬礼，这钟怎么敲？","days":20,"npc":"","memory":"没有尸首的葬礼","choices":[{"title":"把名字刻进钟壁","desc":"你用铁钉在钟内壁划三个名字，划完再敲，敲到手指发麻。","hint":"钟壁多了三道划痕。","tone":"repair","outcome":"铁钉打滑，划破你左手虎口。钟响的时候声音是空的，像敲在一口井上。三家人跪下去，阿树的媳妇把烟杆插进沙里。议会来人看了钟壁，说坏了规矩，罚你三个月不许上塔。那三道划痕一直在，后来每回敲钟，你都听得见它们在响。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":3},"flag":"carved_three_names","thread":"钟壁上的三道划痕"}},{"title":"照规矩，不敲","desc":"你把钟绳盘好挂回钉子，说没有尸首就不能敲，谁求也不敲。","hint":"有个人朝你扔了鞋。","tone":"rule","outcome":"阿树的媳妇把鞋脱下来朝你扔，沙撒了一地。她说不敲，他们就成了无声的东西，在海底拖着整座岛。你弯腰把鞋捡起来，放回席上。三家人自己抬着空席去了海边，没有钟，只有浪。那之后那片海没人撒网，鱼多得发黑。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"那片海没人撒网"}},{"title":"去行会借一口钟","desc":"你去捞钟行会借来一口钟，说先办事，账以后再算。","hint":"那口钟的声是别人的。","tone":"trade","outcome":"钟是从外岛运来的，铜色发青，声音比本岛的尖。敲到第三下，阿树的媳妇抬头看塔，说这不是他听惯的声。事办完了，三家人各自回家。你欠行会三个月的活，替他们刷船底、晒网。后来阿树的小女儿问你：我爹的名字敲起来是什么声。你张了张嘴，没答上来。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"恶":1},"flag":"rented_bell","thread":"他女儿问名字的声音"}}]},{"id":"zhong_x14","act":"side","age":[31,31],"mode":"narration","title":"全岛的狗","opening":"三十一岁那年春天，不知谁家的黄狗先学会的。钟一响，它就把脖子伸长，嗷——一声，拖得比钟还长。第三天，巷子里的三条狗跟着叫；第五天，半座岛的狗都在叫。退潮钟响七下，狗叫七回，中间还带换气的。夜里静下来，远处还有一两条狗在补叫，像忘了词又想起来。你上塔敲钟，手一落，底下就起一片，声音从巷子里滚到滩上，再从滩上滚回来。孩子们乐得在门口跳，大人拿扫帚赶，赶了这头那头又叫。那条黄狗站在巷子正中间，脖子伸得笔直，叫完了还回头看看有没有人跟着它。","ask":"全岛的狗跟着钟叫，你先管谁？","days":15,"npc":"","memory":"满巷的狗跟着叫","choices":[{"title":"跟着叫一声","desc":"你站在塔上，深吸一口气，跟着狗叫。","hint":"你破了音。","tone":"defy","outcome":"声音难听，破了音。塔下的孩子先愣住，然后笑得蹲在地上。第二天全巷的人见了你都学那一声，学得比你像。你娘在门口听见了，回屋把门关上，过了一会儿又开开，端了碗水出来。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":6},"flag":"","thread":""}},{"title":"把领头的狗领回家","desc":"你用半条咸鱼换下那条黄狗，养在灶边。","hint":"你娘说多一张嘴。","tone":"warm","outcome":"它夜里睡在灶边，钟一响就抬头看你一眼，不叫了。后来整巷的狗都在叫，它也不叫。你娘说多一张嘴，说了半个月，后来给它起了个名字，叫阿响。阿响活到第十一年，埋在塔后的土坡上。","eff":{"bond":1,"health":0,"reputation":0,"coins":-3,"stats":{"机缘":1},"emotion":{"喜":4,"爱":3},"flag":"kept_dog_axiang","thread":"塔后土坡上的阿响"}},{"title":"敲钟前把狗关起来","desc":"你提前把自家的狗关进仓里，插上门闩。","hint":"插销被咬断了。","tone":"practical","outcome":"它在里头撞门，撞了三天，把仓门的插销咬断，跑出去领头叫。你修门的时候它蹲在旁边看你，尾巴一下一下扫地。那年的钟声里，总有它先起头，别人的狗跟着。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":4,"惧":1},"flag":"","thread":""}}]},{"id":"zhong_s05","act":"side","age":[33,33],"mode":"narration","title":"她还抱着那件小袄","opening":"三十三岁那年，阿箬来塔下找你。她老得快，头发白了一半，怀里抱着一件小袄，袖口磨破，领子上有一圈洗不掉的黑。她说：我屋里一直有这件袄，我每天早上给它掸灰，掸完就站在门口。她顿了顿，说听说守钟人记性好。她抬眼看你：你别让我忘了她。我已经忘了，我怕连“忘”这件事也忘掉。","ask":"她求你别让她忘了女儿，你怎么应？","days":15,"npc":"","memory":"阿箬抱着小袄","choices":[{"title":"应下，每年念一次","desc":"你点头，问清日子，说每年的那一天我来门口念她的名字。","hint":"你拿自己的记性垫给她。","tone":"carry","outcome":"你把阿鲛两个字记在自己心里，每年那天去她门口念一遍。她听见了，就问是谁家的孩子，你说是海上的。她点头，给你留一碗鱼汤。念到第七年，你发现自己忘了别的一些事，先忘的是鱼汤的味道。小袄还挂在她屋里，灰越掸越薄。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":3},"flag":"carries_a_jiao_again","thread":"先忘的是鱼汤味"}},{"title":"告诉她实话","desc":"你说你记不住那么久，钟声一响，谁都会忘，别指望我。","hint":"她再没上过塔。","tone":"honest","outcome":"阿箬的手从袖口上松开。她站了一会儿，说：那我记着袄就行了。她转身下塔，走到第三级又回头问你：她是不是叫阿鲛。你说不知道。她点点头，走了。此后她再没上过塔。每年那天你还是去海边站着，不进门。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":1},"flag":"","thread":"她在第三级回头问过"}},{"title":"把小袄收进塔里","desc":"你说袄放这儿，塔里干燥，她什么时候想看就上来看。","hint":"她后来不来了。","tone":"keep","outcome":"你把小袄折好，放进塔底那只旧木柜，柜里还有几块没刻字的耳蜡。阿箬头一个月来了四回，第二个月来一回，后来不来了。小袄在柜里放了很多年，领子上那圈黑还在。有一年潮气重，袄角生了霉，你拿出去晒，晒完又叠好放回去。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"kept_a_ruo_coat","thread":"柜里那件小袄"}}]},{"id":"zhong_x15","act":"side","age":[34,34],"mode":"narration","title":"台风夜","opening":"三十四岁那年秋天，台风来了。风从东南来，先掀了晒鱼的棚子，再掀屋顶。铜喉塔在风里晃，铜皮一块一块地响，像有人在外头拿石头砸。你上塔收钟绳，刚到第七层，绳子断了——不是断，是脱了扣，钟失去牵制，在梁上荡起来，一下比一下大，撞在塔壁上，整座塔跟着震。铜屑落下来，落在你脖子里，痒，又不敢伸手去拨。塔下有人在喊，声音被风撕碎，听不清。雨是横着来的，打在脸上像沙子。你抓着梯子，铁是凉的，凉到手心发麻，一松手就要被风掀下去。","ask":"绳断了，钟还在荡，你上不上？","days":10,"npc":"","memory":"荡起来的铜钟","choices":[{"title":"拴着腰爬出去","desc":"你解下腰带，一头拴栏杆，一头拴腰，爬出去够绳头。","hint":"虎口割开一道。","tone":"brave","outcome":"风把你按在塔壁上，铜皮冰凉。手抓到绳头时，一片铜皮割开你的虎口，血混着雨往下淌。你把绳接上，钟稳住。下塔时你走不动，是被人架下来的，脚在地上拖出两道印。","eff":{"bond":2,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":5,"喜":2},"flag":"fixed_bell_rope","thread":"虎口上那道口子"}},{"title":"割断钟绳","desc":"你拔出刀，把钟绳齐根割了，让钟自己撞。","hint":"钟裂了，哑了半年。","tone":"practical","outcome":"钟没了牵制，荡得更凶，最后撞在钟架上，裂了一道。风停以后钟还能响，只是哑，像人哭过。议会来看了，说要换钟就得少一年。你心里过了一遍：钟哑，比塔塌了强。这话你没跟任何人说。","eff":{"bond":0,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"cut_bell_rope","thread":""}},{"title":"抱住钟梁等风停","desc":"你把脸贴在梁上，抱住，等风过去。","hint":"那一夜没算。","tone":"steady","outcome":"钟在你头顶上荡，每荡一下，梁就吱一声。你数着荡的次数，数到一百多，天亮了。钟没掉。那天该敲的钟没敲，全岛那一夜没算——不是少算，是那一夜根本没进时间里。","eff":{"bond":-1,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"哀":2},"flag":"missed_bell_night","thread":"没算的那一夜"}}]},{"id":"zhong_s12","act":"side","age":[35,35],"mode":"narration","title":"它为什么哭","opening":"三十五岁那年，小螺的女儿阿蜊五岁。她跟着上塔送饭，蹲在钟口底下，忽然抬头问：它为什么哭。那天海上起风，风从钟口的裂缝挤进去，出来时变成一种细声，一高一低，跟人憋着哭一样。她仰着脸等你说，手里还攥着半块饼。塔下有人在晒网，海腥味顺着塔身往上爬，钟锤靠在墙角，柄上有一圈汗渍。","ask":"一个五岁的孩子问钟为什么哭，你怎么答？","days":10,"npc":"","memory":"裂缝里的哭声","choices":[{"title":"告诉她在数名字","desc":"你蹲下来，说钟里有人在数名字，数到自己那一个就停一下。","hint":"她开始跟着数。","tone":"honest","outcome":"她听完没说话，把饼掰成小块，一块一块摆在钟座上。当晚她躺在席上数手指，数到第七下停一停。半个月后她能在钟声里听出那个多出来的名字，跟你十五岁时一样。小螺在门口站了一夜，第二天问你：你教她的。你没答。她从此不让阿蜊上塔，可阿蜊已经会数了。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"惧":4},"flag":"taught_child_names","thread":"阿蜊已经会数了"}},{"title":"爬上去糊住那条缝","desc":"你带着蜡和旧网爬上钟肩，把那条裂缝一层层封死。","hint":"缝里的气没处走。","tone":"repair","outcome":"蜡一按上去，哭声就断了。阿蜊在底下拍手，说它不哭了。她记了很多年，逢人就说塔上的钟是哑的。那冬天缝从钟肩爬到了钟腰，议会来看了一回，罚你三个月不许碰钟。你后来才知道，那声音是钟在出气，气堵住了，钟就自己往里裂。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":2},"flag":"sealed_bell_crack","thread":"缝爬到了钟腰"}},{"title":"抱她上塔听一夜","desc":"你把她裹在怀里抱上塔顶，坐到天亮，让她自己听。","hint":"你胳膊麻了三天。","tone":"carry","outcome":"她听到半夜就睡着了，脸压在你肩上，口水湿了一片。那一夜风停着，钟一声没哭。天亮下塔，小螺提着灯站在门口，接过孩子，只说了句饭在锅里。她把孩子抱走，没回头。你举了一夜的胳膊，麻了三天，抬不起来敲钟。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":2},"flag":"held_child_all_night","thread":"那晚钟一声没哭"}}]},{"id":"zhong_x16","act":"side","age":[37,37],"mode":"narration","title":"锅盖钟","opening":"三十七岁那年，塔上少了一口小钟。那小钟是备用的，铜薄，声音尖，平时挂在第七层的钉子上。你找了三天，第四天在阿蚝家的灶台上看见了——那口钟扣在锅上，当锅盖，钟钮朝上，缝里冒白汽。阿蚝的媳妇正往灶里塞柴，一抬头看见你，说：这盖子沉，压得严，就是有点响。她掀开钟，一屉包子，白胖，个个底上带着一圈铜锈印。灶屋里全是面味和铜味，混在一起说不清是什么味。她用手背抹了一下钟钮，钟钮烫，烫得她甩手。明天塔上要替人敲名，缺这口钟就少敲一个名字。","ask":"钟在灶上扣着，你要回来还是要人等？","days":10,"npc":"","memory":"灶台上的小钟","choices":[{"title":"连锅端走","desc":"你抱起锅就走，包子留在屉里，还冒着汽。","hint":"她追掉了一只鞋。","tone":"practical","outcome":"她在后头追，追到巷口，鞋跑掉一只。全巷的人都出来看，看一个守钟人抱着一口锅跑，锅里还冒汽。第二天她把那屉包子送来了，说：你尝尝，一股铜味。你吃了两个，确实是铜味。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":5},"flag":"","thread":""}},{"title":"蹲在灶边等","desc":"你蹲下来，等她把这一屉蒸完，又等下一屉。","hint":"误了敲名的时辰。","tone":"wait","outcome":"等到日头偏西，钟拿到手，该敲的时辰已经过了。那家人后来跟人说：守钟人在我家灶前蹲了一下午。你没解释。那天的名字你第二天补敲，敲得比往常重，敲完手心里一道红印。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"哀":1},"flag":"","thread":""}},{"title":"敲一下锅盖","desc":"你拎起钟，用拳头在钟口上敲了一下。","hint":"半条巷跑出来。","tone":"defy","outcome":"声音不大，可整条巷都听见了。有人从屋里跑出来，一边跑一边系腰带，跑到巷口才看见是你抱着一口锅。阿蚝的媳妇笑得扶着门框。那口钟从此有了个说法，叫锅盖钟，叫了很多年。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":6},"flag":"pot_lid_bell","thread":"锅盖钟这个说法"}}]},{"id":"zhong_x17","act":"side","age":[41,41],"mode":"narration","title":"摸不到的名字","opening":"四十一岁那年，塔下来了个瞎眼老人，姓岑，八十多，年轻时也是守钟的。他说钟内壁刻着名字，是他师父那辈刻的，刻得浅，用手摸得出来。他上不了七层，求你扶他。爬到第四层他就要歇，歇的时候手在墙上摸，摸到一道刻痕，念出一个名字，念完自己点点头。铜壁被摸得发亮，有一片特别亮，是他常年摸的地方。塔里很静，只有他的呼吸声和手掌擦过铜面的沙沙声。到第七层，他摸了很久，手停住了。他没有说话，只用指腹在那一片铜上按了一下，又按一下，像在等一道刻痕自己长出来。","ask":"他摸不到那个名字了，你说不说？","days":10,"npc":"","memory":"手掌擦过铜面","choices":[{"title":"扶他摸够一个时辰","desc":"你扶着他在钟口底下站着，从左边摸到右边。","hint":"你腰疼了三天。","tone":"escort","outcome":"他在钟口底下站了一个时辰，来回摸三遍，让你扶着他把每一道刻痕都过了一遍。下塔时他腿抖，几乎是一阶一阶挪下去的。第二天你腰疼得直不起来，躺着的时候想：他明天还来不来。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"他明天还来不来"}},{"title":"把他念的记下来","desc":"他念一个，你记一个，记在钟谱背面。","hint":"后来你也分不清。","tone":"learn","outcome":"念到第十九个，他停了，说：这个我念过了。你没说话，把笔尖按住。那天回去你对着纸看了半宿，发现自己也分不清哪几个是他念的，哪几个是你自己想起来的。纸上的字挤成一团。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}},{"title":"说摸到了","desc":"你看了看他手停的地方，说：摸到了，是阿蓁。","hint":"他说不是。","tone":"hide","outcome":"他没动，手还按在那儿，说：不是。他说阿蓁的蓁字，底下有三横。他摸了一会儿，把手放下，说：明天再来。第二天他又来了，还是停在同一处。第三天你没敢上去，让他儿子扶的。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"底下有三横"}}]},{"id":"zhong_s06","act":"side","age":[42,42],"mode":"narration","title":"第七句是什么","opening":"四十二岁那年冬天，你在塔下补钟绳。门外有女孩跳格子，唱数钟歌，唱到第七句，她唱“睡”。你张嘴要纠正，忽然发现下一句不在嘴里了。调子还在，三个字的位置还在，唱到那里要停半拍也还记得——就是不记得那三个字。风从塔缝里钻进来，带着盐，也带着一点焦布味，母亲今天又在海边烧东西。你把手里的绳结拆开重打，打了三遍，三遍都是空的。","ask":"第七句那三个字，你怎么办？","days":30,"npc":"","memory":"忘掉的第一句","choices":[{"title":"到滩上替她担下来","desc":"你跟大人们说歌是你让改的，与孩子无关，骂名你接。","hint":"你被当成糊涂人。","tone":"protect","outcome":"老婆子在滩上骂了你半天，说你守钟守糊涂了，把歌都守丢了。女孩没挨打，站在人后面看你。往后她编的那三个字就这么唱下去，一年一年，谁也说不清哪一版是真的。你在塔上听着，听着听着也当它是真的了。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"took_blame_for_song","thread":"你也当它是真的了"}},{"title":"按她重唱到我点头","desc":"你叫住她，说唱错了，一遍遍重来，唱到你点头为止。","hint":"你指的其实是自己猜的。","tone":"teach","outcome":"女孩重唱了六遍。你听着，觉得哪一种都像，就指了第二遍，说这个对。她记住了，回家教她弟弟。第二年滩上的孩子都这么唱。她后来做了歌头，谁唱错她打谁手心。你站在塔上听，听不出哪儿不对，只是心里知道自己给的是猜的。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"恶":2},"flag":"taught_guessed_song","thread":"她打人手心"}},{"title":"跟着她哼过去","desc":"你把那三个字改成哼，哼得含糊，混在孩子的声音里。","hint":"第七句从此只哼不唱。","tone":"hide","outcome":"女孩没听出来，跳到下一格。后来你也这么哼，孩子们跟着学，第七句就没了词，只剩三个音。有回外岛来的人问这歌怎么唱，孩子们哼到那儿一齐停半拍，接下去。你在旁边听着，喉咙里有点痒，像还欠一口气。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"hummed_seventh_line","thread":"欠着的那半拍"}}]},{"id":"zhong_x18","act":"side","age":[45,45],"mode":"narration","title":"搁浅的大家伙","opening":"四十五岁那年秋天，一头鲸搁在七声礁外的浅滩上。天没亮就有人看见了，敲着盆喊，全岛的人都往滩上跑。它侧躺着，比三条船接起来还长，皮是灰的，上面挂满藤壶，白花花一片。嘴半张着，里头能站一个人。潮水还没退干，它的尾巴偶尔抬一下，拍在水里，溅起一人高的水。孩子们已经爬上去了，在背上一路跑到尾巴，脚下滑，摔了就笑。空气里全是腥味，浓得发甜。有个孩子蹲下去，把耳朵贴在它肚子下面，说里面在响。有人扛着刀来了，有人扛着盆。","ask":"这么大的鱼躺在滩上，你做什么？","days":10,"npc":"","memory":"鲸背上的藤壶","choices":[{"title":"爬上去走一趟","desc":"你踩着藤壶爬上背脊，从脖子一路走到尾根。","hint":"肋骨疼了半个月。","tone":"brave","outcome":"皮是凉的，粗的，踩上去像踩在老树根上。走到一半脚下一滑，摔在藤壶上，肋骨磕在一块硬壳上。你在它背上躺了一会儿，看天。那天回家你不敢大口喘气，一喘就疼，疼了半个月。","eff":{"bond":0,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":5,"惧":1},"flag":"","thread":""}},{"title":"割一大块扛回家","desc":"你用衣襟包了一大块肉，扛在肩上往回走。","hint":"肉掉进礁缝里。","tone":"greed","outcome":"走了半里，肩膀麻了，肉太沉，滑下来，掉在礁石缝里。你回去拿刀再割，那块已经被浪卷走了。晚上全岛都在熬油，你家的锅里只有一点碎渣，你娘没问，把碎渣倒进粥里，粥上浮着一层油花。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"哀":1},"flag":"","thread":""}},{"title":"站在鱼头前拦刀","desc":"你张开手站在它头前，说潮水还没退干，它还能回去。","hint":"血从你脚边流过去。","tone":"protect","outcome":"有人骂你，有人推你，有人从你身边绕过去下刀。血顺着滩上的沟流，流进海里，一小片红。潮水到底没把它带回去。第三天它开始臭，全岛捂着鼻子过了半个月，晒的鱼都沾了味。","eff":{"bond":-3,"health":-1,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"恶":2},"flag":"","thread":"滩上那片红"}}]},{"id":"zhong_s13","act":"side","age":[47,47],"mode":"narration","title":"三天的哑钟","opening":"四十七岁那年，哑姑要死了。她住在静湾后面的石屋里，屋里没有钟，连一块铜片都没有——静潮教团的人不许有钟。她瘦得只剩一把骨头，用指头在你手心写：我有名字。写完又写：三天。意思是她那口钟只等三天。可她的名字早不在谱上：入教那年，议会把她的名字从旧册上划了，那页纸泡烂了，划痕比字还粗。塔上的钟这几天一直没响，海腥味压在湾里散不开。","ask":"三天里，这个没名字的人怎么办？","days":10,"npc":"","memory":"没有名字的钟","choices":[{"title":"报上自己的名字敲","desc":"第三天清早，你报上自己的名字，替她敲了那口小钟。","hint":"钟以后会数你两遍。","tone":"carry","outcome":"钟响的时候她还睁着眼，听见了，嘴角动了一下。她走后教团的人把骨灰撒进湾里，没立碑。第二年钟声里数名字，数到第七下多出一个，是你的名字。你在塔上站着，觉得脚下轻了半寸。再往后有人叫你，你回头总要慢半拍。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":3},"flag":"rang_for_mute_with_own_name","thread":"你回头总要慢半拍"}},{"title":"报议会，按无名处置","desc":"你上塔翻出旧册，把她那一栏空着报了上去。","hint":"她走的时候钟没响。","tone":"rule","outcome":"议会当天就回了话：无名者不敲钟，免得全岛多背一年。第三天夜里她走了，石屋里静得能听见潮。教团的人来抬她，不让你进门。他们把一口没响过的小钟放在她胸口，一起抬去静湾。那年冬天湾里的水特别响，渔民说底下有东西在撞船板。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"湾里有东西撞船板"}},{"title":"编一个名字给她","desc":"你在石屋门口的沙上写三个字，教教团的孩子念。","hint":"那不是她的名字。","tone":"niche","outcome":"你编的名字叫阿默，好念，孩子学了三遍就会。第三天钟响了，声音发闷，像敲在一口装满沙的罐子里。全岛多背了一年，议会查不出多的是谁。后来有人在静湾捡到一块耳蜡，上头刻着阿默两个字，边上插了一炷香。你不知道该不该说那名字是假的。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"invented_mute_name","thread":"耳蜡上那个假名字"}}]},{"id":"zhong_x19","act":"side","age":[49,49],"mode":"narration","title":"耳朵里的棉花","opening":"四十九岁那年冬天，你发现自己的耳朵不行了。先是听不见退潮时礁石上水往下淌的声音，后来是风穿过窗缝的哨声。钟还能听见，只是隔了一层，像有人在你耳朵里塞了一小团棉花。守钟房里安静，你坐在那儿，手里那块蜡捏软了也没刻出字。夜里躺在炕上，听见的全是自己的心跳，一下一下，太清楚了。岛上有一种病叫聋钟病，守钟人得的多。你父亲晚年也这样，他从没跟人说过，只是把手掌贴在钟壁上，一贴就是半天。你现在也这么做了，铜把掌心的热吸走，吸得手指发僵。","ask":"耳朵听不见了，你说不说？","days":60,"npc":"","memory":"耳朵里那团棉花","choices":[{"title":"把手掌贴在钟壁上","desc":"你不说，靠震数，钟响一下，掌心麻一下。","hint":"有一夜数岔了。","tone":"hide","outcome":"这么守了半年。有一回你数岔了，少敲一记，全岛那一夜没算。第二天没人提，你自己知道。你把两只手都贴上去，贴到发麻，还是漏了。父亲当年贴半天的那个动作，你现在懂了。","eff":{"bond":0,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"哀":3},"flag":"hid_deafness","thread":"少敲的那一记"}},{"title":"去议会交锤","desc":"你走进议会，把钟锤放在桌上，说听不见了。","hint":"柄上那圈汗渍朝上。","tone":"honest","outcome":"管事听完，让你把锤子交上去，说守钟人听不见钟，留着是害人。锤子放在桌上，柄上那圈汗渍朝上。走出议会时海风很大，你听不见它。回家路上小螺问你今天怎么回来得早，你没答。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"gave_up_hammer","thread":""}},{"title":"让小螺替你数","desc":"你跟小螺说了，她第二天把船卖了，搬回塔下。","hint":"她再没下过海。","tone":"help","outcome":"钟响的时候她坐在你旁边，用手指在你手背上敲，一下一下，替你数。她不说话，你也不问。这样守了三年，她再没下过海，晒网的时候总往海那边看，看很久，手里的梭子停着。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"sister_counts_for_you","thread":"她再没下过海"}}]},{"id":"zhong_x20","act":"side","age":[54,54],"mode":"narration","title":"骂过你的人","opening":"五十四岁那年，秤叔要死了。他年轻时在鱼市上骂过你父亲，骂得很难听，说你家的钟谱是假的，说你父亲多记名字骗潮铢。那天半条街的人都围着看，你父亲站着没还嘴，回家把手洗了很久。这些年两家不来往，路上遇见就绕开，绕开的时候谁也不看谁。现在他躺在床上，只有出的气。按规矩，守钟人要去他家坐一夜，替他把名字念到钟响。他儿子来请的时候站在塔下，头低着，话说得很轻，说完把一只手扶在塔壁上。天快黑了，风里有雨的味道。","ask":"骂过你的人要死了，你去不去？","days":10,"npc":"","memory":"塔下低着的头","choices":[{"title":"去，坐满一夜","desc":"你到他床边坐下，一夜没合眼，念到钟响。","hint":"桌角那碗水凉了。","tone":"rule","outcome":"他家里人不跟你说话，给你倒了一碗水，放在桌角，凉了也没人添。天快亮时他咽了气，你念他的名字，念到钟响。出门时他儿子追出来，塞给你一条咸鱼，你接了，鱼还是凉的。","eff":{"bond":3,"health":-2,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":3},"flag":"sat_with_scale_uncle","thread":""}},{"title":"站在门外念","desc":"你去了，站在门外，隔着门板把名字念完。","hint":"这算不算，你说了算。","tone":"distance","outcome":"念完你就走，没进屋。他儿子追出来问：这算不算。你说：不算。第二天议会来问，你照实说了，罚了三个月的班次。全岛的说法不一样，有说你有骨气的，有说你记仇的。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"恶":1},"flag":"","thread":""}},{"title":"让别人替你去","desc":"你让小螺替你去，自己在塔上敲钟。","hint":"请帖被退回来了。","tone":"refuse","outcome":"钟响的时候，你听见滩上有人在哭，隔得远，听不真。第二天他儿子把请帖退回来，纸被揉过，边角起了毛。你父亲那天在门后擦锤子，擦了很久，一句话没说，木柄擦得发亮。","eff":{"bond":-3,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"恶":1},"flag":"","thread":"退回来的请帖"}}]},{"id":"zhong_x21","act":"side","age":[58,58],"mode":"narration","title":"谱上的死人","opening":"五十八岁那年，北坡的阿绒活过了谱上写的日子。谱上记着她去年冬天就该走，日子、时辰都写着，字是议会的人写的，写得很正。可她还坐在门口晒太阳，牙掉光了，见人就招手。议会的人来核过两回，翻着谱说：不对，这人已经还完债了。她那间屋的门牌被摘了，口粮停了，祠堂不让她进，孙女的婚礼也没请她。她还是每天坐在门口，把晒干的鱼一条一条摆整齐，摆完再摆一遍。鱼是去年的，硬得像木片，她的手在上面摸。有人从她门口过，她就问：今天初几。","ask":"谱上她已经死了，人还活着，怎么办？","days":30,"npc":"","memory":"门口晒干的鱼","choices":[{"title":"每天从后墙递饭","desc":"你傍晚端一碗饭，用布盖着，从后墙递进去。","hint":"有人看见了，没说什么。","tone":"secret","outcome":"送了两个月。有一回你被另一家的媳妇看见，她没吭声，第二天她家门口也多了一碗。阿绒一直不知道是谁送的，见人就问：是不是钟上的人。问了很多年，没人答她。","eff":{"bond":3,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"喜":2},"flag":"","thread":"后墙递进去的碗"}},{"title":"把她的日子往后挪","desc":"你翻三天谱，找到那一行，把日子往后挪一年。","hint":"有人替她垫了一年。","tone":"repair","outcome":"挪完你在塔上坐了很久，手心里全是汗。按规矩，改一笔记一年，那一年从谁身上出，谱上不写。阿绒的门牌挂回去了，她还是坐在门口，摆她的鱼，不知道有人替她垫了一年。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"moved_death_date","thread":"不知谁替她垫的一年"}},{"title":"陪她去议会说","desc":"你扶她走到议会门口，让管事当着她的面说清楚。","hint":"她说腿麻。","tone":"honest","outcome":"她走得很慢，走到半路坐在路边的石头上，说腿麻。你背她，她轻得像一捆干海带。到了门口，管事说：谱上的人不能进门。她听懂了，自己从你背上下来，说：那我回去。路上她一直没说话，到门口才问：今天初几。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"","thread":""}}]},{"id":"zhong_s07","act":"side","age":[60,60],"mode":"narration","title":"还你一句话","opening":"六十岁那年，外岛船靠岸，下来一个男人，头发白了，背一只旧鱼篓。他在鱼市站了半天，问有没有一户姓周的，没有人接话。他走到塔下坐下，唱数钟歌，唱到第七句，唱的是“睡”。四十年前，他娘阿婵临死前把一张泡烂的纸塞给你，纸上是两个字，她让你收着，说有一天会有人来问。她还说：他不是沉在海里，他是自己走的。这话别跟岛上人讲。","ask":"他坐在塔下，那句话你说不说？","days":20,"npc":"","memory":"泡烂的那张纸","choices":[{"title":"把纸和实情都给他","desc":"你把纸摊在他膝上，说：你娘让我记着，你是自己走的。","hint":"她托你守住的那句话，你破了。","tone":"honest","outcome":"他把纸捏在手里，指头抖了一下，说他知道，是他自己走的。他问娘有没有骂他。你说没有，她只说你走那天鞋没带。他低下头，很久没说话。走前他把鱼篓留给你，篓底一层干盐。你回塔后想起阿婵交纸时的眼睛，觉得自己欠她一句。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"told_zhou_truth","thread":"他走那天鞋没带"}},{"title":"只说娘等他到老","desc":"你把纸给他，说她等到最后一天，别的话一个字不提。","hint":"他谢了你，眼里没有底。","tone":"keep","outcome":"他问娘临死前说了什么。你说她念你的名字，念了好多遍，别的没说。他点头，把纸折成小方块收进怀里，说那就好。第二天他上船走了，在船尾朝塔挥了挥手。纸的事你办完了，那句话还留在你这里，像一颗咽不下去的盐粒。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":3},"flag":"kept_chan_promise","thread":"咽不下去的盐粒"}},{"title":"到鱼市把名字喊出来","desc":"你站到鱼市中间，把周载两个字喊三遍，喊到钟自己响。","hint":"全岛要多背一年。","tone":"brave","outcome":"名字喊出去，塔上的钟自己响了一声，卖鱼的都停了手。有人忽然说：我见过一个额角有疤的孩子。话一开头，又有人想起阿婵在门口晒咸鱼。那年冬天岛上死了两个老人，比往年多，议会把多出来的名字记在谱末，写得很小。他留下来了，住在北坡。","eff":{"bond":4,"health":-1,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"惧":2},"flag":"spoke_zhou_name","thread":"谱末那个小字"}}]},{"id":"zhong_s14","act":"side","age":[62,62],"mode":"narration","title":"多出来的名字","opening":"六十二岁那年，议会要重修钟谱。最后一口钟裂着，谁也不知道还能撑几年，旧谱上的名字得赶紧抄进新册。父亲那本谱交到你手上，纸被海水泡过，边角发毛，翻一页掉一点渣。你抄到最后一页，那里有两行字：一行是阿澜，你知道是谁；阿澜下面还有一行，字更小，被手掌擦了半辈子，擦得只剩轮廓。你凑到灯下看，是铜九——你父亲自己的名字，写在亡者那一栏，日子是你出生那天。","ask":"这一行多出来的名字，你怎么办？","days":60,"npc":"","memory":"谱上多出的一行","choices":[{"title":"照原样抄进新谱","desc":"你把铜九两个字一笔一画抄下来，抄在阿澜下面。","hint":"岛上要多背一年。","tone":"rule","outcome":"新谱收上去那天，抄谱的老先生数了一遍，抬头看你一眼，没说话，在页末添了个小字。那年冬天岛上死了两个老人，比往年早。鱼市上有人骂，问谁家又多记了一个。你没应。父亲的嗓门你早记不全了，可那两个字在谱上，白纸黑字，谁也擦不掉。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"copied_father_name","thread":"谱末那个小字"}},{"title":"抄在手心，刮掉那行","desc":"你先把铜九写在左手心，再用指甲把谱上那一行刮白。","hint":"名字离了纸，得有人接着。","tone":"carry","outcome":"刮到最后纸破了个小洞。那年冬天岛上没多死人，你却在开春白了半头，眼睛也花了。父亲的名字没进新谱，只在你手心。汗一洇就淡，你每隔几天重写一遍，写到后来，笔画抖得不成形。旧谱你烧了一半，又夹出来，缺了一角。","eff":{"bond":2,"health":-3,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"carried_father_name","thread":"手心一次次淡下去的两个字"}},{"title":"拿去问最老的守钟师","desc":"你抱着谱上塔，去问议会里最老的那个守钟师。","hint":"他把谱收走了。","tone":"elder","outcome":"老守钟师把谱摊在膝上，指头压着那行小字，说：你爹来过，问我一个人的名字能不能写两回。我说不能。他哦了一声。第二天他报了上去，说旧谱有误，要收去校。谱被人用油布包走，你再去问，说在库里。此后你只在梦里见过那一页，铜九两个字被手掌擦得发白。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"怒":2},"flag":"","thread":"梦里那一页被擦白"}}]},{"id":"zhong_x22","act":"side","age":[63,63],"mode":"narration","title":"一块旧布","opening":"六十三岁那年，阿蜊要离岛。她是小螺的女儿，三十三岁，头发剪短了，行李只有一只鱼篓和一卷铺盖。岛上这些年走的人多，船一开，声界就断了，走了的人多半不回来。她来塔下跟你道别，站在门口，脚上是一双新鞋，鞋面还没沾过沙。你翻箱底，翻出母亲织机底下压着的一块旧布——巴掌大，烧过的边，焦味早就散了，只剩一点硬。针线盒还在，梭子也在，线是旧的，一拉就断。窗外有人在装船，木板碰木板，一声一声。海风从窗缝进来，把针线盒里一张旧纸吹得翻了个身。","ask":"她明天就走，你给她什么？","days":10,"npc":"","memory":"箱底那块旧布","choices":[{"title":"缝进她的衣领","desc":"你把那块布剪成两半，一半缝进她的衣领。","hint":"剩下的一半在你袖口。","tone":"warm","outcome":"针脚很密，缝完她低头看，说：这布上有股味。你说：老布都这样。她上船的时候一直在摸领子，摸了很多回。你站在滩上，袖口里那半块布贴着腕子，硬的，硌人。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":5,"哀":3},"flag":"sewed_cloth_in_collar","thread":""}},{"title":"什么也不给，送到滩上","desc":"你空着手送她到滩上，看船开出去。","hint":"她回头看了一眼。","tone":"escort","outcome":"她上船，回头看了一眼，你站着没动。船开出去，橹声一下一下，慢慢听不见。你在滩上站到潮水涨上来，鞋湿了才回去。那块布还在箱底，你没再翻过，也知道它在。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"说岛上也能活","desc":"你站在门口，说：别走了，岛上也能活。","hint":"她把鱼篓放下了。","tone":"honest","outcome":"她听完，把鱼篓放下了。第二天船开了，她没上。第二年她嫁在岛上，男人是个补网的。她再没提过海那边，只是每年船开的那几天，她会到滩上站一会儿，站到船看不见。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"爱":1},"flag":"asked_her_to_stay","thread":"船开那几天她去滩上站着"}}]},{"id":"zhong_x23","act":"side","age":[67,67],"mode":"narration","title":"哭错了门","opening":"六十七岁那年，滩上办丧事。死的是补网的阿灿。雇来的哭丧婆姓何，六十多，嗓门好，一路从巷口哭进来，哭词一套一套的。她哭到第三家就拐错了门，一头进了阿灿隔壁——那家躺着的是阿灿的哥哥阿炉，活着，瘫了三年。何婆跪在床前，拍着床沿哭：你怎么就走了啊。阿炉在床上睁着眼，先是愣，后来咧开嘴，笑得直咳嗽。屋里屋外站了一圈人，谁也不知道该不该拉她。隔壁的真丧事那头，阿灿的媳妇已经在门口张望了。何婆还跪着，哭得鼻涕都下来了，一边哭一边去拍阿炉的手。","ask":"她哭错了门，你先怎么办？","days":10,"npc":"","memory":"哭错的第三家","choices":[{"title":"把她领到隔壁","desc":"你过去拉她起来，一路把她领到真办事的那家。","hint":"她把词忘了。","tone":"help","outcome":"她一路走一路问：死了几个。到了对的那家，她站定，张了张嘴，词忘了，只哭出一声干嚎。阿灿的媳妇没怪她，给她倒了碗水。那天的丧事办得很快，哭得也短，天黑前就散了。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"哀":2},"flag":"","thread":""}},{"title":"站着看下去","desc":"你不拉，站在门口，看她把这场哭完。","hint":"阿炉说：还有呢。","tone":"peace","outcome":"何婆哭了半个时辰，把阿炉从小到大的事都哭了一遍，哭得比真的还真。阿炉听得直点头，说：还有呢。何婆愣了一下，接着哭。隔壁的丧事自己办完了，阿灿的媳妇后来说：算了，他哥爱听。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":6},"flag":"","thread":"阿炉说还有呢"}},{"title":"跟着一起哭","desc":"你走到床前，跟着何婆一起哭，一句不差。","hint":"全岛传了半年。","tone":"brave","outcome":"你哭得比她响，词是她编的，你一句不差。屋里的人全看你。何婆停下来看你，你也停下来。阿炉笑得喘不上气，说：你们俩是来送我的？那天全岛都在传：守钟人替活人哭了一场。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":6},"flag":"cried_for_living_man","thread":""}}]},{"id":"zhong_x24","act":"side","age":[71,71],"mode":"narration","title":"最后一个记得的人","opening":"七十一岁那年，有个外岛来的后生上塔，问你认不认识一个叫阿澜的。他说他娘临死前念过这个名字，念得很轻，像是怕人听见。他娘是从这个岛出去的，走的时候还年轻。你在谱上翻，翻了很久，翻到最后一页，那里有一行字，被手掌擦过，只剩轮廓。你看着那行字，忽然想不起那个人的脸，也想不起她为什么在这个岛上。塔外的潮水在退，退得很慢，礁石一块一块露出来，像有人在下面把石头往上推。后生站在楼梯口，手里捏着一顶帽子，捏得帽檐都变形了。","ask":"最后一个记得的人也要忘了，怎么办？","days":30,"npc":"","memory":"只剩轮廓的那行字","choices":[{"title":"写下来，写七遍","desc":"你摊开纸，把阿澜两个字写下来，一遍一遍重写。","hint":"手抖，越写越不像。","tone":"carry","outcome":"笔画抖，第二个字多了一横。你重写，写了七遍，一遍比一遍不像。后生把最后一张接过去，说：这就行。他走后你把那七张纸全烧了，看着火苗把字吃掉，一个也没留住。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"爱":2},"flag":"","thread":"烧掉的七张纸"}},{"title":"教他记她怕黑","desc":"你说：你记着，她怕黑，左耳后面有颗痣。","hint":"他把痣念成了记。","tone":"teach","outcome":"后生跟着念，把痣念成了记。你纠正了三回，第四回他念对了，你却说：算了，差不多。他走的时候一直在念那个名字，念得跟你不一样，尾音往上挑。你在塔上听着，听他把名字带下七层。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"爱":3},"flag":"","thread":""}},{"title":"合上谱，带走名字","desc":"你把谱合上，压在铜锭底下，说：我带走了。","hint":"脚步声一层层往下。","tone":"keep","outcome":"后生站了一会儿，下塔去了。你听见他的脚步声一层一层往下，最后听不见。那天夜里你坐在钟口底下，把那个名字在心里念了很多遍，念到天亮，念得只剩下一个音，像谁在很远的地方敲了一下。","eff":{"bond":-2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":2},"flag":"kept_name_to_bell","thread":"只剩下一个音"}}]},{"id":"zhong_s15","act":"side","age":[74,74],"mode":"narration","title":"下一个守钟人","opening":"七十四岁那年，议会送来一个女孩，叫阿蚬，十一岁，瘦，头发用一根鱼线扎着。她站在塔底，仰头看那道从钟肩爬到钟口的裂缝，看了很久。她是北坡织网人家的孩子，三个月前在钟声里数名字，数到第七下，说多了一个。议会的人说这孩子耳朵有病，让你看看。你让她上楼，敲了一下小钟，她数到第七声，停住，说：这儿多一个。你手里的钟锤停在半空。四十年了，这句话你只在自己嘴里听过。","ask":"这个听得出多一个的孩子，你怎么教？","days":200,"npc":"","memory":"第七声多一个","choices":[{"title":"教她全部的名字","desc":"你把谱上的、谱外的名字一个一个念给她，让她跟着数。","hint":"教一个，你少一个。","tone":"teach","outcome":"教到第三个月，她能在钟声里数出四百一十三个名字，一个不差。你开始忘事：先忘了自己教过哪一句，后来忘了她叫什么，见了面只点头。她把你的名字写在塔壁内侧，用炭，写完用手掌抹平。你每天上去摸一遍，摸到字就安心，摸不到也想不起来少了什么。","eff":{"bond":5,"health":-3,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"爱":4,"哀":4},"flag":"taught_next_keeper","thread":"塔壁内侧用炭写的名字"}},{"title":"只教谱上的名字","desc":"你按议会的新册教，她一说多，你就说她数错了。","hint":"她学会了不信自己。","tone":"rule","outcome":"她学得很快，数得干净，四百一十二个，一个不多。议会来人考她，她答得一字不差，当场定了守钟的班次。她走那天在塔门口回头问：那第七下真的没有吗。你说没有。她点头，用蜡把耳朵封上。后来她敲钟敲得很准，只是从来不在塔上多站一刻。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"taught_by_the_book","thread":"她用蜡把耳朵封上"}},{"title":"挂回钟锤，下塔去静湾","desc":"你把父亲的钟锤挂回钉子，不再教，坐到静湾的沙上。","hint":"她跟议会的人学。","tone":"quit","outcome":"她在塔上等了你三天，第四天议会派了个老执事来，教她按册点名，点完就关窗。你坐在静湾的沙上，听见她敲错了一回，敲在退潮前半个时辰。你没上去。后来她敲得越来越顺，顺得像钟本来就这么响。你听着，觉得那声音里少了一个人。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":2},"flag":"left_next_keeper","thread":"那声音里少了一个人"}}]},{"id":"zhong_s08","act":"side","age":[76,76],"mode":"narration","title":"雾里没有钟声","opening":"七十六岁那年春天，海上起雾。雾不是从海上来，是从水里长出来的，先没了七声礁，再没了塔尖。你按时敲钟，钟响了，声音出不去，像敲在一床湿棉被上。街上的人先是互相看，后来卖鱼的放下刀，整条街都停了。有人问：今天涨潮没有。没人答得出。这是全岛第一次害怕——不是怕死，是怕不知道自己还在不在时间里。","ask":"钟声出不去，你先做什么？","days":10,"npc":"","memory":"听不见钟的岛","choices":[{"title":"一直敲，敲到手掌裂","desc":"你不下塔，两天两夜抱着钟绳敲，手心磨破也不停。","hint":"你左耳再听不见高音。","tone":"grind","outcome":"敲到第二天，钟口是温的，你的手掌裂开两道，血沾在绳上。第三天有个孩子在岸边说他听见了，从水底下。雾当天下午散了。你的左耳从此听不见高音，小钟的声音你再也听不着。夜里安静的时候，那两天两夜的钟声还在耳朵里响。","eff":{"bond":2,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"rang_through_fog","thread":"左耳听不见高音"}},{"title":"让各家把名字写手上","desc":"你挨家敲门，让每个人用炭把名字写在手心，一个时辰念一次。","hint":"有三家搬走了。","tone":"rule","outcome":"多数人照做了，念名字的声音一条街一条街地起。有个老头念到一半停住，说不记得自己叫什么，把手藏到背后。雾散了以后，有三家收拾东西搬去了外岛，说这岛疯了。留下的人从此有个习惯，洗手前先看一眼手心。","eff":{"bond":1,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":2},"flag":"wrote_names_on_hands","thread":"洗手前先看手心"}},{"title":"上塔把钟绳割断","desc":"你拿刀上塔，把钟绳割了，让这座岛这几天不算时间。","hint":"全岛欠了三天的债。","tone":"defy","outcome":"绳断的时候钟晃了一下，没响。岛上睡了三天，雾散才有人醒。醒来第一件事是算日子，可日子少了三天，谁也对不上。应响的债、耳蜡上刻的期、出海的班次，全都错开三天，此后年年有人为这三天吵架。你把断绳收在柜里，没再换新的。","eff":{"bond":-1,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"恶":1},"flag":"cut_bell_rope","thread":"年年为那三天吵架"}}]}]},"髓云都市":{"no":5,"name":"髓云都市","subtitle":"被删掉的那个人，还在你身体里","through":"你卖掉一段最好的记忆换母亲的手术费。她活了下来，却不记得你。","cast":[{"id":"mother","name":"母亲","role":"裁缝","tag":"母"},{"id":"father","name":"父亲","role":"码头工","tag":"父"},{"id":"friend","name":"阿棠","role":"记忆整理师","tag":"友"}],"main":[{"id":"sui2_m01","act":"main","age":[0,0],"mode":"montage","title":"缝在衣角","opening":"产房在城最底下那一层，窗外是排雾管，白雾一层压一层往上走，走到高处就散了。接生的护士拿雾髓棉球按你的脚心，屋里一股甜味，甜得发闷。你哭了一声，不大。母亲躺在铁床上，头发湿透，先问的是：孩子的手指全不全。父亲在走廊里坐着，鞋上带着码头的黑泥，帽子攥在手里，没进来。母亲把你的小褂翻过来，在衣角上缝了三个字，针脚一个挨一个。她说：这样我忘了，衣裳还记得。","ask":"她把你抱过来，你抓住什么","days":300,"npc":"","memory":"衣角上的三个字","choices":[{"title":"攥住她的手指","desc":"你攥住她右手食指，攥得指节发白，她没抽。","hint":"她那只手阴天就抬不起来","tone":"family","outcome":"她低头看你，手指没动，任你攥着，直到护士来抱你去洗澡。她后来跟人说，这孩子生下来手就是凉的。那天夜里她把你放在胸口，一只手一直握着你的手，另一只手在缝。她的右手食指后来阴天就抬不起来，她说是泡水泡的，没提你。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"爱":4,"哀":1},"flag":"","thread":""}},{"title":"推开那根针","desc":"你伸手去推她手里的针，针尖扎进自己掌心。","hint":"掌心留了个白点","tone":"warm","outcome":"血珠冒出来，你没哭，她先慌了，把你的手含进嘴里，尝到铁锈味。她说：傻的。那天她把针收进一只铁盒，盒子塞在缝纫机抽屉最里头。你左手掌心留下一个白点，一辈子都在。她后来提起，只说是你自己淘气。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":1},"flag":"","thread":""}},{"title":"让护士抱走","desc":"你松开手，让护士把你抱去婴儿室，不哭。","hint":"她说那晚听见你没哭","tone":"obey","outcome":"门一关，走廊里只剩推车轮子响。母亲躺回去，眼睛一直看门。半夜她扶着墙走到婴儿室窗外，站了半个钟头，回去时伤口渗了血。第二天她说：这孩子昨晚没哭。护士说哭了。她说不信，我听着呢。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"sui2_m02","act":"main","age":[6,6],"mode":"dialogue","title":"甜雾","opening":"雾髓温室在城北，玻璃顶，里面白得看不见人。母亲给温室的工人缝工装，二十件，捆在一块蓝布里，让你抱着。进门要过一道风帘，帘子一掀，甜味就上来了，像有人把一整罐糖化在水里。母亲把工装摊在案子上，让管事点数。点完她转过身，站在雾里，手还伸着，忽然不动了。她看看自己的手，又看看你，说：我来干什么的。管事在后头催。她的手在围裙上擦了擦。","ask":"她的手空着，你要怎么做才好","days":20,"npc":"mother","memory":"温室门口的空手","choices":[{"title":"替她把话说清","desc":"你告诉管事，我妈最近老忘事，工装是她缝的。","hint":"她再没接过温室的活","tone":"honest","outcome":"管事看了她一眼，把工钱数出来，说以后不用送了。母亲把钱攥在手里，一路没说话。回到家她把工装上的线头一根一根剪，剪得很齐。晚上她给你缝校服，缝到袖口停下，问你：今天是不是有人跟我说了什么。你说没有。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"牵她出来","desc":"你拉住她的手往外走，说衣服送到了，回家。","hint":"那批工装留在门口","tone":"protect","outcome":"她跟着你走，走到风帘外还回头看了一眼。工装留在案子上，工钱没结，第二天管事派人送了半价来，说活没交齐。她收下，没问为什么少。你在温室里站了小半个时辰，回家后半天想不起自己进门时先迈的哪只脚。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":""}},{"title":"进去替她送","desc":"你抱起蓝布包，一个人穿过风帘，把衣服放上案子。","hint":"那天你只记得甜味","tone":"carry","outcome":"雾到你胸口，甜的，凉的，进到鼻子里就化开。你把工装一件件摆好，出来时腿有点软。母亲在门口数自己的手指，数到第三遍才看见你。她问：你怎么从里头出来。你说我一直在外头。那天以后，你只记得甜味，别的一点都想不起来。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}}]},{"id":"sui2_m03","act":"main","age":[12,12],"mode":"narration","title":"一整面墙","opening":"十二岁那年，学校带我们去封存塔认瓶。塔是灰的，进去要脱鞋，换一双薄底布鞋。管理员给每人发一块铜牌挂在脖子上，牌上打着号：B-1147。他说丢了要重新申请资格。塔里冷，瓶子码在架子上，码到看不见顶。玻璃上有一层薄雾，像刚有人朝上面呵过气。甜味从通风口里一点点渗下来。母亲在门外等你，看见你就招手，叫了一个名字，不是你的；她顿了顿，改口叫：阿砚。","ask":"队伍往前走，你在哪儿停下","days":10,"npc":"","memory":"铜牌上的号码","choices":[{"title":"数到最上面一层","desc":"你仰着头一层一层数，数乱了就从头再来。","hint":"出塔时队伍早走了","tone":"learn","outcome":"你数到一百二十七就乱了，重数，又乱。管理员来拍你的肩，说走了。出塔时队伍已经没影，母亲在门口蹲着，手里拎着你的鞋。回去的车上你还在数。很多年后你做审计员，站在架子前扫一眼，就知道哪一格空过。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"惧":1},"flag":"counted_the_wall","thread":""}},{"title":"问赎不回来怎么办","desc":"你指着墙角那排没名字的瓶子，问管理员那些是谁的。","hint":"母亲的针停了很久","tone":"ask","outcome":"管理员说，到期不赎，归公共库，名字刮掉，编号留着。他说：人还在，记忆归大家。晚上你把这话学给母亲听，还说她的名字以后也会被刮掉。她正在给你缝衣角，针停在布上，停了好一会儿，说：算。就是轻一点。她说完低头继续缝，线用完了也没换。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"knows_public_pool","thread":""}},{"title":"写下母亲的名字","desc":"你在纸片上写她的名字，塞进一只空瓶，摆回架子。","hint":"她在外头等到天黑","tone":"warm","outcome":"管理员发现了，罚你把那一排架子擦一遍。你擦到手指发白，铜牌在胸口撞来撞去。母亲在塔外的台阶上等到天黑，没进来找，也没问为什么。那双薄底布鞋你穿回家，鞋底磨穿一个洞，她连夜给你补，补到半夜。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui2_m04","act":"main","age":[17,17],"mode":"dialogue","title":"差一截","opening":"医院在第九层，电梯里全是消毒水味，混着一点甜，是雾髓镇痛剂的味道。母亲躺在靠窗的床上，手背上扎着针，管子里一滴一滴。医生说越早置换越好，说排期在下个月，说费用还差一截。父亲蹲在走廊尽头，搪瓷缸里是散酒，酒味压过了消毒水。他今天话多，从码头的吊机讲到他二十岁扛过的盐包，一句一口。母亲摸你的手，说：别听你爸的，他喝多了。她的手比去年凉。","ask":"母亲说想回家，你先做什么","days":30,"npc":"father","memory":"走廊尽头的酒","choices":[{"title":"去办出院","desc":"你下楼办出院单，护士说排期作废，要重新等。","hint":"她那一夜睡得很沉","tone":"obey","outcome":"护士把单子推回来，让你签第二张。你签完上楼，父亲把搪瓷缸捏扁了，没骂你。回家那晚母亲睡得很沉，你守在床边听她呼吸。第二天早上她把药当成盐撒进了粥里，你吃了两碗，谁也没说破。排期再排上，是四个月以后。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"postponed_surgery","thread":"排期推到了四个月后"}},{"title":"说出还差多少","desc":"你站在床边，把还差多少、爸在借钱，全说了。","hint":"她把你的手抽了回去","tone":"honest","outcome":"母亲听完，把手从你手里抽出来，放在被子上，说：那就不做了。她那天没吃晚饭，护士来劝，她说胃不舒服。父亲半夜在阳台上抽烟，烟头一个一个摁在栏杆上。你回屋时听见她跟父亲说：别卖东西。父亲没应。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":3},"flag":"","thread":""}},{"title":"倒掉父亲的酒","desc":"你夺过搪瓷缸，把酒倒进洗手池，等他开口。","hint":"他说的那件事你没敢应","tone":"protect","outcome":"父亲愣住，随即笑了，笑得眼睛发红。他说他去问过价，码头三十年的记忆能换一半，说这话时手在裤子上擦。他还说：别跟你妈说。你点了头。回病房前你在楼梯间站了很久，听见楼下有人在喊号。第二天你开始打听另一种卖法。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":4},"flag":"father_offered_memory","thread":"你答应替父亲瞒着"}}]},{"id":"sui2_m05","act":"main","age":[18,18],"mode":"dialogue","title":"签在第三页","opening":"医院的走廊很白，护士让你在一张纸上签字。纸上的字你都认得，连起来却看不懂。签完你去了忆井广场。签约室在地下二层，桌上摊着七页合同，第三页是质押物清单，打着一行字：十六岁夏季，全段，含感官与情绪层，编号 B-1147。采集师把听膜推过来，说签这儿。你的外套搭在椅背上，衣角翻着，露出三个字。父亲跟在你身后，说去上个厕所，去了很久。","ask":"笔在你手里，你先想起什么","days":15,"npc":"father","memory":"十六岁的夏天","choices":[{"title":"留住那枚硬币","desc":"你要求留下买冰那枚硬币的记忆，只要这一件东西。","hint":"为这一件，价少了一截","tone":"keep","outcome":"采集师说可以，叫单点锚，要减价。你签了，父亲从走廊回来，在担保人那栏写了名字，写完把笔放下，手在裤子上擦。管子贴上太阳穴，像一条凉线爬进脑袋。醒来时天黑了，你手里攥着一枚旧硬币，磨得发亮，你不知道它是哪来的。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"kept_coin_anchor","thread":"你留着一枚不知来历的硬币"}},{"title":"签掉整段夏天","desc":"你在每一页上签字，最后一页按了手印，没抬头。","hint":"醒来时你数到十七","tone":"sell","outcome":"采集师数到十七，你就什么都不知道了。醒来时窗外全黑，桌上放着一张收据和一杯凉水。父亲坐在门口，见你睁眼，站起来又坐下，说：走吧。回家路上你问他今天几号，他说了，你算了算，少了一个夏天。你没觉得少了什么，这才是最怪的。","eff":{"bond":-2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":6,"惧":2},"flag":"sold_whole_summer","thread":""}},{"title":"叫父亲进来签","desc":"你走到走廊，把父亲叫进来，让他当着你的面签担保。","hint":"他把左手缩进了袖子","tone":"honest","outcome":"父亲进来，看了看合同，从口袋里摸出老花镜，镜腿用线缠着。他签得很慢，左手按纸，右手写。签完他把左手缩进袖子，说：别跟你妈讲。采集师笑了一声。出门你们在楼下各吃一碗面，谁都没提合同。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":4},"flag":"father_signed_guarantor","thread":"你答应不告诉母亲"}}]},{"id":"sui2_m06","act":"main","age":[19,19],"mode":"dialogue","title":"这个年轻人是谁","opening":"母亲醒在第三天早上。术前医生说过，手术会拿走一段，拿哪段说不准。她先看窗，再看自己的手，看了很久，像在认。护士进来换瓶，把窗帘拉开一半，光落在被子上。她问：姑娘，我这是在哪儿。护士说医院。她点点头，忽然看见床尾的你，指了指，问护士：这个年轻人是谁。护士的手停在瓶子上，看了你一眼。","ask":"护士看着你，你先开不开口","days":20,"npc":"nurse","memory":"她问了句这是谁","choices":[{"title":"说我是阿砚","desc":"你往前走一步，说妈，我是阿砚。","hint":"她客气地请你坐下","tone":"honest","outcome":"她看着你，很礼貌地笑了一下，说：我儿子也叫阿砚，他今年八岁，左眉上有个疤。她把被子往上拉了拉，问你吃过饭没有，说医院的粥不好吃。你坐下，说吃过了。她点点头，转头看窗。你在床边坐到中午，她睡着了，手还搭在被子上，掌心朝上。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":2},"flag":"","thread":"她说阿砚左眉上有疤"}},{"title":"让护士替你说","desc":"你退到门外，让护士告诉她，这是你儿子。","hint":"她问儿子怎么没来","tone":"dodge","outcome":"护士出来说，她哦了一声，问儿子怎么没来。你说他忙。中午你进去，她正把饭里的肉挑出来，堆在碗边，说留给阿砚。你把那碗饭端去热，回来时肉还在。她问你：你是护士吧。你说不是。她想了想，说：那你是好人。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":1},"flag":"","thread":""}},{"title":"翻出那个衣角","desc":"你把枕边外套翻过来，指着衣角上的三个字给她看。","hint":"她摸完字，改摸你的手","tone":"warm","outcome":"她摸着那几个字，一个指头一个指头地摸。她说：这是我缝的。她抬头看你，眼神变了一下，只一下。她抓住你的手，说：你手怎么这么凉。你走时把外套留在她床上，穿单衣回去，夜里发烧两天。第二天她在纸上写你的名字，写了三遍，问护士这是谁。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":6},"flag":"she_touched_the_corner","thread":"她记得针脚，不记得人"}}]},{"id":"sui2_m07","act":"main","age":[26,26],"mode":"dialogue","title":"听别人的夏天","opening":"审计室在封存塔三层，没有窗，通风口里有雾髓的甜味。桌上摆着待核的瓶子，标签写着：某某，某年夏，全段。你戴上听膜，把里面的东西过一遍，看是否如标签。第一天核了十一瓶。第七瓶是一个女人卖掉的三岁女儿，你听见孩子唱一支跑调的歌，唱到一半停了。你摘了听膜，坐了会儿，接着核第八瓶。阿棠推门进来，两杯豆浆，说：你脸色像刚从雾里捞上来的。她笑了一下，笑完眼底那层青还在。","ask":"阿棠说这活干不长，你怎么答","days":60,"npc":"friend","memory":"核到第十一瓶","choices":[{"title":"递给她听膜","desc":"你把听膜塞给她，让她自己听一段，别说话。","hint":"她听完说这瓶是她收的","tone":"help","outcome":"她听了一半就摘了，说这瓶是她收的。她还说，她柜子底下压着一瓶客人的东西，两年没上交。你把那份核验单抽出来，签了自己的名，写了合格。她看着你签，没拦。从那天起，你们两个人守同一件事，谁都没再提。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":3},"flag":"covered_atang","thread":"你替阿棠签了那张合格单"}},{"title":"照实写进报告","desc":"你把掺水的那瓶写进报告，连卖家姓名一起交上去。","hint":"父亲那晚没有喝酒","tone":"report","outcome":"报告交上去第三天，卖家的市民资格降了一级，是个在码头扛了半辈子盐包的老工人。父亲认识他，吃饭时听说了，筷子停了一下，说：你做得对。然后他进屋了，那晚没喝酒。你收拾碗的时候，发现他把酒坛的盖子扣得很严。","eff":{"bond":-3,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"reported_diluted","thread":""}},{"title":"改做无名瓶","desc":"你申请专核标签脱落、没人认领的那些瓶子。","hint":"这一格没人愿意干","tone":"niche","outcome":"上司同意了，因为没人愿意干。你给每一只无名瓶重新编号，记下里面的第一句话、最后一个动作。有一只是老太太在择菜，择到一半说起一个名字，说了三遍。你在备注栏写：疑似儿子。写完你想起母亲，把笔放下，去走廊上站了一会儿。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"audits_nameless","thread":""}}]},{"id":"sui2_m08","act":"main","age":[33,33],"mode":"dialogue","title":"标价十七倍","opening":"漂忆港在旧码头，退潮时滩上全是碎玻璃，踩上去咯吱响。摊子一个挨一个，东西不一样，价也不一样：有人卖初雪，有人卖一整个童年。雾从上层压下来，甜的，黏在喉咙口。你走在一排夏天的摊子中间，忽然停住。玻璃柜里横着一只瓶，标签发黄，编号 B-1147。价签用红笔写，数字后面加了三个零，是当初的十七倍。柜底有一层薄薄的白，像化了的冰。阿棠在你旁边，没说话。","ask":"摊主问你要不要，你怎么办","days":15,"npc":"friend","memory":"十七倍的价签","choices":[{"title":"报给鉴证师","desc":"你说这瓶来路不正，当场叫了港口的鉴证师。","hint":"瓶子被封进了公共库","tone":"report","outcome":"鉴证师来了两个，把柜子里的瓶子一只只登记。摊主被带走时回头看了你一眼，说：你有本事别来这行。阿棠说你这事做得对，又说：这下你更赎不回来了。瓶子进了公共库，编号还在，价签被撕了，柜台上留着一圈红笔印。","eff":{"bond":-2,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_b1147","thread":"B-1147 被封进公共库"}},{"title":"抄下编号和价","desc":"你掏出本子，把编号、价钱、摊位号一笔一笔记下。","hint":"本子越记越厚","tone":"save","outcome":"你回家把本子塞进铁盒，铁盒是母亲装针的那个，盖子上有一道凹。从那天起你每个月往里头放钱，放完把盖子按紧。第二年漂忆港搬了地方，你又去找，摊子还在，价又涨了。你在本子上添了一行，写得比上回用力。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"欲":2},"flag":"saving_for_b1147","thread":""}},{"title":"送母亲做延缓","desc":"你把攒的钱取出来，带母亲去做延缓，瓶子不赎了。","hint":"她多认了你两年","tone":"family","outcome":"支架做了两个钟头，她出来时握着你的手说想吃面。那两年她记得你的名字。第三年她先忘了你不吃葱，往你碗里撒了一把；过了半年，她问你今年十几；再后来把你的鞋当成她弟弟的，收进柜子。你路过漂忆港，不进去。","eff":{"bond":5,"health":-1,"reputation":0,"coins":-200,"stats":{"智识":1},"emotion":{"爱":4,"哀":4},"flag":"paid_for_mother_care","thread":""}}]},{"id":"sui2_m09","act":"main","age":[45,45],"mode":"dialogue","title":"只剩一半","opening":"赎回窗口在漂忆港最里头。你把合同复印件推过去，他对着灯看了很久，说：二十七年，最后一个月。瓶子调出来，编号 B-1147，跟十二岁那块铜牌一个号，装在一只纸盒里。阿棠在外头等，说：趁热，这玩意儿比记忆甜，还便宜。回家你把听膜贴上，听到第三段，声音断了。换一副，还是断。瓶里只到傍晚就没了，底下剩一层薄薄的白。合同背面有一行小字：提取时按浓度分装，浓者先售。","ask":"阿棠问要不要找剩下的一半","days":40,"npc":"friend","memory":"剩下一半的夏天","choices":[{"title":"跑遍漂忆港","desc":"你带着编号一家一家问，问到第四家，有人说浓的都进了私人柜。","hint":"那半瓶不拆卖","tone":"seek","outcome":"私人柜在城上层，雾最浓的地方，电梯要验三次记忆龄。你在楼下站了半天，没上去。回家你把半瓶放进缝纫机的抽屉，跟母亲的针盒、那枚旧硬币挨着。抽屉一拉开有股铁锈味。你后来每年开一次，不开听膜，只看一眼。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"欲":3},"flag":"","thread":""}},{"title":"放给母亲听","desc":"你把听膜贴到她耳边，让她听那段夏天。","hint":"听一次，瓶里薄一层","tone":"family","outcome":"听膜一贴，瓶里就薄一层。你还是让她听了。她听到中间伸手摸你的手，听完问：这是谁家的夏天。你说不知道。她点点头，说里头的蝉叫得好。第二天她把被子叠成方块，问你是哪家的师傅。你给她梳头，她一直看窗外。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":6},"flag":"","thread":""}},{"title":"摊开合同问他","desc":"你拿着合同去阳台，指着担保人那一栏问他。","hint":"他的字是用左手写的","tone":"honest","outcome":"父亲看了很久，咳嗽了两声。他说那年差的钱，担保人得签字。他怕你不肯，就趁你上厕所时签了。他说他这辈子只签过那一次假名字。你问他为什么用左手，他说右手抖。他把烟摁灭，说：你别怪我。你没说话，把合同折好，折得很慢。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":3},"flag":"knows_guarantor","thread":"父亲用左手签了担保"}}]},{"id":"sui2_m10","act":"main","age":[60,60],"mode":"dialogue","title":"归忆堂","opening":"母亲是立秋那天走的。走前三天不认人，只认得手，谁伸过去她就摸一摸，摸完说：凉。葬礼在城西归忆堂，塑料花上落了灰，角落点着雾髓香，甜得发闷。你穿着她缝的那件外套，衣角上三个字磨得只剩两个。净忆局送来一只小瓶，说是余忆，规定要在葬礼上放。司仪拧开瓶盖，她的声音很慢，叫的是你的小名：阿砚，饭在锅里，冰棍化了，你怎么才回来。","ask":"瓶子放完，司仪伸手来收，你","days":10,"npc":"friend","memory":"阿砚，饭在锅里","choices":[{"title":"要回那只瓶子","desc":"你说这瓶归家属，伸手从司仪手里拿回来，不松。","hint":"阿砚是她给你起的小名","tone":"keep","outcome":"你要回来，签了两张单子，一张交净忆局，一张自己收着。每年立秋你放一遍，第二遍声音就薄了，第五年只剩一句：饭在锅里。第八年你左耳听不清了，医生说别再听。你把瓶子挪到右耳边，还是听。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":7,"爱":5},"flag":"kept_funeral_bottle","thread":"瓶子一年比一年薄"}},{"title":"问是谁送来的","desc":"你拉住司仪，问这瓶哪年存的，为什么从没给过你。","hint":"底单在档案袋里等了十九年","tone":"ask","outcome":"司仪翻了底单，说十九年前她本人来存的，附一张纸，上面是她的字：等我走了再放，别提前给他。落款写得歪，最后一笔拖得很长。你把纸折起来放进内袋，出门时忘了拿伞，雨落在塑料花上。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":7,"爱":3},"flag":"knows_she_filed_it","thread":"她十九年前就写好了那张纸"}},{"title":"照规矩封存","desc":"你把手收回来，说按规定办，封存，别放了。","hint":"阿棠在门口站了很久","tone":"rule","outcome":"司仪把瓶子装进布袋，登记，让你签了名。亲戚散的时候有人低声说这儿子心硬。阿棠帮你收塑料花，收到一半说：她这辈子就攒下这一句。你说我知道。她把纸箱搁在门口，先走了。你在空屋里坐到天黑。","eff":{"bond":-4,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"怒":2},"flag":"sealed_residue","thread":"她最后那句被装进布袋"}}]},{"id":"sui2_m11","act":"main","age":[74,74],"mode":"montage","title":"不收记忆","opening":"七十四岁这年，净忆局来信，说你的记忆龄不足，要重新申请市民资格。附表有一栏：可支配记忆，请勾选愿交出的部分。阿棠的店在旧码头，门口挂一块木牌：不收记忆。她前年走了，店留给你。门后挂着母亲那件外套，衣角上只剩两个字。你在半瓶里听见十六岁的自己说：你别老摸我手了，热。她在余忆里记的你，蹲下来握她的手，说：妈，你手怎么这么凉。同一个下午，你们记成了两个人。","ask":"表在你手里，你勾哪一栏好","days":200,"npc":"","memory":"最后一个夏天","choices":[{"title":"交上半瓶夏天","desc":"你在表上勾了十六岁夏天，把剩下的半瓶也交了出去。","hint":"办事的人说这段不值钱","tone":"practical","outcome":"办事的年轻人抬头看了你一眼，说这段不完整，折不了多少。你说我知道。他给你换了一张临时市民证，纸的，压一层膜。你走出门，天有点阴，雾从街口漫过来。你忽然想不起母亲的缝纫机是什么颜色，站住想了很久，没想起来。","eff":{"bond":-2,"health":2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":6,"惧":3},"flag":"surrendered_memory","thread":""}},{"title":"摆两瓶在柜台","desc":"你把 B-1147 和她的小瓶并排摆在柜台上，写：非卖。","hint":"有小孩进来问那是什么","tone":"keep","outcome":"你找两块干净布把瓶底擦了一遍，标签自己写，字有点抖。有小孩进来问这是什么，你说：两个人的夏天。小孩问哪个是好的，你说都不好，也都不坏。一个月后信又来催，你没回，市民资格停了，配给也停了。你把门上的木牌翻过来，背面有阿棠写的一行：开了就别关。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"爱":5,"哀":3},"flag":"kept_both","thread":""}},{"title":"去封存塔查他","desc":"你带着余忆的编号去封存塔，查那个少年的档案。","hint":"系统里没有这个人","tone":"seek","outcome":"窗口的人查了三遍，说系统里没有这个编号，也没有这个人的脸。你说再查查。他说老太太的余忆里常有这种，是他们自己缝出来的人。你回家，把那个少年的样子画在纸上：十六岁，头发湿的，站在门口。画得不像，你还是贴在了柜台后头。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"he_was_never_registered","thread":"她记得的那个人没有档案"}}]}],"side":[{"id":"sui2_x01","act":"side","age":[7,7],"mode":"narration","title":"一勺糖霜","opening":"配给遗忘每旬领一回，装在一只旧盐罐里，罐口的字是母亲用刀刻的，刻得歪。她说这东西一天只能抿一小撮，多了要把事忘光。那天下午你饿，柜子里没有别的。罐子里是白的，细的，舔一口，甜的，像糖霜化在舌头上，还有一点凉。你吃了两勺。头一勺下去，窗外的雾好像薄了一层。第二勺下去，你忽然想不起上午干了什么。隔壁的丫头在门口探进头来问：哥，你家盐呢，我妈借一勺。你说不知道。她看了你一会儿，转身进厨房，回来时举着那只罐子，罐底见了白。她说：你吃了。","ask":"她举着那只罐子，你怎么办","days":12,"npc":"","memory":"罐底见了白霜","choices":[{"title":"让她写满胳膊","desc":"你把袖子卷到肩膀，让她把今天的事一件一件写上去。","hint":"晚上洗澡，字糊成一片。","tone":"warm","outcome":"她写得认真，一笔一画，从早起写到母亲出门，写到她自己忘了的地方就编。你举着胳膊，走到哪儿念到哪儿，念到“下午挨骂”那行，母亲在厨房里笑了一声。晚上洗澡，字糊了，胳膊上剩一层蓝，第二天只认得出三个：饭、盐、哥。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":"胳膊上剩下三个字"}},{"title":"把罐子放回去","desc":"你把剩下的倒回罐里，抹平，盖上盖，装没动过。","hint":"那一旬，全家没能忘事。","tone":"hide","outcome":"母亲那旬没舍得再领，罐底那点白她省着用。父亲在码头挨了骂，回来坐在门槛上骂了半宿，母亲听着，没吃。夜里她起来洗衣服，搓到天亮，搓破了一件你的褂子。第二天她把褂子补好，补丁在里侧，你穿了半年才发现。隔壁那丫头从此见了你就笑，笑得你心里发毛。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"ate_forget_ration","thread":""}},{"title":"去广场补一段","desc":"你揣着两枚铜子跑去忆井广场，找那个补忆的摊子。","hint":"补回来的是别人的下午。","tone":"seek","outcome":"摊主收了两枚铜子，给你扣上听膜，三分钟：一个男人蹲在门口修自行车，链条掉了，手上有机油，楼上有女人喊吃饭。你回家讲了一路。丫头说你家没有自行车。母亲问你在哪儿听的。你说在外面。她没再问，把罐子挪到了柜子最高一层。","eff":{"bond":0,"health":0,"reputation":-1,"coins":-5,"stats":{"机缘":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":""}}]},{"id":"sui2_s01","act":"side","age":[8,8],"mode":"narration","title":"养出来的童年","opening":"母亲把二十件工装摊在膝上，一件一件对齐衣角，你跟她进城北的玻璃棚。棚后头有间小屋，地上铺草席，墙角码着一排空瓶，瓶底一层薄白。屋里坐着一个和你差不多大的男孩，戴听膜，面前一只瓶，标着 K-032。管事的说这叫养童年，养到十二装瓶，卖给上头那些没有小时候的人。男孩摘下听膜问：你妈打你吗。你说打。他说他那个妈不打，只给他剥橘子，剥得很慢。他问橘子什么味。你说酸的。他说：我的是甜的。","ask":"他等着你说话，你先做什么","days":20,"npc":"","memory":"瓶底的橘子籽","choices":[{"title":"摘下他的听膜","desc":"你把听膜摘了，跟他讲你妈的手、衣角上的字，讲到天黑。","hint":"出来时你忘了那个下午","tone":"warm","outcome":"你讲一句，他学一句，学你妈叫你的腔调，两个人都笑。管事的来撵人时，他已经把你的话记住了大半。出门雾灌进鼻子，甜得发腻，那个下午你讲了什么，后来一句也想不起来，只记得嗓子哑了三天。第二年你再去，K-032 那格空了，管事的说装瓶出货了。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"你记不住自己讲过的那个下午"}},{"title":"去告诉管事","desc":"你拉着管事的袖子说，那是个孩子，不是样品，不能装瓶。","hint":"他提前三个月出了货","tone":"report","outcome":"管事的笑了一声，说这孩子的身子四岁就押给温室了，押到十二。第二天来了两个穿灰衣服的人查资质，温室怕生事，把 K-032 提前装了瓶。男孩被抬走时还戴着听膜，手在空气里抓。管事的说：你要是不多那句嘴，他还能在这儿养到十二。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":3},"flag":"reported_cultivated_child","thread":"他提前三个月被装瓶"}},{"title":"戴上他的听膜","desc":"你把听膜扣在自己耳朵上，想尝一口他说的那种甜。","hint":"你从此记得一只没养过的狗","tone":"greed","outcome":"里面是一个下午：有人剥橘子，剥得很慢，一只黄狗趴在门槛上，蝉在叫。甜味顺着耳根化开，比雾还甜。你把听膜还给他，回家路上一直咽口水。后来你妈给你剥橘子，你嫌她剥得不对。很多年里你都记得那只黄狗，记得它叫来福，你从来没养过狗。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"喜":2,"欲":3},"flag":"tasted_cultivated_child","thread":"你记得一只没养过的黄狗"}}]},{"id":"sui2_s09","act":"side","age":[9,9],"mode":"narration","title":"入伏的柿子树","opening":"入伏头一天，忆井广场的雾最薄，日头一晒，甜味就从地缝里往上冒，黏在嘴唇上。母亲给东头的裁缝送线，让你在台阶上等。台阶上坐着一个老太太，蓝布衫，手背上生着褐斑，膝头一只布袋，袋口露出一角手绢。她拉住你的袖子，让你替她看瓶上的字。摊主老柯从柜里取出一只瓶，瓶身一道白痕，编号 D-2071，标签写着：七岁，院子，柿子树，全段十二分钟。她说：就这个，我每年听一回。","ask":"她把一把铜子放在你手心，你怎么办","days":20,"npc":"","memory":"十二分钟的院子","choices":[{"title":"陪她坐到日头落","desc":"你把听膜替她扣好，坐在旁边扶着瓶，一直扶到天黑。","hint":"回家时母亲找了你半条街","tone":"escort","outcome":"她听到第九分钟手就抖了，抓着你的手腕，抓出四道红印。听完她把瓶还回去，说：这院子我认得。日头落了，广场的灯一盏一盏亮，母亲从街那头跑过来，第一次打了你一巴掌，打完又把你抱起来。第二年入伏她又来，隔着两排摊子朝你抬了抬下巴。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"母亲第一次打了你"}},{"title":"说这院子不是她的","desc":"你指着标签说，这上头没她的名字，院子是别人的。","hint":"第二年那张小板凳空着","tone":"honest","outcome":"她把手绢叠好塞回袋里，说：我知道。她把铜子一枚一枚数给老柯，数完站起来，走得比来时慢。老柯等她走远，低声说你多嘴。第二年入伏，那张小板凳空着。过了几年你听说，养老层有个姓吴的老太太，把每月配给的遗忘都攒着没领。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"told_wu_truth","thread":"她攒着遗忘没领"}},{"title":"拿余钱买两根冰","desc":"你替她数完，把多出的几枚铜子揣进兜，跑去买冰。","hint":"那几个铜子你一直没还","tone":"greed","outcome":"冰是桂花味的，甜和广场上的甜混在一起，分不清哪个是哪个。你回来时她已经走了，小板凳上留着一小片撕下来的手绢角。你把冰棍纸塞进台阶缝，回家没提。往后每年入伏你都在台阶上坐一会儿，等一个穿蓝布衫的。铜子你留着，一直没花。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"欲":2},"flag":"","thread":"你留着几枚不属于你的铜子"}}]},{"id":"sui2_x02","act":"side","age":[9,9],"mode":"narration","title":"池底的瓶盖","opening":"入夏最热那几天，雾薄得能看见对面的楼顶，太阳一晒，瓷砖烫脚。忆井广场的水池是给雾管降温的，水从铁管里出来，带一点甜，喝一口舌头发麻，没人真喝。你和二毛、丫丫泡在里头，水到膝盖，池底滑，长着一层绿，踩上去像踩着一块肥皂。比的是谁在水下睁眼最久。二毛睁到十九下就蹿上来了，眼睛红得像兔子，蹲在池边吐水。丫丫摸到一只铜瓶盖，举起来迎着光看，说这是名人瓶上的。你潜下去，水从耳朵灌进去，摸到一枚旧硬币，还有半只瓶盖，边上有一道牙印。管理员老吴举着竹竿从台阶那头过来了，拖鞋拍着地，一下一下。","ask":"老吴举着竹竿过来，你们跑不跑","days":20,"npc":"","memory":"池底的铜瓶盖","choices":[{"title":"把瓶盖送他","desc":"你爬上去，把带牙印的瓶盖放在他手里，说给他留的。","hint":"第二天池子加了铁栏。","tone":"warm","outcome":"老吴捏着瓶盖看了半天，说这玩意儿不值钱，揣进了兜。他让你们再玩一刻钟，自己在台阶上坐着，竹竿横在膝上。第二天池子四周围了铁栏，门上挂了锁。你们改去雾沟里蹚水，水更凉，底下有碎玻璃。丫丫说还是池子好。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"爱":1},"flag":"","thread":"池子锁了"}},{"title":"一头扎下去","desc":"你吸一口气潜到池底，贴着瓷砖从另一头冒出来。","hint":"膝盖磕在池底，落了疤。","tone":"defy","outcome":"你在水里睁着眼，看见老吴的竹竿在头顶上戳来戳去，像钓鱼。你从池子另一头冒出来，丫丫笑得蹲在地上。晚上回家膝盖青了一块，后来结了个痂，痂掉了留一道月牙。那道疤跟了你一辈子，洗澡时摸到还会想起那天的水是温的。","eff":{"bond":1,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":4,"惧":2},"flag":"","thread":""}},{"title":"上来替他捡竿","desc":"你自己爬上去，把滚远的竹竿捡回来，递到他手里。","hint":"那个夏天你成了看池子的。","tone":"obey","outcome":"老吴愣了一下，说你这孩子懂事。他让你替他看半个钟头，他去打水。半个钟头变成一下午，一下午变成整个夏天。你坐在台阶上，看着别人在水里扑腾，手里攥着那根竹竿。二毛他们后来不叫你了，说你跟他们不是一伙的。","eff":{"bond":0,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"喜":2},"flag":"","thread":""}}]},{"id":"sui2_x03","act":"side","age":[10,10],"mode":"narration","title":"墙那边的课","opening":"合同是三月签的，质押物写着：小学全段，含课本、课间、毕业照，押三年。父亲签的字，你的名字在随附人那一栏，是别人代写的。条款后头有一行小字，说质押期内不得新增同类记忆，否则影响成色。所以你不能去上学。母亲把书包收进柜子顶上。你每天照旧六点半出门，走到学校，坐在楼梯间的暖气片旁边。墙是空心砖，声音从砖缝里漏出来：老师点名的声音，粉笔断在黑板上的声音，全班一起念课文的声音，一声一声。下课铃一响，同学涌出来，有人问你：你怎么不上学。你说我上。那天下午，门底下塞出来一张卷子，是老师从里面推的。","ask":"老师从门缝塞出考卷，你接不接","days":90,"npc":"","memory":"空心砖里的课文","choices":[{"title":"接过来做完","desc":"你把卷子铺在膝盖上，用半截铅笔做完，从门缝塞回去。","hint":"分数被划掉，改成不算。","tone":"study","outcome":"你做了四十分钟，膝盖硌得疼。门底下塞回来一张，红笔打了个一百分，旁边又画了一道，写上“不算”。你把那张纸折好，塞进暖气片后头。第二天去，纸还在。你在灰上把一百分描了一遍，描得很大，放学的人从楼梯上下来，谁都看见了。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"哀":3},"flag":"","thread":"暖气片后头那张卷子"}},{"title":"把卷子推回去","desc":"你用脚把卷子顶回门缝里，站起来，下了楼。","hint":"老师在里面站了很久。","tone":"refuse","outcome":"卷子在门缝里卡了一下，进去了。里面没有声音。你走到楼下，回头看了一眼那扇门，门上的漆掉了一块，露出底下的木头。第二天你没去。第三天也没去。母亲问你怎么不去了，你说不想去。她把柜子顶上的书包拿下来，拍了拍灰，又放了回去。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":4,"怒":2},"flag":"","thread":""}},{"title":"去跟父母说不押","desc":"晚上你把合同摊在饭桌上，说我不押了，我要上学。","hint":"妹妹的药盒就摆在旁边。","tone":"ask","outcome":"父亲把筷子放下，没说话。母亲把合同翻到最后一页，指着违约金那一行，说：这个数，咱家拿不出来。你去上学，母亲的药就断。母亲在里屋咳嗽，一声一声。你把合同折起来，推回母亲手边，说那我去楼梯间。母亲说：楼梯间冷，加件衣裳。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"母亲的药盒"}}]},{"id":"sui2_s02","act":"side","age":[11,11],"mode":"narration","title":"小学全段","opening":"开学第三个星期，同桌陈果没来。第四天他来了，人瘦了一圈，坐下就问：咱们现在是一年级还是三年级。他妈妈站在校门口，跟一个穿灰衣服的人签一张纸，纸角露出四个字：小学全段。老师进来，让大家别跟他提从前上过的课，说提了对他不好。陈果从书包里摸出一只空瓶，瓶底一层白，瓶身有一串编号，磨得看不清，凑近闻还有点甜。他小声问你：去年冬天，我是不是借过你一块橡皮。","ask":"他把空瓶推过来，你先做什么","days":30,"npc":"","memory":"瓶底的一层白","choices":[{"title":"一件一件讲给他","desc":"每天中午你给他讲一件从前的事：橡皮、下雪、老师那把尺。","hint":"你的算术掉到及格线下","tone":"warm","outcome":"你讲一件，他记一件，记在空瓶的标签背面。讲到第三个月，他家里又来签了一张纸，说记住的要紧，押得更贵。期末他没来考试。很多年后你在招工的队伍里看见他，他认不出你，忽然说：我小时候好像有人给我讲过下雪。你说是我。他说：哦。队伍往前挪了。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":-1,"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"他记得下雪，不记得你"}},{"title":"去告诉班主任","desc":"你把那张纸上的字抄下来交给班主任，说陈果被押了。","hint":"全班都知道了是谁说的","tone":"report","outcome":"第二天净忆局来了两个人，把陈果带去重定记忆龄，他妈妈的市民资格停了一年。他转学那天在校门口站了会儿，问你：老师为什么那样看我。你说不知道。秋天开学，你的书包被人扔进雾沟，捞上来时课本全软了。你做得没错，可这个班上再没人跟你同桌。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":4},"flag":"reported_chenguo","thread":"他在校门口问过你一句"}},{"title":"求老师换座位","desc":"你举手说看不清黑板，搬到最后一排靠窗，不再回头。","hint":"毕业照上他的位置空着","tone":"distance","outcome":"老师给你换了座，陈果的新同桌是个不爱说话的女生。期末你考得不错，母亲被请去学校，回来给你煮了两个蛋。毕业照洗出来，他站的那一格是空的，因为那天他已经被除名。照片你一直收着，搬了三次家都没丢，也没再打开看过。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":"毕业照上空着一格"}}]},{"id":"sui2_x04","act":"side","age":[12,12],"mode":"narration","title":"一段真的假的","opening":"每年秋天学校要做记忆防漏抽检，每人交一段家庭记忆做样本，说是建档。检测室在医务室隔壁，一把椅子，一副听膜，屏幕上一根绿线。前头的同学交的是过年放炮，机器滴了一声，过了。轮到你，你坐在椅子上，脑子里是空的。父亲的脸你想得起来，可他在场的下午，一段也没有——那些年他卖得太干净。你张嘴，开始编：父亲蹲在门口修自行车，链条掉了，手上有机油，母亲在楼上喊吃饭。你一边说一边看见。机器滴了一声，绿灯。老师说：很好，很真。","ask":"机器亮了绿灯，你说点什么","days":20,"npc":"","memory":"门口那辆二八车","choices":[{"title":"认下这一段","desc":"你点头，把它当成真的，记进自己的档案里。","hint":"它成了你唯一记得的父亲。","tone":"keep","outcome":"往后几十年，你记得父亲修过一辆二八车，记得他手上有机油，记得母亲在楼上喊。有一年你跟他提起，他正低头剥蒜，说：我没修过车，咱家那车是借的。你说修过。他想了想，说：那就修过吧。蒜皮落在他膝盖上，他没掸。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":3},"flag":"kept_invented_father","thread":"父亲说那就修过吧"}},{"title":"跟老师说是编的","desc":"你说这段是假的，家里没有这段，重测吧。","hint":"档案上记了一笔源不清。","tone":"honest","outcome":"老师看了你一会儿，把机器关了，让你重测。你重测三次，三次都是空的。她在表上写“记忆源不清”，笔尖顿了一下。第二年你转学，新学校的老师拿着档案问了一句，你说不知道。这事到高中还跟着你，像衣服上一块洗不掉的印。","eff":{"bond":0,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"admitted_fake_memory","thread":""}},{"title":"回家问父亲","desc":"晚上你问他：你修过自行车吗。他正在喝酒。","hint":"他说修过，你不知真假。","tone":"ask","outcome":"他端着杯子停了一下，说修过。你问什么时候。他说你小时候。你再问，他就讲码头，讲吊机，讲盐包，一句接一句，讲到你母亲把灯关了。你躺在黑里想，他到底修没修过。这个问题你没再问第二遍，他也再没提过自行车。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"sui2_x05","act":"side","age":[14,14],"mode":"narration","title":"比她像妈","opening":"暑假你在雾髓温室打杂，擦架子，送工装，管两顿饭。育室在最末一排后头，推门进去甜味更浓，浓到发苦。屋里坐着一个女人，三十来岁，戴听膜，面前一排小瓶，标签写着：母亲·早、母亲·午、母亲·夜。管事说这是给上头一户人家养的妈，孩子八岁，亲妈忙。样本是从旧库里调的。你送工装那天，她拉住你的手，说：手怎么这么凉，过来烤烤。她的声音跟你母亲一模一样。你抽回手。她也不恼，说：那你坐着，我给你把袖子放下来。傍晚母亲来接你，站在门口说：袖子放下来，像什么样子。","ask":"她学你妈叫你，你应一声吗","days":30,"npc":"","memory":"把袖子放下来","choices":[{"title":"应一声","desc":"她叫你的小名，你抬头应了，声音比自己想的大。","hint":"真妈来接时你没应。","tone":"obey","outcome":"她笑了，笑得跟你母亲不一样，太稳。第二天她又叫，你又应。到第五天，母亲在门口叫你，你正低头听她讲夜里盖被子的事，慢了半拍才回头。母亲什么也没说，回去的路上走在前面。你跟在后面，看见她后颈上有一道晒出来的印子。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"answered_fake_mother","thread":"母亲走在前头"}},{"title":"说她叫得不对","desc":"你告诉她：我妈叫我，尾音是往下掉的，你这个往上。","hint":"她第二天换了个人。","tone":"honest","outcome":"她认真听了，练了一下午，练到嗓子哑。管事来查，说不对，返工，扣了她半月工钱。第二天育室里换了个人，年纪更大，声音更粗。你问原来那个呢。管事说调到洗衣房了。你在架子后头站着，手里还捏着那件没送出去的工装。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"","thread":""}},{"title":"教她一句真话","desc":"你教她说一句你母亲从没说过的话：慢点吃，锅里还有。","hint":"这句后来卖到了别人家。","tone":"teach","outcome":"她学得快，练了两遍就会，说完自己愣住，说这句好。她每天中午都跟你说一遍。月底她装瓶出货，标签上写着“母亲·午·加长”。三年后你在漂忆港听见一只瓶里有人说“慢点吃，锅里还有”，声音是她的。你站着听完，没买。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui2_s10","act":"side","age":[15,15],"mode":"narration","title":"育室最后一排","opening":"温室在城北，玻璃顶上一层水，一晒往下掉，落进脖子里是凉的。你穿着母亲缝的褂子，衣角翻着，替她送工装。管事让你留下改袖口，管两顿饭。育室在最末一排架子后头，推门进去，甜味更浓，浓到发苦。屋里坐着一个女人，三十来岁，戴听膜，面前一排小瓶，瓶签上写着：母亲·早、母亲·夜、母亲·手。她见你进来就站起，摸你的手，摸完说：凉的。她说话很慢，一句和一句之间要停一停。","ask":"她把手放回膝上，等你再开口","days":20,"npc":"","memory":"母亲·夜那只瓶","choices":[{"title":"坐下让她练手","desc":"你把手放回她掌心，随她一遍一遍叫你的名字。","hint":"你回头时慢了半拍","tone":"warm","outcome":"她练了四天：叫你的名字，说饭在锅里，说天凉了加件衣裳。到第四天她已经很像，像到你想应一声。屋角那排瓶一直亮着，管事在门口看了会儿，在本子上记了一笔。月底你拿到两顿饭钱，回家路上你妈在巷口叫你，你回头慢了半拍才应。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"惧":2},"flag":"practiced_as_son","thread":"你回头慢了半拍"}},{"title":"告诉她实情","desc":"你说你不是谁的妈，你是雇来的，工钱按天算。","hint":"那间育室换了人","tone":"honest","outcome":"她把手收回去，摘下听膜，问：那我儿子呢。你说那是别人的儿子。第二天她结了工钱走了，孩子在走廊里哭了三天，嗓子哑了。管事扣你半月工钱，说这间育室要重开。三个月后你在洗衣房看见她，手泡得发白，正一只一只刷瓶，见你也没认出来。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":2},"flag":"told_surrogate_truth","thread":"那孩子在走廊里哭了三天"}},{"title":"把那只瓶带走","desc":"你趁她去打水，把母亲·夜那只瓶揣进褂子里。","hint":"那是你自己那个下午","tone":"sneak","outcome":"她少了这一段，考核那天叫不出孩子的名字，被调去洗瓶子。你回家贴上听膜，听见的却是自己那个下午：她在学你妈的口音，一句一句，学得很准，连停顿都一样。你听到第三遍，把瓶塞进床底。往后十几年你搬了几回家，那只瓶一直带着，标签朝里。","eff":{"bond":-1,"health":-1,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"欲":2},"flag":"stole_mother_night","thread":"床底那只母亲·夜"}}]},{"id":"sui2_x06","act":"side","age":[15,15],"mode":"narration","title":"三十秒一段","opening":"漂忆港的夜市到后半夜最热闹，棚子上挂一串灯泡，甜味混着烤鱿鱼的油烟，落在衣服上，回家洗一遍还有味。试听摊的老头缺两颗牙，听膜是公用的，边上沾着别人的耳油，你用袖子擦了两下，越擦越亮。一角钱三十秒，随你挑。你和周三把兜里的钱凑在一起，一共七角，摊在掌心数了三遍，有一枚是缺角的，老头收了。摊上摆着几十只瓶，标签都是手写的：婚礼·致辞、打鼾·整夜、骂街·四分钟、教骑车·摔了、产房·走廊。周三说先听骂街，你说明明先听打鼾。两个人争到后半夜，棚子上的灯泡灭了一只，最后谁也没说服谁，只剩一角钱了。","ask":"只剩一角钱了，你们听哪段","days":10,"npc":"","memory":"一角钱三十秒","choices":[{"title":"听骂街那四分钟","desc":"你们扣上听膜，听一个女人骂了四分钟不带重样。","hint":"你学了一嘴，回家说漏。","tone":"greed","outcome":"骂的是她男人把工钱输了。她骂得有理有据，从早上骂到晚上，中间还抽空看了一眼锅。你和周三笑得蹲在地上，听完一路学着骂回码头。第二天你在家顺嘴说了一句，母亲手里的锅铲停在半空，问：你跟谁学的。你说不上来。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":5,"惧":1},"flag":"","thread":"你顺嘴说了一句"}},{"title":"听那夜打鼾","desc":"你们选了打鼾·整夜，想听听能有多响。","hint":"你后来睡不着就学这声。","tone":"niche","outcome":"那是一个男人打了一整夜的呼噜，中间停过两次，停得人心慌，然后接着打。旁边有人翻身，床板响，一只猫叫。你听完耳朵里嗡嗡的。后来很多年你失眠，就自己在嗓子眼里学那声呼噜，学着学着就睡着了。周三说你这是病。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":4},"flag":"","thread":""}},{"title":"让老头自己选","desc":"你把最后一角钱推回去，说您选一段，我们陪着听。","hint":"他选了亡妻的一段。","tone":"warm","outcome":"老头挑了半天，挑了一只标签磨白的，说这个。里面是下雨，一个女的在收衣服，嘴里数着件数，数到第七件停了，说：这件是谁的。就这些。老头听完摘了听膜，说：她老忘。你们没笑，把钱放在摊上走了。走出半条街，周三才说：那件是谁的。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":1},"flag":"","thread":""}}]},{"id":"sui2_x07","act":"side","age":[16,16],"mode":"narration","title":"巷口那辆车","opening":"车是灰的，停在巷口，把整条巷子堵住，两边的门都开不了。两个穿灰衣服的人夹着吴远下来，他没挣，一只鞋掉在台阶下，鞋带还系着。有人说他脑子里多了一段，是他哥的，他哥去年没了，他妈找人植的，没登记。神经追踪一响，车就来了。巷子里有人探头，看一眼又缩回去，窗户一扇一扇关。你站在车头前，手心里全是汗，膝盖在打抖。司机按了一下喇叭，很长，把楼上的鸽子惊起来。吴远抬起头看你，嘴动了一下，没出声。他另一只脚上的鞋也没了，袜子底是黑的。","ask":"司机又按了一下喇叭，你让不让","days":15,"npc":"","memory":"巷口那辆灰车","choices":[{"title":"站着不动","desc":"你站住不动，两只手撑在车头上，看着司机。","hint":"你被带走问了一夜。","tone":"brave","outcome":"司机下车推你，你抓住雨刷，被拖了半米，膝盖在水泥地上磨破。后来是片警来把人分开的。你被带走问了一夜，写了三份说明，学校记了一笔，高考资格往后延一年。吴远第二天就被送走了。走之前托人给你带话，说那只鞋别扔。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"哀":3},"flag":"blocked_the_van","thread":"那只鞋还在你床底下"}},{"title":"去捡那只鞋","desc":"你绕到台阶下，把那只鞋捡起来，擦干净，抱在怀里。","hint":"车开走时你只拿到鞋。","tone":"help","outcome":"你把鞋抱在怀里，车从你身边开过去，玻璃是黑的。你追了两步，没追上。回到巷口，人都散了，台阶上还剩一只袜子。你把鞋和袜子放在他家门口，敲了门就走。他妈开门，看了半天，说：你是谁家的。你说同学。她说：哦。门关上了。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"记车牌去举报","desc":"你掏出铅笔，把车牌抄在手背上，转身往局里跑。","hint":"手续齐全，举报没用。","tone":"report","outcome":"你在局里排了一个钟头，窗口的人查了查，说手续齐全，强制封忆的批文三天前就下了。你问那孩子呢。他说按规定办。你回学校写了检讨，因为旷课。吴远的座位空了一个月，后来搬来一个新同学，个子很高，坐不下，桌子往后挪了半尺。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":""}}]},{"id":"sui2_x08","act":"side","age":[18,18],"mode":"narration","title":"一百二十桌","opening":"那时你在漂忆港给人看柜台，管过秤、验瓶、写标签。港上的规矩是卖家自己报价，报多少写多少，港上抽一成。男人是下午来的，袖口磨破，手指在柜台上敲，敲一下报一个数，越报越高。他说他卖结婚那天，全段，含酒席、鞭炮、闹房。他说摆了八十桌。想了一下，说一百二十桌。又说光鞭炮就放了半个钟头，响得邻村来敲门。你正要开单子，门口进来一个女人，蓝布围裙，手里拎着饭盒，葱味先到了。她站住，看了看他，又看了看那只瓶，说：你卖这个干什么。","ask":"她站在柜台前问你，你怎么做","days":40,"npc":"","memory":"一百二十桌席","choices":[{"title":"收下，照他的价","desc":"你开了单子，按一百二十桌的价，一分没压。","hint":"他老婆后来问过一回。","tone":"trade","outcome":"她说完，把饭盒放在柜台上，说：那天你喝多了，吐在我娘家门口。他说我没吐。她说吐了。柜台后头的人都笑。两个人一前一后出去了，瓶子忘在柜台上。过了一个礼拜，他一个人又来了，站在柜台前，说：按我说的价。他签了字，手抖，签完说：你别跟她说。你说好。","eff":{"bond":1,"health":0,"reputation":0,"coins":50,"stats":{"智识":1},"emotion":{"喜":3},"flag":"","thread":"她说她记错了"}},{"title":"劝他拿回去","desc":"你把瓶推回去，说这段卖不得，回去跟她认个错。","hint":"他骂你不懂事。","tone":"refuse","outcome":"他把瓶子抓过去，说你知道什么，我闺女下个月要交学费。他骂了两句，声音很大，港上的人都看过来。骂完他抱着瓶子走了。三个月后他又来，人瘦了一圈，瓶子还在怀里，说：还是卖吧。你开了单子。这回他没讲价。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"怒":2,"喜":2,"哀":2},"flag":"","thread":""}},{"title":"骑车去追她","desc":"你从后门出去，骑上板车追到街口，把她叫回来。","hint":"他半年没跟你说话。","tone":"help","outcome":"她回来，站在柜台前，把饭盒打开，说：先吃饭。他不动。她把筷子塞到他手里，说：吃完再卖。他吃了半盒，忽然说：那天我吐了。她说：我知道。两个人把饭吃完，瓶子拿走了。他半年没跟你说话，过年他老婆送来一碗饺子，饺子上撒了葱。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":3},"flag":"","thread":""}}]},{"id":"sui2_x09","act":"side","age":[20,20],"mode":"narration","title":"初恋·十七岁·夏","opening":"那只瓶摆在摊子最里头，标签是旧纸，字写得很好看：初恋·十七岁·夏，全段，四十七分钟。摊主是个老头，说这是压箱底的货，不还价，不试听。你把攒了半年的钱数给他，钱是卷着的，一张一张抹平。抱着瓶回家，路上瓶子贴在胸口，凉的，走一步撞一下。屋里你扣上听膜，按下开关。先是一阵椅子腿刮地的声音。然后一个男人说：宝贝儿，往左一点。又说：不对，往右。整整四十七分钟，他在装一把折叠椅。到最后他说：成了。咔的一声，椅子塌了。他叹了一口气，说：再来。","ask":"瓶里没有初恋，你打算怎么办","days":20,"npc":"","memory":"那把塌了的椅子","choices":[{"title":"留着，逢人放","desc":"你把瓶摆在桌上，谁来都给听一遍，听一次笑一次。","hint":"你成了港上的笑话。","tone":"keep","outcome":"头一个月来了七拨人，笑到拍桌子。第二个月来了三拨，第三个月只有周三还来。你没扔，用布包好放在柜子顶上。后来谁失恋了，谁家里出了事，你就把瓶拿下来，让人听一遍。听完的人都会说一句：这算什么。然后笑一下。你也笑。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"爱":2},"flag":"","thread":"柜子顶上那把折叠椅"}},{"title":"回去找他退货","desc":"你抱着瓶跑回夜市，摊子已经收了，只剩一地竹签。","hint":"你在港上转了一夜。","tone":"collect","outcome":"你问了七个摊主，都说那老头一个月只来一回，卖完就走。你在港上转到天亮，风从水面过来，衣服湿了一层。第二天你发烧，躺了三天，烧的时候一直听见有人说宝贝儿往左一点。退烧后你把瓶塞进床底，再没听过。钱也没要回来。","eff":{"bond":0,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":-1},"emotion":{"怒":3,"喜":1},"flag":"","thread":""}},{"title":"照着学那腔调","desc":"你把那段听了二十遍，学会了那种又软又急的口气。","hint":"你后来为此挨过一拳。","tone":"study","outcome":"你学得像，尤其是那声宝贝儿。跟人说话带上它，姑娘们笑，男的皱眉。有一回在码头你跟人抬杠，顺口来了一句，对方一拳打在你嘴上，破了皮。你捂着嘴，血从指缝里出来，忽然想起那把塌了的椅子，笑了一下。对方以为你在挑衅，又打了一拳。","eff":{"bond":-1,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":2},"emotion":{"喜":4,"怒":2},"flag":"","thread":""}}]},{"id":"sui2_s03","act":"side","age":[21,21],"mode":"narration","title":"霜降那晚","opening":"忆井广场的赎回窗口在负一层，冬天开暖气，甜味顺着通风口一阵阵往下掉。霜降那天，修鞋的老周准时来，蓝布围裙上沾着鞋油。他递进一张折成四折的纸，编号 C-0912，质押物写着：二十岁，初恋，全段。他每年赎一晚，第二天一早再押回去，像租一件衣裳。今年窗口换了新规矩，要验记忆龄做担保，他差两年。他把手在围裙上擦了两遍，说：小同志，就差一点。","ask":"他隔着窗口看你，你怎么办","days":15,"npc":"","memory":"编号C-0912","choices":[{"title":"拿自己的年限担保","desc":"你在担保栏签下自己的名字，抵两年记忆龄，让他进去。","hint":"你的档案上多了一道记录","tone":"protect","outcome":"他进去前把围裙解下来叠好，放在窗口台上。第二天天没亮他出来，眼睛肿着，把瓶子重新押了，押金刚好够他老婆一年的药。你那份担保跟着档案走，招考时被人事翻出来问过两回。他后来每年霜降还是来，见你就点一下头，从不多话。你不知道他还认不认得你的脸。","eff":{"bond":4,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":4},"flag":"guaranteed_zhou","thread":"你的档案上留了一道记录"}},{"title":"照新规关窗","desc":"你说差一年也不能赎，到点把铁帘拉下来，没抬头。","hint":"他在台阶上坐到天亮","tone":"rule","outcome":"铁帘落到底，外头没动静。第二天清早你开门，台阶上有一小堆瓜子壳，摆得整整齐齐。他老婆拎着饭盒来接他，两个人一前一后走了。年底清库，C-0912 到期无人续押，划进公共库，名字刮掉，编号留着。你后来在清单上看见它，手指在那行字上按了一下。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":2},"flag":"closed_on_zhou","thread":"C-0912 进了公共库"}},{"title":"跟他进听室","desc":"你说要登记，跟着进去，在隔间扣上第二副听膜。","hint":"你记住了别人初恋里的名字","tone":"greed","outcome":"里面是一个夏天的傍晚，一个姑娘骑车过来，车铃响了两下，喊了一个名字。西瓜切开的味道，蝉在叫。你摘了听膜，手心是湿的。他什么都不知道，第二天照旧把瓶子押回去。往后几年你听见有人叫那个名字，会回头。你从来没跟他提过那一晚，也没跟自己提过。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"欲":4,"哀":2},"flag":"listened_zhou_bottle","thread":"你记住了别人初恋里的名字"}}]},{"id":"sui2_s11","act":"side","age":[23,23],"mode":"narration","title":"给拿走夏天的人","opening":"二十三岁那年你在封存塔做临时工，活儿是给旧瓶换标签：揭下脆纸，写上新号，再蒙一层膜。五层没有窗，通风口一直响，甜味一阵一阵往下沉，落在舌根上发苦。老师傅说这一层都是死档，人早走了，瓶还在。你揭到第七排第十九格，封套里掉出一张纸，折成四折。信封上写：给拿走这个夏天的人。字歪，横画尾巴翘起来，是你自己的字。","ask":"信在你手里，你拿它怎么办","days":30,"npc":"","memory":"给拿走夏天的人","choices":[{"title":"照信上说的做","desc":"每年立秋买一支桂花冰，放在母亲窗台上。","hint":"转正推到了第三年","tone":"family","outcome":"信里只写了两件事：每年立秋给她买一支桂花冰；别让她知道你卖了什么。你照做。她坐在窗边吃，吃到木棍上只剩一点甜，问你哪来的，你说路上买的。为了每年那一天，你请假，转正推到第三年。她从没问过第二遍，也从没剩过一口。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"爱":4,"哀":3},"flag":"followed_old_letter","thread":"每年立秋那一支冰"}},{"title":"去查经手的人","desc":"你按瓶号查到当年的采集师，姓聂，写了报告。","hint":"他家里有个做透析的女儿","tone":"report","outcome":"查下来他压了三成价，也没提合同背面那行小字。报告交上去，他被吊销资格，走的那天在塔下等你，说：你做得对。他说家里有个女儿在做透析，说到这儿就不说了。你说了句对不起。往后每年冬天，他女儿都在塔下站一会儿，不见你，站到雾起来就走。","eff":{"bond":-2,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"reported_collector_nie","thread":"塔下每年冬天站着一个人"}},{"title":"原样封回去","desc":"你把信折回封套，塞进架子最里头，登记时写无。","hint":"你那年就转了正","tone":"keep","outcome":"登记本上那一格你写：附属物无。第二年你转了正，有了工号，进了三层那间没有窗的审计室。往后每到立秋，你嘴里就发苦，想不起为什么。有一年你跑遍全城的冷饮摊，问有没有桂花味的，摊主都摇头。你站在街口，觉得少了点什么，站了一会儿就回去了。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"refiled_letter","thread":"每年立秋嘴里发苦"}}]},{"id":"sui2_x10","act":"side","age":[24,24],"mode":"narration","title":"天台上的三分钟","opening":"停电是晚上八点来的，整栋楼的记忆防漏一起停，楼道黑得伸手不见五指，应急灯只亮了一颗，绿的一点。雾管不响了，空气里那股甜味忽然没了，闻着有点土腥，像下雨前的河滩。楼上有人敲盆，喊都上天台。你抱着凉席上去，水泥地还热，躺下能感觉白天晒进去的温度一层一层往背上贴。白婆婆也上来了，抱一只纸箱，箱里用棉布裹着十几只小瓶。她说这是她攒了三十年的甜记忆，一人一分钟，谁也别多占。楼下有人喊：带电的别带，带瓶的上来。白婆婆把箱子往你面前推了推，说：你先挑。","ask":"白婆婆让你先挑，你挑哪个","days":10,"npc":"","memory":"天台一人一分钟","choices":[{"title":"让别人先挑","desc":"你退到后头，把位置让给小孩和老人，自己最后。","hint":"她把最后那只塞进你口袋。","tone":"warm","outcome":"十几个人轮完，箱子里只剩一只，白婆婆塞进你口袋，说：这段没人要，太淡。你回屋才听：一个中午，蝉在叫，有人在井边洗头，水是温的。听完你把瓶还给她。她说：留着吧，我这记性，留着也是漏。你没推，收在抽屉里，一直没再听。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"","thread":"抽屉里那只太淡的"}},{"title":"问这些卖不卖","desc":"你问她这些瓶值多少钱，能不能卖给你一只。","hint":"她笑了一声，没答。","tone":"practical","outcome":"她笑了一声，说：你这孩子。她把箱子往怀里拢了拢，说这些不卖，都是我自己的，卖了我就没了。你脸上发热，坐回凉席上。后来她搬箱子上下楼，你每回都搭把手，一搭搭了三年。她走的那年，箱子里少了一只瓶，谁也不知道去了哪儿。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":""}},{"title":"把听膜给她","desc":"你把听膜扣到她耳朵上，让她听她自己攒的那段。","hint":"她说这人是谁。","tone":"heal","outcome":"她愣了一下，没摘。听完她说：这人是谁，声音这么年轻。又笑，说：像我。她把听膜摘下来，还给你，手在衣角上擦了擦，说：我攒了三十年，自己一遍没听过，怕听了就没了。那天晚上她睡得早，打呼打得很响，一栋楼都听见了。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":3},"flag":"","thread":""}}]},{"id":"sui2_s04","act":"side","age":[25,25],"mode":"dialogue","title":"漏雨的下午","opening":"阿棠的店在旧码头，屋顶漏，雨一大就往柜台上滴。她踩在凳子上补瓦，让你在底下扶。她穿一件洗白的褂子，袖口磨破了，抬手时露出一截腕子。她说：再往上一点。你扶着凳腿，手心出汗。她下来时踩空半格，你伸手，她抓住了，两个人都没说话。柜子底下压着一只瓶，标签朝里，只露出半截编号。外头雨停了，雾从门缝钻进来，有点甜。她拍拍手说：饿了，下面。","ask":"她背对着你烧水，你做什么","days":10,"npc":"friend","memory":"两碗面的早上","choices":[{"title":"替她守这一夜","desc":"你说锁坏了，抱一床旧毯睡在门内，让她上楼去。","hint":"第二天的考试你没去成","tone":"protect","outcome":"水泥地凉，夜里落了潮，你睡到一半听见她在楼上翻身。天亮她端两碗面下来，一碗多搁了葱，说：你打呼。你腰疼了半年，那年的资格考没去成，名额顺到第二年。她后来提过一次，说那晚要没你，柜子底下那只瓶就保不住了。你没问那瓶是谁的。","eff":{"bond":5,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"惧":1},"flag":"guarded_atang_shop","thread":"柜子底下那只瓶是谁的"}},{"title":"把话说明白","desc":"你叫住她说阿棠我想跟你过，话没说完她抬手打断。","hint":"她从此不让你留到打烊","tone":"confess","outcome":"她笑了一下，笑到一半收住，说：我这行当，早晚得卖自己一段，你别把自己搭进来。她蹲下去把柜底的瓶搬出来给你看，标签上是个女孩的名字，两年前死的，她一直没上交。她说：我留着它，是怕我哪天也卖。那天你们把面吃完，各自回去。往后她关门早了一刻钟。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"told_atang","thread":"她关店早了一刻钟"}},{"title":"夜里来修屋顶","desc":"你半夜拎着沥青和瓦片上房，把漏处补好，锁也换了。","hint":"她一直以为是房东修的","tone":"repair","outcome":"你补到后半夜，沥青滴在衣角上，正好盖住那三个字。她第二天照常开门，抬头看了看屋顶，说：怪了，不漏了。一月后她给你一只搪瓷缸，说房东倒是有良心。你说嗯。那件褂子上的沥青洗不掉，你穿了很多年，衣角那三个字只剩两个还看得清。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"她以为是房东修的"}}]},{"id":"sui2_x11","act":"side","age":[26,26],"mode":"narration","title":"相亲第九分钟","opening":"进审计室头一年，你一天要过二十段，多数是卖菜、修水管、孩子学走路，看着看着会走神，走完神再倒回去听漏掉的那几秒。这一段是婚介所送来的优质样本，说客户条件好，请核验成色。你扣上听膜。茶馆，下午，桌上有两杯茶，一杯没人动。男方四十来岁，穿灰夹克，开口先念了一首诗，是他自己写的，念到第三句把缱绻念成了遣倦。女方没说话。屏风后头有个老太太在嗑瓜子，嗑一颗说一句：这人不行。又说：牙黄。第九分钟，男方手机响了，他接起来说：妈，我在开会。","ask":"这份报告，你打算怎么落笔","days":15,"npc":"","memory":"妈，我在开会","choices":[{"title":"照实写，退回去","desc":"你在备注里写了样本不符，把整段退给婚介所。","hint":"科长知道是你审的。","tone":"rule","outcome":"退回去第三天，科里开会，科长坐在长桌那头，说话时一直没看你。散会他叫住你，问：那段你听了？你说听了。他说：诗写得怎么样。你说没听懂。他笑了一下，说：我也没听懂。后来他再没提过，年终评语里写你业务扎实。","eff":{"bond":-1,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"惧":2},"flag":"","thread":"年终评语那四个字"}},{"title":"改两处让它过","desc":"你把牙黄那句剪掉，把念错的字标成口音，签了名。","hint":"他后来提拔了你。","tone":"hide","outcome":"样本过了，婚介所送来一面锦旗。第二年科长升了，把你也带上去，工位挪到窗边。开会时他说话，你总忍不住看他的牙。有一回他问你：我牙上有东西？你说没有。他说：那你老看什么。你说灯光晃眼。他哦了一声，把窗帘拉上了。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"惧":2},"flag":"passed_chief_sample","thread":""}},{"title":"剪下第九分钟","desc":"你把那段单独拷了一份，揣进兜里，报告写无异常。","hint":"你成了唯一知情的人。","tone":"greed","outcome":"那三分钟你听了十几遍：妈，我在开会。后来科里聚餐，科长喝多了，说他妈去年走了，走之前一直以为他在开会。你说我知道。他抬头看你。你说我听说的。他点点头，又倒了一杯。那天晚上你没把那三分钟删掉，也没再听。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"欲":3,"喜":1},"flag":"","thread":""}}]},{"id":"sui2_x12","act":"side","age":[26,26],"mode":"narration","title":"雾里有人叫你","opening":"夜班到两点，你从塔里出来，雾已经涨到膝盖，走一步像蹚水。回住处要穿过三条巷子，路灯只亮一颗，光在雾里散成一团黄，什么也照不亮。甜味浓到发苦，贴在脸上像一层湿布，用手一抹，手上也是甜的。走到第二条巷子，你听见有人叫你的名字。声音从后头来，很近，像有人贴着你耳朵。你站住。又叫了一声，是你母亲的腔调，尾音往下掉。你没回头。第三声换了，是你自己的声音，在叫一个女孩的名字。你手心出汗，鞋底在湿地上打滑，前面巷口有个坑，去年掉下去过一个人。","ask":"雾里还在叫你的名字，你应不应","days":20,"npc":"","memory":"雾里叫的那三声","choices":[{"title":"应一声","desc":"你回头，说：我在。雾一下子就静了。","hint":"有三个月你想不起自己叫什么。","tone":"brave","outcome":"雾里没有东西。你站了一会儿，走回家，锁门，坐在床沿上。第二天上班，你在考勤表上写自己的名字，写到第二个字停了一下，像在挑哪个字对。这种停顿持续了三个月。三个月后的一天早上，你忽然想起那天晚上雾里那声是谁的，想起的同时，又忘了。","eff":{"bond":0,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":5,"哀":2},"flag":"answered_the_fog","thread":"你在考勤表上停了一下"}},{"title":"捂耳朵快走","desc":"你捂住耳朵，低着头往前走，脚底打滑也不停。","hint":"到家发现少了一只鞋。","tone":"escape","outcome":"你一路走回家，进门才低头看，左脚只剩袜子，袜底磨穿了一个洞。你锁上门，把椅子顶在门后，坐到天亮。第二天回去找，巷子里什么都没有，连那个坑都填平了。从此你绕远路，宁可多走二十分钟。有人问你怎么不走近道，你说那边雾大。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"喜":1},"flag":"","thread":""}},{"title":"站着听清是谁","desc":"你不走了，靠在墙上，闭着眼听那声音到底像谁。","hint":"你听出了十六岁的自己。","tone":"seek","outcome":"第三遍你听清了，那是你十六岁的声音，在叫一个女孩的名字。那女孩姓什么你想不起来，只记得她骑车，车铃响两下。声音叫了七遍，越来越远，最后散在雾里。你在墙边站到天亮，衣服湿透，回家烧了两天。退烧后你想起那个女孩姓周，别的还是想不起来。","eff":{"bond":0,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"欲":2},"flag":"","thread":""}}]},{"id":"sui2_x13","act":"side","age":[28,28],"mode":"narration","title":"整排都错了","opening":"老太太来赎她女儿说的第一个字。手帕包着瓶，一层一层打开，标签是旧的：第一个字·妈。她递进来的时候手在抖，说攒了二十年。你扣上听膜，放出来的是一个年轻人的声音，在喊一二一，接着是脚步声，然后有人放了个屁，全班笑，教官骂人。你摘了听膜。老太太看着你的脸，说：是不是丫头不肯叫妈。你翻出库档，一查，那一整排三十七只瓶的标签，二十年前被一个上夜班的临时工换过，说是闹着玩。规程写着：更正需经三部门复核、重做鉴定、缴纳工本费；申请表一式十二份，其中一份要贴在瓶子原处。表在第七个抽屉里，抽屉的钥匙在第八个抽屉里，第八个抽屉锁着。没人改过。","ask":"瓶里不是她女儿，你怎么说","days":60,"npc":"","memory":"第一个字·妈","choices":[{"title":"照实说，帮她查","desc":"你把听膜递给她，说这瓶不对，我去给你查原件。","hint":"查了十一个月，她没等到。","tone":"honest","outcome":"她听完没说话，把瓶重新包好，说那就查。你跑了十一个月，签了六个字，最后在一只没编号的箱子里找到她的瓶。批文下来那天，她女儿来退手续，说人上个月走了。她把那只瓶带走了，没听。你在窗口坐了一下午，把那张批文折成四折，塞进抽屉。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":2},"flag":"","thread":"抽屉里那张批文"}},{"title":"先不说，让她听","desc":"你说对了，就是这句，把音量调大，让她听完。","hint":"她每月都来听她女儿。","tone":"keep","outcome":"她听完，说：这丫头，嗓子这么粗。第二个月她又来，说想再听一遍。你从架子上把瓶找出来，扣上听膜。她一共来了十一次，最后一次是坐着轮椅来的。她跟护工说：我闺女在里头喊一二一，当兵去了。护工看了你一眼。你点头，说是。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":""}},{"title":"把那排全改了","desc":"你夜里留下，按旧档一只一只对，改了三十七张签。","hint":"你被记过一次。","tone":"repair","outcome":"改到天亮，三十七只瓶归了位，有六只对不上人，你单独列了一张单子。主任把你叫去，说这事该走程序，记了一次过，扣了半年配给。可那排架子从此是对的。后来有个男人来赎他父亲的呼噜声，找到了。他听完说：就是这个，吵得我小时候睡不着。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"爱":2},"flag":"fixed_the_shelf","thread":""}}]},{"id":"sui2_s05","act":"side","age":[29,29],"mode":"narration","title":"忘礼","opening":"忘礼在净忆局二楼办。屋子小，两把椅子对着放，中间一张长桌，桌上排着一列瓶，一年一瓶，瓶身用白笔写着年份，瓶底都刻着编号，一个挨一个。墙上贴着规程：逐段剥离，不得跳段，末瓶封存。何女士先坐下，手袋放在膝上。方先生站着，等你说开始。第一瓶是他们结婚那年，瓶口漏出一点甜味，像放过糖的水。最末一只没写年份，只写一个囡字。","ask":"两个人都看着你，你先做什么","days":20,"npc":"","memory":"末瓶上写一个囡","choices":[{"title":"照着单子剥","desc":"你按年份一瓶一瓶念，念完一瓶剥一瓶，中间不停。","hint":"她让你替她记着顺序","tone":"rule","outcome":"剥到第七瓶，何女士说停一下，方先生说继续。你看了看规程，继续。最后一只封进铅盒，登记，盖章。两个人一前一后出门，谁也没等谁。她在门口回头，说：同志，顺序你替我记着。你点头。那张单子你收在抽屉里，很多年没扔，也没再打开。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"conducted_wangli","thread":"她让你替她记着顺序"}},{"title":"先放一遍再剥","desc":"你说规程没禁听，把每只瓶放一遍，让他们自己喊停。","hint":"你的记录上写了程序不当","tone":"peace","outcome":"放到第三瓶，两个人一起笑了，笑完都不说话。放到第七瓶，何女士伸手过去，方先生把手放在她手背上。他们说今天就到这儿。上司扣了你半月配给，记录上写着程序不当。两年后他们又来，把剩下的剥完，坐得比上回近。他们没点名要你，你也没过去。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"delayed_wangli","thread":"他们两年后又来了一趟"}},{"title":"换下最后那只","desc":"你把囡字那瓶揣进外套，换上一只空瓶，登记封存。","hint":"她后来回来问过一句","tone":"keep","outcome":"前一晚方先生在楼梯间塞给你一张纸条，四个字：留着，别剥。瓶子贴着肋骨，走路时一下一下撞。三个月后何女士一个人回来，站在窗口问：那天有没有剩下什么。你说没有。她站了一会儿，说：那就好。她走进雾里。那只瓶一直在你柜子最里头，你没听过。","eff":{"bond":0,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"kept_nv_bottle","thread":"柜子最里头那只囡字瓶"}}]},{"id":"sui2_s12","act":"side","age":[30,30],"mode":"dialogue","title":"摘牌那天","opening":"阿棠的店在旧码头，门口那块木牌挂了六年，漆掉了一半，还认得清五个字：不收记忆。关店那天落雨，屋顶是新补的，一滴不漏。她站在凳子上把牌子摘下来，让你在底下接。架子上的瓶一只一只取下来擦，标签朝外，编号都用白笔描过一遍。擦到最底下一格，她的手停了停，说：柜底那只，我上个月卖了。她说得很轻，像说别人的事。屋里甜味重，雨在外头，她把抹布绞了两遍。","ask":"她说卖都卖了，你怎么接话","days":15,"npc":"friend","memory":"摘下来的木牌","choices":[{"title":"去把那瓶赎回来","desc":"你按她说的买家找过去，把攒了七年的钱全推上桌。","hint":"你的号又远了一截","tone":"protect","outcome":"买家是个开私人柜的，验过你的记忆龄才让你进门。瓶拿回来，编号还在，玻璃上多了一道新划痕。你不敢给阿棠，把它塞进缝纫机的抽屉，跟母亲的针盒挨着。她问过一回赎回来没有，你说没有。你攒的年限空了，B-1147 的价那年又涨了一轮。","eff":{"bond":3,"health":-1,"reputation":0,"coins":-200,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"redeemed_atang_bottle","thread":"抽屉里那只瓶不是你的"}},{"title":"陪她去登记","desc":"你说服她去净忆局把这一单如实登记，罚轻些。","hint":"木牌被摘了，店还在","tone":"rule","outcome":"罚了三年配给，资格降一级，那块木牌被摘走，说是不合规程。她站在门口看他们摘，没拦。回去的路上她说：你不该这样。可每年冬天她还是给你留一碗面，面里多搁半勺猪油。她再没提过柜底那只瓶，也没再上过二楼。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"registered_atang_sale","thread":"她每年冬天留一碗面"}},{"title":"接过钥匙开门","desc":"你什么也不问，接过钥匙，第二天照常把门打开。","hint":"三个月后她回来买瓶","tone":"keep","outcome":"你把货架擦了一遍，把牌子的漆补上，字照旧。她三个月后回来，站在门口看那块牌，问：这店卖什么。你说卖瓶。她说：那给我一段开店的下午。你在架上找了一只别人的下午卖给她，她听完说：这店不错。她走的时候没回头，你听见雨点落在新补的瓦上。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"惧":2},"flag":"sold_atang_a_fake","thread":"她听过一个假的下午"}}]},{"id":"sui2_x14","act":"side","age":[30,30],"mode":"narration","title":"凌晨两点十七分","opening":"复核是例行公事，一天三十份，看数字对不对，多数看一眼就过。你翻到第十七份，停住。那个单亲母亲的记忆龄比规定少两年，差两年就要强制封忆，孩子送寄养层。她的档案上盖过两个拒签的蓝印，一次是去年，一次是前年。修改记录显示凌晨两点十七分，登录号是老陈的。老陈在你对面坐了六年，搪瓷缸掉了一块瓷，他喝水总从缺口那边喝，说这样不烫嘴。他今天请假，说孩子发烧，走的时候把缸子留在了桌上。科长把这份推给你，说：你再看一遍，没问题我就签。打印机在角落里响，一张一张往外吐，吐到地上也没人捡。","ask":"登录号是他的，你打算怎么做","days":20,"npc":"","memory":"凌晨两点十七分","choices":[{"title":"去跟科长认下来","desc":"你说那一格是你改的，老陈那晚把号借给了你。","hint":"停职半年，老陈不跟你说话。","tone":"brave","outcome":"科长看了你很久，说：你知道这是什么性质。你说知道。停职通知贴在公告栏上，配给扣了半年。老陈回来那天，在食堂端着缸子站了一会儿，没坐你对面。后来他托人送来一条烟，你退回去了。他再没跟你提过那件事，你也再没跟他提过。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"took_blame_for_chen","thread":"他再没坐你对面"}},{"title":"去问他本人","desc":"你下班骑车去他家，把复印件摊在他家饭桌上。","hint":"他说你报吧。","tone":"honest","outcome":"他孩子在里屋睡着，桌上有一碗没动的粥。他看完，说：你报吧。你说为什么。他说那女人上个月来找过他，带着孩子，孩子鞋底是开的。他把粥推给你，说凉了。你第二天报了。他被开除，走的时候把搪瓷缸留在桌上。缸子里还有半缸水。","eff":{"bond":-1,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"reported_chen","thread":""}},{"title":"把数字改回去","desc":"你照原样改回两年，签名，推给科长。","hint":"母子当天就被带走了。","tone":"rule","outcome":"科长签了字，说这才对。第三天车来了，母亲被带走做强制封忆，孩子在楼下哭，被一个穿灰衣服的抱上车。老陈回来上班，看了你一眼，什么也没说。中午食堂人多，他端着缸子走到另一头坐下，背对着你。你们从此再没一起吃过饭。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"reverted_chen_edit","thread":""}}]},{"id":"sui2_x15","act":"side","age":[33,33],"mode":"narration","title":"三小时","opening":"跳闸是晚上十一点四十。备用电源只带得动照明和门禁，冷凝泵停了。五层三千多只瓶，玻璃上很快起了一层水珠，那是髓云在出汗，出了汗就分层，分过层的记忆救不回来。你摸到应急灯，摸到墙角的手摇泵。泵一次只能带一排架子，摇起来要人，一分钟四十转。铁门从外头锁了，对讲机没声，空气里一股氨味，是从管子接头漏出来的，呛得眼睛发酸。温度计指着十九度，还在往上爬。你手心磨破了，握摇柄打滑。两排架子，一排公共库，一排私人寄售。","ask":"泵只能带一排，你先带哪一排","days":10,"npc":"","memory":"玻璃上的水珠","choices":[{"title":"带私人寄售那排","desc":"你把泵接到寄售架，摇到天亮，别的架子不管。","hint":"公共库坏了四十瓶。","tone":"protect","outcome":"那排里有十一只瓶标着童年，最小的一只写着三岁·整年。你摇到凌晨三点，胳膊没了知觉。电来的时候，公共库坏了四十瓶，调查报告上写了你的名字，说处置失当。你签了字。那只三岁·整年后来被人赎走了，赎的人不知道那晚有人为它摇过一夜。","eff":{"bond":2,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":2},"emotion":{"爱":3,"惧":3},"flag":"saved_consignment","thread":"报告上你的名字"}},{"title":"带公共库那排","desc":"你把泵接到公共库，按规程先保公用财产。","hint":"一个孩子的整段童年化了。","tone":"rule","outcome":"你摇了一个钟头，公共库保住了大半。私人寄售那排没人管，第二天开门，最上头一格的瓶子塌了，玻璃里剩一层白浆，标签写着童年·七岁至十二岁。家长来的时候站在那格前面，没哭也没闹，问：还能听吗。你说不能。他说：哦。他把手贴在玻璃上，贴了一会儿。","eff":{"bond":-2,"health":-2,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"哀":5,"恶":1},"flag":"","thread":""}},{"title":"两边轮着摇","desc":"你十分钟换一次管子，两边都带，摇到手腕发麻。","hint":"两边都只保住一半。","tone":"grind","outcome":"你来回换管子，换到第七次，接头崩了，氨水喷在手上，烫出一片红。你接着摇，摇到天亮，握摇柄靠的是腕子。电来的时候两边各坏了一半。你在医务室包了半个月，主任说你这人不会算账。你说我知道。后来那两排架子你每次经过都要看一眼，像能认出少了哪些。","eff":{"bond":1,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"惧":3,"哀":3},"flag":"","thread":""}}]},{"id":"sui2_s06","act":"side","age":[38,38],"mode":"narration","title":"出质人一栏","opening":"走廊那头的库房在销毁旧瓶，甜味从门缝渗进来。审计室在封存塔三层，没有窗。新到一批旧合同要录进系统，纸都发脆，翻页得用竹片。你翻到第七份，手停住。出质人一栏写着：柳素云。质押物一栏是：儿子第一天上小学，全段，含晨光与气味层。日期是你七岁那年九月。背面有一行小字：用于学杂费与一只蓝布书包。你把纸举到灯下，签名旁边有一点褪色的红，是手印。","ask":"这张纸在你手里，你先做什么","days":60,"npc":"","memory":"出质人柳素云","choices":[{"title":"把这一份抽出来","desc":"你把那份合同折成四折，塞进外套内袋，没进系统。","hint":"老陈替你去守了地下室","tone":"hide","outcome":"那批合同少了七页，对不上号。老陈被叫去问了三回，后来调去地下室理旧档，走那天把搪瓷缸留给你。合同在你内袋里放了一个月，又挪进缝纫机的抽屉，跟针盒挨着。你每次开抽屉都听见纸响。老陈后来在楼下遇见你，还点头，你也点头，两个人都没停。","eff":{"bond":0,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"恶":2},"flag":"hid_mother_contract","thread":"老陈替你去了地下室"}},{"title":"拿着它去问她","desc":"你把复印件摊在饭桌上，指着出质人那三个字。","hint":"她不再让你替她梳头","tone":"honest","outcome":"她看了很久，说这不是我写的。你把纸翻过去，让她看那个手印。她把手缩回袖子里，问：阿砚是谁。你说是我。她说：我儿子才八岁，他一会儿放学。她把纸叠得整整齐齐，推回你面前，说：你走吧，门带上。第二天她隔着门说头发自己梳过了。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"怒":2},"flag":"showed_mother_contract","thread":"她开始自己梳头"}},{"title":"把整批都调出来","desc":"你按她的名字检索，一共十一份，一段一段往下看。","hint":"你只赎得起两段","tone":"seek","outcome":"十一份，从你七岁到你十六岁：第一天上学、第一次换牙、学骑车、肺炎那年。你攒的钱只够赎两段。你挑了第一天上学，回家放给她听。她听完说：书包是蓝的，上头有只鸭子。你一直以为是灰的。剩下九份还压在库里，年年涨。你从此不敢算总数。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":5},"flag":"found_eleven_contracts","thread":"还有九段压在库里"}}]},{"id":"sui2_x16","act":"side","age":[38,38],"mode":"narration","title":"买一场雨","opening":"男孩是下午进来的，背着书包，把一只铁皮盒放在柜台上，倒出一堆硬币，一角的、五角的，还有三枚游戏币，滚到柜台边上停住。他说他要买雨。他说话很轻，尾音听不见，得看着他的嘴。他耳朵上有一只旧的听觉移植，外机用胶布缠过，胶布已经发黄。他说他生下来听不见，九岁才装上这个，只听得见低的声音——车、鼓、打雷。雨是低的。你在架子上找，找到一只标签发黄的：雨·屋檐·六月，十一分钟。你把瓶放在柜台上。他把硬币一枚一枚数好，数到最后一枚，抬头看你。","ask":"他把硬币数完了，你怎么办","days":30,"npc":"","memory":"雨是低的声音","choices":[{"title":"收钱，放最响的","desc":"你数了钱，把瓶接到最大的喇叭上，让他贴着听。","hint":"你少收了他一半。","tone":"warm","outcome":"他把耳朵贴在喇叭上，手也贴上去，手指跟着雨点动。听完他说：像有人在楼上走。你说对，就是楼上。他笑了，说明天还来。他来了一个月，每回都带硬币，你每回都少收一半。后来他改带别的东西：一张画、一只瓶盖、一颗玻璃弹子。你都收在抽屉里。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":3},"flag":"","thread":"抽屉里的玻璃弹子"}},{"title":"不收钱，让他摸瓶","desc":"你把钱推回去，把瓶放在他手心里，让他自己转。","hint":"店里的账上少一笔。","tone":"heal","outcome":"他捧着瓶，转一下，停一下，像在称重量。他说：这里头有水。你说有。他说：水在动。他说对了，那段里有人在泼水。你破了自己定的规矩——听瓶要付钱。月底盘账，那一格是空的。你补上了，没跟任何人说。后来你学会了看人怎么听：有人用耳朵，有人用手。","eff":{"bond":3,"health":0,"reputation":-1,"coins":-10,"stats":{"智识":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":""}},{"title":"带他上屋顶","desc":"你看天要下雨，关了店，带他爬到楼顶去等。","hint":"回来时门口排了五个人。","tone":"escort","outcome":"你们在楼顶坐了一个钟头，云压得低，风是凉的。雨下来的时候他站起来，张开手，仰着脸。他说：比瓶里的大。你说那当然。他问：瓶里的雨是谁的。你说不知道。他说：那他也在屋顶上吗。你说大概吧。回到店里，门口排了五个人，有人骂了一句，你赔了三只试听。","eff":{"bond":4,"health":0,"reputation":0,"coins":-20,"stats":{"体魄":1},"emotion":{"爱":5,"喜":2},"flag":"","thread":""}}]},{"id":"sui2_s13","act":"side","age":[40,40],"mode":"narration","title":"走廊上的硬币","opening":"四十岁那年秋天，审计室来了个姓霍的女人，灰呢外套，手袋的铜扣开了又扣，扣了十七八回。她要办的是童年全段清除，对象是她十岁的儿子。她说：他记得不该记的事。材料袋里一只瓶，编号 G-3088，标签上写着：童年，十岁，含父层。按规程，十二岁以下要当面做意愿确认。孩子被带来，坐在走廊长凳上，两只鞋来回蹭地，手里转一枚旧硬币，转一下，接住，再转。","ask":"孩子抬起头看你，你先问什么","days":20,"npc":"","memory":"G-3088 那只瓶","choices":[{"title":"改成封存待成年","desc":"你在系统里改了这一格，责任栏签上自己的名字。","hint":"你被停职半年","tone":"protect","outcome":"她被叫去谈了三回，最后签字同意。孩子在走廊上把那枚硬币放在你桌上，说：这个给你。你被停职半年，复职后调去地下室理旧档，工号后面加了一个字母。八年后那孩子满十八，来窗口办过一次手续，没认出你，只问：这儿以前是不是有个姓沈的。你说有。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"sealed_boyhood","thread":"桌上那枚不是你的硬币"}},{"title":"把他的话说进去","desc":"你把孩子那句我不想忘写进确认书，按了手印。","hint":"他被送去了寄养层","tone":"report","outcome":"未成年人保护科当天来了人。他母亲在楼下骂了半个钟头，最后被两个穿灰衣服的带走问话。孩子上车前回头问你：是不是我做错了。你说不是。他点头，硬币攥得很紧。后来你查过他的档案，转学三次，十八岁那年自己申请改了姓。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":3},"flag":"reported_huo_child","thread":"他问过是不是自己做错了"}},{"title":"签字收下那笔钱","desc":"你在清除单上签了字，把那一段标成自然衰减。","hint":"母亲三年延缓的钱有了","tone":"greed","outcome":"钱到账那天你去交了母亲三年的延缓费，收据折好放进铁盒。孩子没有再来过。第二年春天你在街上看见他们母子，孩子牵着她的手，叫得很顺口。你站在卖冰的摊子前，站得有点久，摊主问你要什么，你说不上来。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":150,"stats":{"机缘":1},"emotion":{"喜":2,"恶":3},"flag":"deleted_huo_childhood","thread":"街口那个卖冰的摊子"}}]},{"id":"sui2_x17","act":"side","age":[42,42],"mode":"dialogue","title":"那场婚礼","opening":"先是卖鱼的说的。他说那天他坐第三桌，新娘穿蓝旗袍，敬酒敬到他这儿，他还说了句吉利话。卖豆腐的说你坐第五桌，我坐第七桌，我那边上的甜汤洒了。两个人吵起来，吵到把秤都掀了，秤砣滚进沟里，谁也不去捡。后来整条街都在说这场婚礼，说老糖厂的厂房，说门口的两棵梧桐，说有人放了一挂鞭把裤子崩了个洞。有人翻出旧照片，照片上没有婚礼，也没人管，照片传了一圈又传回来，边角起了毛。晚上你回家，母亲正在择菜，抬头说：那天我穿的是蓝褂子。","ask":"母亲说她也去了，你怎么接","days":40,"npc":"mother","memory":"蓝褂子和甜汤","choices":[{"title":"顺着她往下问","desc":"你问她坐哪桌，跟谁去的，她说什么你都点头。","hint":"她讲了一个钟头。","tone":"obey","outcome":"她说她坐靠门那桌，旁边是个戴眼镜的，把甜汤洒了。她说新娘是她远房表妹，姓什么想不起来。她讲了一个钟头，讲到新郎给她敬酒，说这杯得喝。她端起自己的茶杯，比了一下，喝了。你看着她，忽然想不起她年轻时穿没穿过蓝褂子。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":3},"flag":"","thread":"她讲了一个钟头"}},{"title":"说这婚礼不存在","desc":"你告诉她这是记忆瘟疫，全街都记错了，别当真。","hint":"她把菜篮子放下了。","tone":"honest","outcome":"她停下手，说：怎么会不存在，我去了。你说医生说了，这是瘟疫，过一阵就忘。她把菜篮子放在地上，说：那我记着干什么。那天晚饭她没吃。一个月后瘟疫过去了，街上没人再提婚礼，她却还在念叨那碗甜汤，念了半年，念到自己也说不清有没有去过。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"喜":2,"哀":2},"flag":"","thread":""}},{"title":"去街上补办一场","desc":"你找了几个闲人，在空地上摆桌，真办了一场。","hint":"你熬了一夜的甜汤。","tone":"warm","outcome":"桌是从各家搬来的，长短不一。甜汤熬了一夜，糊了锅底，捞出来还是甜的。街上来了六十多口人，把最像新娘的刘家老太太按在主位上。有人放了一挂鞭，把裤子崩了个洞。母亲穿了件蓝褂子来，坐在靠门那桌。那天没人提这是假的。散场时地上全是瓜子壳。","eff":{"bond":4,"health":-1,"reputation":2,"coins":-30,"stats":{"魅力":1},"emotion":{"喜":5,"爱":3},"flag":"","thread":""}}]},{"id":"sui2_x18","act":"side","age":[45,45],"mode":"narration","title":"每年短一分钟","opening":"她每年这天来，穿灰外套，头发一年比一年白，来的时候总先在外头站一会儿，把手里的布袋换个手。瓶是老瓶，瓶身有一道划痕，标签上是她丈夫的名字。里面是三分钟：他在厨房切葱，哼一支歌，切到一半回头叫她的小名。你替她扣上听膜，她把手放在柜台上，手指跟着那支歌的拍子动，动到第三个音就停。听完她摘下来，说：今年还剩几分钟。去年是四分钟，前年是五分钟。这瓶子每放一次就薄一层，谁也没办法。她问得很平静，像问今天的天气。","ask":"她问还剩几分钟，你说不说","days":20,"npc":"","memory":"切葱的那支歌","choices":[{"title":"照实说，三分钟","desc":"你说三分钟，把瓶擦干净，推回她手边。","hint":"她让你把她的讲述录下来。","tone":"honest","outcome":"她点点头，说：够了，够我记一年。她起身要走，又坐下，说：我讲一遍给你听，你替我录着，万一哪天没了。她讲了十一分钟，比他切的葱多得多：他走路有点外八，他怕打雷，他切葱切到手指也不吭声。录完她说：原来我记得这么多。第二年来，她听的是自己的。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":2},"flag":"recorded_her_story","thread":"那盘十一分钟的带子"}},{"title":"说还有十分钟","desc":"你骗她还有十分钟，把音量调大，让她慢慢听。","hint":"她听完说明年再来。","tone":"hide","outcome":"她听完，说：怎么这么短。你说瓶子老了都这样。她哦了一声，把瓶收进布袋，说：那我明年再来。她走以后你把瓶子举到灯下，底下那层白又厚了一点。你算了一下，按这个速度，还能撑四年。你没告诉她。第四年她没来，第五年来了个年轻人，说是她儿子。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"陪她一起听","desc":"你另取一副听膜扣上，跟她一起听那三分钟。","hint":"你后来常哼那支歌。","tone":"escort","outcome":"厨房很小，窗上有雾，他切葱切得慢，刀在案板上一下一下。她的小名被他叫出来的时候，她的手指在柜台上停了一下。听完她说：你也听见了。你说听见了。她说：那你替我记着。往后很多年，你在切葱的时候会不自觉地哼那支歌，哼到一半总想不起后面怎么走。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":""}}]},{"id":"sui2_x19","act":"side","age":[48,48],"mode":"narration","title":"幸福的一天","opening":"局里要拍一部宣传片，叫幸福市民的一天，从各科室抽人。你被抽中，因为脸干净，主任说的。拍摄那天来了五个人，反光板、灯、一根挑杆，电线在地上绕成一团，谁走过都要绊一下。导演让你在雾管前面笑，你笑了十七遍，他说不够真。让你买一个包子，咬一口，看镜头，你咬了二十三次，包子凉透了，最后那个直接吐在纸里。让你跟邻居打招呼，那个邻居是雇来的，一天三十块。有人在旁边往你脸上喷水，说这样有精神。拍到天黑，导演说：成了。收工前导演叫住你，说你这脸不上镜，签个字，我们换一张。","ask":"导演说要换脸，你签不签字","days":30,"npc":"","memory":"咬了二十三次","choices":[{"title":"签，拿补贴","desc":"你在同意书上签了字，领了补贴，回家睡了一天。","hint":"你妈指着屏幕说像你。","tone":"obey","outcome":"成片在忆井广场的大屏上放了半个月。你的脸被换成一个年轻人的，眉眼像你二十岁。母亲看了一会儿，说：这个人长得像你。你说像。她说：不是你吧。你说不是。她点点头，说那就好。你站在自己的脸底下，觉得站着有点多余。那年你把家里的相框都收进了柜子。","eff":{"bond":-1,"health":0,"reputation":1,"coins":40,"stats":{"魅力":1},"emotion":{"喜":3},"flag":"signed_face_swap","thread":"相框都收进了柜子"}},{"title":"不签，走人","desc":"你把胸牌摘下来放在桌上，说那我不拍了。","hint":"评优那年没你。","tone":"refuse","outcome":"导演愣了一下，说你这人怎么这样。你说我不习惯。你走出摄影棚，外头太阳很好，雾薄。那天的工钱没结。第二年评优，名单上少了你，主任说你把事情搞僵了。你笑笑。后来那部片子换了个人拍，脸没换，是个真笑的，笑起来牙不齐。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"怒":2},"flag":"","thread":""}},{"title":"要求重拍，用真脸","desc":"你说换脸就别拍，要拍就用我自己的脸，重来。","hint":"成片里你只出现四秒。","tone":"defy","outcome":"导演想了半天，说行，反正你也不上镜。重拍三天，你笑了三百多遍，脸僵了半个月。成片出来，你的镜头只剩四秒，还是个背影，在雾管前面走过去。母亲看完说：这个背影是你。你说对。她说：走得挺快。你说赶着上班。","eff":{"bond":1,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":4},"flag":"","thread":""}}]},{"id":"sui2_s07","act":"side","age":[49,49],"mode":"dialogue","title":"讲不通的下午","opening":"母亲七十一岁那年，耳朵还很好，先听出你上楼的脚步。缝纫机边上立着一只旧瓶，里头插着针。你带了一只铁盒，里头是那件外套的衣角、三张照片、一枚旧硬币，还有一张合同复印件。她给你倒糖水，自己那碗不放糖。你说：妈，你十七岁那年病过一场，后来忘了一些事。她点点头，说人老了都这样。你往下说，说你叫什么，说她给你缝过什么。她听得很有礼貌，像听一个上门修水管的人讲他自己的家。","ask":"她把糖罐盖上，你接着说什么","days":15,"npc":"mother","memory":"她那碗没放糖","choices":[{"title":"顺着她的话演","desc":"你说自己是阿砚的同事，他忙，让我来看看您。","hint":"每次去你都换个身份","tone":"obey","outcome":"她松了口气，从柜里翻出一件毛衣，说织小了，让我儿子穿，你带给他。你抱着毛衣回去，袖子只到你手腕。你穿了三天，第四天脱下来叠好放进柜子。下回去，她又问：你是哪个单位的。你说街道的。她说：街道的好。她伸手摸了摸你的手，说：怎么这么凉。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":4},"flag":"played_colleague","thread":"柜子里那件小毛衣"}},{"title":"把照片摊开","desc":"你把照片一张张摆上桌，指着上头的脸，一张一张认。","hint":"她开始把硬币藏起来","tone":"honest","outcome":"她一张一张看，看到第三张站起来，碰翻了碗，糖水流到桌沿往下滴。她说：你把我儿子怎么了。她走到门口喊邻居，声音很响。你退到楼道里，听见门在里面插上了。晚上社区打来电话问情况，你解释了半个钟头。第二天她把那枚硬币藏进米缸，你看见她藏，没说话。","eff":{"bond":-5,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":4},"flag":"frightened_mother","thread":"她把硬币藏进了米缸"}},{"title":"收好盒子明天来","desc":"你不说了，把桌上的糖水擦干净，说明天再来看您。","hint":"本子越记越厚","tone":"wait","outcome":"她问这盒子是谁的。你说是朋友的，先放这儿。她说放窗台上，别挡道。第二天你又来，从十七岁讲起，她还是听到八岁就停下。你开始记本子：今天讲到哪儿，她问了几遍。本子写到第四十页，她还在八岁。你翻回去看，发现自己也记不清十七岁那年的夏天了。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"爱":3},"flag":"keeps_visiting_log","thread":"本子写到第四十页"}}]},{"id":"sui2_x20","act":"side","age":[52,52],"mode":"narration","title":"门口那个人","opening":"会所是老楼改的，门口三级台阶，漆掉光了，露出底下的红砖。老顾坐在门槛上，盘腿，鞋是补过的，脚边放一只空瓶，瓶里什么都没有。他说那是他留给自己忘的，等他哪天想走了，就对着它把这一辈子倒一遍。净忆局的车停在巷口，下来三个人，拿着一沓文书。围观的人站了半条街，没人出声，有人端着一盆水站在门口，也没泼。文书念到一半，老顾说：我这一辈子没什么可交的。他三十年前就不登记了，靠替人抄经活着。你从这儿路过，身上还挂着审计员的牌子。领头的人走过来，伸手往旁边一拨，说：让开。","ask":"他让你让开，你让还是不让","days":20,"npc":"","memory":"门槛上的老人","choices":[{"title":"站在门口","desc":"你跨上台阶，站在他和那三个人中间，不走。","hint":"你被带走问了一夜。","tone":"brave","outcome":"有人拽你的胳膊，你抓着门框，漆蹭了满手。后来是片警来分开的。你被带走问了一夜，写了四份说明，资格停一年。老顾当天下午还是被带走了。三个月后他回来，人瘦了，见你就点一下头，手里提着一袋橘子，分了你两个。橘子皮很厚，剥了半天。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"哀":3},"flag":"stood_in_the_door","thread":"门框上的漆蹭了满手"}},{"title":"要求看文书","desc":"你伸手要那沓文书，一条一条看，问一句记一句。","hint":"你拖了二十分钟。","tone":"rule","outcome":"文书是齐的，签名、印章、日期都对。你一条一条问，问到第十条，领头的人看了看表。就这二十分钟，巷口来了几个会里的人，站在外圈，不出声。老顾被扶上车的时候朝你点了点头。车开走以后，你在台阶上坐下，把问过的十条在心里又过了一遍，一条也没记住。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}},{"title":"去叫联社的人","desc":"你跑出巷子，去两条街外叫记忆联社的记者。","hint":"第二天报纸上没登。","tone":"seek","outcome":"来了三个人，一个拿相机，一个拿本子，还有一个只是站着。他们拍了照，问了名，说回去写。第二天报纸上什么都没有，第三天上头登了一条取缔非法会所的公告，说安全隐患。会所的门被贴了封条。老顾再没回来。那个拿相机的人后来见了你，绕着走。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"怒":4,"哀":2},"flag":"","thread":""}}]},{"id":"sui2_s14","act":"side","age":[55,55],"mode":"dialogue","title":"同志，你找谁","opening":"她这些年认人有个次序：先摸手，再摸衣角，最后才抬眼。这天早上你提着菜上楼，敲门，她来开，手先伸过来，把你的手翻过来看了看，又捏了捏你的衣角，捏到那三个字磨剩的两个。她抬眼，看了很久，说：同志，你找谁。楼道里的灯闪了一下。她身后的小桌上立着一只瓶，里头插着针；甜味从厨房飘出来，是糖水滚了的味道。","ask":"她的手还搭在门上，你怎么办","days":30,"npc":"mother","memory":"她问同志你找谁","choices":[{"title":"带她回老屋","desc":"你请了长假，把她带回城最底下那层的老房子。","hint":"岗位让人顶了","tone":"family","outcome":"老屋还在，窗台上有她磨出来的一个凹。你把她按在缝纫机前坐下，她的手自己去找踏板，踩了两下。傍晚她忽然叫了一声阿砚，就一声，接着问你晚饭吃什么。回城以后她又忘了。你的岗位让人顶了，回去做临时工。那一声你记了很多年，越记越不敢确定。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":5,"哀":4},"flag":"took_mother_home","thread":"那一声越记越不敢确定"}},{"title":"办记忆龄重定","desc":"你带她去窗口重定记忆龄，从此她归你监护。","hint":"她的市民证被收走了","tone":"practical","outcome":"排了一上午，签字，按印，她的市民证被收走，档案上盖了一个蓝印。配给、吃药、挂号都顺了，你也不用再跟人解释你是谁。她坐在大厅长椅上，把那张表格折成一只小船，折得很整齐，放在膝盖上，一直坐到叫号。回家路上她问你：船什么时候开。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"guardianship_mother","thread":"她膝盖上那只纸船"}},{"title":"在表上写无亲属","desc":"你在养老层的登记表上写下无亲属，把地址留了。","hint":"你从侧门进去看她","tone":"distance","outcome":"写完那一栏，笔尖在纸上顿住，留下一个墨点。她住进去第三个月就不再问门口是谁。你每月去看一次，从侧门进，坐在她对面削一个苹果，皮不断。她吃得很慢，吃完说：谢谢你啊，小伙子。护工说她记性其实不错，就是不肯说自己姓什么。","eff":{"bond":-4,"health":1,"reputation":-1,"coins":0,"stats":{},"emotion":{"哀":6,"惧":2},"flag":"no_kin_form","thread":"她不肯说自己姓什么"}}]},{"id":"sui2_x21","act":"side","age":[56,56],"mode":"narration","title":"听瓶会","opening":"听瓶会是退休的人凑的，每周三下午，活动室，折叠椅，暖瓶，一地瓜子壳，散场时扫出来半簸箕。规矩有三条：只听好笑的，不听悲伤的；一段不超过五分钟；谁带来的段子让大家笑得最响，下回不用带。这周三的段子有：一个男人在澡堂滑倒，爬起来先看有没有人；一个人把盐当糖，给客人冲了一碗，客人喝完说好喝；一个人对着镜子练我爱你，练了四十遍，被儿子听见；一只鹦鹉学人打呼，学了三年，学得比人响。屋里笑得椅子腿刮地。轮到你了，你手里空着。","ask":"轮到你带一段，你带哪一段","days":20,"npc":"","memory":"一屋子人都笑","choices":[{"title":"带自己最丢人的","desc":"你说你相亲那天，把人家姑娘叫成了前一个的名字。","hint":"你成了叫错名字的那个。","tone":"honest","outcome":"屋里静了一秒，然后笑得比刚才都响。有人拍桌子，茶水洒了。有人说再来一遍，你就再说一遍，说到第五遍自己也开始笑。散场时一个老太太说：你这人实在。从此会里都叫你叫错名字的。那件事你藏了二十六年，说出来只用了三分钟。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":2},"emotion":{"喜":5,"爱":2},"flag":"","thread":"会里都叫你叫错名字的"}},{"title":"花钱买一段","desc":"你出门左拐，在摊上花两角钱买了一段别人的糗事。","hint":"有人追问是谁的。","tone":"pay","outcome":"那段是一个男人在婚礼上把戒指掉进了汤里，捞了半个钟头。屋里笑翻了，有人问是谁的。你说不知道，买的。第二天有人去摊上问，摊主说卖出去好几份。会里为这个定了新规矩：买来的段子不算。你下回还得带。","eff":{"bond":0,"health":0,"reputation":-1,"coins":-5,"stats":{"机缘":1},"emotion":{"喜":4,"惧":1},"flag":"","thread":""}},{"title":"什么也不带","desc":"你说没准备，坐着听了一下午，笑得最响。","hint":"散场时没人跟你说话。","tone":"alone","outcome":"你笑得比谁都响，笑到咳嗽，有人给你捶背。散场时大家收拾椅子，你帮着摞，摞完了站在门口，没人叫你一起走。你一个人走回家，路上还在想那只鹦鹉。到家开门，屋里是黑的，你把灯拉着，站在门口又笑了一声。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"喜":5},"flag":"","thread":""}}]},{"id":"sui2_x22","act":"side","age":[60,60],"mode":"narration","title":"最后一瓶","opening":"老人是上午来的，蓝布褂，手背上生着斑，一只瓶用旧报纸包着，报纸是十年前的，日期还看得清。他坐下时膝盖响了一声。他说他卖最后一样。四十年里他把妻子的、女儿的、故乡的、手艺的，一段一段卖了，柜子一格一格空下来，现在夜里翻身，脑子里是空的，连做梦都没有材料。剩这一段：他母亲在井边洗头，太阳很好，水是温的，她拧头发的时候水珠落在脚背上。他说完把瓶推过来，说：你买了，会不会听。他说得很慢，一句和一句之间要停一停，像在数还剩几个字。","ask":"他把瓶子推过来，你接不接","days":30,"npc":"","memory":"井台边上的水珠","choices":[{"title":"买下，当他的面听","desc":"你数了钱，扣上听膜，坐在他对面，从头听到尾。","hint":"他问你这像不像。","tone":"warm","outcome":"井台是石头的，边上有一道裂缝。他母亲把头发拧干，甩了一下，水珠落在脚背上。听完你摘了听膜，说像。他问：像什么。你说像夏天。他点点头，把脸转向窗户，坐了很久。走的时候他把报纸叠好带走，说这个不卖。你后来把瓶摆在架子最上层，标了非卖。","eff":{"bond":3,"health":0,"reputation":1,"coins":-80,"stats":{"魅力":1},"emotion":{"爱":3,"哀":4},"flag":"bought_last_bottle","thread":"架子最上层那只非卖"}},{"title":"劝他留着","desc":"你把瓶推回去，说这段您自己留着，别卖。","hint":"他说留着给谁。","tone":"refuse","outcome":"他看着瓶子，说：留着给谁。我闺女不认我，我老婆的名字我都想不起来。他说这话时很平静。你把瓶收下了，钱照付，标签写成寄存，不写收购。他每月来听一回，听到第七回没再来。养老层的人来退瓶，说他走了，东西没人领。你把瓶留在架子上，没动。","eff":{"bond":2,"health":0,"reputation":0,"coins":-60,"stats":{},"emotion":{"哀":5,"爱":2},"flag":"","thread":""}},{"title":"问他女儿在哪","desc":"你问他闺女住哪儿，说这段该让她听。","hint":"她说这不是她爸的声音。","tone":"seek","outcome":"他报了一个地址，说得很快，像背过很多遍。你找过去，开门的是个五十来岁的女人。你放了瓶，她听了两遍，说：这不是我爸的声音。你说就是他。她摇头，说：我爸说话不是这样。她把瓶还给你，关门前说了一句：他要是还记得我，让他自己来。他没有来。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":2},"flag":"","thread":""}}]},{"id":"sui2_x23","act":"side","age":[65,65],"mode":"narration","title":"讲瓶的人","opening":"养老层在城的边上，走廊长，消毒水味压不住底下的甜。每周四下午你去讲瓶。听的人坐在折叠床边，一排六个，有的流口水，有的从头笑到尾，有的睡着了，醒来问你讲到哪儿，你就从头再讲。他们的听膜大多坏了，配给也不够，一只瓶听三遍就薄了。你就先在自己家里听一遍，记住，再来讲给他们听。你讲的时候带一块湿毛巾，谁的手干了就给擦一擦。你讲得比瓶里多，添油加醋，多加了一阵风、一声狗叫、一个站在门口不说话的人。他们爱听添过醋的。这天靠窗那个老太太拉住你的袖子，说：讲个海吧。","ask":"她让你讲海，你讲还是不讲","days":30,"npc":"","memory":"添过醋的那个海","choices":[{"title":"编一个海给她","desc":"你没见过海，就照着河编，加风、加咸味、加船。","hint":"整条走廊都要听海。","tone":"warm","outcome":"你讲了一个下午：水是灰的，浪一层一层推上来，滩上有一只鞋，没人捡。她听完说：我见过，就是这样。旁边的老头说他也见过。第二个礼拜，六个人都要听海。你编了六个版本，越编越远，编到有一年你自己都信了。你在纸上记下哪一版讲过，怕重了。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"爱":4,"喜":3},"flag":"","thread":"纸上记着六个版本的海"}},{"title":"说没听过海的瓶","desc":"你老实说没有海的瓶，只有河，问河行不行。","hint":"她转过脸去。","tone":"honest","outcome":"她哦了一声，把脸转向窗户。第二天你带了一只河·渡口·清晨的瓶，讲得格外仔细：雾、水声、有人洗菜。她听完说：不像。你说这是河。她说：河我也见过。她闭上眼，不再说话。你把湿毛巾叠了又叠。下班时你在走廊尽头站了一会儿，听见有人在梦里叫妈。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"去买一瓶真的海","desc":"你托港上的人找，花了半个月配给，买回一瓶。","hint":"瓶里是码头卸货。","tone":"seek","outcome":"瓶里是码头，卸货，绳子磨着船舷，海鸥叫，没有海。你把这一段讲给她听，略去了集装箱，只留风和鸟。她听完说：有风就行。她抓住你的手，抓得很轻。你说下次给你找真的。她说不用，海我见过，我就是想再听一次有人提起它。","eff":{"bond":3,"health":0,"reputation":0,"coins":-40,"stats":{"机缘":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":""}}]},{"id":"sui2_s15","act":"side","age":[70,70],"mode":"narration","title":"写在纸上的事","opening":"七十岁这年，你在柜台后头放了一沓裁好的纸。早起第一件事是写：今天几号，店门怎么开，锁往哪边拧。写完抬头，柜台上已经贴着一张，字是你的，墨还没干，你不记得写过。架子上的瓶一只只排着，标签朝外，编号描过三遍，伸手去拿最上头那只，指尖碰到玻璃，凉的。门开了，一个年轻人进来，把一张合同复印件推过来，说他找 B-1147。","ask":"他把复印件推过来，等着你说话","days":30,"npc":"","memory":"柜台上的那张纸","choices":[{"title":"让他听一遍","desc":"你把抽屉拉开，取出瓶，把听膜递给他。","hint":"瓶里又薄了一层","tone":"warm","outcome":"他贴上听膜，听得很直，手放在柜台上不动。听完他说：不是我妈。他把瓶还给你，说了声对不起，走时顺走了柜台上的一张纸。你把瓶举到灯下看，底下的白又厚了一点。那天晚上你在纸上写：今天有人来听过，不是他的。写完又添一句：也不是我的了。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"瓶底那层白又厚了"}},{"title":"叫鉴证师来","desc":"你按住复印件，让学徒去港口叫鉴证师。","hint":"他妹妹在门口跪了一夜","tone":"report","outcome":"合同是照着旧格伪造的，编号抄错了一位。他被带走那天没挣，只问了一句：那我妈的瓶在哪儿。他妹妹在店门口跪了一夜，第二天清早走了，地上留着一只空布袋。你后来在假合同背面看见一行铅笔字，很小：妈，我找不到你的号了。你把那张纸收进抽屉，没交上去。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":1},"flag":"reported_forged_claim","thread":"假合同背面那行铅笔字"}},{"title":"翻册子翻到天亮","desc":"你搬出十几本册子，一格一格找那个编号。","hint":"第二天你不记得他来过","tone":"grind","outcome":"你查到后半夜，字在眼前浮，一行看成两行。天亮时你在柜台上醒来，册子摊着，不记得是谁翻的。门开着，街上有人推车过去。你把册子合上，起身烧水，水开了才想起没放茶叶。那天没有人来，你也不记得有过一个年轻人站在柜台前，说过一个编号。","eff":{"bond":0,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"惧":4,"哀":3},"flag":"forgot_the_claimant","thread":"你不记得他来过"}}]},{"id":"sui2_x24","act":"side","age":[71,71],"mode":"narration","title":"最早的一件事","opening":"女孩是下午来的，小学四年级，做口述史作业，本子上印着格，一格写一件事，格子很小，写不下就挤在边上。她把最字写错了，用橡皮擦，橡皮屑吹到柜台上，落在瓶子中间。她问你：爷爷，你最早记得什么。你坐在柜台后头想。店里甜味淡，架子上的瓶落了一层灰，抬手一抹一道印，抹完了又落。你想起一个下午：河边，太阳斜着，有人给你剥橘子，橘子皮扔在石头上，江水从脚边过。你想得很清楚，清楚到能闻见橘子皮的味。你说：七岁，河边。","ask":"她追问那是哪条河，你怎么答","days":15,"npc":"","memory":"河边那瓣橘子","choices":[{"title":"接着说下去","desc":"你说河在城南，说那座桥，说她剥得很慢。","hint":"它成了你的一生。","tone":"keep","outcome":"你讲了半个钟头：桥是石头的，栏杆上刻着字，河上有船，船工姓什么你说了个姓。女孩一笔一笔记，记满了两页。她读回来给你听，问对不对。你说对。她合上本子，说爷爷你小时候真有意思。她走了以后你坐在柜台后头，忽然想起来，你这辈子没在河边住过。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"喜":2},"flag":"told_borrowed_childhood","thread":"本子上那两页河"}},{"title":"说记不清了","desc":"你说老了，记不清，让她去问别人家爷爷。","hint":"她写下什么都不记得。","tone":"honest","outcome":"她有点失望，笔尖在本子上顿了一下，写：爷爷什么都不记得。写完给你看。你把本子要过来，在那一行底下补了一句：他记得一瓶别人的橘子。她问这是什么意思。你说没什么，写着玩。她把本子收进书包，说那我把这句也抄上。你说别抄。她说已经抄了。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"喜":1},"flag":"","thread":""}},{"title":"去翻铁盒","desc":"你蹲下去，从柜子最底下把那只铁盒拖出来。","hint":"盒里只剩两样东西。","tone":"seek","outcome":"铁盒里一枚旧硬币，一张合同复印件，纸脆得一碰就掉渣。你拿起硬币，讲那年买冰，讲到一半，发现自己在讲另一件事：一个男人在井边切葱。你停住。女孩抬头等。你把硬币放回盒里，说：就这些。她看了看盒底，说爷爷你这里还有一张纸。你说那是废纸。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":""}}]},{"id":"sui2_s08","act":"side","age":[72,72],"mode":"narration","title":"别人的一生","opening":"漂忆港搬到新堤以后，摊子都挤在铁棚下，雾从棚顶的缝往下沉，落在肩上是一层白，闻着发甜。阿棠的店归了你，门口那块木牌还挂着：不收记忆。你把领子竖起来，衣角被风掀着走。一个十七八岁的后生支着折叠桌，桌上只摆一只大瓶，标签是他自己的字：别人的一生。他放样品：一个女人的笑，一个男人数楼梯，数到第七级停了。再往后是蝉。蝉声里冒出半句：你别老摸我手了，热。","ask":"后生问你要不要听，你怎么做","days":30,"npc":"","memory":"蝉声里的半句","choices":[{"title":"买一瓶回去听","desc":"你数出钱放在桌上，把那只大瓶抱回家，听了三夜。","hint":"左耳后来听不清了","tone":"seek","outcome":"三天三夜，别人家的婚丧、搬家、吵架、一碗面。第二夜过半，蝉声来了，那个十六岁的声音在里头说：你别老摸我手了，热。就三秒。你把这三秒放了一遍又一遍，瓶子一天比一天薄。医生让你别再用听膜，你换了右耳，写标签的时候手有点抖：非卖。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"欲":3,"哀":5},"flag":"bought_a_life","thread":"那三秒越放越薄"}},{"title":"叫鉴证师来","desc":"你退到棚外，借摊上的电话叫了港口的鉴证师。","hint":"他走时问你听出来了吧","tone":"report","outcome":"来了三个人，把瓶子一只只登记，说这是从公共库扫出来的碎段，拼起来卖，坏了规矩。后生被带走时回过头问你：你听出来了吧。你没答。三个月后店里收到一只小瓶，没有寄件人，标签上一个赠字。你把它放进缝纫机的抽屉，跟硬币、合同挨着，一直没打开。","eff":{"bond":-2,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"reported_life_seller","thread":"抽屉里那只赠字瓶"}},{"title":"教他写清来路","desc":"你让他把每段编号抄在瓶上，标签写明：拼的，不是一个人的。","hint":"你的店也被查了一回","tone":"teach","outcome":"他照写了，字歪，写了半宿。客人一看是拼的，掉头就走，一天卖不出一只。你让他把摊子挪到店门口，替你扫地从冬天扫到开春。净忆局来查执照，问这后生是谁，你说是学徒。他走那天从你架子上拿了一只瓶，你没拦。后来架子上空着的那一格，你一直没补。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"哀":3},"flag":"taught_life_seller","thread":"架子上空着一格"}}]}]},"星耒野":{"no":6,"name":"星耒野","subtitle":"在陨尘里种下一点光","through":"父亲一辈子在等一场好星雨。你小时候觉得他傻，长大后才懂他种的不是粮食。","cast":[{"id":"father","name":"耒三","role":"夜灌农","tag":"父"},{"id":"mother","name":"穗娘","role":"种子库管理员","tag":"母"},{"id":"sibling","name":"小满","role":"陨铁城学徒","tag":"妹"}],"main":[{"id":"xing_m01","act":"main","age":[0,3],"mode":"montage","title":"夜灌灯","opening":"你生在陨季的第三夜。接生婆不敢点灯，说星雨前见火要招星，父亲就把夜灌灯提到门外，用背挡着。母亲的手很凉，翻你、拍你、剪脐带，一样一样做得很快。屋里有湿土和铁锈的味，窗纸上一闪一闪，是星尘在落。父亲进来时肩上落了一层白，他没拍，先蹲下去，把门槛下的一把土攥在手里捻。母亲把灯罩推上，说：推上，星就看不见咱们。你满月那天，父亲又这么蹲着。","ask":"父亲蹲在门槛边伸出手，你怎么办？","days":300,"npc":"","memory":"门槛下那撮土","choices":[{"title":"抓他手里的土","desc":"你把手指插进他掌心那撮土里，攥得指缝发黑。","hint":"土里有碎星，扎手。","tone":"learn","outcome":"父亲没松手，让你抓。碎星扎进你的指腹，你哭了一声，他才把土抖掉，说：这土认人。那晚他给你洗了三遍手，指甲缝里还是黑的。后来你三岁，能自己蹲在垄边抓土，抓起来先闻一闻。母亲说像个小老头。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":1},"flag":"","thread":""}},{"title":"跟她进冷房","desc":"母亲要去换班，你抱住她的腿，她只好把你抱进种子库。","hint":"你在冷房里烧了一夜。","tone":"family","outcome":"冷房的门一开，白气扑到脸上，你打了个抖。母亲一手抱你，一手点数，点到第三格时你开始发热。她把你裹在棉袄里跑回家，那一盘新芽没人翻，第二天冻坏了一半。她没跟父亲说，只把坏掉的芽埋进后院。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}},{"title":"指门让他走","desc":"你在他怀里扭，手指着门外，让他去看水。","hint":"他走时回头看了两次。","tone":"practical","outcome":"父亲愣了一下，把你放到母亲怀里，提灯出门。那夜的水放得比谁都匀，他回来时天已经亮了，蹲在门槛上看你，没伸手抱。母亲说他在渠边站了很久才走。你后来学会的第一件事，是听门外的脚步，辨他有没有回来。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":"他蹲在门槛上没伸手抱你"}}]},{"id":"xing_m02","act":"main","age":[5,5],"mode":"dialogue","title":"举起来","opening":"望星台的钟敲了三下，是星雨。全村的人往地棚里钻，母亲拽你，父亲却把你抱起来，往田埂上走。他说：看一眼，就一眼。天上一层一层地亮，像有人在上头撒谷。风里有烧石头的味。他把你举过头顶，你的影子落在垄上，亮了很久。星尘落在他头发上，白了一层。他抬头看了看台子，说：钟慢了一刻。","ask":"第一颗星落下来，你要做什么？","days":20,"npc":"father","memory":"亮了很久的影子","choices":[{"title":"拽他回地棚","desc":"你想起母亲的交代，攥住他的袖子，把他往地棚那边拖。","hint":"村里笑他白等一场。","tone":"obey","outcome":"他被你拖了两步，站住，弯腰把你抱进棚里。棚里的人都笑，说耒三的星雨让儿子搅了。他没笑，蹲在棚口看天，一直看到雨停，背上落满白。那年他的星历上少记了一场。母亲给你擦脸，什么也没说。","eff":{"bond":-2,"health":2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":"他的星历上少记了一场"}},{"title":"睁着眼看完","desc":"你不躲，仰着头，把整场星雨一颗一颗看到尾。","hint":"你连着三夜梦见天在烧。","tone":"brave","outcome":"父亲的手一直托着你的肋。星落到第三阵，天忽然白了一下，你的眼睛疼了两天，闭着也看见亮斑。母亲用凉布给你敷，说：跟你爹一个样。你五岁那年记住的不是星，是他举着你时胳膊在抖，一直没放下。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":"你的眼睛疼了两天"}},{"title":"伸手去接","desc":"你从他肩上探出去，摊开手掌接落下来的星尘。","hint":"掌心留下一小点白。","tone":"risk","outcome":"一粒星尘落在你手心，烫出针尖大的一个白点，你没哭。父亲把你的手翻过来看了看，说：接住了？你说接住了。他笑了，说：傻。那点白跟了你一辈子，洗手洗不掉，冬天发亮。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"惧":1},"flag":"palm_star_mark","thread":"掌心那点白跟你一辈子"}}]},{"id":"xing_m03","act":"main","age":[9,9],"mode":"narration","title":"发光的穗","opening":"九岁那年，你在西垄最边上一株麦子跟前蹲住了。天已经黑透，那穗子是亮的，不刺眼，像有人在穗心里点了一盏很小的灯。你伸手碰，穗子上的光就顺着你的手指爬到手腕。四周的麦都是黑的。你回头看，田埂上没有人，只有夜灌灯在远处一晃一晃。你听见自己的心跳，也听见穗子里有很细的响声，像米在锅里。","ask":"那株麦子在夜里亮着，你要做什么？","days":15,"npc":"","memory":"夜里发光的穗","choices":[{"title":"守它到天亮","desc":"你怕巡田的看见，蹲在垄边用身子挡着，守到天亮。","hint":"你误了早上的水。","tone":"wait","outcome":"天快亮时，穗子暗下去，像灯油烧尽。你伸手一摸，穗粒是空的，一捻就碎，掌心留下三粒黑的。你把它们藏进墙洞。母亲问你去哪了，你说看水。那天的水没放完，下游一垄旱了。三粒黑种你留到十四岁，没敢种。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"kept_three_black_seeds","thread":"三粒黑种藏到十四岁"}},{"title":"报给巡田的","desc":"你跑去田头，把巡田的农盟人叫来看这株麦。","hint":"烧的是整垄，不只一株。","tone":"report","outcome":"巡田的人看了一眼，脸就沉了，说变异株要烧。他们抱来干草，把西垄边整整一垄都点了。火里噼啪响，那穗子亮到最后一下才灭。父亲赶到时只剩灰。他没骂你，蹲下去抓了一把灰，说：烧得对。那晚他没回家吃饭。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"burned_variant_row","thread":"父亲那晚没回家吃饭"}},{"title":"移进米缸底下","desc":"你连根挖起，用衣襟包着，塞进灶边米缸底下。","hint":"母亲的手比缸底还凉。","tone":"sneak","outcome":"母亲当晚就发现了。她把那株麦拿出来，看了很久，没问哪来的，只说：以后别碰。她掀开米缸，底下已经压着一包纸包的种子。两包并排放着，她的手指在上面按了按。冷气从缸底漫上来，你打了个抖。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"惧":2,"爱":2},"flag":"saw_mother_packet","thread":""}}]},{"id":"xing_m04","act":"main","age":[14,14],"mode":"dialogue","title":"收糠的车","opening":"陨铁城的收糠车是午后进坑的。车轱辘上裹着布，压过田埂不出声。收购的人在晒场上摆开秤，秤砣是陨铁打的，黑得发亮。父亲把一袋星糠解开，让他看。那人抓了一把，用牙咬，说：潮。父亲说：这季雨多。那人报了个价，比去年低三成。小满穿着城里发的褂子，袖子长出一截，站在那人身后捧册子，说城里的仓房比咱家三间屋还大。父亲没看价牌，先问：明年的种粮，还能不能赊。","ask":"父亲伸手要按手印，你打算怎么办？","days":10,"npc":"father","memory":"帽檐里的契纸","choices":[{"title":"挡住那杆秤","desc":"你一脚踩上秤盘，说这个价不卖，让他把车赶走。","hint":"小满回城挨了罚。","tone":"defy","outcome":"收购的人把秤一收，说要走。父亲把你拉到身后，还是按了手印，价又低了一成。回家的路上他说：你一闹，明年的赊账就难了。他没骂你，只把那页契纸折得很小，塞进帽檐里。小满回城时没跟你道别。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"惧":2},"flag":"","thread":"小满手背上的竹条印"}},{"title":"替他捧墨盒","desc":"你双手捧住墨盒，看他把拇指按进墨里，再按在纸上。","hint":"你的指印也在下面。","tone":"carry","outcome":"他按完，把墨盒递给你，说：你也按一个。你说我又不是当家。他说：记着这个价。你就按了，拇指上沾了黑，回家洗了三遍才掉。那张契纸在城里存了二十年，上头两个指印，一个深，一个浅。后来城里来催，找的是下面那个浅的。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":2},"flag":"thumbprint_on_receipt","thread":"城里来催找的是你"}},{"title":"夜里藏两袋","desc":"半夜你和小满把两袋星糠藏进渠边的草垛里。","hint":"父亲让你当着人背回去。","tone":"greed","outcome":"第二天收购的人点数，差两袋。父亲看了你一眼，没说话，自己去草垛里把袋子拖出来，当着人扛回车上，回头还是按了手印。收购的人扣了半秤。回家父亲把那半袋糠倒进你的碗里，说：吃。你吃了三口就吃不下。","eff":{"bond":-3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":""}}]},{"id":"xing_m05","act":"main","age":[18,18],"mode":"dialogue","title":"星尘进了眼","opening":"星雨提前了半宿。望星台的钟只响了一下就哑了，父亲还在西沟关闸。他回来时两只手捂着脸，指缝里往外淌水，睫毛上挂着一层白，像霜。他说：别点灯。母亲把夜灌灯的灯罩推上，屋里黑了。他坐在灶边，慢慢把手放下来，眼睛睁不开，眼白上有一片细碎的亮点，像撒进去的星糠。他一个字一个字地说：还好，还能看见土。","ask":"父亲的眼睛睁不开，你先做什么？","days":30,"npc":"father","memory":"眼白里的亮点","choices":[{"title":"跑去望星台","desc":"你光脚往台上跑，跑得上气不接下气，去叫守台的人。","hint":"来回八里，天亮了。","tone":"seek","outcome":"守台的人提着药箱跟你下来，天已经发白。他掰开父亲的眼皮看了看，说：洗晚了。他留下一个小瓷瓶，收了两升星糠。父亲的眼睛后来能看见路，看不清人脸。守台的人临走说：你们那块地，本来就不在台上眼里。父亲说：我知道。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":4},"flag":"father_eyes_dim","thread":"父亲再没夜里下田"}},{"title":"含水给他冲","desc":"你含一口温水，凑过去，一点一点冲他眼里的白。","hint":"你咳了三年。","tone":"heal","outcome":"星尘顺着水进了你的喉咙，辣得像吞了碎瓷。父亲的眼睛冲出来一些，能睁开一条缝。你咳了半个月，后来每到星雨就咳，咳了三年。母亲说你是把星吃进去了。父亲听见了，蹲下去抓了把土，没说话。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":3},"flag":"father_eyes_dim","thread":"你落下了星雨咳"}},{"title":"先熄那盏灯","desc":"你先把灯罩推死，才去扶他，因为灯会招星。","hint":"他自己上的药，没让你碰。","tone":"rule","outcome":"灯一灭，院里黑得看不见手。父亲往前迈了一步，踩空，整个人摔进排水沟，膝盖磕在石头上。你摸过去拉他，他先摸到你的手，说：灯灭了没有。你说灭了。他说：那就好。他自己上的药，没让你碰。","eff":{"bond":-2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":3},"flag":"father_eyes_dim","thread":"他膝盖上的伤养了一月"}}]},{"id":"xing_m06","act":"main","age":[23,23],"mode":"narration","title":"土里的声音","opening":"第一次独自守夜灌，是二十三岁那年。母亲把灯递给你，灯罩擦得很亮，教过你的那句话还在：推上，星就看不见咱们。父亲没出来，只在他屋门口说了一句：水走慢些。银穗坑的夜里有雾，麦子只到膝盖。你把水引进垄沟，蹲下去看水头。就在这时候，你听见土里有声音。不是虫，也不是水，是很低的一下一下，像有人在很深的地方敲一只空碗。你把耳朵贴到地上，土是温的。","ask":"土里的声音一直没停，你要怎么办？","days":10,"npc":"","memory":"土里的敲碗声","choices":[{"title":"挖开看","desc":"你用锹把声音那处的土挖开，挖到小臂深。","hint":"那东西整夜发烫。","tone":"seek","outcome":"挖出一块拳头大的陨铁，黑里透红，握在手里像握着一只刚熄的灶。声音停了。你把它包在衣襟里带回家，塞进墙洞。那夜以后，那块土一直比别处暖，麦子早熟了三天。你没跟任何人说。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"喜":3,"惧":2},"flag":"found_warm_iron","thread":"墙洞里那块陨铁整夜发烫"}},{"title":"把水让开","desc":"你把进水口改小，让水绕开那块地，自己那垄旱着。","hint":"那垄麦没抽穗。","tone":"protect","outcome":"水从垄边淌过去，那块地一滴没沾。你蹲在干土上听，声音慢慢平了，像有人睡过去了。那一季你那垄麦没抽穗，交糠时短了一截，你说是水没放匀。父亲看了一眼那块地，什么也没问。第二年，那块地的麦长得最好。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"spared_the_ground","thread":"你那垄麦没抽穗"}},{"title":"叫醒父亲","desc":"你提着灯跑回家，把父亲从炕上叫起来。","hint":"第一夜就算没过。","tone":"elder","outcome":"父亲披衣出来，蹲在那块地上，把手掌平放下去，听了很久。他说：是土在记路，别挖。他陪你坐到天亮，回去就咳，咳了半个月。母亲说你不该叫他。你的第一夜守夜，按规矩不算过。你自己没再提。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"父亲为这一夜咳了半月"}}]},{"id":"xing_m07","act":"main","age":[31,31],"mode":"dialogue","title":"他笑了","opening":"大星雨落了半夜。第二天的银穗坑像一只摔碎的碗。半个坑的土烧成黑玻璃，踩上去咯吱响，麦子只剩焦秆，玻璃上落着一层白，是星尘。农盟的人在坑边点数，谁家的地毁了。有人问父亲还种不种，他蹲着，隔了很久才慢慢说：种。父亲一处一处走，走到玻璃最厚的地方，蹲下去，把手掌贴在还烫的地上。他听了听，忽然笑了，笑得像咳嗽。他说：七十三垄，毁了四十一垄。他说：你听。","ask":"父亲蹲在玻璃地上笑，你怎么办？","days":20,"npc":"father","memory":"玻璃地上的笑","choices":[{"title":"跟着他听","desc":"你也蹲下去，把耳朵贴在烫土上，听底下的响。","hint":"村里说这家疯了。","tone":"warm","outcome":"底下有水在走，滴答滴答，像有人在玻璃下面敲碗。父亲说：我知道救不回来。可人得先信明年，不然这个冬过不去。他说：这半边，明年种什么都活。旁边的人摇头走了。第二年那半边果然出苗最齐。父亲没跟人争过一句。","eff":{"bond":5,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"爱":3},"flag":"understood_father","thread":""}},{"title":"把他拉走","desc":"你架住他的胳膊，把他从人群眼里拖回家。","hint":"他以后再没在你面前笑过。","tone":"protect","outcome":"他没挣，跟着你走，走到院门口才说：你不信。你说我信。他点点头，进屋去了。那天之后他还是下田，还是不紧不慢，只是再没跟你说过地里的事。毁掉的那半边，后来是他一个人收拾的。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":2},"flag":"","thread":"他再没跟你说过地里的事"}},{"title":"下地捡穗","desc":"你不笑也不拉他，拿镰刀进焦地，去割那些没烧透的穗。","hint":"你的手割了七道口子。","tone":"carry","outcome":"焦秆脆，镰刀一碰就断，断口比刀子还利。你割到天黑，捡回三筐半焦的穗。父亲后半夜也来了，蹲在你旁边割。你们谁也没说话。那三筐穗打出两斗糠，掺着吃过了冬。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"手上的七道口子"}}]},{"id":"xing_m08","act":"main","age":[38,38],"mode":"dialogue","title":"清库","opening":"农盟来清库那天，种子库的冷房开着门，白气从门槛下往外爬，像水。母亲穿着棉袄，手冻得发红，把一格格种子搬出来点数。清库的人拿着册子，念到第三格时停住了：耒三，私种一袋，未上交。父亲站在门外，没进来。冷气扑到他脸上，他的眼睛眯起来。你看见母亲的手在围裙上擦了一下，又去搬下一格。","ask":"清库的人伸手去拉第三格，你拦不拦？","days":20,"npc":"mother","memory":"冷房的第三格","choices":[{"title":"抱走那袋种","desc":"你抢先把袋子抱在怀里，说这是我的，记在我名下。","hint":"罚的是明年一季的水。","tone":"protect","outcome":"清库的人看了你一眼，在册子上写下你的名字，罚了明年一季的水。父亲在门外听见了，转身就走。你抱着袋子在门口坐了一夜，第二天胳膊抬不起来。那袋种保住了，可那一季你家的田最后才放上水，秧苗比别家矮半截。","eff":{"bond":3,"health":-1,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":3},"flag":"took_blame_for_seed","thread":"罚了明年一季的水"}},{"title":"指给清库的","desc":"你伸手一指第三格，说那袋在这里，按规定办。","hint":"父亲再没进过冷房。","tone":"report","outcome":"清库的人把袋子拖出来，倒进焚烧桶，冷房里全是烧纸的味。父亲在门外看着，没进来，也没说话。从那天起他再没进过种子库，连门口都不站。母亲照旧每天去冷房，回来时手更凉。","eff":{"bond":-5,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"burned_father_seed","thread":"父亲再没进过冷房"}},{"title":"换一个口袋","desc":"你趁人转身，把两袋种换了口袋，真的一袋塞进米缸。","hint":"母亲看了你很久。","tone":"sneak","outcome":"清库的人提走了半袋陈种，在册子上画了勾。母亲回家掀开米缸，看见那袋种，手停在缸沿上。她把缸盖轻轻放回去，说：你爹的种，你爹的命。她没让你交出去。那年冬天冷房封了一间，米缸底下挤着两包种子。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"爱":2},"flag":"hid_two_packets","thread":"米缸底下挤着两包种"}}]},{"id":"xing_m09","act":"main","age":[47,47],"mode":"dialogue","title":"坡上","opening":"父亲是在田里走的。清早去看水，天黑没回来。你提灯去找，他靠在垄头木桩上，一只手还插在土里，夜灌灯的油烧干了，灯罩上结了一层星尘。他脸朝着望星台。葬在能看见台子的坡上，坟前立的是台上换下来的旧碑，正面刻了三个字：耒三。下葬那天小满跪着，话比谁都多，说她十二岁那年替城里记过父亲的名字，说城里仓房的钥匙她配过。父亲早就知道。","ask":"小满还跪在碑前不肯起，你怎么做？","days":30,"npc":"sibling","memory":"坡上那块旧碑","choices":[{"title":"把她拉起来","desc":"你伸手把她从土里拉起来，替她拍掉膝上的泥。","hint":"这事你们瞒了母亲一辈子。","tone":"warm","outcome":"她站起来还在说，说了很多，从城里的仓房说到册子的边角。你听着，没应。你在泥里跪久了，膝盖疼了半个月。母亲在坡下等，你们谁也没提。那以后小满每年回来，都在米缸里放一包城里的糖。母亲到走都不知道这件事。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":5},"flag":"","thread":"你们瞒了母亲一辈子"}},{"title":"让她去说","desc":"你说：你自己下去，跟母亲说。然后你走开。","hint":"母亲听完，把手炉放在了地上。","tone":"honest","outcome":"小满在坡下跪了很久，母亲听完，没打也没骂，只把手里的手炉放在地上，说：我早知道。她转身回屋，门没关。那晚小满在灶边坐了一夜。第二天母亲照常去冷房，回来时手更凉，谁也没再提。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":4},"flag":"","thread":"母亲把手炉放在了地上"}},{"title":"问她记的哪三个字","desc":"你问她，册子上写的是哪三个字，一笔一划怎么写的。","hint":"他的名字只留在别人册上。","tone":"ask","outcome":"小满用手指在碑前的土上写：耒、三。她说城里人不会写耒字，是她替他们写的。你看着那两个字，想起父亲蹲在地上抓土的样子。他的名字，除了这块碑，就只有城里那本册子还记着。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"爱":3},"flag":"knows_city_ledger","thread":"他的名字只在别人册上"}}]},{"id":"xing_m10","act":"main","age":[65,65],"mode":"narration","title":"爷爷种过星星吗","opening":"六十五岁这年，星雨来得晚。你带着小禾上坡，她六岁，走一半就要抱。你说自己走，走到台子底下给你买糖。她就自己走。坡上那块旧碑还在，字磨得只剩一个三。天黑下来，第一层星尘落在她头发上，她伸手去接，接了个空。她忽然问：爷爷真的种过星星吗。母亲走了八年，米缸还在灶边，缸底压着两包种子。","ask":"小禾仰着头等你回答，你怎么说？","days":30,"npc":"","memory":"爷爷种过星星吗","choices":[{"title":"领她进冷房","desc":"你带她下到种子库，开最后一间冷房，指那袋种。","hint":"冷气进了她的肺。","tone":"teach","outcome":"白气从门里涌出来，她咳了两声，还是往里走。你从袋里抓了一小把黑种，放进她手心，说：这是你太爷爷藏的。她攥着跑了。那年冬天你咳了一整季。第二年开春，墙根下冒出一株麦，瘦，夜里有一点微弱的光。她把那株麦当成宝，天天去看。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":3},"flag":"gave_last_seeds","thread":"墙根下的麦，她天天去看"}},{"title":"说她爷爷傻","desc":"你说他傻，等了一辈子雨，最后死在田里。","hint":"女儿在坡下听见了。","tone":"honest","outcome":"小禾问：那你还种？你说：不种吃什么。她想了想，说：那你也傻。女儿在坡下喊她，声音很硬。回家的路上谁也没说话。那年冬天小禾画了一张画，画里一个蹲着的人，头发上全是白点。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"","thread":"女儿听见你说他傻"}},{"title":"把她举起来","desc":"你学父亲的样子，把她举过头顶，让她看地上的影子。","hint":"你的胳膊疼了三天。","tone":"warm","outcome":"你举到一半，腰响了一声，还是举直了。她的影子落在坡上，被星照得很长。她说：爷爷也这样举过你吗。你说举过。她就不问了，伸手去够天。回去的路上她趴在你背上睡着了，你胳膊抖得扶不住栏杆。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":5,"哀":2},"flag":"","thread":""}}]},{"id":"xing_m11","act":"main","age":[76,76],"mode":"narration","title":"最后一颗","opening":"七十六岁，望星台拆得只剩半截。农盟说坑田要退，种子库的冷房开到月底。夜里你带小禾上去，她十七了，在台上做记星雨的学徒。旧碑还立在坡上，字磨得只剩一个三。天上很干净，只有一颗星在往下走，走得很慢，像谁提着一盏灯找路。风里有烧石头的味。小禾把手里的灯罩推上又推开，等你说话。","ask":"那颗星正往坑心里落，你怎么做？","days":60,"npc":"","memory":"最后一颗星落下","choices":[{"title":"伸手去接","desc":"你把铜盆举过头顶，迎着那颗星，往前走了三步。","hint":"你的手从此端不住碗。","tone":"brave","outcome":"星落在盆里，盆底当场化了。你用手去捧，掌心烫出一片白，跟五岁那年那个点连在一起。你把那团东西埋进坑心，把缸底最后一把种按进去。天亮时土面顶出一根绿芽，不发光。你蹲下去看它，想起他说想种一茬不用看天色的庄稼。手包了三个月，后来端碗要用两只手。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"爱":3,"哀":3,"喜":2},"flag":"caught_last_star","thread":"你的手端不住碗"}},{"title":"熄灯，不看它落","desc":"你把灯罩推死，背过身，听它自己走完最后一段。","hint":"在你的记忆里它还在天上。","tone":"wait","outcome":"灯一灭，天显得更大。你背对着坑心，听那颗星走，走过第三道渠，走到坡那边，才有一声很闷的响。小禾问你为什么不看。你说看了一辈子，这回让它自己走。第二年荒滩上绿了一片，农盟去划了新坑，叫野星坑，归了拾尘会。你始终没去看过。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":3},"flag":"let_last_star_go","thread":"野星坑归了拾尘会"}},{"title":"把灯递给她","desc":"你把灯放进小禾手里，教她哪边关，哪边开，说：你来。","hint":"你没看见它落在哪。","tone":"teach","outcome":"她握着灯绳，手很稳，先看你一眼，然后把灯罩推死。你说：明年还会来。她说：那明年我还来。星落下去的时候你闭着眼，听见她轻轻数数。你们坐在坡上，谁也没再说话。天亮你醒了，她靠在你胳膊上睡着，天上什么也没有。","eff":{"bond":5,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":5,"哀":2,"喜":2},"flag":"passed_the_lamp","thread":""}}]}],"side":[{"id":"xing_x01","act":"side","age":[6,6],"mode":"narration","title":"缸里的星","opening":"傍晚落了一阵星尘，薄薄一层，落在院里的水缸里。水面上浮着白，像谁撒了一把面粉。你趴在缸沿上，看见自己的脸被那层白分成几块，鼻子一块，眼睛一块。隔壁二丫搬来一只碗，舀起一碗，端着在院里跑，光在碗里晃，泼出来一点，落在地上还亮了一下。碗沿是凉的，贴在嘴唇上，有一点铁味。你们把缸里的水一瓢一瓢舀出来，看谁舀到最亮的一碗。水越来越少，缸壁上留下一圈湿印，慢慢干了。母亲在灶间喊你挑水，喊了三遍，你应了一声，没动。天已经黑透，碗底那点光还亮着，照着她半张脸。","ask":"缸里的水见了底，你还舀不舀？","days":10,"npc":"","memory":"水缸里的一层白","choices":[{"title":"舀到娘动手","desc":"你不理灶间的喊声，把最后半瓢也舀进碗里。","hint":"晚饭的碗盛得比往常浅。","tone":"defy","outcome":"母亲提着扁担出来，一把夺过碗，扣在缸沿上，说这水还要吃。你把最后半碗藏在身后，泼了一裤腿。夜里渴醒，你摸到缸边，缸底只剩一层带土腥的水。第二天二丫又来，站在篱笆外问：今天还舀不舀。你说不舀了，她站了一会儿才走。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"惧":1},"flag":"","thread":"泼湿的那条裤子"}},{"title":"端一碗给娘","desc":"你捧着最亮的一碗进屋，举到母亲面前给她看。","hint":"她先擦手才接。","tone":"warm","outcome":"母亲把手在围裙上擦了两下，才接过去。她端着看了很久，说：像你爹讲的银河。她让你倒在灶台上，说别糟蹋。那碗水在灶台上亮了一夜，第二天干了，留下一圈白印。她洗碗时没洗掉，那圈白印在灶台上留了半个月。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":1},"flag":"","thread":""}},{"title":"盖上缸盖","desc":"你把缸盖推回去，说明天再来看。","hint":"第二天缸里什么也没有。","tone":"practical","outcome":"第二天早上掀开，水面上什么也没有，只有一层灰。二丫来问，你说光了。她蹲在缸边看了半天，说光是不是沉底了。你伸手进去摸，摸到缸底一层细沙，捞起来，手心是黑的。你们把手举到太阳底下看，什么也没看出来。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":1,"哀":2},"flag":"","thread":""}}]},{"id":"xing_s01","act":"side","age":[7,7],"mode":"narration","title":"收粮的独轮车","opening":"收粮的人是晌午到的，从陨铁城来，一个人，一辆独轮车，车把上挂着一杆铜盘小秤。父亲去望星台换星历，母亲在冷房当班，走时带出一股冷气。院里只有你，夜灌灯还挂在枣树上，灯罩推着。他把车停住，蹲下来跟你一般高，问：你家的糠在哪只缸里。他身上有煤烟和干鱼的味，袖口磨得发亮。秤盘边有一道旧焊痕，焊得发乌。晒场上的糠皮和星尘一起被风卷起来，落在他的睫毛上，他不掸。","ask":"他问糠在哪只缸里，你怎么答？","days":12,"npc":"","memory":"秤盘上的焊痕","choices":[{"title":"舀一升给他","desc":"你搬开缸盖，舀满一升倒进他的袋，没要他手里的盐。","hint":"母亲回来数过缸沿。","tone":"warm","outcome":"他愣了一下，把一小包盐放在门槛上，推车走了。母亲回来，手指在缸沿上抹了一圈，没问，晚饭的碗盛得比往常浅。那包盐她一直没拆，搁在灶神像后头，受潮结成了块。后来你才知道，那年城里也缺粮，收粮的人自己车上装的是麸。","eff":{"bond":0,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"哀":1},"flag":"","thread":""}},{"title":"去冷房叫娘","desc":"你把院门闩上，跑去种子库，把母亲从冷房里叫回来。","hint":"冷房门开着，冻坏一盘芽。","tone":"tell","outcome":"母亲跑回来时围裙上还挂着白霜，收粮的人已经走了。冷房的门她没来得及关严，一盘新芽冻坏了半边，清点的人记了她一笔。她没骂你，只把冻坏的芽一粒粒捡进手心，说：叫得对。那晚她把手炉让给你，自己的手一直没暖过来。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"爱":2},"flag":"","thread":"冷房冻坏的那盘芽"}},{"title":"指去二娘家","desc":"你说家里的糠早卖了，抬手把他指到隔壁二娘的院门口。","hint":"二娘从此关着门。","tone":"dodge","outcome":"他推车去了二娘家。二娘卖了半袋，价钱比往年低，称完在门口站了很久。第二天她隔着篱笆问你：是你指来的？你说不是。她没再问，往后见了你就把门带上。那年冬天她家借糠，绕过了你家。你记得她的门闩声，比话还响。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"xing_x02","act":"side","age":[8,8],"mode":"narration","title":"发光的猪","opening":"老祁家的猪是晌午拱开圈门跑出来的。它先在西头晒场上吃了半簸箕星糠，那糠摊在席子上晒，准备交的。吃完它就在村里走，走得很慢，肚子鼓着，嘴边挂着一圈黄。天黑下来，第一层星尘落地的时候，有人看见老祁家猪圈那边有光。猪站在圈里，从头到尾亮着，像有人把一盏灯塞进了它肚子里，连耳朵尖都是透的。老祁提灯去看，刚走到圈门口，猪从门底下钻出来，一溜小跑。光在土墙上一晃一晃，把半个村子的影子都拽歪了。有人在喊，有人提着锹追，老祁他婆娘连鞋都没穿，脚上只一只。","ask":"猪从你身边冲过去，你怎么办？","days":10,"npc":"","memory":"追了一夜的猪","choices":[{"title":"跟着人群追","desc":"你撒腿就追，跟着火把和喊声绕村跑。","hint":"第二天脚底全是泡。","tone":"brave","outcome":"追到渠边，猪一头扎进水里，光在水下散成一片，全村人站在岸上看。最后是二丫她爹脱下褂子，把猪头一蒙，猪才站住。牵回去时天已经亮了。老祁蹲在渠边洗那件褂子，说：这猪比我值钱。你回家脱鞋，脚底三个泡，最大的那个有铜钱大。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":4,"惧":1},"flag":"","thread":"脚底三个泡"}},{"title":"抄近路堵圈门","desc":"你不追，绕到猪圈后头，把圈门推开等着。","hint":"猪撞在你腿上。","tone":"practical","outcome":"猪从巷子里冲回来，一头撞在你腿上，你坐在地上，它自己进了圈，站定，喘得像拉风箱。全村人随后赶到，看见你坐在圈门口。老祁抓了一把炒豆塞给你。此后村里叫你关门那个。你娘不喜欢这个叫法，说像看门的。","eff":{"bond":1,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"喜":3},"flag":"","thread":"村里叫你关门那个"}},{"title":"爬墙头看","desc":"你爬上老祁家的墙头，坐在上面看全村跑。","hint":"他儿媳妇记住了你在笑。","tone":"alone","outcome":"你看见火把、灯、手电，绕着村子转了三圈。猪最后在一口井边停下，低头舔井沿上的霜，谁靠近它就跑。老祁的儿媳妇追得蹲在地上吐。第二天她见你还在笑，说：你倒清闲。你娘在旁边拿眼瞪你，你低下头，嘴角还没收回去。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":4,"恶":1},"flag":"","thread":""}}]},{"id":"xing_s09","act":"side","age":[10,10],"mode":"narration","title":"斗底的锡疤","opening":"十岁那年秋后，下坳村来了一个人，姓韩，站在院门外不进来。他手里提着一只斗，斗底裂过，用锡补了一道。他身后跟着个男孩，跟你差不多高，低头看自己的鞋。他说他们坑今年只收了三成，种子库进了水，想借半斗种，秋后还一斗。父亲在渠上，母亲在冷房。院角的种缸盖着草帘，缸口往外冒冷气。地里发光的麦穗在夜里亮成一片。夜灌灯挂在枣树上，灯罩推着。","ask":"他把斗递过来，你接不接？","days":30,"npc":"","memory":"斗底那道锡疤","choices":[{"title":"舀半斗给他","desc":"你搬开种袋，舀半斗好种倒进他的斗，没要他许的糠。","hint":"母亲回来点了三遍种袋。","tone":"help","outcome":"他连声道谢，把斗抱在怀里，走几步回一次头。母亲回来点了三遍种袋，没问，只把袋口重新扎紧。开春你家少种两垄，秋后短了半袋。第二年秋后他真的来了，背来一斗糠，糠里掺着沙。母亲收下，倒进猪食缸。那男孩站在门外，长高了一头，还是不看人。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":"他背来的一斗糠掺着沙"}},{"title":"领他去农盟","desc":"你锁上院门，把他领到农盟棚下，让巡田的照规矩登记。","hint":"他家的名字上了册。","tone":"rule","outcome":"巡田的人翻开册子，问坑名、户名、人口，一笔一笔记下，说私借种要两家连坐。他站在棚下，斗一直提在手里，走时没跟你说话。那年他家没借到种，春天地里荒着。秋后农盟发救济，按册子发，他家排在最后。他儿子后来在晒场上见你，绕着走。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":"他家排在救济册最后"}},{"title":"让他把斗留下","desc":"你说种要等父亲回来点，让他先把斗搁在门槛上。","hint":"那只斗搁了一秋。","tone":"dodge","outcome":"他把斗搁在门槛上，说下回再来，领着孩子走了。斗在门槛上放了一秋，落满星尘，你每天跨过去，渐渐看不见它。入冬他家孩子来讨斗，站在门外，你才想起。你把斗擦干净递过去，他接了，没再提借种的事。那道锡疤，你记了很多年。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"门槛上搁了一秋的斗"}}]},{"id":"xing_x03","act":"side","age":[10,10],"mode":"narration","title":"湿绳子","opening":"农盟来量界，两个人，一根麻绳。绳子昨天淋了雨，今天还没干，量到你家地头，短了三尺。领头的人说：界往这边挪三尺。父亲说昨天不是这儿。那人说昨天绳子是干的。父亲蹲下去抓了一把土，抓了很久，指缝里往下漏。你站在垄上看那根绳子，一个结一个结，结上还挂着水珠，风一吹，水珠掉在土里，砸出小坑。日头照在绳子上，麻绳冒着一点白气，像刚出锅的面。晒场那边有人在喊号子，声音一阵一阵过来。你想说绳子湿了会缩，可你不知道这话该怎么说，也不知道说了有没有用。","ask":"绳子还在滴水，你说不说话？","days":15,"npc":"","memory":"滴水的量地绳","choices":[{"title":"拿湿绳量他家","desc":"你说：那拿这根绳子去量量你家门口。","hint":"父亲把你提回了家。","tone":"rebel","outcome":"那人愣了一下，笑了，说这娃有出息。父亲一把提起你的后领，拽回家，路上一句话没说。进门他才说：地是量不完的。那三尺地后来种上了麦，长得比别人家的矮半截。可第二年再量界，那人绕开了你家地头，绳子拉得笔直。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"怒":2,"喜":2},"flag":"","thread":"父亲提你后领的那一下"}},{"title":"把绳子晾干","desc":"你捡起绳子，挂在枣树上，说晒干了明年好用。","hint":"那人以为你在讨好。","tone":"practical","outcome":"那人看了你一眼，说这娃懂事。父亲在屋里咳了一声。第二年绳子果然是干的，量出来多地半尺。清点的人说算了。父亲把那半尺种了三棵白菜，一棵也没吃，全冻在地里。他蹲下去看冻白的菜心，看了很久。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"喜":1},"flag":"","thread":""}},{"title":"夜里挪界桩","desc":"半夜你摸到地头，把界桩拔起来，插回原来的土眼。","hint":"秋天册子上还是少三尺。","tone":"sneak","outcome":"界桩插回去，土眼对得上，谁也没看出来。可秋天清点，册子上还是少三尺。父亲交糠那天把界桩重新钉下去，锤了七下，一下比一下重。你在旁边数着，数到第七下，他直起腰，说：记住这个数。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":"界桩上锤了七下"}}]},{"id":"xing_s02","act":"side","age":[11,11],"mode":"narration","title":"不肯发光的麦","opening":"十一岁那年，西垄的麦穗在夜里都亮，只有一株不亮。它比旁边的矮半尺，穗子却饱，麦芒发黄，摸上去是干的。你蹲在它跟前，风从坑心那边过来，带着冷气，别的麦穗沙沙响，它不响。巡田的人说，不发光的是病株，要拔。父亲蹲在另一头，用指甲掐开一粒，放进嘴里嚼，说：是甜的。夜灌灯挂在柳枝上，灯罩里积了一层星尘，风一吹，白灰往下掉。","ask":"天快亮了，这株麦你拔不拔？","days":20,"npc":"","memory":"一株不亮的麦","choices":[{"title":"把水让给它","desc":"你在垄头挖一道细沟，把夜里的水全引到它根下。","hint":"你那垄旱到抽不出穗。","tone":"protect","outcome":"水淌进它根下的土，土色深了一块。那株麦又活了七天，最后自己倒了，穗子散在垄上。你那垄麦旱得没抽穗，交糠时短了半袋。父亲没问水去了哪，只把散落的穗捡起来，搓出十几粒，装进一个小布袋。第二年他悄悄种在墙根，长出来的麦，夜里也不怎么亮。","eff":{"bond":2,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":2,"爱":2},"flag":"kept_dark_wheat","thread":"你那垄麦没抽穗"}},{"title":"叫巡田的来","desc":"你跑到田头，把巡田的人领到西垄，指那株麦。","hint":"父亲那天没吃晚饭。","tone":"report","outcome":"巡田的人蹲下看了一眼，说拔。他连根拔起，扔进草堆，火点得很小，像烧一把湿草。父亲站在旁边看，手插在袖子里，说：留着也活不成。那天晚饭他没上桌，母亲把碗端进屋，又原样端出来。西垄空出一个坑，后来的麦都往那边倒。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":""}},{"title":"移到棚后去","desc":"你连根挖起那株麦，栽到地棚后头的湿土里。","hint":"它的粒是甜的。","tone":"sneak","outcome":"它在地棚后活了半个月，没发光，也没死。秋后你收了小半把，搓开，粒是褐的，磨成粉掺进面里。父亲吃了两口，说今天的面怎么是甜的。你说不知道。那半把种你没舍得吃完，包起来塞进墙洞，跟往年攒下的几粒种放在一处。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"惧":1},"flag":"","thread":""}}]},{"id":"xing_x04","act":"side","age":[12,12],"mode":"narration","title":"门缝里的白气","opening":"母亲在冷房当班，三天没回家吃饭。你提着饭篮去种子库，篮里两个菜团子，一碗热汤，汤上扣着一只碗，怕凉。路上有风，你把篮子抱在怀里，怕汤洒了。冷房的门关着，门缝底下往外爬白气，贴着地，像水。白气漫到你鞋面上，鞋面一会儿就湿了，脚趾头开始发麻。你敲门，母亲在里面说：放门口。你把篮子放下，蹲在门外等。等了很久，门开了一条缝，一只手伸出来，手很凉，指节发红，摸到篮子就缩回去了。门又关上。你隔着门听见她吹汤，吹得很轻，一口一口。","ask":"门里传来吹汤的声音，你走不走？","days":12,"npc":"","memory":"门缝底下的白气","choices":[{"title":"坐着等她吃完","desc":"你靠着门框坐下，等她把空碗推出来。","hint":"回去的路上你摔了一跤。","tone":"wait","outcome":"门再开时，篮子推出来，碗是空的，汤喝得干净。碗底压着两块冰糖，用纸包着。你走到半路摔了一跤，膝盖磕破了，糖还在兜里，纸磨破了一角。回家母亲问怎么这么晚，你说路上玩。她看了看你的膝盖，什么也没说，拿凉水给你擦。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"喜":1},"flag":"","thread":"兜里那两块冰糖"}},{"title":"回去热一遍","desc":"你端起凉了的汤往家跑，重新烧热，再送一趟。","hint":"汤洒了半碗。","tone":"heal","outcome":"第二趟你跑得急，汤洒了半碗，碗沿烫起一个小泡。母亲开门时愣了一下，接过碗，先摸了摸你的手。她说：傻。她站在门口把汤喝了，喝得很快，白气扑在她脸上。你看见她眼下一片青。她把碗递回来，说：回去睡。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4},"flag":"","thread":""}},{"title":"推门进去","desc":"你推开门，端着篮子走进冷房，放在她脚边。","hint":"冷气扑出来，冻坏一盘芽。","tone":"brave","outcome":"冷气扑到脸上，你打了个抖。她让你出去，你不动。她只好把门关上，两个人在冷房里吃。那盘新芽还是冻坏了半边，她记在册子上，写的是自己的名字。回家路上她把手炉塞给你，自己抱着胳膊走，走得很快。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":""}}]},{"id":"xing_x05","act":"side","age":[13,13],"mode":"narration","title":"渠边的半袋穗","opening":"巡田的人在渠边拦住拾尘会的阿婆。她拾了半袋落穗，袋口没扎，麦芒露在外头。那人说越界拾谷，要收。阿婆不撒手，两只手攥着袋口，手背上全是褐斑。她说就在自己地头拾的。那人说地头也是地。你在渠里洗脚，水凉，脚趾缩起来，脚底下的卵石滑。太阳已经落到望星台后头，田里的麦还没亮起来，一垄一垄伏着，像睡着的脊背。四下没有别人，只有渠水的声音，很细，像有人在很远的地方说话。阿婆看见你了，眼睛在你脸上停了一下，又挪开。","ask":"那人伸手来夺袋子，你上不上？","days":10,"npc":"","memory":"渠边那半袋穗","choices":[{"title":"站到袋子前面","desc":"你从渠里上来，光着一只脚，站在袋子和那人中间。","hint":"他记下了你家的门牌。","tone":"protect","outcome":"那人推了你一把，你摔在渠埂上，半边身子湿了。阿婆趁这工夫把袋子拖走了，拖得很快，像拖一捆柴。那人看了看你，从兜里掏出个小本，记下你家的门牌。回家父亲问你怎么湿的，你说滑了一跤。那晚他给你烧了热水，没再问。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"爱":2},"flag":"","thread":"小本上记着你家门牌"}},{"title":"扯着嗓子喊人","desc":"你朝晒场那边喊，喊到有人回头看。","hint":"她的袋子还是被收走半袋。","tone":"tell","outcome":"人围过来，那人松了手，说按规定收半袋。阿婆坐在地上，把剩下的半袋抱在怀里，抱得很紧。你帮她捡撒在地上的穗，一粒一粒，捡到天全黑。她数到后来不数了，把袋子往怀里一搂。第二天她送来一小把炒麦，麦子是焦的。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"说是你拾的","desc":"你说这袋是你拾的，要收收你的。","hint":"你家的糠被扣了。","tone":"carry","outcome":"那人看了看你，把袋子提到车上，说：算你家的。父亲清点时发现短了，问了一晚上，你只说不知道。阿婆隔天在地头等你，把一小包东西塞进你手里，是七个鸡蛋，用糠裹着，还温。你没要，她塞进你怀里就走了。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}}]},{"id":"xing_x06","act":"side","age":[15,15],"mode":"narration","title":"渠边烧麦","opening":"麦子刚灌浆，穗子还软，掐一把能挤出白水。你、二柱子、还有老韩家的闺女，三个人蹲在渠边挖了个浅坑。麦穗是从三家地里各掐的一把，谁也不许多掐。火是二柱子生的，他趴在地上吹，吹得满脸是灰，眉毛燎了一截，自己还不知道。麦穗在火上翻，麦芒烧得噼啪响，一股焦香往上冒，混着渠水的凉气，往鼻子里钻。老韩家的闺女把烧黑的穗子在掌心里搓，搓出一把青白的麦粒，塞进嘴里，烫得直吸气，又伸手来抢。你的手也黑了，指甲缝里全是碳，舔一下，是苦的。","ask":"第二把麦穗刚架上火，远处有灯过来，怎么办？","days":10,"npc":"","memory":"渠边那堆焦麦","choices":[{"title":"踩灭火装没事","desc":"你一脚踩进坑里，把火和麦穗全踩进泥里。","hint":"鞋底糊了一层焦麦。","tone":"hide","outcome":"火灭了，冒起一股白烟，比火还显眼。三个人蹲在渠埂下头，谁也不敢动。提灯的是巡田的，走过渠埂，站了一下，说：谁在这儿烧东西。没人答。他站了一会儿走了。你们从渠埂下爬出来，坑里的麦穗糊成一团，不能吃了。二柱子说：白瞎。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"喜":2},"flag":"","thread":"鞋底那层焦麦"}},{"title":"分他一把","desc":"你站起来，把烧好的那把递过去，说：尝尝。","hint":"他记住了三家的地。","tone":"warm","outcome":"巡田的接过去，捏了一粒，吹了吹，放进嘴里。他嚼了两下，说：掐早了，没肉。说完又捏了一粒。他蹲下来，在火边烤手，说：下回掐东头那块，那块熟得早。三个人都不敢接话。他走的时候说：坑填了。你们填了坑，回去的路上笑了一路。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":4,"惧":1},"flag":"","thread":""}},{"title":"让他自己来拿","desc":"你不站起来，蹲着说：就几穗，你抓吧。","hint":"他真抓了，抓的是二柱子。","tone":"dodge","outcome":"巡田的走过来，看了看三个人，伸手把二柱子提起来了。二柱子满手是灰，嘴里还含着麦粒，说不出话。他爹被叫来，当着人打了他一巴掌。你和老韩家的闺女蹲在原地，谁也没吭声。第二天二柱子见了你，绕开走。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"","thread":"绕开走的二柱子"}}]},{"id":"xing_s10","act":"side","age":[16,16],"mode":"narration","title":"坑口冒冷气","opening":"十六岁那年，后半夜一声闷响，窗纸白了一下。你提灯跑出去，西头那块地中间多了一个坑，坑口两臂宽，往下看是黑的。坑壁像烧过的碗，摸上去还烫，坑口往外冒的却是冷气，扑在脸上像地窖里出来的风。夜灌灯倒在垄上，油洒了一片，灯芯还冒烟。父亲比你早到，蹲在坑边，一只手伸下去，停在半空。坑底一层白，是星尘。发光的麦穗倒在垄上，最后一点光从坑口透上来，照着他的下巴。","ask":"天快亮了，这个坑你打算怎么办？","days":20,"npc":"","memory":"坑口冒出的冷气","choices":[{"title":"指给拾尘会","desc":"你天不亮就去棚里，把坑指给无田的几户，说我家种不过来。","hint":"你家的地界缩进三尺。","tone":"warm","outcome":"他们扛着锹来，先围着坑磕三个头，才动手清坑壁。农盟按实种划界，你家地往里缩了三尺。父亲在界桩边蹲半晌，把桩扶正，没说话。你替他们挑了三天土，掌心磨出四个泡。那年坑里种出一片麦，夜里亮得很整齐。收糠时他们送来一小袋，父亲没动，你自己煮了吃。","eff":{"bond":1,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"地界缩进的那三尺"}},{"title":"报到望星台","desc":"你跑上台，把落点报给守台的，让他们来插牌封坑。","hint":"父亲夜里去拔了一次牌。","tone":"rule","outcome":"守台的人午后下来，量了坑口，插一块黑木牌，写上落点号。你被记了一功，免了半季的巡田差。当天夜里父亲去拔牌，被巡田的撞见，罚了两斗糠。第二天他把牌子重新插好，插得比原来深。回来他洗了手才吃饭，一顿饭没抬头。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":"父亲拔过一次的木牌"}},{"title":"把种全倒进去","desc":"趁父亲回屋，你把家里留的种全倒进坑心，用脚踩实。","hint":"第二颗星跟着来了。","tone":"gamble","outcome":"出苗只用了七天，长得齐腰高，夜里一片亮，亮得能照见人脸。第九天夜里第二颗星来了，正落在坑里，把新苗连土掀到半空。地棚顶被掀掉一半，你额上留了一道疤。父亲清早去看，回来只说一句：坑吃种。那年你家没留种，开春跟人换了三升。","eff":{"bond":-4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":2},"flag":"","thread":"额上那道疤"}}]},{"id":"xing_s03","act":"side","age":[17,17],"mode":"dialogue","title":"十二里路的沉默","opening":"十七岁秋后，你跟父亲去修渠首的闸。十二里路，来回一天。他一路上只说了三句话：走这边；水别踩；天要变。晌午坐在渠边啃冷馍，他把馍掰成两半，大的给你。他蹲着抓土，抓了很久，指缝里漏下去，又抓一把。两边的麦在夜里亮着，光落在渠水上，一晃一晃。你想说去城里的事，话到嘴边，他先站起来，说：走了。回来的路上你们没再说一个字。夜灌灯挂在车把上，星尘落在馍上，也没人掸。","ask":"到院门口了，这沉默你破不破？","days":10,"npc":"father","memory":"十二里的沉默","choices":[{"title":"蹲下抓把土","desc":"你在院门口蹲下，也抓一把土，摊在手心给他看。","hint":"那句话说回去，咽了很多年。","tone":"learn","outcome":"他停下来，看了你手心里的土，伸出两根手指，把里头一块碎星挑掉。他说：这土认人。这是他那天最后一句话。你去城里的话没出口，后来也没再找到那样的机会。第二年开春，他往你那双旧鞋里塞了半袋干粮，什么也没说。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":2},"flag":"left_words_unsaid","thread":"那句去城里的话没出口"}},{"title":"把话说完","desc":"你说冬天过后就跟小满进城，不再下田了。","hint":"他先进屋，门没关。","tone":"honest","outcome":"他听完，把夜灌灯从车把上解下来，塞进你怀里，说：城里也用得着。他先进了屋，门没关严，灯光从门缝里漏出来，照在门槛上。母亲在你门外站了很久，脚步声来回。你走的那天，他没送到坑口，只在你包里塞了一双新纳的鞋。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":""}},{"title":"说个城里的笑话","desc":"你笑着说城里人管星糠叫土，把话岔过去。","hint":"他笑得不是地方。","tone":"dodge","outcome":"他笑了一声，笑得不是地方，笑完低头把灯芯剪短。那晚他多喝了一碗粥，母亲看了你一眼。后来你们还有过很多次沉默，可这一次不一样：这一次两个人都等着对方先开口，谁也没有。你后来想起渠上的风，总记得他掰馍时手上那层土。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"xing_x07","act":"side","age":[17,17],"mode":"narration","title":"没熄的那盏灯","opening":"你在地里放水，望星台的钟没响。先是风停了，接着天上亮起来。你抬头，看见一层白从西边压过来，压得很低，像一床湿被子。父亲说过，这种时候先熄灯，灯会招星。灯就在你脚边的垄上，罩子开着，火苗被风拉得偏了。你伸手去推，手抖，推了两次没推上。第一粒星尘落在你手背上，烫了一下，像烟灰，你还闻到一点自己皮肉的焦味。田里的麦忽然全亮了，亮得能看见自己的影子，影子往西倒，很长。到地棚还有半里，中间隔着一道渠。第二层白已经压到头顶，风又起来了。","ask":"灯还亮着，半里外是地棚，先做什么？","days":15,"npc":"","memory":"没推上的灯罩","choices":[{"title":"先推灯罩","desc":"你蹲下去，两只手压住灯罩，推死了才起身。","hint":"手背烫出一片白泡。","tone":"rule","outcome":"灯罩合上时火苗跳了一下，灭了。你抱着灯往地棚跑，跑到半路跌进渠沟，膝盖磕在石头上。地棚里的人把你拉进去，有人拍你背上的火星。你的手背起了一片白泡，后来留下一块疤，摸上去是硬的，冬天发亮。","eff":{"bond":1,"health":-2,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"喜":1},"flag":"","thread":""}},{"title":"扔下灯就跑","desc":"你把灯丢在垄上，什么也不管，往地棚跑。","hint":"灯化了，一垄麦焦了。","tone":"escape","outcome":"你跑进地棚时腿软，跪在地上。外面亮得像白天，那盏灯在田里烧，火苗被风扯得很长。第二天去看，灯没了，铜底座化在土里，周围一垄麦烧成黑灰。父亲蹲在灰里找了半天，只找到那根灯绳，绳头是焦的。","eff":{"bond":-3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"哀":2},"flag":"","thread":"化在土里的铜底座"}},{"title":"抱灯滚进渠沟","desc":"你抱着灯滚下渠沟，用身子压住，脸埋进泥里。","hint":"你在泥水里泡了半个时辰。","tone":"hide","outcome":"水很浅，冰凉，泥进了耳朵。你听见星尘落在水上，沙沙响，像下小雨。有一粒落在后颈，烫得你一抖，你没动。等声音停了，你从沟里爬出来，浑身是泥，灯还亮着。父亲在田头找你，提灯照见你，说：像只泥猪。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":2},"flag":"","thread":""}}]},{"id":"xing_x08","act":"side","age":[19,19],"mode":"dialogue","title":"半块糖","opening":"小满要去陨铁城了。行李是一只木箱，箱角用铁皮包过，钉子敲得歪。她走的前一晚坐在灶边，把口袋里攒的糖一块一块掏出来，摆在案板上。糖是从城里带回来的，用油纸包着，有几块化了，粘在纸上，撕不开。她一边掏一边说城里的事，说仓房、说管账的先生、说城里的面是白的，说她去了就能穿上那种褂子。说到后来不说了，把最后一块糖掰成两半，一半塞给你。灶膛里的火快灭了，屋里暗下来，只有糖纸反一点光，照着她手背上的一小片油。她把那一半含在嘴里，没嚼。","ask":"那半块糖在你手里，你说什么？","days":10,"npc":"sibling","memory":"案板上那半块糖","choices":[{"title":"说不好就回来","desc":"你说：城里要是不好，就回来。","hint":"她笑了一下，没接话。","tone":"warm","outcome":"她把糖纸抚平，折成一个小方块，塞进你兜里。她说：回来干什么，回来种地？你说种地也不差。她没再说，低头把木箱的锁扣按了按。第二天她走的时候没叫你，你醒来时灶上留着一碗粥，还是温的，碗边搁着那双她补过的鞋。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"塞给她几粒种","desc":"你从墙洞里摸出几粒黑种，用纸包了，放进箱底。","hint":"那几粒种你攒了三年。","tone":"secret","outcome":"她看着你包，问是什么。你说是种。她说城里不能种。你说那就放着。她把纸包捏了捏，放进箱底，压在衣服底下。三年后她回来，那包种还在箱底，纸黄了，她没种，也没扔。她说：我一直带着。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":1},"flag":"gave_seeds_to_sister","thread":"箱底那包黄纸"}},{"title":"把糖吃了不说话","desc":"你把糖含在嘴里，一句话也没说。","hint":"她等了一会儿才起身。","tone":"keep","outcome":"糖很甜，甜到后来发苦。她坐了一会儿，见你不说话，就站起来，把案板上的糖纸一张张收进袖子。进屋前她在门口站了一下，说：我走了。你说嗯。第二天她走时你还在睡，醒来木箱已经不在了，案板上留着一层糖渣，蚂蚁排成一条线。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}}]},{"id":"xing_x09","act":"side","age":[20,20],"mode":"narration","title":"不能指星","opening":"农盟在晒场上贴了新告示：指星骂天者，罚糠三斗。字是请城里先生写的，一笔一划，贴在告示栏最上头。老祁不识字，站在那儿听人念，念完他哼了一声，说：破星，落了又不长东西。话音刚落，巡田的从人堆后头转出来，说：老祁，你骂了。老祁的脸一下白了，两只手在裤子上擦，擦了两下又擦两下。他被记了名，罚三斗糠。他拉住你的袖子，说：你替我说说，我不是骂，我是说猪。他说着，嘴一撇，学了一声猪叫，学得很像，连鼻子都皱起来。人堆里有人笑，巡田的没笑。","ask":"老祁冲你挤眼，还学了猪叫，你怎么说？","days":12,"npc":"","memory":"晒场上那声猪叫","choices":[{"title":"照实说他骂了","desc":"你对巡田的说：他骂了，我听见了。","hint":"他再没找你借过牛。","tone":"honest","outcome":"巡田的把名字记牢，罚三斗，限三天交。老祁站在原地看着你，看了很久，什么也没说。第三天他挑着糠去农盟，路过你家门口没停。他婆娘后来在井台上跟你娘说：你家那口子嘴直。这话传了半年，传到最后变成：你家那口子卖人。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"","thread":"井台上那句话"}},{"title":"替他作证说猪","desc":"你说：他是在骂他家那头猪，猪拱了圈门。","hint":"巡田的让你也按个手印。","tone":"protect","outcome":"巡田的盯着你看了半晌，把册子推过来，让你按手印作证。你按了。他收起册子，说：两个人一起罚，一人一半。老祁当场就急了，你按住他的胳膊。三斗糠分下来，你家一斗半。老祁第二天送来一斗，你退了半升，他硬塞回来。","eff":{"bond":4,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"怒":1},"flag":"vouched_for_qi","thread":"册子上并排的两个手印"}},{"title":"当着人学猪叫","desc":"你也学了一声猪叫，说：是这个声吧。","hint":"满场笑成一片。","tone":"rebel","outcome":"满场人笑弯了腰，巡田的也绷不住，嘴角抽了两下。他最后把册子合上，说：下不为例，三斗免了，罚他给晒场扫三天。老祁扫了三天场，扫得干干净净，边扫边骂猪。那三天村里人来看他扫地，比看星雨的人还多。","eff":{"bond":3,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":2},"emotion":{"喜":4,"恶":1},"flag":"","thread":""}}]},{"id":"xing_s11","act":"side","age":[21,21],"mode":"dialogue","title":"灯下的怕死","opening":"二十一岁那年秋后，望星台来招记星的学徒，考三天，考上就住在台上。报名要一块竹牌，牌子搁在灶台上，还没写名字。那晚父亲让你替他穿针，针眼对着灯，怎么也对不上。他的眼睛是那年星尘灼坏的，看人只剩一个轮廓。线穿过去，他捏住，忽然说：我怕死。他说得很慢，像在说别人家的事。夜灌灯在桌上，灯罩落了一层星尘，冷气从门缝底下进来，贴着脚背走。窗外发光的麦穗一直亮到天亮。","ask":"他捏着线不动，你怎么接这句话？","days":15,"npc":"father","memory":"灯下那句怕死","choices":[{"title":"把竹牌烧了","desc":"你把那块没写名字的竹牌塞进灶膛，说：我不去了。","hint":"他没问为什么。","tone":"stay","outcome":"竹牌烧出一股焦味。他把针线放下，看了灶膛一眼，没问。第二天他照常天不亮下田，回来时给你带了一双新草鞋。台上的人第三天就走了，招满了。你留下替他放了三年水，学会看云、看风、看坑口的白气。三年后你想去考，招人的说，年纪过了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"三年后再去，年纪过了"}},{"title":"说他的肺","desc":"你说星尘早进了他的肺，咳成这样，撑不过下个陨季。","hint":"他把种袋放下了。","tone":"honest","outcome":"他捏着针的手停在半空，过了很久，把种袋放下，说：我知道。那夜他咳得比往常久，母亲起来给他烧水。第二天他开始把地里的活一件件交给你，交得很急，像在赶什么。他不再下田，坐在门槛上看你走，看了三年。他到底又过了六个陨季。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":2},"flag":"","thread":"他提前交出来的地"}},{"title":"让他教怕的事","desc":"你问他：你怕的事有几件，一件件教我，我记着。","hint":"他教得像在交代后事。","tone":"learn","outcome":"他愣了一下，笑了一声，说：你这孩子。第二天起他教你认星、听水、辨土，一样一样，讲到第三样时不讲了，说：够了。你后来才知道，他讲的都是他一个人会的，母亲一样也不会。那些话你记在本子上，本子后来受了潮，字糊了一半。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"哀":3},"flag":"","thread":"受潮的本子"}}]},{"id":"xing_x10","act":"side","age":[22,22],"mode":"narration","title":"评亮会","opening":"农盟办星穗评比，一家送三穗，看谁的麦夜里最亮。头名奖半斗种，还上望星台的册子。晒场上摆了长桌，桌上铺黑布，穗子一排摆开，亮得像一排小灯。有人不服，说亮不亮看的是土，不是人。也有人说自家那三穗是特意留的。评到一半，风把黑布吹起来，桌上一穗滚下去，摔断了，断口里是空的。那人当场就急了，说是谁碰的。老祁蹲下去把断穗捡起来，举到眼前看，说：这穗里塞了星糠。满场静了。黑布边上落了一层星尘，一碰就白；桌腿下头还压着去年的旧告示，边角卷了。","ask":"老祁举着那截断穗，满场人看你，你说什么？","days":12,"npc":"","memory":"评亮会那截断穗","choices":[{"title":"让他把穗掰开","desc":"你说：都掰开看，谁的穗里塞了东西，自己说。","hint":"掰到第三家就没人吭声了。","tone":"ask","outcome":"头两穗是实的，第三穗一掰，糠末子往下掉。那家男人站着不动，他婆娘在人群外头哭。农盟的人把评比停了，说今年不评了。三穗断在桌上，谁也没拿走。散场时老祁把那半斗种抱回去了，说：本来也不该这么评。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"喜":2},"flag":"","thread":"桌上那三截断穗"}},{"title":"说评土不评穗","desc":"你说：亮是土给的，要评去评坑，别评人。","hint":"农盟的人记了你的话。","tone":"rebel","outcome":"农盟的人愣了一下，真去把各家的地走了一遍，量了坑心的远近。评比改成评地，头名给了靠坑心最近的那家，那家去年刚死了男人。半斗种送到他家门口，他婆娘不开门。老祁说：这还不如评穗。你没接话。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"喜":1},"flag":"","thread":""}},{"title":"把自己三穗收回","desc":"你不说话，走过去把自家三穗拿了，揣进怀里就走。","hint":"头名给了老祁家。","tone":"quit","outcome":"你走出晒场，穗子在怀里硌着肋骨。评到最后头名给了老祁家，他家那三穗确实亮。第二天他把半斗种分了一半给你，说：你家的也亮，就是不圆。你收下了。那半斗种你种在西头，出苗比别家晚三天。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":2},"flag":"","thread":""}}]},{"id":"xing_x11","act":"side","age":[24,24],"mode":"narration","title":"哑钟","opening":"望星台换了新钟，是农盟凑糠铸的，钟身上铸了一圈麦穗。挂上去那天敲了三下，声音闷，像敲在一口装满土的缸上。守台的老瞿说是钟舌短了，垫了一块铁片，再敲，还是不响。他敲了半个月，敲得胳膊抬不起来。这天夜里该有星雨，村里人等钟，等到后半夜没动静，以为台上的人睡死了。二十几个人打着灯上坡，走到台下一看，老瞿正抱着钟槌敲，一下一下，满头是汗，钟一声不出。坡上的风把灯吹得斜，人影在台上晃来晃去。老瞿的汗滴在钟上，一滴一滴，砸出小坑。","ask":"老瞿还在敲，满坡人都看着，怎么办？","days":12,"npc":"","memory":"台上那口哑钟","choices":[{"title":"上去替他敲","desc":"你接过钟槌，让老瞿歇着，自己抡起来敲。","hint":"你的虎口震裂了。","tone":"help","outcome":"你敲了十几下，虎口裂开一道口子，血渗到槌柄上。钟还是不响，只发出一种很闷的嗡。底下有人笑，说这钟是哑巴投的胎。老瞿蹲在台边，看着钟，说：响不了就不响吧，我拿锣。第二天他真找了面破锣，星雨来的时候敲锣，声音尖，全村都听见了。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"哀":2},"flag":"","thread":"虎口上那道口子"}},{"title":"说这钟铸歪了","desc":"你绕着钟看了一圈，说：不是舌的事，是钟身歪了。","hint":"铸钟的人记了你。","tone":"ask","outcome":"你伸手在钟口上摸，一边厚一边薄，差了一指。老瞿凑过来摸，摸了半天，说：怪不得。第二天农盟来人，把钟卸下来，横放在台上，看了半天，说重铸。铸钟的是城里来的匠人，站在旁边不说话，走的时候看了你一眼。新钟挂上去，第一下就响了。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"智识":2},"emotion":{"喜":4,"怒":1},"flag":"","thread":""}},{"title":"领人先躲雨","desc":"你说钟不响就不响，先带人下坡进地棚。","hint":"那夜星落得比报的早。","tone":"practical","outcome":"你把人带下坡，赶到地棚里。刚关上门，天上就白了，落得比报的早半个时辰。棚里挤着二十几个人，谁也没说话，只听见外头沙沙响。第二天有人说，要不是你，那一夜得有人躺在坡上。老瞿没下来，他在台上守了一夜，钟还是没响。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"喜":2},"flag":"","thread":""}}]},{"id":"xing_s04","act":"side","age":[26,26],"mode":"narration","title":"地棚底下的敲声","opening":"二十六岁那年陨季，你在地棚里守夜。星雨在外头，夜灌灯的灯罩推死了，棚里只闻得见草席和湿土。后半夜，土里有声音：三下，停一停，又三下。不重，像有人用指节敲一只扣着的碗。你把耳朵贴到地上，土是温的，比棚里的空气暖。你想起望星台的钟这些年一直缺一声，守台的人说钟舌早年丢了。棚外一阵风，星尘从缝里漏进来，落在手背上，像细盐。","ask":"那声音又响了三下，你怎么办？","days":15,"npc":"","memory":"土里三下敲碗声","choices":[{"title":"挖出来埋回去","desc":"你挖开棚底的土，把挖出的东西裹好，送到坡上无名坟前。","hint":"半袋种受了潮。","tone":"escort","outcome":"挖出来是一截铜舌，裹在烂布里，布上还系着一根褪色的绳。你冒雨把它送到坡上那座没有名字的坟前，挖了个浅坑埋了。回棚时灯被风吹灭，半袋种受了潮，出芽少了三成。那夜你咳到天亮，后来每到星雨就咳几声。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"buried_bell_clapper","thread":"半袋种受了潮"}},{"title":"报给望星台","desc":"天一亮你就上台，把地棚底下有东西的事说了。","hint":"阿婆再没跟你说过话。","tone":"report","outcome":"守台的人带着锹下来，挖走了那截铜舌，说要化了铸新钟。隔壁独眼的阿婆在棚外站了一夜，第二天问你：底下还有声音没有。你说没有了。她看了你很久，转身回屋，门关得很轻。从那以后她再没跟你说过话，晒场碰见也只点一下头。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}},{"title":"把土拍平","desc":"你把土填回去，压上两块砖，吹灯睡了。","hint":"大星雨的夜里它还响。","tone":"keep","outcome":"土拍平了，砖也压上了。后来每到大星雨，那底下还是会响三下，不多不少。你没再挖，也没跟人说。住过这棚的人换了几茬，都说这棚子夜里不干净，睡到半夜总听见有人敲碗。你照旧每年住进去，照旧不解释。","eff":{"bond":0,"health":-1,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":1},"flag":"","thread":""}}]},{"id":"xing_x12","act":"side","age":[26,26],"mode":"narration","title":"晒场上的秤","opening":"收购的人在晒场上摆开秤，秤砣是陨铁打的，黑得发亮。他抓起一把星糠，用牙咬，说潮，报的价比去年低四成。父亲没吭声。旁边几家也没吭声，都看着自己脚边的袋子，像在看别人的东西。收购的人说，今年城里仓满，不收也行，反正路上还有三辆车。晒场上风大，糠皮卷起来，粘在人脸上，粘在汗上，拍不掉。你走过去，把自家那袋糠提起来，解开袋口，整袋倒在秤盘上。糠堆得比秤盘高，往下淌，落在秤砣边上。四周一下静了，连风都像停了。","ask":"糠倒在秤上，收购的人看着你，你说什么？","days":10,"npc":"","memory":"倒空的那袋糠","choices":[{"title":"让他当众咬","desc":"你说：你咬，咬着哪粒是潮的，指给我看。","hint":"他记住了你的脸。","tone":"defy","outcome":"他站着没动，牙关咬着，脸上一层油汗。围观的人往前挪了半步。他最后把手里的那把糠撒回秤盘，说：不收了。车赶出坑口时，没人送。父亲蹲下去，一捧一捧把糠捧回袋里，捧了很久。那年冬天，你家的糠是自己挑进城卖的。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"魅力":2},"emotion":{"怒":3,"喜":2},"flag":"stood_up_to_buyer","thread":""}},{"title":"说价照旧秤要换","desc":"你说价按你的，秤换一杆，当众校。","hint":"校秤的三家都被记了名。","tone":"bargain","outcome":"他愣了一下，从车上取了另一杆秤。校完，一斤少二两。围观的人炸了。他当场把秤砸了，重新称，价还是那个价，可每家的糠多出来几斤。称到第三家，他不看人了。回家路上父亲说：你今天像个当家的。他说完咳了两声。","eff":{"bond":3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"喜":3,"怒":1},"flag":"","thread":""}},{"title":"把糠倒回袋里","desc":"你一言不发，把秤上的糠捧回袋里，扛起就走。","hint":"父亲跟在你后头。","tone":"quit","outcome":"你扛着袋子走出晒场，父亲跟在后头，走了半里才说：不卖了？你说不卖了。他那年没再提这事，只在入冬前把糠挑进城，一趟走一天，回来时鞋底磨穿了。城里给的价比收购的高一点，扣掉脚力，剩的差不多。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"哀":2},"flag":"","thread":""}}]},{"id":"xing_s12","act":"side","age":[29,29],"mode":"narration","title":"图上那个矿字","opening":"二十九岁那年开春，陨铁城来了七个人、两辆车。他们在坑口立杆，红布被风吹得啪啪响。领头的人摊开图，银穗坑被画成一个方，方里一个字：矿。他说底下有陨铁脉，要整片收，签契的搬到坡上去，补三年糠。农盟的人手插在袖子里，不说话。地里发光的麦穗亮着，风里有冷气，把星尘刮到图上，那七个人也不掸。小满穿城里的褂子，站在后头，不看你。父亲把图倒着拿很久，递给你，说：你念。","ask":"图在你手里，你先念哪一段？","days":40,"npc":"","memory":"图上那个矿字","choices":[{"title":"把契念给全村","desc":"你站到碾盘上，把契从头到尾念一遍，念给围过来的人听。","hint":"你家的水先断了。","tone":"protect","outcome":"念到永不复耕那一句，人群里有人骂了一声，接着都骂起来。七个人收了图走了，说回去请示。第三天渠水小了，你家的田在渠尾，一滴没进。父亲扛着锹去渠首守了三夜，回来时鞋上全是泥。那年秋后，全村有一半人家偷偷签了。","eff":{"bond":2,"health":-2,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":"渠尾断水的那三夜"}},{"title":"劝父亲按手印","desc":"你把契上的条款一条条讲给他听，说这地种不下去了，签吧。","hint":"他按完手印去地里坐着。","tone":"practical","outcome":"他听完，把手在裤子上擦了擦，按了。按完他没回家，往银穗坑走，在界桩边坐到天黑。第二天他又去，坐了一整天。母亲送饭过去，碗原样端回来。头一年的糠发下来了，他一粒没动。搬上坡那天，他把夜灌灯挂在界桩上，没带走。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":2},"flag":"","thread":"界桩上挂着的灯"}},{"title":"让小满捎个名","desc":"你连夜找小满，让她把你的名字从户册上挪进城里去。","hint":"父亲的名字留在契上。","tone":"deal","outcome":"小满在册子上添了一笔，说下不为例。三天后你进了城，在仓房里点数星糠，手上不再有土。父亲一个人按了手印，一个人搬上坡。你走时他没送，只把你的旧鞋摆在门槛上，鞋里塞了一双新纳的。第二年你托人捎糠回去，糠退回来了，口袋是空的。","eff":{"bond":-4,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"退回来的空口袋"}}]},{"id":"xing_x13","act":"side","age":[29,29],"mode":"dialogue","title":"空着的那一格","opening":"母亲让你去冷房替她取一包种，说要给南头那家补。格子有木牌，写着年份和姓。你按她说的找到第三排，看见一块牌上写着自家姓，年份是你出生那年。你顺手拉开，里面是一只纸包，纸已经脆了，一碰掉渣。包得很认真，四角都折进去，麻绳绕了两圈，结打在背面。你把它捧到灯下拆开，里头是空的，一粒种也没有，只有一层黑末，粘在纸上，像烧过的灰。外头母亲在台阶上等着，脚轻轻地跺，冷气从门槛底下往外爬。台阶上的霜化了一小片，她站在那片湿里。","ask":"空纸包在你手里，你问她吗？","days":20,"npc":"mother","memory":"空着的那一格","choices":[{"title":"拿出去问她","desc":"你把空纸包捧到台阶上，问这是哪一年的。","hint":"她说那年的种没出芽。","tone":"ask","outcome":"她看了一眼，手停在半空，说：你出生那年，落星落得凶，种下去全烂在土里，这一包是留下的最后一把。她说她一直没敢扔，怕扔了就真的一年也没有了。她把纸包接过去，抚平，揣进围裙口袋。那天要补的那包种，她后来自己又跑了一趟。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":3},"flag":"knows_empty_seed_packet","thread":"她揣进围裙的那只纸包"}},{"title":"抓把新种填进去","desc":"你从旁边格子抓了一把种，倒进空纸包，重新包好。","hint":"纸包鼓起来，牌子还是那年的。","tone":"sneak","outcome":"纸包鼓起来，绳子绕不上了，你换了根新绳。牌子还是那年的。母亲进来催，你把纸包塞回格子，说找着了。她看了一眼，没说话，伸手在纸包上摸了摸，摸到饱满的粒。她把牌子摘下来，翻过来，在背面写了两个字，又挂回去。写的是：补的。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"把空包收进怀里","desc":"你不问，把空纸包折好，塞进自己怀里，另取一包给她。","hint":"她接过去时看了你一眼。","tone":"keep","outcome":"你另取了一包，捧出去给她。她接过去，看了你一眼，又看了看你胸口鼓起来的那块，什么也没问。回家你把那张脆纸压在米缸底下，跟别的纸包放在一处。后来每次舀糠，都能听见那点纸响，很轻，像有人在底下翻身。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}}]},{"id":"xing_x14","act":"side","age":[32,32],"mode":"narration","title":"初七和十七","opening":"望星台新来的徒弟姓周，二十二岁，戴一副铜边眼镜，说话爱用手指头点人。他挨家挨户通知播种的日子，手里捧着一本册子，念：初七下种。全村信了，初六夜里就把种都撒了下去。初八天亮，农盟的人来查，说谁让你们播的，星历上写的是十七。晒场上站了半村人，都把册子翻出来看。徒弟翻到那一页，脸白了。那一页的字是老的观星人写的，一笔潦草，初七的七，写得像个十七。他一只手扶着册子，一只手在页边搓，搓出一道毛边。他咽了一口唾沫，喉结上下动了一下。","ask":"满场人都看着徒弟，你先说什么？","days":15,"npc":"","memory":"册子上那个七","choices":[{"title":"替他认下来","desc":"你说册子是你们看错的，不怪他。","hint":"他后来每年给你送星历。","tone":"protect","outcome":"农盟罚了半季的水，摊在全村头上。徒弟站在人堆里，眼镜滑到鼻尖，没敢扶。散场后他跟在你后头走了很远，说：我知道是我念错了。你说知道就行。他第二年送来一本新星历，纸是白的，字是刻的，一格一格，再没有草字。他送了七年，送到调走。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":2,"哀":1},"flag":"","thread":""}},{"title":"带他找老观星人","desc":"你揪着他的袖子，把他拽上望星台，让师父认这个字。","hint":"老头笑了很久。","tone":"honest","outcome":"老头把册子举到眼前，看了半天，笑了，笑得直咳，说这个七我写了一辈子，头一回见人念成十七。他笑完在页边补了一个正楷的七，又把册子推回去，说：这本给你，我重抄一本。徒弟捧着册子下楼，一路没说话，走到半坡才说：丢人。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"哀":1},"flag":"","thread":""}},{"title":"刨出来重播","desc":"你不吵，回家扛锹，把刚下的种一垄一垄刨出来。","hint":"刨出来的种沾了泥。","tone":"grind","outcome":"刨了两天，种捡回来大半，沾着泥，摊在席上晒。晒干了重新拌了星糠，等十七那天下种。那年出苗晚了十天，穗子比别人家的短，可没绝收。徒弟来帮了半天，蹲在垄上刨，眼镜掉进沟里，摸了很久。","eff":{"bond":0,"health":-3,"reputation":1,"coins":0,"stats":{"体魄":2},"emotion":{"哀":2,"喜":2},"flag":"","thread":""}}]},{"id":"xing_x15","act":"side","age":[35,35],"mode":"narration","title":"烫手的石头","opening":"孩子在田里捡回来一块石头，鸭蛋大，黑里透红。他说会热。你接过来，石头是温的，握久了有点烫，得倒手。你把它搁在灶台上，想等凉了再看。半夜灶间响了一声，像有人往锅里扔了一粒豆。你起来，看见灶台上那块石头红透了，搁板冒着烟，火苗从裂缝往上舔，舔到了房梁，舔出一线黑。孩子还在里屋睡，母亲的手炉搁在门边。屋里有股焦木头的味，很冲，呛得喉咙发紧。房梁上开始有东西往下掉，一小块一小块，落在灶台上，还带着火。你赤着脚跑出去，脚底踩到一块凉的东西。","ask":"房梁着了，孩子还在里屋，先做什么？","days":10,"npc":"","memory":"灶台上那块红石头","choices":[{"title":"抱孩子冲出去","desc":"你冲进里屋，把孩子连被子一起抱起来往外跑。","hint":"那间屋烧掉了半间。","tone":"protect","outcome":"孩子在你怀里醒过来，问怎么了。你没答，跑到院里才放下。回头看，火已经上了屋顶，半间屋的梁塌下来，砸在灶台上，火星子溅到院里。邻居提着水桶赶来，水泼上去，噗的一声，白气腾起来。石头在灰里还是红的，天亮才暗下去。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"爱":3},"flag":"","thread":"烧掉的半间屋"}},{"title":"端水泼石头","desc":"你舀起一盆水，兜头泼在石头上。","hint":"石头裂了，迸了一屋子火星。","tone":"risk","outcome":"水泼上去，石头炸开一道缝，火星子迸出来，落了一灶台。你的胳膊上烫了七八个点，最大的一个有指甲盖大。火小了一点，可房梁上的火还在烧。你抓过被子扑，扑了十几下，火才压住。孩子自己醒了，站在里屋门口看，没哭。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":4,"喜":1},"flag":"","thread":""}},{"title":"先把石头挑出去","desc":"你用火钳夹住石头，扔到院里的雪堆上。","hint":"雪化了，石头还在烧。","tone":"practical","outcome":"石头扔进雪里，雪化了半尺，露出底下的土，土也烧黑了，石头还在红。你回屋，房梁上的火已经烧大了，你和母亲一人一桶水，泼到天亮。孩子一直在里屋没出来，第二天问他，他说他听见了，不敢动。屋梁烧焦了一截，用绳子绑了三年。","eff":{"bond":-1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"","thread":""}}]},{"id":"xing_x16","act":"side","age":[38,38],"mode":"narration","title":"名签","opening":"北渠决了口，农盟来征丁，一家一签，抽中的下水堵口。抽签在晒场上，签是竹片，一头黑一头白。老韩家的儿子抽中了，他十七，上个月刚埋了他爹，人瘦得褂子空着。他捏着签站在那儿，手一直在抖，抖得竹片响。旁边有人低声说：他家就剩他一个了。风从渠那边过来，带着水的凉气，吹得人后颈发紧。农盟的人已经开始念下一个名字，念得很快，像在念一串不相干的东西。你走过去，把他手里的签抽出来，换了自己那根。竹片换手的时候，两根都还是温的。","ask":"两根签换了手，农盟的人抬头，你说什么？","days":15,"npc":"","memory":"换过去的名签","choices":[{"title":"说我家多个男丁","desc":"你说：他家没劳力了，我家有，我去。","hint":"你娘在人群外头站着。","tone":"carry","outcome":"农盟的人看了看册子，把你的名字写上，划掉他的。老韩家的儿子站在原地，嘴唇动了两下，没出声。你娘在人堆外头，手攥着围裙。下水那天水冷得刺骨，你在水里泡了两个时辰，上来时腿不是自己的。他后来每年开春来帮你家修渠，修了十年。","eff":{"bond":2,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":2},"emotion":{"爱":2,"惧":2},"flag":"took_draft_slot","thread":"水里泡坏的两条腿"}},{"title":"跟农盟讲他家","desc":"你把册子按住，说他家只剩一个人，按规矩该免。","hint":"规矩上没这一条。","tone":"ask","outcome":"农盟的人翻了三页，说：册上没写孤丁免役。他把你的手拨开，念了下一个名字。你回头看那孩子，他还捏着签，捏得指节发白。那天晚上你去了他家，他坐在灶前烧水，说：我去就我去。水开了，他没动，壶盖一直响。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}},{"title":"陪他一起下水","desc":"你不换签，说：我陪你下去，两个人堵得快。","hint":"两个人都下了水。","tone":"escort","outcome":"农盟的人说名额是一个，你去了算白搭。你还是去了。水里你们两个扛一个草袋，他的牙一直在打颤，你让他咬着草绳。堵到半夜，口子合上了。上来时他蹲在地上吐，吐完抬头说：我爹要是看见我今天，会骂我。","eff":{"bond":3,"health":-3,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}}]},{"id":"xing_s13","act":"side","age":[39,39],"mode":"narration","title":"说星的人","opening":"三十九岁那年大星雨，村里人都进了地棚，只有坡口的瞎子全不肯进，坐在门槛上，脸朝天。他八岁瞎的，没见过星雨，耳朵却灵，能听出星落在第几道渠。风起来了，第一层星尘落在他的白发上，白上加白。坡下发光的麦穗看不出来，只听叶响。渠水泛上来一股冷气，贴着他的裤脚。夜灌灯在他脚边，灯罩推死了。他伸手在空气里摸，摸到你的袖子，说：你在这儿吧。你给我说说，它们长什么样。","ask":"他的手抓着你的袖子，你怎么说？","days":12,"npc":"","memory":"瞎子全的白头发","choices":[{"title":"坐下来慢慢说","desc":"你在门槛上坐下，一颗一颗说给他听，说到天亮。","hint":"你的麦烂在地里。","tone":"warm","outcome":"你说星是白的，落下来先亮一下，再暗一下，像有人在上头撒谷。他跟着点头，嘴里数着，数到七十三就乱了。天亮时他的眉毛上全是白。你那两夜该抢收的麦烂在垄上，穗子发了黑，一捻就碎。第二年春天他走了，走前跟人说，他看过一场星雨。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"烂在地里的两夜麦"}},{"title":"背他进地棚","desc":"你弯腰把他背上，任他捶你的背，塞进地棚里闩上门。","hint":"他再没跟人说过星。","tone":"protect","outcome":"他在棚里捶门，捶了很久，骂你不孝，骂到嗓子哑了才停。星雨过后他出来，谁问都不说话，坐在门槛上抽了半天旱烟。他冬天走的，收拾东西时，他儿子在拐杖上数出七十多道刻痕，一道一道，深浅不一。你不知道那是哪一年的星。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"哀":4},"flag":"","thread":"拐杖上的七十道刻痕"}},{"title":"转身去抢收","desc":"你说星雨没什么好看的，提灯下地，去割你自己的麦。","hint":"他在门槛上坐到天亮。","tone":"practical","outcome":"你割了两夜，麦子全进了仓，一粒没烂。回来时他还坐在门槛上，衣襟落满星尘，眉毛白了一层。他问你星落完了没有，你说落完了。他哦了一声，说：我听见了。那年冬天他走了。后来每次听见星落，你都想起那句我听见了，可你始终没告诉他，星是什么颜色。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"没告诉他的颜色"}}]},{"id":"xing_s05","act":"side","age":[41,41],"mode":"narration","title":"挂在梁上的种袋","opening":"四十一岁那年冬，米缸见了底，留种的布袋挂在灶房梁上。后半夜你听见灶房有响，提灯过去，看见邻家的石头踩在凳子上，一只手伸进种袋里，指甲缝里全是麦。他十二岁，瘦得脖子上的筋一根根看得清。见了你，手没抽出来，只说：我娘三天没吃东西了。窗外地里的麦还亮着，光贴在窗纸上。灯罩上落了一层白，是星尘，冷气从缸底往上冒，扑在脚背上。","ask":"他的手还在种袋里，你怎么做？","days":20,"npc":"","memory":"梁上的种布袋","choices":[{"title":"倒给他半袋种","desc":"你把他抱下凳子，倒半袋种给他，又抓两把糠掺进去。","hint":"开春你家少种两垄。","tone":"warm","outcome":"他抱着袋子跑了，跑到门口又回头，把掉在地上的几粒捡干净。开春你家少种两垄，秋后短了半袋。他娘清明那天来还空袋，袋里装着七个鸡蛋，蛋上沾着糠，放在门槛上就走了。那两垄荒了一年草，你没锄。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"fed_stone","thread":"那两垄荒了一年草"}},{"title":"收袋报给农盟","desc":"你夺下种袋挂回梁上，天亮去农盟叫了巡田的人。","hint":"石头以后绕着你走。","tone":"report","outcome":"巡田的人来了，把石头带回家，在他家门上画了一道黑。他娘在门口跪了半宿，第二天照常去拾谷，没跟人说话。春天他家那块地荒着，草长到腰。你按规矩办了，那年冬天你家一粒没少。石头后来见你就绕着走，绕得很远。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"","thread":""}},{"title":"只留他吃一顿","desc":"你把种袋挂回梁上，用最后一点糠煮了粥，看他吃完。","hint":"他空着手回家了。","tone":"practical","outcome":"粥很稀，他喝得很快，碗底都舔干净了。你送他到门口，他站住，等你转身去拿种袋，你没转。他懂了，低着头走进黑里。第二天他娘来借簸箕，站在门外没进来。你后来常想起那只碗，碗沿上有一道缺口，是他咬的。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":"碗沿上那道缺口"}}]},{"id":"xing_x17","act":"side","age":[42,42],"mode":"narration","title":"门槛上的凉席","opening":"母亲这两年睡得少。你夜里放水回来，总看见门槛上坐着个人，背靠着门框，膝上搭一条凉席。她听见脚步就站起来，说：锅里有。锅里的饭用棉布裹了三层，还温着，掀开时一股热气扑到脸上，混着柴火味。有天你回来得比往常晚，渠那边堵了一阵，远远看见她歪在门框上睡着了，一只手还攥着灯绳。夜里有风，凉席滑到地上，她也没醒。院里那盏夜灌灯没点，灯罩擦得发亮，挂在枣树上。你站在院门口，看着她，脚步放轻了，还是踩响了门槛下的一块碎瓦。","ask":"她靠在门框上睡着了，你怎么做？","days":20,"npc":"mother","memory":"门槛上的凉席","choices":[{"title":"抱她进屋","desc":"你弯腰把她抱起来，送进屋里放到炕上。","hint":"她醒了，一晚上没再睡。","tone":"heal","outcome":"她很轻，抱起来像抱一捆干草。放到炕上时她醒了，睁眼看见是你，说：水放完了？你说放完了。她点点头，闭上眼。第二天她说腰疼，说你不该抱。可那以后她不在门槛上睡了，改成坐在灶边，灶边暖和。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":""}},{"title":"坐下陪她","desc":"你在她旁边坐下，把凉席捡起来盖在她腿上。","hint":"那晚的水没放完。","tone":"stay","outcome":"你坐到后半夜，她醒了一次，看见你在，说：你怎么不回屋。你说坐坐。她又睡了。天亮你去看水，下游一垄旱了，麦子蔫着。她第二天照旧坐在门槛上，只是凉席换成了厚的。你后来每回走到院门口，都放慢脚步。","eff":{"bond":4,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"下游旱了的那一垄"}},{"title":"把灯绳剪短","desc":"第二天你把门框上的灯绳剪短一截，让她够不着。","hint":"她找了半宿。","tone":"practical","outcome":"她够不着灯绳，站在门框下抬头看，看了很久。晚上她问你：绳子怎么短了。你说磨断了，接不上。她哦了一声。那以后她坐到屋里去了，门开着，屋里黑着。你回来时看见门口一团黑，心里一沉，走近了才看见她坐在那儿。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":""}}]},{"id":"xing_x18","act":"side","age":[46,46],"mode":"narration","title":"三尺地","opening":"东头老周家和西头老陈家为三尺地打了二十年。今年又打，打到农盟，让两家各出一个人去丈量。老周家来的是儿子，老陈家来的是女婿，两个年轻的站在地里，谁也说不出那三尺原来在哪。他们的爹都死了，一个死在前年，一个死在去年。地里的麦长得一样高，风一过，一齐往东倒。农盟的人把绳拉直，问：从哪头量。两个年轻人都不说话，脚在土里蹭，蹭出两个浅坑。绳子上挂着露水，亮得像一条细线。有人在地头蹲着看，看了一会儿又走了。谁的鞋尖先动了，又缩回去。","ask":"绳子拉直了，两边都等你说话，怎么办？","days":20,"npc":"","memory":"地头拉直那根绳","choices":[{"title":"照册子量","desc":"你翻开册子，找到二十年前那一页，说照这个量。","hint":"册子上那页被水洇过。","tone":"rule","outcome":"那一页被水洇过，字迹糊了一半，只能看出个大概。农盟的人照着量，老周家多出半尺。老陈家的女婿站在那半尺上，脸涨红，最后什么也没说，弯腰把那半尺的麦拔了。拔得很慢，一棵一棵。老周家的儿子看着，没拦。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}},{"title":"两家各让一垄","desc":"你说：三尺不算什么，两家各让一垄，合成一条路。","hint":"农盟的人不认这条路。","tone":"peace","outcome":"两个年轻人对视了一眼，都点了头。他们各让一垄，中间空出一条三尺宽的路。走路的人从此从那儿过，踩出一条白印。农盟的人说不合规矩，可没人来填。第二年那条路上长出了草，两个年轻人在地头碰见，会点一下头。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"喜":3,"哀":1},"flag":"","thread":""}},{"title":"把三尺挖成沟","desc":"你拿锹在三尺上挖了一道沟，说水从这儿走。","hint":"两家都少了一口气。","tone":"niche","outcome":"沟挖了一尺深，渠水引进来，从两家地头中间淌过去。农盟的人看了半天，说这倒省事，在册子上写：划为渠。两个年轻人站在沟两边，看着水，谁也没说话。老周家的儿子蹲下去捧了一捧水，喝了。老陈家的女婿说：这水是甜的。","eff":{"bond":1,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":2,"哀":2},"flag":"","thread":""}}]},{"id":"xing_x19","act":"side","age":[50,50],"mode":"narration","title":"去看热闹","opening":"下游坑里落了颗大星，落点离村十里。半夜有人敲窗，说去看。你披衣起来，老祁已经在院门外，提着灯，二柱子在后头，扛着一壶酒。三个人走夜路，露水把裤脚打湿，鞋底粘泥，越走越沉。走到半路，老祁说他的腰不行了，坐下歇，歇完接着走。天上的星一颗一颗往下掉，落在远处，没有声音。到地方天还没亮，落点被一圈篱笆围起来，篱笆是新打的，木头上还有白茬，门口挂着灯，有人在收钱，两文一看。篱笆里黑着，什么也看不见。二柱子把酒壶举起来晃了晃。","ask":"收钱的人伸出手，你怎么办？","days":12,"npc":"","memory":"走了十里的夜路","choices":[{"title":"掏两文进去","desc":"你摸出两文钱，三个人挤进去看。","hint":"里面那块石头是黑的。","tone":"pay","outcome":"篱笆里就是一个坑，坑底一块黑石头，跟别处的石头没什么两样。二柱子蹲下去看了半天，说：这不就是石头。收钱的人说：是星。老祁说：星怎么不亮。三个人站在坑边，把酒喝了，喝完往回走。路上二柱子说：十文钱，够买半斤盐。","eff":{"bond":2,"health":-1,"reputation":0,"coins":-10,"stats":{"机缘":1},"emotion":{"喜":3,"哀":1},"flag":"","thread":""}},{"title":"绕后头翻篱笆","desc":"你带着他们绕到篱笆后头，踩着土坎翻进去。","hint":"老祁的裤子挂在桩上。","tone":"sneak","outcome":"土坎是虚的，踩上去塌了一块，老祁摔进沟里，裤子挂在木桩上撕了一道。你们把他拽上来，裤子裂到膝盖。三个人蹲在坑边看那块石头，看了很久，二柱子伸手摸，烫得缩回来。翻出去时有人喊，你们跑了一里地才停，笑得直不起腰。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"喜":4,"惧":2},"flag":"","thread":""}},{"title":"在篱笆外坐着等","desc":"你说不看了，在篱笆外头坐下，等天亮。","hint":"你们看见的比里面多。","tone":"stay","outcome":"三个人靠着篱笆坐，把酒分了。天慢慢亮，篱笆里的坑看得见了，那块石头在坑底，边缘有一圈烧过的白。老祁说：比在里面看得清。回去时太阳出来，照得田里的麦一片黄。二柱子走着走着唱起来，唱得跑调，老祁跟着哼。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":4,"爱":1},"flag":"","thread":""}}]},{"id":"xing_s14","act":"side","age":[52,52],"mode":"narration","title":"碎在石阶上的灯","opening":"五十二岁那年，孩子八岁，在院里追一只萤火虫。夜灌灯挂在枣树上，他跳起来够，手指勾住了灯绳。灯掉在石阶上，玻璃罩碎成三块，灯芯断在里面，油顺着阶缝淌到你鞋边。石阶缝里往上冒冷气，油淌过去，凝成一层薄壳。他站着一动不动，手背在身后，眼睛看地。那是父亲留下的灯，灯罩换过四次，铜底座磨得发亮。星尘落在碎玻璃上，白了一层。天快黑了，地里发光的麦穗还亮着，水没放。","ask":"他背着手站在那儿，你先做什么？","days":15,"npc":"","memory":"碎在石阶上的灯","choices":[{"title":"先看他的手","desc":"你蹲下去，把他的手从背后拉出来，一片一片看有没有割破。","hint":"你的手先出了血。","tone":"heal","outcome":"他手指肚上有一道白印，没出血。你去捡碎片，玻璃在掌心划开一道口子，血滴在灯座上。那晚你用一只粗陶碗盛油，搓了根棉线当灯芯，光只有原来一半。水放得慢，渠尾那一垄麦旱了一夜，穗子瘪了些。孩子睡在你旁边，一只手抓着你的衣角，抓了一夜。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":"渠尾瘪下去的那垄麦"}},{"title":"领他到碑前","desc":"你收好碎片，牵着他上坡，让他跪在父亲碑前。","hint":"他半夜发起热来。","tone":"rule","outcome":"你让他跪着，说打碎祖物要跪到月亮偏西。他跪了，膝盖压在碎石上，一声没哭。后半夜他发起热来，说胡话，喊的不是你。你把他抱回屋，用凉布敷了一夜。第二天他把碎玻璃一片片捡进簸箕，手很稳。从那以后，他夜里走路总要先看一眼脚下。","eff":{"bond":-3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"怒":1},"flag":"","thread":"他夜里总先看脚下"}},{"title":"进城配灯罩","desc":"你把碎片包进布，第二天进城，让锡匠比着配一个。","hint":"孩子以为这事过去了。","tone":"practical","outcome":"锡匠配了个新罩，白玻璃，点起来亮得刺眼。你回来时孩子已经睡了，你没叫醒他，也没提灯的事。新灯照在田里，影子比从前硬。第二年冬天，他把母亲留下的手炉从柜上碰下来，摔掉一只耳。他站在那儿看你，等你说话。你还是没说。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"摔掉一只耳的手炉"}}]},{"id":"xing_s06","act":"side","age":[53,53],"mode":"dialogue","title":"最后一间冷房","opening":"入冬前，农盟贴了告示：老种子库最后一间冷房要在封冻前腾空，种并到新库去，冰脉归城里。母亲在库里干了三十年。那天她把告示从墙上揭下来，折成四折，塞进围裙口袋。白气从门槛底下往外爬，落在她裤脚上，结了一层薄霜。她把手伸进第三格，摸了很久，说：这格是你爹的。冷气把她的话托起来，又放下去。库里一排排木格黑着，只有她手边那盏夜灌灯亮着。","ask":"她站在冷房门口不动，你怎么办？","days":30,"npc":"mother","memory":"锁眼里的棉花","choices":[{"title":"陪她背完","desc":"你找出一条麻袋，把几百格种一袋一袋背去新库。","hint":"你的肩膀磨破了。","tone":"carry","outcome":"你们从天黑背到天亮，最后几趟她的腿在抖，还是不肯坐。你的肩膀磨破一层皮，抬了半个月。最后一格她没交，用围裙裹着塞进你怀里，说：拿回去，压米缸底下。冷房空了，门上了锁，她在锁眼里塞了一团棉花，说风从那儿进来。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":3},"flag":"saved_last_room_seed","thread":"锁眼里的那团棉花"}},{"title":"按告示清点","desc":"你拿过册子，照格点数，把第三格的袋口扎紧上交。","hint":"她把手泡在凉水里。","tone":"rule","outcome":"清点的人把第三格的袋子倒进大麻袋，母亲伸手扶了一下袋口，没拦。她跟在后头把空格一格格擦干净，擦到第三格时停了一会儿。那天回家她把手泡在热水里，水凉了也没添。后来她再没提过种子库，围裙口袋里的告示也没拿出来。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"进城找小满","desc":"你连夜进城，让小满在农盟的册子上想办法。","hint":"她的名字被划掉了。","tone":"deal","outcome":"小满托了人，冷房多留一个月，代价是母亲的名字从册子上划掉，算提前退了。她在家坐了一个冬天，手一直凉，闲下来就擦那盏灯。房最后还是关了，只是晚了一个月。小满回来时带了一包城里的糖，母亲没吃，放在灯边化了一层。","eff":{"bond":1,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"xing_x20","act":"side","age":[54,54],"mode":"dialogue","title":"灯递过来","opening":"老祁病了一个月。屋里药味压不住另一股味，窗关着，炕上铺着草席。他瘦得只剩一把骨头，手背上青筋鼓着，指甲发灰。他儿子在城里，捎了信，说月底回。他看见你进来，眼睛动了一下，伸手到炕头摸，摸到那盏夜灌灯，灯罩上有一道裂，用锡补过。他把灯往你这边推，推不动，就松开手。他说：今晚的水，你替我放。他说完就闭上眼，喘得很轻，胸口起伏得越来越慢。窗外田里的麦还亮着，光落在窗纸上，一动一动。他婆娘站在门边，两只手绞在一起。","ask":"灯在你手里，他还睁着眼等，你说什么？","days":15,"npc":"","memory":"补过锡的夜灌灯","choices":[{"title":"接灯，去放水","desc":"你接过灯，说：我放，你放心。然后提灯出门。","hint":"回来时炕上已经空了。","tone":"carry","outcome":"水放到后半夜，你一直想着快点。回来时门口挂着白布，人已经抬到门板上了。他婆娘说他走的时候手还在炕头摸，摸了两下。你把灯放在他枕边，灯罩上那道锡疤在灯下亮了一下。那一夜的水放得很匀，一垄也没旱。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":5,"爱":3},"flag":"","thread":"枕边那盏补锡的灯"}},{"title":"守着，不去放水","desc":"你把灯放回炕头，搬个凳子坐下，说：水明天再放。","hint":"他半夜问了一次水。","tone":"wait","outcome":"他半夜醒过一次，问：水放了没有。你说放了。他嗯了一声，又睡过去。天快亮时他走了，走得很静，你都没察觉，是他婆娘进来才发现的。那一夜的水没放，第二天他家那垄麦旱了半边。他儿子回来，跪在门口，你把灯递给他。","eff":{"bond":4,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":4},"flag":"","thread":""}},{"title":"去城里叫他儿子","desc":"你把灯塞回他手里，说：我去叫你儿子，你等着。","hint":"你没赶上。","tone":"seek","outcome":"你走了一夜，天亮在城门口等到他儿子出工。你们往回赶，走到半路碰见村里来报信的人。他儿子蹲在路边，蹲了很久，站起来时腿是麻的。回到村里，人已经入了殓。他儿子在灵前问：我爹最后说什么。你说：他让我放水。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"路边蹲着的那个人"}}]},{"id":"xing_x21","act":"side","age":[57,57],"mode":"narration","title":"一只鹅的利息","opening":"谢二来还糠。三年前借的三斗，他挑来一担，口袋鼓鼓的，往地上一放，声音不对，是糠皮的声。他说今年收成不好，掺了点皮，明年补上。说完又从身后拎出一只鹅，翅膀捆着，脖子伸得老长，说这是利息。鹅一落地就挣开了绳，扑棱着往灶间钻，掀翻了锅盖，锅里的水泼了一地。谢二追，他婆娘也追，鹅从人腿中间穿过去，一路叫着跑进院里，撞得灶房门来回晃，撞翻了晾菜的竹匾。谢二一边追一边喊：这鹅是我拿两升麦换的。他婆娘说：你换的时候它就不听话。两个人绕着院子跑了三圈。","ask":"鹅在院里乱窜，谢二满脸通红，你说什么？","days":15,"npc":"","memory":"那只挣开绳的鹅","choices":[{"title":"当他的面筛糠","desc":"你把口袋解开，拿筛子架在缸上，一瓢一瓢筛。","hint":"他婆娘扭头就走了。","tone":"honest","outcome":"糠皮筛出来小半袋，风一吹，飘了一院子。谢二蹲在旁边看，手指头抠着地。筛完你没说话，把实的那半袋倒进缸里。他站起来，说：明年我补。他婆娘已经走到院门外了。第二年他真补了一斗，是他婆娘挑来的，放下就走。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"","thread":""}},{"title":"收下留他吃饭","desc":"你把口袋整个倒进缸里，说：够了。又让母亲添双筷子。","hint":"那袋糠掺了多少，你俩都清楚。","tone":"warm","outcome":"饭桌上谢二吃得很少，筷子一直停在碗边。鹅被拴在桌腿旁，伸着脖子啄他的鞋。他走的时候在门口站住，说：我知道那袋里有多少皮。你说知道。他点点头，把鹅绳塞到你手里。那只鹅后来下了三年蛋，蛋比别家的小。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"那只下小蛋的鹅"}},{"title":"糠退回只要鹅","desc":"你把口袋推回去，说糠你挑回去，鹅我留下抵。","hint":"他挑着担子在门口站了很久。","tone":"practical","outcome":"他把口袋重新挑上肩，绳在手里绕了两圈，说：那我明年再来。他挑着担子走出院门，走得很慢，担子一颤一颤。鹅留下了，第二天开始下蛋。你把蛋攒着，攒了七个，让他婆娘来拿，她没来。第八个蛋你自己吃了。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":1},"flag":"","thread":""}}]},{"id":"xing_s07","act":"side","age":[58,58],"mode":"narration","title":"缸底的油纸包","opening":"母亲走后第二年，你才敢动那只米缸。缸里剩半缸陈糠，缸底垫着一块青砖。你搬开砖，底下是一个油纸包，包了三层，最里头用她的旧头巾裹着，角上打了个死结。纸上没有字。你打开，里面是黑亮的种，比麦粒大一圈，握在手里有点温。灶间很静，冷气从缸口往上冒，窗纸上落着星尘。夜灌灯在案上没点，灯罩擦得很干净。","ask":"这包种在你手里，你怎么处置？","days":30,"npc":"","memory":"母亲的头巾角","choices":[{"title":"分一半上坡","desc":"你留下一半，把另一半包好，连夜送到父亲坟前埋了。","hint":"回来的路上崴了脚。","tone":"escort","outcome":"你在坟前挖了个浅坑，把纸包放进去，土没埋严，留了一角油纸在外面。回来时你崴了脚，肿了半个月。另一半你用原来的油纸包好，塞回缸底。第二年春天，坟边的草里冒出几株黑麦，长得瘦，夜里没有一点光。你每年去割，割了捆好放在碑前，不吃。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":4},"flag":"found_mother_packet","thread":"坟边那几株黑麦"}},{"title":"交到农盟去","desc":"你把油纸包原样提到农盟，报上母亲的名字。","hint":"小满在灶边坐了一夜。","tone":"report","outcome":"他们当着你的面把种倒进焚烧桶，火苗是绿的，没有烟。登记的人问名字，你说了穗娘，册子上多一行：私藏变异种一包，已销。小满从城里赶回来，在灶边坐了一夜，说：那是娘的。你说：我知道。她第二天一早就走了，走前把缸底那块青砖掀起来看了看，又放回去。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":""}},{"title":"夜里种三粒","desc":"你趁夜在墙根下挖了三个坑，埋进三粒黑种。","hint":"它的穗是黑的。","tone":"sneak","outcome":"出苗很快，长得比人高，穗子是黑的，不发光。秋后你收了一小袋，磨面吃了，味道发苦，吃完嘴里一整天都是铁的味。剩下的你用油纸包好，放回缸底，压上青砖。那包种一直在那儿，你每次舀糠都听见纸响，像有人在底下翻身。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"喜":2},"flag":"","thread":""}}]},{"id":"xing_x22","act":"side","age":[62,62],"mode":"narration","title":"井水变温","opening":"冷房封了一年，农盟又来了人，这回是来挖冰脉。他们说冷房底下那一层冰是几百年的，城里要拿去做药。铁镐凿了三天，凿到第三尺，冰层断了，底下是一层黑水。冰一车一车往城里拉，车轮压在冻土上，一路响。拉走的那天，村里的井水就变了，打上来不冰手，温的，像放了一夜。老人说水是活的，冰走了，水就散了。你打了一桶，提回家，倒进缸里，缸壁上没起白霜。以前这个时节，缸壁上一层霜，手指头按上去会化一个印。井台上摆着一只木桶，桶里的水照得见天。","ask":"井水是温的，村里人都站在井台，怎么办？","days":30,"npc":"","memory":"不冰手的井水","choices":[{"title":"夜里把坑填回去","desc":"你扛着锹，半夜把凿开的坑一锹一锹填上土。","hint":"天亮就被查出来了。","tone":"defy","outcome":"填到一半，巡田的提灯来了，站在坑边看你。你没停，把最后一锹土拍实。他说明天还得挖开。你说那就明天再填。第二天他们照挖，你照填，填了四夜。第五夜他没来，坑也没人挖了，水还是温的。你在坑边坐到天亮。","eff":{"bond":2,"health":-3,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":"填了四夜的那个坑"}},{"title":"挑水给坡上老人","desc":"你挑着两桶温水，走上坡，给那几个下不了地的老人。","hint":"你的膝盖肿了半个月。","tone":"carry","outcome":"坡上住着四户，都是走不动的。你把水倒进各家的缸里，最后一户是个瞎眼的老太太，她摸了摸桶沿，说水是温的。你说井水变了。她说：温的好，我手冷。你挑了三趟，第三趟在半坡歇了两次。回家时天黑了，自家的缸还是空的。","eff":{"bond":3,"health":-3,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"进城去问小满","desc":"你搭车进城，去仓房找小满，问冰脉归了谁。","hint":"她让你别再问。","tone":"ask","outcome":"小满在仓房后头见你，围裙上沾着账灰。她听完，说：归城里，签过契的。你问契上写没写水。她不说话，低头把手在围裙上擦。擦了很久，说：哥，你别问了，问了也没用。你当天搭车回来，车上颠，水壶里的水晃出来，温的。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":""}}]},{"id":"xing_x23","act":"side","age":[66,66],"mode":"narration","title":"叫错的姓","opening":"望星台最老的守台人姓全，八十九了，眼睛还亮。他这半年开始认错人，把来上香的人叫成死人的名字。有人不高兴，他也不管。那天你上去送星历，他坐在台边的石阶上晒太阳，膝上盖着一件旧棉袄。他看见你，招手，说：老耒，你来啦，今年的雨我看过了，比去年好。他说完自己愣了一下，又说：你不是老耒，老耒早走了。他把手放回膝上，看着坡下。坡下的田一块一块，很整齐。风把他一撮白头发吹起来，贴在额头上，他没拂。石阶被晒得温热，坐久了有点烫。","ask":"他管你叫了你爹的名字，你怎么接？","days":20,"npc":"","memory":"石阶上那句老耒","choices":[{"title":"应一声坐下","desc":"你说：是我。然后在他旁边坐下，跟他一起看坡下。","hint":"他那天说了很多话。","tone":"warm","outcome":"他讲你爹年轻时守夜，讲他一次把灯提到台上来，被骂了一顿；讲那年雨大，整村人在台上挤着。他讲得清楚，人名一个不错。讲到后来他停住，转过头看你，说：你不是他。你说不是。他点点头，说：那你坐吧。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":""}},{"title":"说我不是我爹","desc":"你说：全爷，我是他儿子。","hint":"他把手从你胳膊上拿开了。","tone":"honest","outcome":"他把手从你胳膊上拿开，放在膝上，说：哦。坐了半晌，他问：那你爹呢。你说走了，十九年了。他说：我怎么不记得。他又坐了一会儿，站起来，说要去收星历。他走到台边，站住，回头问：你叫什么来着。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":1},"flag":"","thread":"他回头问的那一句"}},{"title":"问他雨的事","desc":"你不纠正，顺着问：今年的雨好在哪里。","hint":"他讲的雨你记下来了。","tone":"ask","outcome":"他眼睛亮起来，说今年的雨落得散，不砸地，能渗进去；说往年落得急，一层壳，水进不去。他讲了小半个时辰，讲完说：你记着，别让它砸。你回去把这话写在册子边角。第二年雨果然落得急，你提前把垄沟挖深了半寸。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"哀":2},"flag":"","thread":""}}]},{"id":"xing_s15","act":"side","age":[70,70],"mode":"narration","title":"一个人的田","opening":"七十岁那年陨季最后一夜，村里只剩几户，都上了坡。你一个人留在银穗坑守水。望星台的钟没响，守台的年轻人上月走了，台上没人值夜。渠水走得很慢，田里发光的麦穗一片很淡的光。你把夜灌灯放在埂上，灯罩开着，火苗只有指甲盖大。后半夜风向变了，冷气从渠底翻上来，星尘开始落，落在灯罩上，沙沙地响。渠埂内侧渗出一个洞，水从洞里往外冒，把土泡软了，一点一点往下塌。","ask":"洞越冲越大，你一个人怎么办？","days":30,"npc":"","memory":"一个人守到天亮","choices":[{"title":"躺进渠沟堵洞","desc":"你把灯塞进怀里推死，躺进渠沟，用背抵住那个洞。","hint":"天亮时你站不起来。","tone":"carry","outcome":"水从你背底下渗过去，冷得像刀。星尘落在你脸上，落一层化一层。你数着数，数到八百多，天边才白。那垄麦保住了，只倒了三株。小禾早上下来找你，看见你躺在沟里，吓得把灯都摔了。她拖不动你，跑去叫人。你的腰在床上躺了一个月。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":"腰躺了一个月"}},{"title":"关死上游的闸","desc":"你摸黑走到渠首，把闸门一格格压死，断了这一夜的水。","hint":"下游三家的田旱了。","tone":"rule","outcome":"闸门压到底，水声一下子没了，渠里只剩泥响。你回来时洞不再冒水，埂保住了。天亮下游三家的人站在渠口骂，说自家的田旱了一夜。你没解释，把闸重新提起来，让水先往他们田里走。那一季你家的水排在最后，麦比人家矮半尺。","eff":{"bond":-2,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":2},"flag":"","thread":"下游三家的骂声"}},{"title":"提灯去坡上叫人","desc":"你提着灯往坡上走，挨家敲门，把能叫的人都叫起来。","hint":"你回去时埂已经塌了。","tone":"seek","outcome":"你敲开三家门，只起来两个老人，一个瘸，一个咳。等你们回到田里，埂已经塌了半丈，水冲过一垄，麦倒在泥里。大家站在埂上看了很久，谁也没下去。天亮你一个人把倒的麦一株株扶起来，扶不直。小禾蹲在田头，问你：明年还种吗。你说种。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"扶不直的那一垄麦"}}]},{"id":"xing_x24","act":"side","age":[71,71],"mode":"narration","title":"门板戏台","opening":"陨铁城来的戏班子有三个人、一头驴、两扇门板。门板架在晒场的石碾上就是台，汽灯挂在枣树上，白得刺眼。他们唱的是《望星记》，讲一个农人追着星星种地。扮农人的那个嗓子不错，就是怕黑，汽灯一晃他就往台边缩。扮星的那个举着一盏纸糊的灯，灯里点了蜡，唱到第三折蜡烧完了，星就灭了。台下的人笑得拍大腿，有人笑得蹲下去，有人拿袖子擦眼睛。班主站在台口收糠，收一升唱一折。那头驴拴在台后，把扮老旦的假胡子嚼了半截，嚼得吧嗒响。","ask":"台上的星又灭了，班主看着你的糠袋，怎么办？","days":12,"npc":"","memory":"晒场上的门板戏台","choices":[{"title":"把糠全倒给他","desc":"你把整袋糠倒在班主的斗里，说：接着唱，唱到天亮。","hint":"这个冬天你家的粥稀了。","tone":"expand","outcome":"班主愣了一下，把斗里的糠按了按，回头喊：加一折！扮星的换了新蜡，那盏纸灯重新亮起来。台下的人不肯走，蹲着的、坐着的，一直看到鸡叫。散场时扮农人的那个在台上睡着了，鼾声很响。那年冬天你家的粥确实稀，可村里人提起来都说：那夜唱到天亮。","eff":{"bond":2,"health":-1,"reputation":2,"coins":0,"stats":{"魅力":2},"emotion":{"喜":4,"爱":1},"flag":"","thread":""}},{"title":"上台替他唱","desc":"你翻上台，接过那盏纸灯，说我唱农人这一段。","hint":"你唱错了两句，全村记住了。","tone":"brave","outcome":"你一开口，台下静了一下，随后哄起来。你唱到追星那一段，词忘了，站着干瞪眼，扮星的在旁边小声给你提词，提的也是错的。台下有人喊：就是这么唱的！你唱完下来，腿是软的。此后半年，村里小孩跟在你后头学你忘词那一段，学得一模一样。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"喜":5,"惧":1},"flag":"","thread":"小孩学你忘词那一段"}},{"title":"推二柱子上台","desc":"你说：这戏该二柱子唱，他追过发光的猪。","hint":"他上去就没下来。","tone":"niche","outcome":"二柱子被推上台，先是摆手，后来一开口，把追猪那夜编进词里，唱得比戏文还长。台下笑得有人蹲在地上。班主也不拦，蹲在台口听，听到后来把自己的胡琴递上去。那夜散得很晚。第二天二柱子嗓子哑了，见人就摆手，可嘴角一直往上。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"喜":5},"flag":"","thread":""}}]},{"id":"xing_s08","act":"side","age":[74,74],"mode":"narration","title":"只落了三颗星","opening":"七十四岁这年，陨季只落了三颗星。望星台的钟没响，守台的年轻人说，三颗不算雨，值不得开钟。村里人还是都出来了，站在田埂上仰头，像等一句没等来的话。第一颗落在坑心，第二颗落在渠那边，第三颗很小，落在坡上父亲那块旧碑旁边。坡下的麦穗不亮。夜灌灯在脚边，灯罩推着。拾尘会的丫头攥住你的衣角，问：就这么多了吗。你说：还有，剩下的堵在云后头。话出口才知道自己撒了谎。","ask":"话已经出口，她还仰着脸等，你怎么做？","days":40,"npc":"","memory":"只落三颗的夜","choices":[{"title":"把谎圆下去","desc":"你说再等两天，星从云后头来，还给她数了三回。","hint":"她会在坑口等很多天。","tone":"warm","outcome":"她信了，掰着手指头数，每天傍晚跑到坑口看天。过了两天没有星，她又来问，你又说了一遍。你把棉袄脱下来裹住她，自己咳了一冬。那年冬天没有第二场星雨，她把那三颗画在棚子的土墙上，画了满满一面，最后一颗画在坡那边。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"lied_to_child_about_stars","thread":"她会在坑口等很多天"}},{"title":"把话收回","desc":"你蹲下来，说刚才那是哄她的，今年不会再有星了。","hint":"她的手从你衣角上松开。","tone":"honest","outcome":"她没哭，手从你衣角上松开，走回棚里，路上没回头。第二天拾尘会的人来借种，你把种拿出来，他们看了看天，又放下了，说：没雨，种了也白种。那年冬天棚里走了四户。她走前问你那三颗叫什么，你说了三个名字，她记不住，还是跟着车走了。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":""}},{"title":"抱她上坡","desc":"你不再说星，把她抱起来，走到碑边看那点亮灭下去。","hint":"她以后见你只点头。","tone":"carry","outcome":"她趴在你肩上看，看到那点亮灭下去，说：像灯。你说：像灯。她把脸埋在你颈窝里，没再问星的事，你也没再提云后头的话。回去的路上她睡着了，你抱着走了一里，胳膊抖得厉害。后来她长大，在晒场见了你总要点一下头，不亲，也不远。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":""}}]}]}};
const STORY_ORDER=["穗骨原", "无昼京", "借寿渡", "钟葬群岛", "髓云都市", "星耒野"];
